void TestSurfaceGetApproximateSize() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Flat P(u,v)=(u,v,0) surface over domain [0,3]x[0,2] (control grid at
  // integer spacing) - no curvature at all, so the control-polygon
  // -length approximation is exact here: hand-derivable width=3,
  // height=2, confirmed by a debug run before finalizing.
  std::vector<Point3d> grid;
  for (int u = 0; u <= 3; ++u) {
    for (int v = 0; v <= 2; ++v) {
      grid.emplace_back(u, v, 0);
    }
  }
  const NurbsSurface flat = NurbsSurface::FromControlGrid(grid, 4, 3, 1, 1);
  const auto flat_size = flat.GetApproximateSize();
  Check(std::abs(flat_size.width - 3.0) < 1e-9 && std::abs(flat_size.height - 2.0) < 1e-9,
        "a flat surface's approximate size is exactly its true size "
        "(3 x 2), since there's no curvature for the control-polygon "
        "approximation to overstate");

  // Cylinder wall, radius 1: U wraps the unit circle (true circumference
  // 2*pi ~ 6.283), V is the straight height (1.0, exact - a line has no
  // curvature either). GetApproximateSize() now measures a representative
  // isocurve's own true arc length (NurbsCurve::Length()'s convergent
  // polyline sampling) rather than the control polygon's own vertex
  // spacing, so this is close to the true circumference (previously
  // overstated it substantially: 8.0 vs 6.283, the control-polygon-length
  // gap this fix closes).
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 1.0);
  const ON_Cylinder cylinder(circle, 1.0);
  ON_NurbsSurface cylinder_surface;
  Check(cylinder.GetNurbForm(cylinder_surface) != 0, "ON_Cylinder::GetNurbForm succeeds");
  NurbsSurface wall;
  wall.raw() = cylinder_surface;
  const auto wall_size = wall.GetApproximateSize();
  Check(std::abs(wall_size.width - 2.0 * ON_PI) < 1e-3,
        "the cylinder wall's approximate width closely matches the true "
        "circumference (2*pi), now that GetApproximateSize() measures a "
        "representative isocurve's true arc length instead of the "
        "control polygon's own coarser vertex spacing");
  Check(std::abs(wall_size.height - 1.0) < 1e-9,
        "the cylinder wall's approximate height is exactly 1.0, the "
        "true straight-line height");
}

void TestSurfaceTessellateGridClippedExactRejectsTooFewPoints() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point2d;
  using dino8::kernel::Point3d;

  // The most serious finding in this whole validation-gap sweep: unlike
  // every other "silently wrong result" gap found so far, a debug run
  // showed an *empty* trim_polygon here doesn't just tessellate wrong -
  // it SEGFAULTS. Root cause (found by reading the crash site): the
  // concave-clipping path's ClipPolygon() has a "no boundary crossings
  // at all" fallback that unconditionally dereferences clip[0] to test
  // which polygon contains the other - an out-of-bounds vector access
  // when clip (the trim_polygon) is empty. A 1- or 2-point polygon isn't
  // a real closed polygon either, so all three are rejected the same
  // way, checked before the (necessarily insufficient for this case)
  // IsSimplePolygon check below it.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);

  for (const int point_count : {0, 1, 2}) {
    std::vector<Point2d> trim_polygon;
    for (int i = 0; i < point_count; ++i) {
      trim_polygon.push_back(Point2d(0.1 * i, 0.1 * i));
    }
    bool threw = false;
    try {
      surface.TessellateGridClippedExact(4, 4, trim_polygon);
    } catch (const std::invalid_argument&) {
      threw = true;
    }
    Check(threw,
          "TessellateGridClippedExact throws std::invalid_argument (rather than segfaulting or "
          "misbehaving) on a trim_polygon with fewer than 3 points");
  }
}

void TestSurfaceTessellateGridRejectsTooFewTrimPoints() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point2d;
  using dino8::kernel::Point3d;

  // The milder sibling of the TessellateGridClippedExact() segfault
  // fixed above: TessellateGrid()'s whole-cell path goes through
  // PointInPolygon() instead of the crashing ClipPolygon() concave path,
  // and PointInPolygon() itself is safe on a too-short polygon (an
  // unsigned n-1 underflow that never gets dereferenced, since the loop
  // bound is also 0) - so this one was "only" a silent full-empty-mesh
  // result (V=0, F=0 for all of 0/1/2 points, confirmed by a debug run),
  // not a crash. Still a real, previously-missing check: fixed in the
  // shared TessellateFromValues() helper, so both TessellateGrid() and
  // TessellateGridNonUniform() get it.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);

  for (const int point_count : {0, 1, 2}) {
    std::vector<Point2d> trim_polygon;
    for (int i = 0; i < point_count; ++i) {
      trim_polygon.push_back(Point2d(0.1 * i, 0.1 * i));
    }
    bool threw = false;
    try {
      surface.TessellateGrid(4, 4, &trim_polygon);
    } catch (const std::invalid_argument&) {
      threw = true;
    }
    Check(threw,
          "TessellateGrid throws std::invalid_argument on a non-null trim_polygon with fewer "
          "than 3 points");
  }
}

void TestSurfaceTessellateGridValidation() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // A real gap found while adding ApproximateArea(): TessellateGrid()
  // used to have no division-count validation at all, silently producing
  // NaN parameter values via an unguarded 0/0 division on a 0 division
  // count (confirmed by reading the old implementation) instead of
  // failing loudly. Now fixed directly in TessellateGrid() itself.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);

  bool threw_on_u = false;
  try {
    surface.TessellateGrid(0, 5);
  } catch (const std::invalid_argument&) {
    threw_on_u = true;
  }
  Check(threw_on_u, "TessellateGrid throws std::invalid_argument when u_divisions is 0");

  bool threw_on_v = false;
  try {
    surface.TessellateGrid(5, -1);
  } catch (const std::invalid_argument&) {
    threw_on_v = true;
  }
  Check(threw_on_v, "TessellateGrid throws std::invalid_argument when v_divisions is negative");

  // Same real gap, same fix, in TessellateGridClippedExact() - it reaches
  // ParameterAt() and (on the concave path) a grid-width division the
  // same unguarded way TessellateGrid() used to.
  using dino8::kernel::Point2d;
  const std::vector<Point2d> trim_loop = {
      Point2d(0.15, 0.15),
      Point2d(0.85, 0.15),
      Point2d(0.85, 0.85),
      Point2d(0.15, 0.85),
  };
  bool threw_clipped = false;
  try {
    surface.TessellateGridClippedExact(0, 5, trim_loop);
  } catch (const std::invalid_argument&) {
    threw_clipped = true;
  }
  Check(threw_clipped,
        "TessellateGridClippedExact throws std::invalid_argument when u_divisions is 0");
}

void TestSurfaceTessellateGridNonUniform() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);

  // Equivalence check: evenly-spaced u_values/v_values should reproduce
  // TessellateGrid()'s own output exactly - confirmed by a debug run
  // before finalizing (byte-for-byte matching vertex/face counts and
  // area).
  const std::vector<double> even_u = {0.0, 0.25, 0.5, 0.75, 1.0};
  const std::vector<double> even_v = {0.0, 1.0 / 3.0, 2.0 / 3.0, 1.0};
  const auto uniform_via_new = surface.TessellateGridNonUniform(even_u, even_v);
  const auto uniform_via_old = surface.TessellateGrid(4, 3);
  Check(uniform_via_new.VertexCount() == uniform_via_old.VertexCount() &&
            uniform_via_new.FaceCount() == uniform_via_old.FaceCount(),
        "TessellateGridNonUniform with evenly-spaced values matches "
        "TessellateGrid's own vertex/face counts exactly");
  Check(std::abs(uniform_via_new.Area() - uniform_via_old.Area()) < 1e-9,
        "...and matches its area exactly too");

  // Genuinely non-uniform values on the same flat surface: area should
  // still be (up to float32 vertex precision) exactly 1.0 - the
  // identity-mapped unit square's true area never depends on where the
  // grid lines fall, only on the domain's own outer extent.
  const std::vector<double> non_uniform_u = {0.0, 0.05, 0.1, 0.5, 0.9, 0.95, 1.0};
  const std::vector<double> non_uniform_v = {0.0, 0.5, 1.0};
  const auto non_uniform_mesh = surface.TessellateGridNonUniform(non_uniform_u, non_uniform_v);
  Check(std::abs(non_uniform_mesh.Area() - 1.0) < 1e-6,
        "a genuinely non-uniform grid on the flat unit-square surface "
        "still measures the exact true area (1.0), regardless of where "
        "the (uneven) grid lines fall");
  Check(non_uniform_mesh.VertexCount() == 21 && non_uniform_mesh.FaceCount() == 24,
        "the non-uniform mesh's own vertex/face counts exactly match "
        "its 7x3 grid of parameter values (21 vertices, "
        "6x2 cells x 2 triangles = 24 faces)");

  bool threw_too_few = false;
  try {
    surface.TessellateGridNonUniform({0.0}, {0.0, 1.0});
  } catch (const std::invalid_argument&) {
    threw_too_few = true;
  }
  Check(threw_too_few,
        "TessellateGridNonUniform throws std::invalid_argument when "
        "u_values has fewer than 2 entries");

  bool threw_not_increasing = false;
  try {
    surface.TessellateGridNonUniform({0.0, 0.5, 0.3, 1.0}, {0.0, 1.0});
  } catch (const std::invalid_argument&) {
    threw_not_increasing = true;
  }
  Check(threw_not_increasing,
        "TessellateGridNonUniform throws std::invalid_argument when "
        "u_values isn't strictly increasing");
}

void TestSurfaceSuggestedParameterValuesAndTessellateGridNonUniformAdaptive() {
  using dino8::kernel::NurbsSurface;

  // Same cylinder wall used throughout this file: U is the circular
  // direction (real curvature everywhere), V is the straight height
  // (zero curvature). Confirmed by a debug run before finalizing:
  // direction 0 needs real (non-trivial) bisection - its own segment
  // count (32) is, as with the earlier circle-curve test, the smallest
  // power of 2 at or above the independently-computed SuggestedDivisions
  // count (23) - while direction 1 needs none at all, landing on exactly
  // its domain's own 2 endpoints [0, 1], matching SuggestedDivisions.v's
  // own value of 1.
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 1.0);
  const ON_Cylinder cylinder(circle, 1.0);
  ON_NurbsSurface cylinder_surface;
  Check(cylinder.GetNurbForm(cylinder_surface) != 0, "ON_Cylinder::GetNurbForm succeeds");
  NurbsSurface wall;
  wall.raw() = cylinder_surface;

  const double chord_tolerance = 0.01;
  const auto u_values = wall.SuggestedParameterValues(0, chord_tolerance);
  const auto v_values = wall.SuggestedParameterValues(1, chord_tolerance);
  const auto divisions = wall.SuggestedDivisions(chord_tolerance);
  const int expected_u_segments = static_cast<int>(
      std::pow(2.0, std::ceil(std::log2(static_cast<double>(divisions.u)))));
  Check(static_cast<int>(u_values.size()) - 1 == expected_u_segments,
        "direction 0's own segment count matches the smallest power of "
        "2 at or above SuggestedDivisions()'s independently-computed "
        "minimum threshold, the same relationship the curve-level test "
        "already established");
  Check(v_values.size() == 2 && v_values.front() == 0.0 && v_values.back() == 1.0,
        "direction 1 (zero curvature) needs no bisection at all - "
        "exactly its domain's own [0, 1] endpoints");

  // Wiring check: TessellateGridNonUniformAdaptive() must produce
  // exactly the same mesh as calling SuggestedParameterValues() for
  // both directions and TessellateGridNonUniform() by hand.
  const auto adaptive_mesh = wall.TessellateGridNonUniformAdaptive(chord_tolerance);
  const auto manual_mesh = wall.TessellateGridNonUniform(u_values, v_values);
  Check(adaptive_mesh.VertexCount() == manual_mesh.VertexCount() &&
            adaptive_mesh.FaceCount() == manual_mesh.FaceCount(),
        "TessellateGridNonUniformAdaptive produces the exact same mesh "
        "as calling SuggestedParameterValues() (both directions) then "
        "TessellateGridNonUniform() by hand");

  bool threw = false;
  try {
    wall.SuggestedParameterValues(0, -1.0);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw,
        "SuggestedParameterValues throws std::invalid_argument on a "
        "non-positive chord_tolerance");
}

void TestSurfaceReverseAndTranspose() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  // Same flat P(u,v)=(u,v,0) surface TestSurfaceNormalAt() already
  // established has normal exactly (0,0,1) everywhere.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };

  // Reverse(0) (U) flips the outward normal exactly, since u_dir x v_dir
  // negates when u_dir reverses direction - confirmed here rather than
  // just asserted from the cross-product algebra.
  NurbsSurface reversed = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  Check(reversed.Reverse(0) == dino8::kernel::Result::Ok, "NurbsSurface::Reverse(0) succeeds");
  // Same domain-not-preserved caveat NurbsCurve::Reverse() has - a [0,1]
  // domain came back as [-1,0] here too - so re-fetch fresh rather than
  // reusing a captured one.
  const ON_Interval u_after = reversed.raw().Domain(0);
  const ON_Interval v_after = reversed.raw().Domain(1);
  const Vector3d normal_after_reverse =
      reversed.NormalAt(u_after.ParameterAt(0.5), v_after.ParameterAt(0.5));
  Check(std::abs(normal_after_reverse.x) < 1e-9 && std::abs(normal_after_reverse.y) < 1e-9 &&
            std::abs(normal_after_reverse.z - (-1.0)) < 1e-9,
        "Reverse(0) flips the flat surface's normal from (0,0,1) to "
        "exactly (0,0,-1)");

  // Transpose() swaps U and V entirely, which has the same normal-
  // flipping effect (v_dir x u_dir = -(u_dir x v_dir)) as Reverse() -
  // independently confirmed, not assumed to behave the same way just
  // because both involve "reversing something".
  NurbsSurface transposed = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  transposed.Transpose();
  const ON_Interval tu = transposed.raw().Domain(0);
  const ON_Interval tv = transposed.raw().Domain(1);
  const Vector3d normal_after_transpose =
      transposed.NormalAt(tu.ParameterAt(0.5), tv.ParameterAt(0.5));
  Check(std::abs(normal_after_transpose.x) < 1e-9 && std::abs(normal_after_transpose.y) < 1e-9 &&
            std::abs(normal_after_transpose.z - (-1.0)) < 1e-9,
        "Transpose() also flips the flat surface's normal to exactly "
        "(0,0,-1)");
}

void TestSurfaceTrim() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // Same flat P(u,v)=(u,v,0) surface as TestSurfaceReverseAndTranspose().
  // Trimming only the U direction to [0.2, 0.7] should leave V's domain
  // [0,1] untouched and, since the surface is an identity mapping, should
  // make the new U-domain's own endpoints land exactly at u=0.2 and
  // u=0.7 - confirmed by a debug run before writing these assertions,
  // not assumed.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  Check(surface.Trim(0, 0.2, 0.7) == Result::Ok, "NurbsSurface::Trim(0, ...) succeeds");

  const ON_Interval u_after = surface.raw().Domain(0);
  const ON_Interval v_after = surface.raw().Domain(1);
  Check(std::abs(u_after.Min() - 0.2) < 1e-9 && std::abs(u_after.Max() - 0.7) < 1e-9,
        "trimming direction 0 sets that direction's domain to exactly "
        "[0.2, 0.7]");
  Check(std::abs(v_after.Min() - 0.0) < 1e-9 && std::abs(v_after.Max() - 1.0) < 1e-9,
        "trimming direction 0 leaves direction 1's domain [0,1] unchanged");

  const Point3d p_lo = surface.PointAt(u_after.Min(), v_after.Min());
  const Point3d p_hi = surface.PointAt(u_after.Max(), v_after.Max());
  Check(std::abs(p_lo.x - 0.2) < 1e-9 && std::abs(p_lo.y) < 1e-9 && std::abs(p_lo.z) < 1e-9,
        "PointAt the trimmed domain's low corner is exactly (0.2, 0, 0)");
  Check(std::abs(p_hi.x - 0.7) < 1e-9 && std::abs(p_hi.y - 1.0) < 1e-9 && std::abs(p_hi.z) < 1e-9,
        "PointAt the trimmed domain's high corner is exactly (0.7, 1, 0)");

  bool failed = false;
  NurbsSurface backwards = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  if (backwards.Trim(0, 0.7, 0.2) == Result::Failed) {
    failed = true;
  }
  Check(failed,
        "Trim() fails on a backwards interval (t0 >= t1) rather than "
        "silently doing something undefined");
}

void TestSurfaceSplit() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // Same flat P(u,v)=(u,v,0) surface as TestSurfaceTrim(). Splitting
  // direction 0 (U) at t=0.4 should give a west half covering u in
  // [0, 0.4] and an east half covering [0.4, 1], both sharing v's domain
  // [0,1] unchanged, and the two halves should meet exactly at u=0.4 -
  // confirmed by a debug run before finalizing these assertions.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  NurbsSurface west, east;
  Check(surface.Split(0, 0.4, west, east) == Result::Ok, "NurbsSurface::Split(0, ...) succeeds");

  const ON_Interval wu = west.raw().Domain(0);
  const ON_Interval wv = west.raw().Domain(1);
  const ON_Interval eu = east.raw().Domain(0);
  const ON_Interval ev = east.raw().Domain(1);
  Check(std::abs(wu.Min() - 0.0) < 1e-9 && std::abs(wu.Max() - 0.4) < 1e-9,
        "the west half's own domain(0) is exactly [0, 0.4]");
  Check(std::abs(eu.Min() - 0.4) < 1e-9 && std::abs(eu.Max() - 1.0) < 1e-9,
        "the east half's own domain(0) is exactly [0.4, 1]");
  Check(std::abs(wv.Min()) < 1e-9 && std::abs(wv.Max() - 1.0) < 1e-9 &&
            std::abs(ev.Min()) < 1e-9 && std::abs(ev.Max() - 1.0) < 1e-9,
        "both halves keep direction 1's domain [0,1] unchanged");

  const Point3d w_hi = west.PointAt(wu.Max(), wv.Min());
  const Point3d e_lo = east.PointAt(eu.Min(), ev.Min());
  Check(std::abs(w_hi.x - 0.4) < 1e-9 && std::abs(w_hi.y) < 1e-9 && std::abs(w_hi.z) < 1e-9,
        "the west half's own u_max edge lands exactly at (0.4, 0, 0)");
  Check(std::abs(e_lo.x - 0.4) < 1e-9 && std::abs(e_lo.y) < 1e-9 && std::abs(e_lo.z) < 1e-9,
        "the east half's own u_min edge lands at the same exact point "
        "(0.4, 0, 0), so the two halves share the split line with no "
        "gap or overlap");

  bool failed = false;
  NurbsSurface endpoint_source = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  NurbsSurface endpoint_west, endpoint_east;
  if (endpoint_source.Split(0, 0.0, endpoint_west, endpoint_east) == Result::Failed) {
    failed = true;
  }
  Check(failed,
        "Split() fails when t sits exactly at a domain endpoint rather "
        "than strictly inside it");
}

void TestSurfaceExtend() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // Same flat P(u,v)=(u,v,0) surface as TestSurfaceSplit(). Extending
  // direction 0 to [-0.5, 1.0] should analytically extrapolate the
  // identity mapping rather than approximate it, leaving direction 1's
  // domain untouched - confirmed by a debug run before finalizing these
  // assertions.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  Check(surface.Extend(0, -0.5, 1.0) == Result::Ok, "NurbsSurface::Extend(0, ...) succeeds");

  const ON_Interval u_after = surface.raw().Domain(0);
  const ON_Interval v_after = surface.raw().Domain(1);
  Check(std::abs(u_after.Min() - (-0.5)) < 1e-9 && std::abs(u_after.Max() - 1.0) < 1e-9,
        "extending direction 0 sets that direction's domain to exactly "
        "[-0.5, 1.0]");
  Check(std::abs(v_after.Min()) < 1e-9 && std::abs(v_after.Max() - 1.0) < 1e-9,
        "extending direction 0 leaves direction 1's domain [0,1] unchanged");

  const Point3d p = surface.PointAt(u_after.Min(), 0.5);
  Check(std::abs(p.x - (-0.5)) < 1e-9 && std::abs(p.y - 0.5) < 1e-9 && std::abs(p.z) < 1e-9,
        "PointAt the extended domain's new u_min edge lands exactly on "
        "(-0.5, 0.5, 0), the same identity mapping extrapolated, not a "
        "different surface");

  NurbsSurface unchanged = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  Check(unchanged.Extend(0, 0.2, 0.8) == Result::NoOpAlreadySatisfied,
        "Extend() to a sub-range already inside the current domain "
        "reports NoOpAlreadySatisfied rather than Ok or Failed");

  NurbsSurface backwards = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  Check(backwards.Extend(0, 1.0, -0.5) == Result::Failed,
        "Extend() fails on a backwards interval (t0 >= t1) rather than "
        "silently doing something undefined");
}

void TestSurfaceDomain() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Same reasoning as `TestCurveDomain()` above, per direction: a 4x4
  // control grid at degree 3x3 is a single Bezier span in both u and v,
  // so both domains are exactly [0, 1] - confirmed via a debug run
  // against the wrapper's own `raw().Domain(direction)` before
  // finalizing.
  std::vector<Point3d> grid;
  for (int i = 0; i < 4; ++i) {
    for (int j = 0; j < 4; ++j) {
      grid.push_back(Point3d(static_cast<double>(i), static_cast<double>(j), 0.0));
    }
  }
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 4, 4, 3, 3);
  const auto u_domain = surface.Domain(0);
  const auto v_domain = surface.Domain(1);
  const ON_Interval raw_u = surface.raw().Domain(0);
  const ON_Interval raw_v = surface.raw().Domain(1);
  Check(u_domain.min == raw_u.Min() && u_domain.max == raw_u.Max() &&
            v_domain.min == raw_v.Min() && v_domain.max == raw_v.Max(),
        "NurbsSurface::Domain(direction) matches the underlying "
        "ON_NurbsSurface::Domain(direction) exactly, for both directions");
  Check(u_domain.min == 0.0 && u_domain.max == 1.0 && v_domain.min == 0.0 && v_domain.max == 1.0,
        "a 4x4-control-point, degree-3x3 surface's domain is exactly [0, 1] in both directions");
}

void TestSurfaceSetWeightAt() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // Bilinear surface (2x2 control grid, degree 1x1), all four Bernstein
  // weights exactly 0.25 at (u,v)=(0.5,0.5). Same "stored (X,Y,Z) isn't
  // rescaled when W changes" mechanism NurbsCurve::SetWeightAt()'s own
  // test documents, cross-checked here on a second, independent
  // construction (a surface, not a curve) rather than assumed to
  // generalize. FromControlGrid()'s own SetCV(u, v, ...) mapping places
  // control_grid[u * v_count + v] at (u, v) - confirmed by reading its
  // source, not guessed - so index (1, 0) here is control_grid[2],
  // point (1, 0, 5).
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 5),
      Point3d(1, 1, 0),
  };
  NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  const Point3d before = surface.PointAt(0.5, 0.5);
  Check(std::abs(before.x - 0.5) < 1e-12 && std::abs(before.y - 0.5) < 1e-12 &&
            std::abs(before.z - 1.25) < 1e-12,
        "the ordinary (unweighted) bilinear surface midpoint is exactly the average of all 4 "
        "corners, (0.5, 0.5, 1.25)");

  // Hand-derived: numerator (X, Y, Z) = sum(0.25 * raw_corner) is
  // UNCHANGED by the weight change (still (0.5, 0.5, 1.25), same as
  // `before` - the raw stored coordinates aren't rescaled), while the
  // denominator W = 0.25*(1 + 4 + 1 + 1) = 1.75 does change. Final point
  // = (0.5, 0.5, 1.25) / 1.75 = (2/7, 2/7, 5/7).
  const Result set_result = surface.SetWeightAt(1, 0, 4.0);
  Check(set_result == Result::Ok, "SetWeightAt returns Ok when it changes a real weight");
  Check(surface.IsRational(), "the surface is rational after SetWeightAt changes a weight from "
                               "1.0");
  Check(surface.WeightAt(1, 0) == 4.0, "WeightAt(1, 0) reflects the newly-set weight exactly");
  const Point3d after = surface.PointAt(0.5, 0.5);
  const double expected = 2.0 / 7.0;
  const double expected_z = 5.0 / 7.0;
  Check(std::abs(after.x - expected) < 1e-12 && std::abs(after.y - expected) < 1e-12 &&
            std::abs(after.z - expected_z) < 1e-12,
        "the new midpoint matches the hand-derived homogeneous-blend result (2/7, 2/7, 5/7) "
        "exactly");

  Check(surface.SetWeightAt(1, 0, 4.0) == Result::NoOpAlreadySatisfied,
        "SetWeightAt reports NoOpAlreadySatisfied when the weight already matches");
  Check(surface.SetWeightAt(99, 99, 2.0) == Result::Failed,
        "SetWeightAt returns Failed (not a crash) on an out-of-range (i, j)");
}

void TestSurfaceMakeRationalAndNonRational() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // MakeRational() on a flat (already-non-rational) surface: genuinely
  // shape-preserving, same guarantee as the curve case.
  const std::vector<Point3d> flat_grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  NurbsSurface flat = NurbsSurface::FromControlGrid(flat_grid, 2, 2, 1, 1);
  Check(!flat.IsRational(), "the surface starts non-rational");
  const Point3d before_flat = flat.PointAt(0.5, 0.5);
  Check(flat.MakeRational() == Result::Ok, "MakeRational returns Ok when it changes the surface");
  Check(flat.IsRational(), "the surface is rational after MakeRational");
  Check(flat.PointAt(0.5, 0.5) == before_flat,
        "MakeRational is exactly shape-preserving on a surface with uniform weights");
  Check(flat.MakeRational() == Result::NoOpAlreadySatisfied,
        "MakeRational reports NoOpAlreadySatisfied when already rational");

  // MakeNonRational() on a genuine sphere: the same real shape-breaking
  // finding as the circle case, cross-checked independently rather than
  // assumed to generalize. A radius-3 sphere's distance from center
  // should stay exactly 3.0 everywhere; after forcing non-rational, a
  // debug run showed it instead varies between ~3.02 and ~3.27 across a
  // grid of sampled (u, v) values - confirming a real, measurable shape
  // change, not floating-point noise.
  const ON_Sphere on_sphere(ON_3dPoint(0, 0, 0), 3.0);
  ON_NurbsSurface sphere_surface;
  Check(on_sphere.GetNurbForm(sphere_surface) != 0, "ON_Sphere::GetNurbForm succeeds");
  NurbsSurface sphere;
  sphere.raw() = sphere_surface;
  Check(sphere.IsRational(), "the genuine sphere starts rational");
  Check(sphere.MakeNonRational() == Result::Ok,
        "MakeNonRational returns Ok when it changes the surface");
  Check(!sphere.IsRational(), "the surface is non-rational after MakeNonRational");

  double min_dist = std::numeric_limits<double>::max();
  double max_dist = std::numeric_limits<double>::lowest();
  for (double u : {0.1, 0.3, 0.5, 0.7, 0.9}) {
    for (double v : {0.1, 0.5, 0.9}) {
      const double dist =
          sphere.PointAt(u * sphere.Domain(0).max, v * sphere.Domain(1).max)
              .DistanceTo(ON_3dPoint(0, 0, 0));
      min_dist = std::min(min_dist, dist);
      max_dist = std::max(max_dist, dist);
    }
  }
  Check(max_dist - min_dist > 0.1,
        "MakeNonRational genuinely breaks the sphere's shape - sampled distances from center "
        "vary by more than 0.1 instead of staying at a constant radius, confirming this is a "
        "real shape change");

  Check(sphere.MakeNonRational() == Result::NoOpAlreadySatisfied,
        "MakeNonRational reports NoOpAlreadySatisfied when already non-rational");
}

void TestSurfaceInsertKnotAt() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // 4x2 control grid, degree 2 in u (domain [0,2]) / degree 1 in v
  // (domain [0,1]), with z varying by u index so the surface is
  // genuinely curved in u (not flat) - a real shape for InsertKnotAt to
  // (not) change. Confirmed by a debug run that the default
  // clamped-uniform u-knot vector is [0,0,1,2,2] - so 1.0 is already an
  // existing interior knot, which is exactly what exposed the
  // `multiplicity` no-op nuance `NurbsCurve::InsertKnotAt()`'s own doc
  // comment now describes; 0.5 is a genuinely new value, used here for
  // the main "shape unchanged, control points added" assertions.
  std::vector<Point3d> grid;
  const std::vector<double> z_by_u = {0.0, 3.0, -2.0, 1.0};
  for (int i = 0; i < 4; ++i) {
    for (int j = 0; j < 2; ++j) {
      grid.push_back(
          Point3d(static_cast<double>(i), static_cast<double>(j), z_by_u[static_cast<size_t>(i)]));
    }
  }
  NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 4, 2, /*u_degree=*/2, /*v_degree=*/1);
  Check(surface.CVCountU() == 4 && surface.KnotCount(0) == 5,
        "the surface starts with 4 u-control-points and 5 u-knots");
  std::vector<Point3d> before_points;
  for (double u : {0.3, 0.9, 1.0, 1.5, 1.8}) {
    before_points.push_back(surface.PointAt(u, 0.5));
  }

  const Result result = surface.InsertKnotAt(0, 0.5, /*multiplicity=*/1);
  Check(result == Result::Ok, "InsertKnotAt returns Ok on a valid interior knot value");
  Check(surface.CVCountU() == 5 && surface.KnotCount(0) == 6,
        "InsertKnotAt adds exactly one new u-control-point and one new u-knot for a genuinely "
        "new knot value");

  bool shape_unchanged = true;
  size_t idx = 0;
  for (double u : {0.3, 0.9, 1.0, 1.5, 1.8}) {
    if ((surface.PointAt(u, 0.5) - before_points[idx++]).Length() > 1e-9) {
      shape_unchanged = false;
    }
  }
  Check(shape_unchanged,
        "PointAt() matches before and after InsertKnotAt to within 1e-9 at 5 different u "
        "values - the surface's shape genuinely didn't change");

  // The same real `multiplicity` no-op nuance NurbsCurve::InsertKnotAt()
  // documents, cross-checked here independently: 1.0 already exists in
  // the u-knot vector with multiplicity 1, so inserting it again at
  // multiplicity 1 is a genuine no-op.
  const Result already_present_result = surface.InsertKnotAt(0, 1.0, 1);
  Check(already_present_result == Result::Ok,
        "InsertKnotAt still returns Ok when the requested multiplicity is already satisfied");
  Check(surface.CVCountU() == 5 && surface.KnotCount(0) == 6,
        "...but adds no new control points or knots, since 1.0 already has multiplicity 1");

  bool boundary_threw = false;
  try {
    surface.InsertKnotAt(0, 2.0, 1);
  } catch (const std::invalid_argument&) {
    boundary_threw = true;
  }
  Check(boundary_threw,
        "InsertKnotAt throws std::invalid_argument at the domain's own boundary (not strictly "
        "interior)");

  bool multiplicity_threw = false;
  try {
    surface.InsertKnotAt(0, 1.0, 5);
  } catch (const std::invalid_argument&) {
    multiplicity_threw = true;
  }
  Check(multiplicity_threw,
        "InsertKnotAt throws std::invalid_argument when multiplicity exceeds the degree in that "
        "direction");
}

void TestSurfaceKnotAt() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Non-square (5x3 control points, degree 2x1) so u and v aren't
  // accidentally checked against the same numbers - same discipline
  // TestSurfaceCVCount() already uses. u: KnotCount = 5 + 2 - 1 = 6,
  // knots [0,0,1,2,3,3] (3 spans since u_count - degree = 5 - 2 = 3,
  // matching the domain [0, 3] the clamped-uniform-knots rule already
  // established for CVCount()/Domain() predicts). v: KnotCount =
  // 3 + 1 - 1 = 3, knots [0,1,2]. Confirmed by a debug run before
  // finalizing, not assumed from the formula alone.
  std::vector<Point3d> grid;
  for (int i = 0; i < 5; ++i) {
    for (int j = 0; j < 3; ++j) {
      grid.push_back(Point3d(static_cast<double>(i), static_cast<double>(j), 0.0));
    }
  }
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 5, 3, /*u_degree=*/2,
                                                              /*v_degree=*/1);
  Check(surface.KnotCount(0) == 6, "KnotCount(0) is exactly 5 + 2 - 1 = 6");
  const std::vector<double> expected_u = {0.0, 0.0, 1.0, 2.0, 3.0, 3.0};
  bool u_match = true;
  for (int i = 0; i < surface.KnotCount(0); ++i) {
    if (surface.KnotAt(0, i) != expected_u[static_cast<size_t>(i)]) {
      u_match = false;
    }
  }
  Check(u_match, "the u-direction knot vector is exactly [0, 0, 1, 2, 3, 3]");

  Check(surface.KnotCount(1) == 3, "KnotCount(1) is exactly 3 + 1 - 1 = 3");
  const std::vector<double> expected_v = {0.0, 1.0, 2.0};
  bool v_match = true;
  for (int i = 0; i < surface.KnotCount(1); ++i) {
    if (surface.KnotAt(1, i) != expected_v[static_cast<size_t>(i)]) {
      v_match = false;
    }
  }
  Check(v_match, "the v-direction knot vector is exactly [0, 1, 2]");
}

void TestSurfaceControlPointAt() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 5),
      Point3d(1, 1, 0),
  };
  NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  Check(surface.ControlPointAt(1, 0) == Point3d(1, 0, 5),
        "ControlPointAt(1, 0) is exactly the original construction point");

  // Same "divide the unchanged raw coordinate by the new weight"
  // mechanism as the curve case, cross-checked independently here:
  // (1, 0, 5) / 4 = (0.25, 0, 1.25).
  surface.SetWeightAt(1, 0, 4.0);
  const Point3d after_weight = surface.ControlPointAt(1, 0);
  Check(std::abs(after_weight.x - 0.25) < 1e-12 && std::abs(after_weight.z - 1.25) < 1e-12,
        "ControlPointAt(1, 0) after SetWeightAt(1, 0, 4.0) is exactly the original point divided "
        "by the new weight, (0.25, 0, 1.25)");

  const Result set_result = surface.SetControlPointAt(1, 0, Point3d(9, 9, 9));
  Check(set_result == Result::Ok, "SetControlPointAt returns Ok when it changes the position");
  Check(surface.WeightAt(1, 0) == 1.0, "SetControlPointAt resets the weight to 1.0 as documented");
  Check(surface.ControlPointAt(1, 0) == Point3d(9, 9, 9),
        "ControlPointAt(1, 0) after SetControlPointAt is exactly the new point, undivided");

  bool get_threw = false;
  try {
    surface.ControlPointAt(99, 99);
  } catch (const std::out_of_range&) {
    get_threw = true;
  }
  Check(get_threw, "ControlPointAt throws std::out_of_range on an out-of-range (i, j)");
}

void TestSurfaceWeightAt() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Non-rational: every weight is exactly 1.0.
  const std::vector<Point3d> flat_grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface flat = NurbsSurface::FromControlGrid(flat_grid, 2, 2, 1, 1);
  Check(flat.WeightAt(0, 0) == 1.0 && flat.WeightAt(1, 1) == 1.0,
        "a non-rational surface's control points all have weight exactly 1.0");

  // A genuine sphere's NURBS form (9 x 5 control points) has a weight
  // grid that's exactly the tensor product of the same alternating
  // 1.0/sqrt(2)/2 pattern `TestCurveWeightAt()`'s circle uses in each
  // direction independently - confirmed by a debug run printing the
  // full 9x5 grid before finalizing, not assumed from the circle result
  // alone (a sphere's u and v isocurves are each circles, but the
  // *tensor-product* weight relationship is a real fact about
  // `ON_Sphere::GetNurbForm()`'s construction, not a given).
  const ON_Sphere on_sphere(ON_3dPoint(1, -2, 0.5), 3.0);
  ON_NurbsSurface sphere_surface;
  Check(on_sphere.GetNurbForm(sphere_surface) != 0, "ON_Sphere::GetNurbForm succeeds");
  NurbsSurface sphere;
  sphere.raw() = sphere_surface;
  Check(sphere.CVCountU() == 9 && sphere.CVCountV() == 5,
        "the sphere's NURBS form has exactly a 9x5 control grid");
  const double sqrt2_over_2 = std::sqrt(2.0) / 2.0;
  bool weights_match = true;
  for (int i = 0; i < sphere.CVCountU(); ++i) {
    const double u_weight = (i % 2 == 0) ? 1.0 : sqrt2_over_2;
    for (int j = 0; j < sphere.CVCountV(); ++j) {
      const double v_weight = (j % 2 == 0) ? 1.0 : sqrt2_over_2;
      if (std::abs(sphere.WeightAt(i, j) - u_weight * v_weight) > 1e-9) {
        weights_match = false;
      }
    }
  }
  Check(weights_match,
        "the sphere's weight grid is exactly the tensor product of the u and v alternating "
        "1.0/sqrt(2)/2 weight patterns");
}

void TestSurfaceIsRational() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Same reasoning as `TestCurveIsRational()` above: FromControlGrid()
  // never builds a rational surface, while a genuine sphere's NURBS form
  // needs real per-control-point weights - confirmed by a debug run
  // before finalizing.
  const std::vector<Point3d> flat_grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface flat = NurbsSurface::FromControlGrid(flat_grid, 2, 2, 1, 1);
  Check(!flat.IsRational(), "a FromControlGrid() surface is never rational");

  const ON_Sphere on_sphere(ON_3dPoint(1, -2, 0.5), 3.0);
  ON_NurbsSurface sphere_surface;
  Check(on_sphere.GetNurbForm(sphere_surface) != 0, "ON_Sphere::GetNurbForm succeeds");
  NurbsSurface sphere;
  sphere.raw() = sphere_surface;
  Check(sphere.IsRational(), "a genuine sphere's NURBS form is rational");
}

void TestSurfaceApproximateArea() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Flat 3x2 identity-mapped plane: true area is exactly 6.0, no
  // curvature for the flat-facet tessellation to fall short of - exact
  // at any resolution, confirmed at both a fine (10x10) and coarse (2x2)
  // grid, not just the fine one.
  const std::vector<Point3d> flat_grid = {
      Point3d(0, 0, 0), Point3d(0, 2, 0), Point3d(3, 0, 0), Point3d(3, 2, 0),
  };
  const NurbsSurface flat = NurbsSurface::FromControlGrid(flat_grid, 2, 2, 1, 1);
  Check(std::abs(flat.ApproximateArea(10, 10) - 6.0) < 1e-9,
        "a flat surface's approximate area is exact (6.0) at a fine grid");
  Check(std::abs(flat.ApproximateArea(2, 2) - 6.0) < 1e-9,
        "a flat surface's approximate area is exact (6.0) even at a coarse 2x2 grid");

  // A genuine sphere, true area 4*pi*r^2: the flat-triangle tessellation
  // must understate the true area (confirmed, not assumed, the mirror
  // image of GetApproximateSize()'s own overstating error) and converge
  // toward it as the grid refines - checked as a real inequality between
  // two resolutions plus a tight bound at the finer one, not just "it's
  // roughly right".
  const double radius = 3.0;
  const ON_Sphere on_sphere(ON_3dPoint(0, 0, 0), radius);
  ON_NurbsSurface sphere_surface;
  Check(on_sphere.GetNurbForm(sphere_surface) != 0, "ON_Sphere::GetNurbForm succeeds");
  NurbsSurface sphere;
  sphere.raw() = sphere_surface;
  const double true_area = 4.0 * ON_PI * radius * radius;
  const double coarse_area = sphere.ApproximateArea(20, 20);
  const double fine_area = sphere.ApproximateArea(80, 80);
  Check(coarse_area < true_area && fine_area < true_area,
        "a sphere's approximate area understates the true area at both a coarse and fine grid, "
        "the flat-facet tessellation's real error direction");
  Check(fine_area > coarse_area,
        "the finer grid's approximate area is strictly closer to (larger than) the coarser "
        "grid's, confirming convergence rather than a fluke");
  Check(std::abs(fine_area - true_area) < 0.1,
        "the 80x80 grid's approximate area is within 0.1 of the true 4*pi*r^2 area");

  bool threw = false;
  try {
    flat.ApproximateArea(0, 5);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw, "ApproximateArea throws std::invalid_argument when a division count is below 1");
}

void TestSurfaceCVCount() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Deliberately non-square (5 x 3 control points, degree 2 x 1) so U and
  // V aren't accidentally the same number - a real cross-check that
  // CVCountU()/CVCountV() aren't just returning the same value for both
  // directions by coincidence. Confirmed exact (5 and 3) via a debug run
  // before finalizing, matching what was actually passed to
  // FromControlGrid() and the raw ON_NurbsSurface::CVCount(dir) values.
  std::vector<Point3d> grid;
  for (int i = 0; i < 5; ++i) {
    for (int j = 0; j < 3; ++j) {
      grid.push_back(Point3d(static_cast<double>(i), static_cast<double>(j), 0.0));
    }
  }
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 5, 3, 2, 1);
  Check(surface.CVCountU() == 5, "CVCountU() returns exactly the 5 control points passed in U");
  Check(surface.CVCountV() == 3, "CVCountV() returns exactly the 3 control points passed in V");
  Check(surface.CVCountU() == surface.raw().CVCount(0) &&
            surface.CVCountV() == surface.raw().CVCount(1),
        "CVCountU()/CVCountV() match the underlying ON_NurbsSurface::CVCount(dir) exactly");
}

void TestSurfaceClosestPoint() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Flat P(u,v)=(u,v,0) surface, domain [0,1]x[0,1]. Query point
  // (0.37, 0.62, 5)'s closest point on the plane is exactly its vertical
  // projection (0.37, 0.62, 0), distance 5 - hand-derivable exact,
  // confirmed by a debug run before finalizing (converged to within
  // ~4e-5 of the exact answer, well inside the 1e-3 tolerance used here
  // for the coarser 2D grid search).
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface surface = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  const Point3d p = surface.ClosestPoint(Point3d(0.37, 0.62, 5));
  Check(std::abs(p.x - 0.37) < 1e-3 && std::abs(p.y - 0.62) < 1e-3 && std::abs(p.z) < 1e-3,
        "ClosestPoint returns approximately (0.37, 0.62, 0), the "
        "vertical projection of the query point onto the plane");
  Check(std::abs((p - Point3d(0.37, 0.62, 5)).Length() - 5.0) < 1e-3,
        "the distance from the query point to its closest point is "
        "approximately 5, matching the hand-derivable vertical distance");

  // A query point outside the domain entirely (both u and v beyond
  // [0,1]) has its closest point clamp to the surface's own boundary
  // corner (1,1,0), not extrapolate past the domain - confirmed by the
  // same debug run, not assumed.
  const Point3d p2 = surface.ClosestPoint(Point3d(5, 5, 0));
  Check(std::abs(p2.x - 1.0) < 1e-6 && std::abs(p2.y - 1.0) < 1e-6 && std::abs(p2.z) < 1e-6,
        "a query point far outside the domain clamps to exactly the "
        "surface's own boundary corner (1,1,0), not an extrapolation "
        "past its domain");

  // A genuine sphere (radius 3, centered at the origin) via
  // ON_Sphere::GetNurbForm, queried at a point whose own closest point on
  // the sphere sits just past the surface's own periodic (u) seam - a
  // real, confirmed bug this test locks in the fix for: for a query point
  // q outside a sphere centered at the origin, the true closest point is
  // exactly `radius * q.Normalize()` (independent of the surface's own
  // parametrization/seam entirely - a hand-derivable closed form, not an
  // approximation), so this doesn't depend on knowing the seam's own u/v
  // location. Before the fix, ClosestPointParameter()'s shrinking search
  // window CLAMPED at the domain boundary instead of wrapping across it,
  // so a coarse sample landing exactly on the seam (u=0) could never
  // explore the physically-adjacent region just past the domain's other
  // end - a query a few degrees off the seam silently snapped to the seam
  // point itself instead of converging to the true answer. Query point at
  // longitude -8 degrees from the seam, radius 5 from center (well
  // outside the sphere): confirmed by a debug run to fall in the
  // previously-broken range.
  const double sphere_radius = 3.0;
  const ON_Sphere on_sphere_for_closest(ON_3dPoint(0, 0, 0), sphere_radius);
  ON_NurbsSurface sphere_surface_for_closest;
  Check(on_sphere_for_closest.GetNurbForm(sphere_surface_for_closest) != 0,
        "ON_Sphere::GetNurbForm succeeds");
  NurbsSurface sphere_for_closest;
  sphere_for_closest.raw() = sphere_surface_for_closest;
  const double angle = -8.0 * ON_PI / 180.0;
  const double query_radius = 5.0;
  const Point3d query(query_radius * std::cos(angle), query_radius * std::sin(angle), 0.0);
  const Point3d expected(sphere_radius * std::cos(angle), sphere_radius * std::sin(angle), 0.0);
  const Point3d p3 = sphere_for_closest.ClosestPoint(query);
  Check((p3 - expected).Length() < 1e-2,
        "ClosestPoint on a sphere near its own periodic seam converges to "
        "the hand-derivable exact answer (radius * query direction), not "
        "the seam point itself");
}

// A real, confirmed bug found by randomized fuzzing against an independent
// brute-force reference: ClosestPointParameter()'s per-level window (the
// search range the NEXT refinement level scans) narrows to best +/- one
// grid cell of THIS level, using `(u_hi - u_lo) / u_divisions` - i.e. the
// SAME u_divisions/v_divisions the caller passed for sampling density. That
// couples the window's cross-level "drift budget" (how far it can move
// from wherever the very first, coarsest-relative-to-the-full-domain level
// happened to land) to 1/divisions, so passing a FINER grid - which should
// only ever help - can instead leave the window unable to travel far
// enough to reach a true minimum sitting more than a few of its own (now
// much smaller) grid cells away from that first sample. Confirmed via a
// hand-instrumented trace (dumping best_u/best_v/window bounds at every
// level) on this exact surface+query: both a 24x24 and a 100x100 run land
// their very first level's best sample in the SAME basin (u in [0.29,
// 0.30], v=1), but 24x24's much wider per-level step lets it walk from
// u~0.29 down to the true nearby optimum at u~0.246 (distance ~893.39)
// within the fixed 8 refinement levels, while 100x100's much narrower step
// only reaches u~0.290 (distance ~908.57) - the opposite of the expected
// finer-is-better-or-equal trend, not just an unlucky pick of a different,
// worse local minimum (this is the SAME basin, arrived at less
// completely). Fixed by capping the divisor used for the window-narrowing
// step (not the sampling density, which keeps benefiting fully from a
// larger u_divisions/v_divisions) so the drift budget never gets worse
// than this method's own default (20x20) provides. Verified via a
// stash-based before/after: fails (908.57 vs 893.39, gap ~15.2) on the
// pre-fix code, passes (~895.2 vs ~893.39, gap ~1.8 - the ordinary
// residual noise any finite multi-level grid search has, already covered
// by this method's own "not a guaranteed global minimum" doc comment) on
// the fix.
void TestSurfaceClosestPointFinerGridNotWorseThanCoarser() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  constexpr int kDegU = 1, kDegV = 3, kCvU = 6, kCvV = 8;
  const double kKnotsU[kCvU + kDegU - 1] = {0, 0.16375993954552437, 0.8712146450345144, 0.88836447635676197,
                                             0.97739768666491145, 1};
  const double kKnotsV[kCvV + kDegV - 1] = {0,
                                             0,
                                             0,
                                             0.46349031362127513,
                                             0.46642385788116175,
                                             0.5478672675887597,
                                             0.97460768787465912,
                                             1,
                                             1,
                                             1};
  // Control points, row-major u-fastest (dumped from the exact fuzzed
  // surface that reproduced the bug).
  const double kCvs[kCvU * kCvV][3] = {
      {-1275.5014096421548, 1476.2458531541276, 786.45586609157658},
      {500.02412185403068, -1387.6312611617536, 1002.5707287152434},
      {205.28156051407768, -1340.8279845419443, 1014.8190084864184},
      {1302.9143343176604, 61.360849633582347, 679.23119982726507},
      {-262.98997383546953, -1115.8554912798843, 923.76275166296159},
      {-1229.6249972217199, -278.98431249360578, 21.763030897905765},
      {584.06021397397103, -150.94200394564928, -934.62265131931701},
      {-96.681654535167127, -272.77795538424266, -1412.8974139500594},
      {-1466.6522302351996, 930.0100971953218, 894.56290524207793},
      {-436.32780613989803, 541.02399455025966, -1221.9053378125343},
      {-746.28401729019822, 786.25619099688424, 1423.0243600014685},
      {-842.02027670601933, 234.08759694076798, -1235.4232348465482},
      {468.20877813596849, -633.23101322871935, 271.77716590942441},
      {-1271.5115905814826, -1233.0003695570715, -985.9535194759809},
      {1408.3592043241836, 1179.0212805649087, -825.56643015005068},
      {-522.21445993647546, 454.93903642969462, -572.94531359665734},
      {901.63612822668915, -1268.8704321762098, -832.66287990016451},
      {280.22611584374818, 1345.5066380304936, 55.028217177012266},
      {1209.494317964042, 565.99221075463197, 804.87320200621139},
      {-889.98761636293898, -1309.0189606838276, -29.878281241650484},
      {109.88921122120723, -1152.6632253340629, -972.35468108816781},
      {-316.25456178466357, 783.07108419756901, -1416.219711933056},
      {-1423.6185928750533, 183.78151041651927, 1476.082116362775},
      {-831.98395857956825, 1235.3907118370992, 558.49515702875055},
      {1094.585597577098, -190.32725255855439, -1409.3587087960957},
      {733.01532616895724, 526.47758044156785, -508.27413596091537},
      {685.08798794408608, 1266.4427000126082, 1070.2197243410967},
      {-1105.8811855183073, -1240.8137865554916, 878.69547336272058},
      {955.99191678631246, -740.96822884391611, 1287.8104219303343},
      {1367.1450169371353, -517.43246602811007, 387.97439745145675},
      {-558.75675145318905, 194.71557004896317, 146.74477622758104},
      {-153.4879474763834, 1139.3968701316001, -313.95508085496044},
      {-169.25857427498363, -1520.3047602968193, -1188.9510301361584},
      {-1495.6428144293939, -329.52202497580765, 651.82804415346232},
      {47.533688510964794, -893.37711621591461, -1149.5569969053922},
      {931.86095304560808, 1293.6732528522709, 987.51883317918077},
      {-408.58722569153542, 937.0672945109261, -1066.421396566639},
      {590.37806465230165, -1116.8414232387249, 1126.6003362668037},
      {-675.07445255110349, -229.99478786535838, 686.08150210696954},
      {276.46549401547873, 310.27503634759796, -939.53546537043007},
      {-1023.0502256973793, 190.9370882148437, -451.04875140490458},
      {-783.60736417951193, 719.84658280172403, 264.11605912803179},
      {-1298.4072079749114, -1478.6888511464351, -1.5265976432572188},
      {1268.0596413097539, 722.18728546851048, -1517.6825039895925},
      {459.00911282331344, 1383.2857883666236, 1424.382637124723},
      {926.48748252130531, -14.95874617045024, 1150.1734037832009},
      {-1302.7626364415794, 1097.6518405063046, -787.4158668430191},
      {-102.96386915832363, -1.5057176929615252, 646.75030107233783},
  };

  ON_NurbsSurface raw;
  Check(raw.Create(3, /*is_rat=*/false, kDegU + 1, kDegV + 1, kCvU, kCvV),
        "ON_NurbsSurface::Create succeeds for the reproduced bug's degree/CV counts");
  for (int i = 0; i < kCvU + kDegU - 1; ++i) raw.SetKnot(0, i, kKnotsU[i]);
  for (int i = 0; i < kCvV + kDegV - 1; ++i) raw.SetKnot(1, i, kKnotsV[i]);
  for (int j = 0; j < kCvV; ++j) {
    for (int i = 0; i < kCvU; ++i) {
      const double* cv = kCvs[static_cast<size_t>(j) * kCvU + i];
      raw.SetCV(i, j, ON_3dPoint(cv[0], cv[1], cv[2]));
    }
  }
  NurbsSurface surface;
  surface.raw() = raw;

  const Point3d query(1937.233924, 541.1802437, -636.9584755);
  const Point3d coarse = surface.ClosestPoint(query, 24, 24);
  const Point3d fine = surface.ClosestPoint(query, 100, 100);
  const double d_coarse = (coarse - query).Length();
  const double d_fine = (fine - query).Length();

  Check(d_coarse < 894.0, "sanity: the 24x24 grid still finds ~893.39, matching the debug trace this test's own "
                          "comment cites (regression-guards the reference case itself, not just the fix)");
  Check(d_fine <= d_coarse + 5.0,
        "a 100x100 (finer) grid does not converge to a meaningfully WORSE "
        "closest point than a 24x24 (coarser) grid on the same surface and "
        "query - before the fix this gap was ~15.2 (908.57 vs 893.39); the "
        "small residual gap left after the fix (~1.8) is ordinary "
        "multi-level-grid-search noise, not this bug");
}

void TestSurfaceClosestPointGlobalReportsConvergenceFailure() {
  using dino8::kernel::Point3d;
  using dino8::kernel::SurfaceClosestPointGlobal;

  // SurfaceClosestPointGlobal() (surface_intersect.h) grid-seeds a Newton
  // polish and is documented to report the SAME convergence status as
  // SurfaceClosestPoint() - a real, previously-undetected bug had it
  // hardcode `return true;` regardless of whether the Newton polish
  // actually converged, silently discarding a genuine failure signal that
  // dino8-app's own commands (SrfSeam, SetSurfaceTangent, SoftEditSrf,
  // several FilletEdge pick-location paths) rely on via `if (!...) { Warn
  // ...; return; }` - those warnings could never fire.
  //
  // This fixture is a real (not synthetic/mocked) rational bicubic NURBS
  // surface with deliberately wild per-control-point weights, found by a
  // randomized probe search (fixed seed 12345, trial 6 of 200000) for a
  // surface+query pair where SurfaceClosestPoint's Newton polish
  // genuinely fails to converge within its default iteration budget -
  // confirmed directly by running the probe standalone against this
  // kernel's own SurfaceClosestPoint(), not assumed. Hardcoded here as
  // exact literal control points/weights so the regression is
  // deterministic and doesn't depend on RNG reproducibility across builds.
  ON_NurbsSurface wild;
  wild.Create(3, /*is_rational=*/true, 4, 4, 4, 4);
  const double cvs[4][4][4] = {
      {{0.713110, 3.048754, 3.493440, 1.621991},
       {-3.202335, 2.076466, 2.549767, 0.575890},
       {3.557721, 4.121677, 3.246089, 4.262293},
       {-2.649201, -4.605644, -1.623153, 1.114224}},
      {{3.599308, -0.612792, -2.225644, 0.668116},
       {1.952605, 4.652838, 4.875471, 1.648461},
       {0.288541, 2.854566, -4.638695, 3.367891},
       {1.453576, -4.600227, -0.736331, 3.381067}},
      {{-2.741354, 2.037432, 2.049326, 2.864950},
       {4.531246, -2.945309, -3.818924, 4.924178},
       {-3.961690, 4.303003, -1.612021, 4.676180},
       {1.078011, 1.232005, -0.587598, 0.673231}},
      {{4.582039, -3.509195, -1.671194, 0.891587},
       {-1.277548, -0.393197, -3.829403, 0.369822},
       {-4.423599, -3.659467, 0.799879, 4.762362},
       {1.602534, -0.952616, 2.106731, 3.293129}},
  };
  for (int u = 0; u < 4; ++u) {
    for (int v = 0; v < 4; ++v) {
      wild.SetCV(u, v, ON_4dPoint(cvs[u][v][0], cvs[u][v][1], cvs[u][v][2], cvs[u][v][3]));
    }
  }
  wild.MakeClampedUniformKnotVector(0);
  wild.MakeClampedUniformKnotVector(1);

  double u = 0, v = 0;
  const Point3d query(4.551276, 4.883771, 3.446433);
  const bool ok = SurfaceClosestPointGlobal(wild, query, u, v);
  Check(!ok,
        "SurfaceClosestPointGlobal reports false (Newton did not converge) "
        "for a genuinely pathological rational surface - not hardcoded "
        "true regardless of the underlying refinement's real outcome");
}

// Regression test for a real, reproduced NurbsSurface::ClosestPointParameter()
// bug: single-seed window narrowing could lock onto a genuinely WRONG, worse
// local minimum on a surface with two separated local-minimum basins of
// different depth, even though the very same level-0 grid scan also sampled
// points inside the TRUE (deeper) global minimum's basin.
//
// The surface below is a flat-in-v extrusion (v is a trivial degree-1
// direction, so PointAt(u, v) = (x(u), v, z(u)) exactly) of a u-profile with
// two notches: a shallow one near u=0.30 - deliberately placed almost exactly
// on a 20x20 grid node, so its sampled distance to the query is very close to
// its true minimum - and a deeper one near u=0.675, deliberately placed
// almost exactly BETWEEN two 20x20 grid nodes (0.65 and 0.70), so every
// sampled distance near it is well short of its true minimum. Confirmed
// directly (not assumed) that before the fix, single-seed
// ClosestPointParameter's one grid-wide best cell landed in the shallow
// notch (whose near-perfect grid alignment made its raw sample look better)
// and converged there (dist ~0.353), never exploring the deeper notch's own
// basin at all even though the SAME level-0 scan had samples inside it -
// while the true closest point (~0.184 away, verified by dense brute-force
// sampling) sits in that deeper notch. Trying more than the single
// grid-wide-best cell as a seed - one seed per distinct local minimum the
// level-0 scan already found, refined independently, keeping the overall
// best - fixes it.
void TestSurfaceClosestPointMultistartFindsGlobalMinimum() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  constexpr int kOrder = 4, kCvCount = 11;
  const double kKnots[kCvCount + kOrder - 2] = {0,
                                                 0,
                                                 0,
                                                 0.23999999999999999,
                                                 0.30000000000000004,
                                                 0.37666666666666665,
                                                 0.4916666666666667,
                                                 0.60666666666666669,
                                                 0.67499999999999993,
                                                 0.74333333333333329,
                                                 1,
                                                 1,
                                                 1};
  // (x, z) pairs - a cubic interpolant through a shallow notch near x=0.30
  // and a deeper one near x=0.675, dumped from the exact surface that
  // reproduced the bug.
  const double kCvs[kCvCount][2] = {
      {0, 5},
      {0.079999999999999474, -85.092496077419469},
      {0.18000000000000049, 84.33481447535118},
      {0.30555555555555536, -27.618877221308598},
      {0.38944444444444498, 66.353495826834802},
      {0.49166666666666597, -30.854543071131459},
      {0.59111111111111236, 58.909966241984613},
      {0.67499999999999916, -29.390527790264844},
      {0.80611111111111378, 107.63581955454389},
      {0.91444444444444162, -94.713128835653691},
      {1, 5},
  };

  ON_NurbsSurface raw;
  Check(raw.Create(3, /*is_rat=*/false, kOrder, 2, kCvCount, 2),
        "ON_NurbsSurface::Create succeeds for the reproduced bug's degree/CV counts");
  for (int i = 0; i < kCvCount + kOrder - 2; ++i) raw.SetKnot(0, i, kKnots[i]);
  raw.MakeClampedUniformKnotVector(1);
  for (int i = 0; i < kCvCount; ++i) {
    raw.SetCV(i, 0, ON_3dPoint(kCvs[i][0], 0.0, kCvs[i][1]));
    raw.SetCV(i, 1, ON_3dPoint(kCvs[i][0], 1.0, kCvs[i][1]));
  }
  NurbsSurface surface;
  surface.raw() = raw;

  const Point3d query(0.4875, 0.5, -5.3);
  const Point3d closest = surface.ClosestPoint(query);
  const double dist = (closest - query).Length();

  Check(dist < 0.25,
        "NurbsSurface::ClosestPoint (default 20x20 divisions) finds the "
        "true, deeper global minimum (~0.184 away) instead of locking onto "
        "the shallower decoy notch's own local minimum (~0.353 away) that "
        "single-seed window narrowing used to converge to");
}

void TestSurfaceCurvature() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // Flat plane: zero curvature everywhere - hand-derivable exact.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 1, 0),
      Point3d(1, 0, 0),
      Point3d(1, 1, 0),
  };
  const NurbsSurface plane = NurbsSurface::FromControlGrid(grid, 2, 2, 1, 1);
  const auto plane_k = plane.CurvatureAt(0.5, 0.5);
  Check(std::abs(plane_k.gaussian) < 1e-9 && std::abs(plane_k.mean) < 1e-9 &&
            std::abs(plane_k.k1) < 1e-9 && std::abs(plane_k.k2) < 1e-9,
        "a flat plane's curvature (gaussian, mean, k1, k2) is exactly "
        "zero everywhere");

  // Sphere of known radius, via ON_Sphere::GetNurbForm (the same real
  // construction Brep::Sphere() uses). Every point on a sphere is an
  // umbilic (k1 == k2), so this is hand-derivable exact: Gaussian
  // curvature is exactly 1/radius^2 (sign-unambiguous - a product of two
  // curvatures with the same sign convention, so signs cancel), and mean
  // curvature and both principal curvatures are exactly -1/radius given
  // this surface's outward-pointing normal - confirmed by a debug run
  // before finalizing these assertions, not assumed from the formula's
  // sign in the abstract.
  const double radius = 3.0;
  const ON_Sphere on_sphere(ON_3dPoint(0, 0, 0), radius);
  ON_NurbsSurface nurbs_form;
  Check(on_sphere.GetNurbForm(nurbs_form) != 0, "ON_Sphere::GetNurbForm succeeds");
  NurbsSurface sphere;
  sphere.raw() = nurbs_form;
  const ON_Interval u_domain = sphere.raw().Domain(0);
  const ON_Interval v_domain = sphere.raw().Domain(1);

  bool all_gaussian_exact = true;
  bool all_mean_exact = true;
  bool all_umbilic = true;
  for (double u_frac : {0.25, 0.5, 0.75}) {
    for (double v_frac : {0.25, 0.5, 0.75}) {
      const double u = u_domain.ParameterAt(u_frac);
      const double v = v_domain.ParameterAt(v_frac);
      const auto k = sphere.CurvatureAt(u, v);
      if (std::abs(k.gaussian - 1.0 / (radius * radius)) > 1e-6) {
        all_gaussian_exact = false;
      }
      if (std::abs(k.mean - (-1.0 / radius)) > 1e-6) {
        all_mean_exact = false;
      }
      if (std::abs(k.k1 - k.k2) > 1e-5 || std::abs(k.k1 - (-1.0 / radius)) > 1e-5) {
        all_umbilic = false;
      }
    }
  }
  Check(all_gaussian_exact,
        "a sphere's Gaussian curvature is exactly 1/radius^2 at every "
        "point tested, sign-unambiguous regardless of normal direction");
  Check(all_mean_exact,
        "a sphere's mean curvature is exactly -1/radius at every point "
        "tested, given this surface's outward-pointing normal");
  Check(all_umbilic,
        "every tested point on the sphere is an umbilic (k1 == k2 == "
        "-1/radius), matching the fact that every point on a sphere has "
        "the same curvature in every direction");
}

void TestSurfaceSuggestedDivisions() {
  using dino8::kernel::NurbsSurface;

  // Same cylinder wall as TestSurfaceIsClosed(): U is the circular
  // direction (radius 1), V is the straight height direction. Every
  // U-isocurve is the exact same unit circle regardless of which V it's
  // sampled at (so this is hand-derivable exact, same as
  // TestCurveSuggestedSamples()'s full-circle case), and every
  // V-isocurve is a straight vertical line (zero curvature) - confirmed
  // by a debug run before finalizing these assertions.
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 1.0);
  const ON_Cylinder cylinder(circle, 1.0);
  ON_NurbsSurface cylinder_surface;
  Check(cylinder.GetNurbForm(cylinder_surface) != 0, "ON_Cylinder::GetNurbForm succeeds");
  NurbsSurface wall;
  wall.raw() = cylinder_surface;

  const double chord_tolerance = 0.01;
  const auto divisions = wall.SuggestedDivisions(chord_tolerance);
  const double expected_angle_step = 2.0 * std::acos(1.0 - chord_tolerance / 1.0);
  const int expected_u = static_cast<int>(std::ceil((2.0 * ON_PI) / expected_angle_step));
  Check(divisions.u == expected_u,
        "SuggestedDivisions' U count for the cylinder wall exactly "
        "matches the independently hand-computed chord-height formula "
        "for its unit-radius circular cross-section");
  Check(divisions.v == 1,
        "SuggestedDivisions' V count is exactly 1, since every V-isocurve "
        "is a straight vertical line with zero curvature");

  bool threw = false;
  try {
    wall.SuggestedDivisions(0.0);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw,
        "SuggestedDivisions throws std::invalid_argument on a "
        "non-positive chord_tolerance");
}

void TestSurfaceTessellateGridAdaptive() {
  using dino8::kernel::NurbsSurface;

  // Same cylinder wall as TestSurfaceSuggestedDivisions(). This is a
  // thin, deterministic composition of two already-verified pieces
  // (SuggestedDivisions() then TessellateGrid()), so the test just
  // confirms it actually wires them together rather than using some
  // fixed default: the untrimmed TessellateGrid() path always emits
  // exactly u_divisions * v_divisions * 2 triangles, so if
  // TessellateGridAdaptive() truly used SuggestedDivisions()'s own
  // return values, calling both separately and comparing face counts
  // must agree exactly.
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 1.0);
  const ON_Cylinder cylinder(circle, 1.0);
  ON_NurbsSurface cylinder_surface;
  cylinder.GetNurbForm(cylinder_surface);
  NurbsSurface wall;
  wall.raw() = cylinder_surface;

  const double chord_tolerance = 0.01;
  const auto divisions = wall.SuggestedDivisions(chord_tolerance);
  const auto adaptive_mesh = wall.TessellateGridAdaptive(chord_tolerance);
  Check(adaptive_mesh.FaceCount() == divisions.u * divisions.v * 2,
        "TessellateGridAdaptive's own face count exactly matches "
        "u_divisions * v_divisions * 2 for the same SuggestedDivisions() "
        "result computed independently");

  const auto manual_mesh = wall.TessellateGrid(divisions.u, divisions.v);
  Check(adaptive_mesh.VertexCount() == manual_mesh.VertexCount() &&
            std::abs(adaptive_mesh.Area() - manual_mesh.Area()) < 1e-9,
        "TessellateGridAdaptive produces the exact same mesh as calling "
        "SuggestedDivisions() then TessellateGrid() by hand");
}

void TestSurfaceTessellateGridClippedExactAdaptive() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point2d;
  using dino8::kernel::Point3d;

  // Same 10x10 flat surface and [0.15,0.85]^2 trim
  // TestExactClippingMatchesAreaButNotCellCounts uses - true trim area is
  // exactly (0.85-0.15)^2 * 100 = 49, independent of tessellation
  // resolution since exact clipping measures the real boundary rather
  // than approximating it with the grid. This is a thin, deterministic
  // composition of two already-verified pieces (SuggestedDivisions()
  // then TessellateGridClippedExact()), so the test confirms both that
  // it wires them together (matches the manual two-call equivalent
  // exactly) and that the result is still the true trim area regardless
  // of which divisions SuggestedDivisions() happens to pick for a flat
  // surface with zero curvature.
  const std::vector<Point3d> grid = {
      Point3d(0, 0, 0),
      Point3d(0, 10, 0),
      Point3d(10, 0, 0),
      Point3d(10, 10, 0),
  };
  const NurbsSurface surface =
      NurbsSurface::FromControlGrid(grid, 2, 2, /*u_degree=*/1, /*v_degree=*/1);
  const std::vector<Point2d> trim_loop = {
      Point2d(0.15, 0.15),
      Point2d(0.85, 0.15),
      Point2d(0.85, 0.85),
      Point2d(0.15, 0.85),
  };

  const double chord_tolerance = 0.05;
  const auto adaptive_mesh = surface.TessellateGridClippedExactAdaptive(chord_tolerance, trim_loop);
  Check(std::abs(adaptive_mesh.Area() - 49.0) < 1e-9,
        "TessellateGridClippedExactAdaptive's own area is exactly 49, "
        "the true trim area, regardless of which divisions "
        "SuggestedDivisions() picked for this flat (zero-curvature) "
        "surface");

  const auto divisions = surface.SuggestedDivisions(chord_tolerance);
  const auto manual_mesh = surface.TessellateGridClippedExact(divisions.u, divisions.v, trim_loop);
  Check(adaptive_mesh.VertexCount() == manual_mesh.VertexCount() &&
            adaptive_mesh.FaceCount() == manual_mesh.FaceCount(),
        "TessellateGridClippedExactAdaptive produces the exact same mesh "
        "as calling SuggestedDivisions() then TessellateGridClippedExact() "
        "by hand");
}

void TestSurfaceSuggestedDivisionsByAngle() {
  using dino8::kernel::NurbsSurface;

  // Same cylinder wall as TestSurfaceSuggestedDivisions(): U is the
  // circular direction (unit radius), V is the straight height direction
  // (zero curvature). U's expected count is now the angle-based
  // NurbsCurve::SuggestedSamplesByAngle() formula directly
  // (ceil(2*pi / angle_tolerance)), not the chord-height one.
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 1.0);
  const ON_Cylinder cylinder(circle, 1.0);
  ON_NurbsSurface cylinder_surface;
  Check(cylinder.GetNurbForm(cylinder_surface) != 0, "ON_Cylinder::GetNurbForm succeeds");
  NurbsSurface wall;
  wall.raw() = cylinder_surface;

  const double angle_tolerance = 0.1;
  const auto divisions = wall.SuggestedDivisionsByAngle(angle_tolerance);
  const int expected_u = static_cast<int>(std::ceil((2.0 * ON_PI) / angle_tolerance));
  Check(divisions.u == expected_u,
        "SuggestedDivisionsByAngle's U count for the cylinder wall exactly "
        "matches ceil(2*pi / angle_tolerance) for its unit-radius circular "
        "cross-section");
  Check(divisions.v == 1,
        "SuggestedDivisionsByAngle's V count is exactly 1, since every "
        "V-isocurve is a straight vertical line with zero curvature");

  bool threw_low = false;
  try {
    wall.SuggestedDivisionsByAngle(0.0);
  } catch (const std::invalid_argument&) {
    threw_low = true;
  }
  Check(threw_low,
        "SuggestedDivisionsByAngle throws std::invalid_argument on a "
        "non-positive angle_tolerance");

  bool threw_high = false;
  try {
    wall.SuggestedDivisionsByAngle(ON_PI + 0.01);
  } catch (const std::invalid_argument&) {
    threw_high = true;
  }
  Check(threw_high,
        "SuggestedDivisionsByAngle throws std::invalid_argument on an "
        "angle_tolerance greater than pi");
}

void TestSurfaceTessellateGridAdaptiveByAngle() {
  using dino8::kernel::NurbsSurface;

  // Same cylinder wall. Thin composition test, same shape as
  // TestSurfaceTessellateGridAdaptive(): confirms TessellateGridAdaptiveByAngle()
  // truly wires SuggestedDivisionsByAngle() into TessellateGrid(), rather
  // than using some fixed default.
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 1.0);
  const ON_Cylinder cylinder(circle, 1.0);
  ON_NurbsSurface cylinder_surface;
  cylinder.GetNurbForm(cylinder_surface);
  NurbsSurface wall;
  wall.raw() = cylinder_surface;

  const double angle_tolerance = 0.1;
  const auto divisions = wall.SuggestedDivisionsByAngle(angle_tolerance);
  const auto adaptive_mesh = wall.TessellateGridAdaptiveByAngle(angle_tolerance);
  Check(adaptive_mesh.FaceCount() == divisions.u * divisions.v * 2,
        "TessellateGridAdaptiveByAngle's own face count exactly matches "
        "u_divisions * v_divisions * 2 for the same SuggestedDivisionsByAngle() "
        "result computed independently");

  const auto manual_mesh = wall.TessellateGrid(divisions.u, divisions.v);
  Check(adaptive_mesh.VertexCount() == manual_mesh.VertexCount() &&
            std::abs(adaptive_mesh.Area() - manual_mesh.Area()) < 1e-9,
        "TessellateGridAdaptiveByAngle produces the exact same mesh as "
        "calling SuggestedDivisionsByAngle() then TessellateGrid() by hand");

  // The genuine point of an angular (rather than chord-height) knob: a
  // tighter angle_tolerance must produce meaningfully more divisions for a
  // curved surface, the same monotonic relationship the chord-based knob
  // already guarantees, just driven by a different physical quantity.
  const auto loose_divisions = wall.SuggestedDivisionsByAngle(0.5);
  const auto tight_divisions = wall.SuggestedDivisionsByAngle(0.01);
  Check(tight_divisions.u > loose_divisions.u * 10,
        "a tighter angle_tolerance produces substantially more U "
        "divisions for the cylinder wall's genuinely curved cross-section");
}

void TestSurfaceMeasureGridTessellationDeviation() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  // A flat surface's own grid tessellation exactly reproduces every point
  // on it (a planar quad's bilinear interpolation IS the true surface),
  // so the measured deviation must be exactly 0 regardless of resolution -
  // the one case with a hand-derivable exact expected answer.
  const std::vector<Point3d> flat_grid = {
      Point3d(0, 0, 0),
      Point3d(0, 10, 0),
      Point3d(10, 0, 0),
      Point3d(10, 10, 0),
  };
  const NurbsSurface flat =
      NurbsSurface::FromControlGrid(flat_grid, 2, 2, /*u_degree=*/1, /*v_degree=*/1);
  Check(flat.MeasureGridTessellationDeviation(3, 3) < 1e-12,
        "MeasureGridTessellationDeviation is exactly 0 for a flat surface "
        "at any resolution - a planar facet never deviates from its own "
        "bilinear source");

  // A genuinely curved surface (the same unit-radius cylinder wall used
  // above) must show real, measurable, nonzero deviation at a coarse
  // resolution, and that deviation must shrink substantially as the
  // resolution tied to it via SuggestedDivisions(chord_tolerance) is
  // tightened - the real cross-check that this measurement function and
  // the existing chord_tolerance machinery agree on what "deviation"
  // means, not two unrelated numbers that happen to both be called
  // tolerances.
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 1.0);
  const ON_Cylinder cylinder(circle, 1.0);
  ON_NurbsSurface cylinder_surface;
  cylinder.GetNurbForm(cylinder_surface);
  NurbsSurface wall;
  wall.raw() = cylinder_surface;

  // At 4 divisions (90 degrees per facet), the true circular sagitta is
  // 1 - cos(45deg) ~= 0.292893 - and since the interior sample points
  // cluster near each triangle's own centroid (close to, but not exactly
  // on, the arc's true angular midpoint), the measured value should land
  // very close to that analytic figure without being asserted to match it
  // exactly. Confirmed directly via a standalone probe
  // (dino8_scratch_test) before finalizing this bound: measured 0.292839,
  // within 0.02% of the analytic 0.292893.
  const double coarse_deviation = wall.MeasureGridTessellationDeviation(4, 1);
  const double expected_sagitta = 1.0 - std::cos(ON_PI / 4.0);
  Check(std::abs(coarse_deviation - expected_sagitta) < 0.001,
        "MeasureGridTessellationDeviation at 4 divisions matches the "
        "analytic circular sagitta (1 - cos(45deg)) to within 0.001");

  // A genuine, honest finding from this same probe: the measured facet
  // deviation at SuggestedDivisions(chord_tolerance)'s own resolution
  // consistently runs SOMEWHAT ABOVE chord_tolerance itself (measured
  // ratios 1.03-1.09 across 0.1/0.01/0.001, confirmed via
  // dino8_scratch_test before finalizing this bound) - not a bug in
  // either function, but a real, previously-unmeasured gap between the
  // single-direction, per-isocurve sagitta estimate SuggestedDivisions()
  // makes and the true, full facet deviation this function measures
  // directly against the diagonal-triangulated 2D grid (whose worst
  // interior point can fall slightly off the pure-u arc midpoint the 1D
  // estimate assumes). Asserted with real headroom (1.5x, comfortably
  // above every observed ratio) rather than tuned to just barely pass.
  for (const double chord_tolerance : {0.1, 0.01, 0.001}) {
    const auto divisions = wall.SuggestedDivisions(chord_tolerance);
    const double measured = wall.MeasureGridTessellationDeviation(divisions.u, divisions.v);
    Check(measured <= chord_tolerance * 1.5,
          "the measured deviation at SuggestedDivisions(chord_tolerance)'s "
          "own resolution stays within 1.5x the chord_tolerance it was "
          "asked to respect - real headroom over the observed ~1.03-1.09x "
          "gap between the two, not a tight certified bound");
  }

  bool threw = false;
  try {
    flat.MeasureGridTessellationDeviation(0, 1);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw,
        "MeasureGridTessellationDeviation throws std::invalid_argument "
        "when either division count is less than 1");
}

void TestBrepTessellateAdaptive() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;

  // Box(): every face is flat (zero curvature everywhere), so
  // SuggestedDivisions() should pick the minimum 1x1 division for every
  // face regardless of chord_tolerance - exactly 6 face meshes, 12
  // triangles total (2 per face), and the closed, welded volume exactly
  // 8.0 (a 2x2x2 box) - hand-derivable exact, confirmed by a debug run
  // before finalizing these assertions.
  const Brep box = Brep::Box(0, 0, 0, 2, 2, 2);
  const auto box_faces = box.TessellateAdaptive(0.01);
  int box_total_faces = 0;
  for (const auto& m : box_faces) {
    box_total_faces += m.FaceCount();
  }
  Check(box_faces.size() == 6, "TessellateAdaptive returns one mesh per Box() face (6)");
  Check(box_total_faces == 12,
        "each flat Box() face needs only the minimum 1x1 division "
        "(2 triangles) regardless of chord_tolerance, 12 triangles total");
  const Mesh box_closed = box.TessellateToClosedMeshAdaptive(0.01);
  Check(std::abs(box_closed.Volume() - 8.0) < 1e-9,
        "TessellateToClosedMeshAdaptive's own volume is exactly 8.0 for "
        "a 2x2x2 box");

  // Sphere(): real curvature everywhere, so a tighter chord_tolerance
  // must produce meaningfully more triangles and a volume meaningfully
  // closer to the true analytic value than a loose one - this is the
  // actual point of curvature-based adaptation, not just "it runs
  // without crashing". Confirmed by a debug run: loose (0.5) tolerance
  // gave 36 faces / volume ~70 (far from the true ~113.1), tight (0.01)
  // gave 1520 faces / volume ~111.9 (within ~1% of true) - a real,
  // substantial improvement, not a coincidence of rounding.
  const double radius = 3.0;
  const Brep sphere = Brep::Sphere(Point3d(0, 0, 0), radius);
  const Mesh loose_sphere = sphere.TessellateToClosedMeshAdaptive(0.5);
  const Mesh tight_sphere = sphere.TessellateToClosedMeshAdaptive(0.01);
  const double expected_volume = (4.0 / 3.0) * ON_PI * radius * radius * radius;
  Check(tight_sphere.FaceCount() > loose_sphere.FaceCount() * 10,
        "a tighter chord_tolerance produces substantially more triangles "
        "for a genuinely curved surface");
  Check(std::abs(tight_sphere.Volume() - expected_volume) <
            std::abs(loose_sphere.Volume() - expected_volume),
        "the tighter chord_tolerance's volume is meaningfully closer to "
        "the true analytic sphere volume than the loose one's");
  Check(std::abs(tight_sphere.Volume() - expected_volume) / expected_volume < 0.02,
        "the tight-tolerance sphere's volume is within 2% of the true "
        "analytic value (4/3 * pi * r^3)");
}

void TestBrepTessellateAdaptiveByAngle() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;

  // Box(): every face flat, so SuggestedDivisionsByAngle() picks the
  // minimum 1x1 division for every face regardless of angle_tolerance,
  // same shape as TestBrepTessellateAdaptive()'s own Box() case.
  const Brep box = Brep::Box(0, 0, 0, 2, 2, 2);
  const auto box_faces = box.TessellateAdaptiveByAngle(0.1);
  int box_total_faces = 0;
  for (const auto& m : box_faces) {
    box_total_faces += m.FaceCount();
  }
  Check(box_faces.size() == 6, "TessellateAdaptiveByAngle returns one mesh per Box() face (6)");
  Check(box_total_faces == 12,
        "each flat Box() face needs only the minimum 1x1 division "
        "(2 triangles) regardless of angle_tolerance, 12 triangles total");
  const Mesh box_closed = box.TessellateToClosedMeshAdaptiveByAngle(0.1);
  Check(std::abs(box_closed.Volume() - 8.0) < 1e-9,
        "TessellateToClosedMeshAdaptiveByAngle's own volume is exactly "
        "8.0 for a 2x2x2 box");

  // Sphere(): real curvature everywhere - the genuine point of an angular
  // knob at the whole-Brep level, same "tighter tolerance -> substantially
  // more triangles and a volume meaningfully closer to the true analytic
  // value" relationship TestBrepTessellateAdaptive()'s own sphere case
  // already establishes for chord_tolerance, now driven by angle_tolerance
  // instead.
  const double radius = 3.0;
  const Brep sphere = Brep::Sphere(Point3d(0, 0, 0), radius);
  const Mesh loose_sphere = sphere.TessellateToClosedMeshAdaptiveByAngle(0.5);
  const Mesh tight_sphere = sphere.TessellateToClosedMeshAdaptiveByAngle(0.02);
  const double expected_volume = (4.0 / 3.0) * ON_PI * radius * radius * radius;
  Check(tight_sphere.FaceCount() > loose_sphere.FaceCount() * 10,
        "a tighter angle_tolerance produces substantially more triangles "
        "for a genuinely curved surface");
  Check(std::abs(tight_sphere.Volume() - expected_volume) <
            std::abs(loose_sphere.Volume() - expected_volume),
        "the tighter angle_tolerance's volume is meaningfully closer to "
        "the true analytic sphere volume than the loose one's");
  Check(std::abs(tight_sphere.Volume() - expected_volume) / expected_volume < 0.02,
        "the tight-angle-tolerance sphere's volume is within 2% of the "
        "true analytic value (4/3 * pi * r^3)");
}

void TestBrepTessellateNonUniformAdaptive() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;

  // Box(): every face flat, same exact result as the uniform adaptive
  // path - 6 face meshes, 12 triangles total, exact volume 8.0.
  // Confirmed by a debug run before finalizing.
  const Brep box = Brep::Box(0, 0, 0, 2, 2, 2);
  const auto box_faces = box.TessellateNonUniformAdaptive(0.01);
  int box_total_faces = 0;
  for (const auto& m : box_faces) {
    box_total_faces += m.FaceCount();
  }
  Check(box_faces.size() == 6, "TessellateNonUniformAdaptive returns one mesh per Box() face (6)");
  Check(box_total_faces == 12,
        "each flat Box() face still needs only the minimum division "
        "(12 triangles total) with the non-uniform path too");
  const Mesh box_closed = box.TessellateToClosedMeshNonUniformAdaptive(0.01);
  Check(std::abs(box_closed.Volume() - 8.0) < 1e-9,
        "TessellateToClosedMeshNonUniformAdaptive's own volume is "
        "exactly 8.0 for a 2x2x2 box");

  // Sphere(): real curvature, isotropic in every direction. A genuine,
  // worth-documenting nuance found by testing, not assumed: the
  // recursive-bisection path's power-of-2 segment counts are less
  // efficient than the uniform path's directly-computed count for this
  // *isotropic* case (4096 faces here vs. the uniform adaptive test's
  // own 1520 at the same tolerance) - non-uniform adaptivity pays off
  // when curvature genuinely varies across a face (the cylinder-wall
  // case), not when it's the same everywhere. Still hits the same real
  // accuracy target.
  const double radius = 3.0;
  const Brep sphere = Brep::Sphere(Point3d(0, 0, 0), radius);
  const Mesh tight_sphere = sphere.TessellateToClosedMeshNonUniformAdaptive(0.01);
  const double expected_volume = (4.0 / 3.0) * ON_PI * radius * radius * radius;
  Check(std::abs(tight_sphere.Volume() - expected_volume) / expected_volume < 0.02,
        "the non-uniform adaptive sphere's volume is within 2% of the "
        "true analytic value (4/3 * pi * r^3), the same accuracy target "
        "the uniform adaptive path hits");
}

void TestFileRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::Model;
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  std::vector<Point3d> grid;
  for (int u = 0; u < 3; ++u) {
    for (int v = 0; v < 3; ++v) {
      grid.emplace_back(u, v, (u == 1 && v == 1) ? 1.0 : 0.0);
    }
  }
  NurbsSurface surf = NurbsSurface::FromControlGrid(grid, 3, 3, 2, 2);
  Brep brep = Brep::FromSurface(surf);
  Check(brep.FaceCount() == 1, "brep has one face");

  Model model;
  model.AddBrep(brep);
  Check(model.ObjectCount() == 1, "model has one object before save");

  const std::string path = "dino8_kernel_roundtrip_test.3dm";
  const auto save_result = model.Save(path);
  Check(save_result == dino8::kernel::Result::Ok, ".3dm save succeeded");

  Model loaded;
  const auto load_result = Model::Load(path, loaded);
  Check(load_result == dino8::kernel::Result::Ok, ".3dm load succeeded");
  Check(loaded.ObjectCount() == 1, "round-tripped model has one object");

  std::remove(path.c_str());
}

// Builds a closed, consistently-oriented (CCW from outside) axis-aligned
// box mesh directly - not via NurbsSurface::TessellateGrid, since that
// only tessellates a single open surface, not a closed solid. Booleans
// need actual watertight input.
dino8::kernel::Mesh MakeBox(double x0, double y0, double z0, double x1,
                             double y1, double z1) {
  dino8::kernel::Mesh mesh;
  ON_Mesh& raw = mesh.raw();

  raw.m_V.Append(ON_3fPoint(x0, y0, z0));  // 0
  raw.m_V.Append(ON_3fPoint(x1, y0, z0));  // 1
  raw.m_V.Append(ON_3fPoint(x1, y1, z0));  // 2
  raw.m_V.Append(ON_3fPoint(x0, y1, z0));  // 3
  raw.m_V.Append(ON_3fPoint(x0, y0, z1));  // 4
  raw.m_V.Append(ON_3fPoint(x1, y0, z1));  // 5
  raw.m_V.Append(ON_3fPoint(x1, y1, z1));  // 6
  raw.m_V.Append(ON_3fPoint(x0, y1, z1));  // 7

  auto add_tri = [&raw](int a, int b, int c) {
    ON_MeshFace face;
    face.vi[0] = a;
    face.vi[1] = b;
    face.vi[2] = c;
    face.vi[3] = c;
    raw.m_F.Append(face);
  };

  add_tri(0, 3, 2);
  add_tri(0, 2, 1);  // bottom (-z)
  add_tri(4, 5, 6);
  add_tri(4, 6, 7);  // top (+z)
  add_tri(0, 1, 5);
  add_tri(0, 5, 4);  // front (-y)
  add_tri(3, 7, 6);
  add_tri(3, 6, 2);  // back (+y)
  add_tri(0, 4, 7);
  add_tri(0, 7, 3);  // left (-x)
  add_tri(1, 2, 6);
  add_tri(1, 6, 5);  // right (+x)

  return mesh;
}

// Same box as MakeBox(), but as 6 genuine quad faces rather than 12
// triangles - each quad below is the same pair of MakeBox() triangles
// merged along their shared diagonal (e.g. bottom's (0,3,2)+(0,2,1)
// becomes the quad 0,3,2,1), so it has the identical outward-normal
// winding, just needed for SubD tests: Catmull-Clark subdivision's
// vertex/face-count growth has a clean, hand-derivable formula on an
// all-quad control net (V_new = V+E+F, F_new = 4x once every face is a
// quad), which a triangulated box wouldn't give.
dino8::kernel::Mesh MakeQuadBoxMesh(double x0, double y0, double z0, double x1, double y1,
                                     double z1) {
  dino8::kernel::Mesh mesh;
  ON_Mesh& raw = mesh.raw();

  raw.m_V.Append(ON_3fPoint(x0, y0, z0));  // 0
  raw.m_V.Append(ON_3fPoint(x1, y0, z0));  // 1
  raw.m_V.Append(ON_3fPoint(x1, y1, z0));  // 2
  raw.m_V.Append(ON_3fPoint(x0, y1, z0));  // 3
  raw.m_V.Append(ON_3fPoint(x0, y0, z1));  // 4
  raw.m_V.Append(ON_3fPoint(x1, y0, z1));  // 5
  raw.m_V.Append(ON_3fPoint(x1, y1, z1));  // 6
  raw.m_V.Append(ON_3fPoint(x0, y1, z1));  // 7

  auto add_quad = [&raw](int a, int b, int c, int d) {
    ON_MeshFace face;
    face.vi[0] = a;
    face.vi[1] = b;
    face.vi[2] = c;
    face.vi[3] = d;
    raw.m_F.Append(face);
  };

  add_quad(0, 3, 2, 1);  // bottom (-z)
  add_quad(4, 5, 6, 7);  // top (+z)
  add_quad(0, 1, 5, 4);  // front (-y)
  add_quad(3, 7, 6, 2);  // back (+y)
  add_quad(0, 4, 7, 3);  // left (-x)
  add_quad(1, 2, 6, 5);  // right (+x)

  return mesh;
}

void TestModelAddMeshRoundTrips() {
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  // AddMesh() is the missing counterpart to AddCurve()/AddBrep(): every
  // closed-solid primitive/boolean result here is a Mesh, but until now
  // there was no way to put one into a .3dm at all.
  const auto box = MakeQuadBoxMesh(0, 0, 0, 2, 3, 4);
  Model model;
  model.AddMesh(box);
  Check(model.ObjectCount() == 1, "model has one object after AddMesh()");

  const std::string path = "dino8_kernel_mesh_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a mesh object succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.ObjectCount() == 1, "round-tripped model has one object");

  // Not just "an object exists" - dig out the actual mesh geometry and
  // check its vertex/face counts and volume genuinely survived the
  // round trip, not just some object of some type.
  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_mesh = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const auto* mesh_geometry = dynamic_cast<const ON_Mesh*>(geometry_component->Geometry(nullptr));
    if (mesh_geometry == nullptr) {
      continue;
    }
    found_mesh = true;
    Check(mesh_geometry->m_V.Count() == box.VertexCount(),
          "the round-tripped mesh object has the original's vertex count (8)");
    Check(mesh_geometry->m_F.Count() == box.FaceCount(),
          "the round-tripped mesh object has the original's face count (6)");
    Mesh reloaded_mesh;
    reloaded_mesh.raw() = *mesh_geometry;
    Check(std::abs(reloaded_mesh.Volume() - box.Volume()) < 1e-9,
          "the round-tripped mesh's volume exactly matches the original "
          "(quad faces preserved, not reinterpreted)");
  }
  Check(found_mesh, "the .3dm file's model geometry actually contains a mesh object");

  std::remove(path.c_str());
}

void TestModelLoadRejectsMeshWithOutOfRangeFaceIndex() {
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  // Regression: OpenNURBS' ON_Mesh::Read() copies each face's vertex
  // indices off the disk without checking them against the vertex count,
  // and Model::Load() used to trust that - so a .3dm mesh with a face
  // pointing past its own vertex array loaded with Result::Ok (ON_Mesh::
  // IsValid() false, but nothing looked), after which every kernel Mesh
  // query indexed m_V out of bounds: a debug run against the pre-fix
  // build got Area() == 0.5 from garbage memory, no error anywhere.
  // Built through this class's own Save() (which OpenNURBS doesn't
  // validate either - the first Check below documents that honestly)
  // rather than hand-written bytes, since the reader is the boundary
  // this test is about.
  const std::string bad_path = "dino8_kernel_model_bad_mesh_index_test.3dm";
  {
    Mesh bad;
    ON_Mesh& raw = bad.raw();
    raw.m_V.Append(ON_3fPoint(0, 0, 0));
    raw.m_V.Append(ON_3fPoint(1, 0, 0));
    raw.m_V.Append(ON_3fPoint(0, 1, 0));
    ON_MeshFace good;
    good.vi[0] = 0; good.vi[1] = 1; good.vi[2] = 2; good.vi[3] = 2;
    ON_MeshFace broken;
    broken.vi[0] = 0; broken.vi[1] = 1; broken.vi[2] = 7; broken.vi[3] = 7;  // 3 vertices only
    raw.m_F.Append(good);
    raw.m_F.Append(broken);
    Check(!raw.IsValid(), "fixture: OpenNURBS itself agrees the mesh is invalid");
    Model model;
    model.AddMesh(bad);
    Check(model.Save(bad_path) == Result::Ok,
          "control: a model holding a mesh with an out-of-range face index still SAVES - "
          "OpenNURBS writes it verbatim, so the READER is the boundary that has to catch it");
  }
  Model loaded;
  Check(Model::Load(bad_path, loaded) == Result::Failed,
        "Model::Load fails on a .3dm whose mesh face references a vertex index beyond the "
        "vertex count, instead of returning Result::Ok with a mesh every kernel query would "
        "then read out of bounds");
  Check(loaded.ObjectCount() == 0, "...and leaves out_model empty rather than half-trusted");
  std::remove(bad_path.c_str());

  // Control: the same three vertices with only the in-range face (a
  // degenerate-but-in-range face too - repeated indices are a legitimate
  // thing other exporters write and indexing them is safe, so the check
  // must NOT be as strict as ON_MeshFace::IsValid()) still load fine.
  const std::string good_path = "dino8_kernel_model_good_mesh_index_test.3dm";
  {
    Mesh fine;
    ON_Mesh& raw = fine.raw();
    raw.m_V.Append(ON_3fPoint(0, 0, 0));
    raw.m_V.Append(ON_3fPoint(1, 0, 0));
    raw.m_V.Append(ON_3fPoint(0, 1, 0));
    ON_MeshFace good;
    good.vi[0] = 0; good.vi[1] = 1; good.vi[2] = 2; good.vi[3] = 2;
    ON_MeshFace degenerate;
    degenerate.vi[0] = 0; degenerate.vi[1] = 0; degenerate.vi[2] = 1; degenerate.vi[3] = 1;
    raw.m_F.Append(good);
    raw.m_F.Append(degenerate);
    Model model;
    model.AddMesh(fine);
    Check(model.Save(good_path) == Result::Ok, "control: the in-range mesh saves");
  }
  Model loaded_fine;
  Check(Model::Load(good_path, loaded_fine) == Result::Ok,
        "control: a mesh whose every face index is in range - including a degenerate "
        "repeated-index face - still loads with Result::Ok");
  Check(loaded_fine.ObjectCount() == 1, "control: ...with its one mesh object intact");
  std::remove(good_path.c_str());
}

void TestModelAddSubDRoundTrips() {
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::SubD;

  // AddSubD() closes the same "no way to put this into a .3dm" gap
  // AddMesh() closed, for SubD instead of Mesh.
  const auto quad_box = MakeQuadBoxMesh(0, 0, 0, 2, 3, 4);
  const auto subd = SubD::FromControlMesh(quad_box);
  Model model;
  model.AddSubD(subd);
  Check(model.ObjectCount() == 1, "model has one object after AddSubD()");

  const std::string path = "dino8_kernel_subd_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a SubD object succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.ObjectCount() == 1, "round-tripped model has one object");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_subd = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const auto* subd_geometry = dynamic_cast<const ON_SubD*>(geometry_component->Geometry(nullptr));
    if (subd_geometry == nullptr) {
      continue;
    }
    found_subd = true;
    Check(static_cast<int>(subd_geometry->VertexCount()) == subd.VertexCount(),
          "the round-tripped SubD object has the original's vertex count");
    Check(static_cast<int>(subd_geometry->FaceCount()) == subd.FaceCount(),
          "the round-tripped SubD object has the original's face count (6)");
  }
  Check(found_subd, "the .3dm file's model geometry actually contains a SubD object");

  std::remove(path.c_str());
}

// AddPointCloud() closes the same "no way to put this into a .3dm" gap
// AddMesh()/AddSubD() closed for their own types - until it existed, a
// dino8::kernel::PointCloud had no path into a Model at all, so
// PointCloud's own doc comment claim that ON_PointCloud "round-trips"
// through .3dm was unreachable from this kernel's API. Checks positions,
// per-point colors, and per-point normals all survive - PointCloud's
// "all or nothing" convention means a partial round trip of any one of
// those would silently look like "no colors"/"no normals" rather than an
// error, so each is checked explicitly rather than just object count.
void TestModelAddPointCloudRoundTrips() {
  using dino8::kernel::Model;
  using dino8::kernel::PointCloud;
  using dino8::kernel::Result;

  PointCloud cloud;
  cloud.AppendPoint(dino8::kernel::Point3d(0, 0, 0));
  cloud.AppendPoint(dino8::kernel::Point3d(1, 2, 3));
  cloud.AppendPoint(dino8::kernel::Point3d(-4, 5, -6));
  cloud.SetColors({ON_Color(255, 0, 0), ON_Color(0, 255, 0), ON_Color(0, 0, 255)});
  cloud.SetNormals({dino8::kernel::Vector3d(1, 0, 0), dino8::kernel::Vector3d(0, 1, 0),
                     dino8::kernel::Vector3d(0, 0, 1)});
  Check(cloud.HasColors() && cloud.HasNormals(), "fixture: cloud carries colors and normals");

  Model model;
  model.AddPointCloud(cloud);
  Check(model.ObjectCount() == 1, "model has one object after AddPointCloud()");

  const std::string path = "dino8_kernel_point_cloud_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a point cloud object succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.ObjectCount() == 1, "round-tripped model has one object");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_cloud = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const auto* cloud_geometry =
        dynamic_cast<const ON_PointCloud*>(geometry_component->Geometry(nullptr));
    if (cloud_geometry == nullptr) continue;
    found_cloud = true;

    Check(cloud_geometry->PointCount() == cloud.PointCount(),
          "the round-tripped point cloud has the original's point count (3)");
    Check(cloud_geometry->HasPointColors(), "the round-tripped cloud kept its per-point colors");
    Check(cloud_geometry->HasPointNormals(), "the round-tripped cloud kept its per-point normals");

    PointCloud reloaded;
    reloaded.raw() = *cloud_geometry;
    for (int i = 0; i < cloud.PointCount(); ++i) {
      Check(reloaded.PointAt(i).DistanceTo(cloud.PointAt(i)) < 1e-12,
            "round-tripped point position matches exactly");
      Check(reloaded.ColorAt(i) == cloud.ColorAt(i), "round-tripped point color matches exactly");
      const auto original_n = cloud.NormalAt(i);
      const auto reloaded_n = reloaded.NormalAt(i);
      Check(std::abs(reloaded_n.x - original_n.x) < 1e-12 &&
                std::abs(reloaded_n.y - original_n.y) < 1e-12 &&
                std::abs(reloaded_n.z - original_n.z) < 1e-12,
            "round-tripped point normal matches exactly");
    }
  }
  Check(found_cloud, "the .3dm file's model geometry actually contains a point cloud object");

  std::remove(path.c_str());
}

// Every Add*() gained an optional `name` parameter - before this, every
// object placed in a Model got a default, empty ON_3dmObjectAttributes,
// so a caller had no way to attach even the most basic .3dm object
// metadata (the name Rhino itself uses for selection-by-name and
// round-tripping object identity). Checks a real round trip of a name
// through an actual .3dm file for two different object types (Mesh,
// Brep), plus the "no name given" case still leaving the object unnamed
// (proving the new parameter is additive, not a behavior change for
// existing callers).
void TestModelAddObjectNameRoundTrips() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  const auto box_mesh = MakeQuadBoxMesh(0, 0, 0, 1, 1, 1);
  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);

  Model model;
  model.AddMesh(box_mesh, "MyMesh");
  model.AddBrep(box_brep, "MyBrep");
  const auto line = dino8::kernel::NurbsCurve::FromControlPoints(
      {dino8::kernel::Point3d(0, 0, 0), dino8::kernel::Point3d(1, 0, 0)}, /*degree=*/1);
  model.AddCurve(line);  // no name given
  Check(model.ObjectCount() == 3, "model has three objects after two named + one unnamed Add*()");

  const std::string path = "dino8_kernel_model_object_name_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with named objects succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_named_mesh = false;
  bool found_named_brep = false;
  bool found_unnamed_curve = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const ON_3dmObjectAttributes* attributes = geometry_component->Attributes(nullptr);
    Check(attributes != nullptr, "every reloaded geometry object still carries its attributes");
    const ON_Geometry* geometry = geometry_component->Geometry(nullptr);
    if (dynamic_cast<const ON_Mesh*>(geometry) != nullptr) {
      found_named_mesh = true;
      Check(attributes->Name() == ON_wString("MyMesh"),
            "the reloaded mesh's object name exactly matches what AddMesh() was given (\"MyMesh\")");
    } else if (dynamic_cast<const ON_Brep*>(geometry) != nullptr) {
      found_named_brep = true;
      Check(attributes->Name() == ON_wString("MyBrep"),
            "the reloaded brep's object name exactly matches what AddBrep() was given (\"MyBrep\")");
    } else if (dynamic_cast<const ON_NurbsCurve*>(geometry) != nullptr) {
      found_unnamed_curve = true;
      Check(attributes->Name().IsEmpty(),
            "the reloaded curve - added with no name argument - has no object name, proving "
            "the new parameter is a no-op when omitted");
    }
  }
  Check(found_named_mesh && found_named_brep && found_unnamed_curve,
        "all three object types (named mesh, named brep, unnamed curve) were found in the "
        "reloaded model");

  std::remove(path.c_str());
}

// Model::AddLayer() plus every Add*()'s new `layer_index` parameter: before
// this, this kernel had no concept of a layer at all (PARITY_MAP.md's
// "kernel-level data exchange" evidence: "grep ON_Layer/ON_Material in
// dino8-kernel/src: none"), so nothing it saved could carry Rhino's most
// basic organizational metadata. Checks a real round trip through an
// actual .3dm file: a named, colored layer; an object placed on it via
// its returned index; a second object left on the default layer (proving
// the new parameter is additive, not a behavior change for existing
// callers); and AddLayer()'s own -1 contract for an empty name.
void TestModelAddLayerRoundTrips() {
  using dino8::kernel::Brep;
  using dino8::kernel::Color;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  Model model;
  const int layer_index = model.AddLayer("MyLayer", Color{200, 100, 50});
  Check(layer_index >= 0, "AddLayer() with a non-empty name returns a valid (>= 0) index");
  Check(model.AddLayer("") == -1, "AddLayer() with an empty name returns -1 rather than aliasing "
                                  "OpenNURBS' own \"Default\" layer");

  const auto box_mesh = MakeQuadBoxMesh(0, 0, 0, 1, 1, 1);
  model.AddMesh(box_mesh, "OnMyLayer", layer_index);
  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep);  // no layer given: stays on the default layer

  const std::string path = "dino8_kernel_model_layer_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a named layer succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  const ON_ModelComponentReference layer_ref = loaded.raw().LayerFromIndex(layer_index);
  const ON_Layer* layer = ON_Layer::Cast(layer_ref.ModelComponent());
  Check(layer != nullptr, "the reloaded model still has a layer at the returned index");
  Check(layer->Name() == ON_wString("MyLayer"),
        "the reloaded layer's name exactly matches what AddLayer() was given (\"MyLayer\")");
  Check(layer->Color() == ON_Color(200, 100, 50),
        "the reloaded layer's color exactly matches what AddLayer() was given");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_layered_mesh = false;
  bool found_default_brep = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const ON_3dmObjectAttributes* attributes = geometry_component->Attributes(nullptr);
    const ON_Geometry* geometry = geometry_component->Geometry(nullptr);
    if (dynamic_cast<const ON_Mesh*>(geometry) != nullptr) {
      found_layered_mesh = true;
      Check(attributes->m_layer_index == layer_index,
            "the reloaded mesh's layer index exactly matches what AddMesh() was given");
    } else if (dynamic_cast<const ON_Brep*>(geometry) != nullptr) {
      found_default_brep = true;
      Check(attributes->m_layer_index == -1,
            "the reloaded brep - added with no layer_index argument - carries OpenNURBS' own "
            "-1 Default-layer sentinel, not a real layer-table index");
      Check(attributes->m_layer_index != layer_index,
            "the default-layer brep's layer index is genuinely distinct from \"MyLayer\"'s own "
            "index, even though \"MyLayer\" - the first layer ever added to this model - "
            "claimed manifest index 0, the same value the old plain-0 default used to collide "
            "with (the bug this -1 sentinel fixes)");
      const ON_ModelComponentReference resolved = loaded.raw().LayerFromIndex(-1);
      const ON_Layer* resolved_layer = ON_Layer::Cast(resolved.ModelComponent());
      Check(resolved_layer != nullptr && resolved_layer->Name() != ON_wString("MyLayer"),
            "LayerFromIndex(-1) resolves to OpenNURBS' own built-in Default layer, not the "
            "named layer that happens to occupy index 0");
    }
  }
  Check(found_layered_mesh && found_default_brep,
        "both object types (layered mesh, default-layer brep) were found in the reloaded model");

  std::remove(path.c_str());
}

// The specific order-dependent defect PARITY_MAP.md's own "kernel-level data
// exchange" evidence named: "the true OpenNURBS default layer index is -1
// ... first AddLayer() call takes index 0". TestModelAddLayerRoundTrips()
// above always calls AddLayer() BEFORE adding the default-layer object, so
// even the old, buggy plain-0 default happened to keep that one test
// passing (both the newly added layer and the default-layer object landed
// on manifest index 0, and the test only ever checked the mesh/brep against
// each other, not against a value recorded before any layer existed). This
// test instead reproduces the actual failure order: an object is added with
// no layer at all while the model's layer table is still completely empty,
// and only afterward does a real named layer get added - the exact
// sequence where a plain-0 default silently reassigns the earlier object
// onto the newly added layer, since both would resolve to the very first
// slot (index 0) in an empty table.
void TestModelDefaultLayerSurvivesLaterAddLayerCall() {
  using dino8::kernel::Brep;
  using dino8::kernel::Color;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  Model model;
  Check(model.LayerCount() == 0, "a fresh Model starts with no layers in its own layer table");

  // Added first, with no layer_index argument, while the layer table is
  // still empty - the exact ordering the old plain-0 default got wrong.
  const auto early_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(early_brep, "AddedBeforeAnyLayer");

  // Only now does a real named layer get added - it claims manifest index
  // 0, the model's very first layer-table slot, precisely the slot the old
  // plain-0 default would have collided with.
  const int later_layer_index = model.AddLayer("AddedAfterward", Color{9, 8, 7});
  Check(later_layer_index == 0,
        "AddLayer()'s first call still claims manifest index 0 (unchanged) - the defect this "
        "test guards against is the default-layer object silently ending up on THIS layer, not "
        "a change to what AddLayer() itself returns");

  const std::string path = "dino8_kernel_model_default_layer_survives_addlayer_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  const auto attributes = loaded.ObjectAttributesAt(0);
  Check(attributes.name == "AddedBeforeAnyLayer", "the reloaded object is the one added first");
  Check(attributes.layer_index == -1,
        "the object added before any layer existed still carries the -1 Default-layer "
        "sentinel after a later AddLayer() call claimed manifest index 0 - it was never "
        "silently reassigned onto \"AddedAfterward\"");
  Check(attributes.layer_index != later_layer_index,
        "the object's layer index is genuinely distinct from the later-added layer's own index, "
        "proving no aliasing occurred");

  const ON_ModelComponentReference resolved = loaded.raw().LayerFromIndex(-1);
  const ON_Layer* resolved_layer = ON_Layer::Cast(resolved.ModelComponent());
  Check(resolved_layer != nullptr && resolved_layer->Name() != ON_wString("AddedAfterward"),
        "LayerFromIndex(-1) resolves to OpenNURBS' own built-in Default layer, never the real "
        "named layer that happens to occupy manifest index 0");

  std::remove(path.c_str());
}

// Every Add*()'s new `render_color` parameter: before this, an object's
// displayed color could only ever come from its layer (ON::color_from_layer,
// ON_3dmObjectAttributes' own default) - the same "kernel-level data
// exchange" gap TestModelAddLayerRoundTrips() closed for `m_layer_index`,
// just for `m_color`/`ColorSource()` instead. Checks a real round trip: one
// object given an explicit render_color (proving it overrides
// ColorSource() to ON::color_from_object and the color itself survives
// save/reload byte-for-byte), and a second object left with no
// render_color argument (proving the new parameter is additive, not a
// behavior change for existing callers - ColorSource() stays
// ON::color_from_layer, the default this kernel used before render_color
// existed at all).
void TestModelAddRenderColorRoundTrips() {
  using dino8::kernel::Brep;
  using dino8::kernel::Color;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  Model model;
  const auto box_mesh = MakeQuadBoxMesh(0, 0, 0, 1, 1, 1);
  model.AddMesh(box_mesh, "ColoredMesh", 0, Color{10, 200, 30});
  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep);  // no render_color given: stays layer-colored

  const std::string path = "dino8_kernel_model_render_color_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with an object render color succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_colored_mesh = false;
  bool found_uncolored_brep = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const ON_3dmObjectAttributes* attributes = geometry_component->Attributes(nullptr);
    const ON_Geometry* geometry = geometry_component->Geometry(nullptr);
    if (dynamic_cast<const ON_Mesh*>(geometry) != nullptr) {
      found_colored_mesh = true;
      Check(attributes->ColorSource() == ON::color_from_object,
            "the reloaded mesh's ColorSource() switched to ON::color_from_object");
      Check(attributes->m_color == ON_Color(10, 200, 30),
            "the reloaded mesh's color exactly matches what AddMesh() was given");
    } else if (dynamic_cast<const ON_Brep*>(geometry) != nullptr) {
      found_uncolored_brep = true;
      Check(attributes->ColorSource() == ON::color_from_layer,
            "the reloaded brep - added with no render_color argument - kept ColorSource() at "
            "its default ON::color_from_layer, proving the new parameter is a no-op when "
            "omitted");
    }
  }
  Check(found_colored_mesh && found_uncolored_brep,
        "both object types (colored mesh, uncolored brep) were found in the reloaded model");

  std::remove(path.c_str());
}

// Every Add*()'s new `user_strings` parameter: Rhino's own "user text"
// key/value attribute mechanism (UserStrings' own doc comment in file_io.h),
// the last field PARITY_MAP.md's ".3dm attribute/metadata fidelity"
// evidence lists that this kernel had no way to write at all. Checks a
// real round trip: one object given two user strings, including a
// repeated key (proving SetUserString()'s own "last value wins" contract
// survives the round trip, not just a single pair); a second object left
// with no user_strings argument (proving the new parameter is additive,
// not a behavior change for existing callers - UserStringCount() stays 0,
// exactly as every object's attributes were before this parameter existed).
void TestModelAddUserStringsRoundTrips() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::UserStrings;

  Model model;
  const auto box_mesh = MakeQuadBoxMesh(0, 0, 0, 1, 1, 1);
  const UserStrings user_strings = {
      {"PartNumber", "PN-1042"}, {"Material", "Aluminum"}, {"PartNumber", "PN-1042-REV-B"}};
  model.AddMesh(box_mesh, "TaggedMesh", 0, std::nullopt, user_strings);
  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep);  // no user_strings given: carries none

  const std::string path = "dino8_kernel_model_user_strings_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with object user strings succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_tagged_mesh = false;
  bool found_untagged_brep = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const ON_3dmObjectAttributes* attributes = geometry_component->Attributes(nullptr);
    const ON_Geometry* geometry = geometry_component->Geometry(nullptr);
    if (dynamic_cast<const ON_Mesh*>(geometry) != nullptr) {
      found_tagged_mesh = true;
      Check(attributes->UserStringCount() == 2,
            "the reloaded mesh carries exactly 2 user strings - the repeated \"PartNumber\" "
            "key collapsed to its last value, not appended as a third entry");
      ON_wString part_number;
      Check(attributes->GetUserString(L"PartNumber", part_number) &&
                part_number == ON_wString("PN-1042-REV-B"),
            "the reloaded mesh's \"PartNumber\" user string is the LAST value given for that "
            "key (\"PN-1042-REV-B\"), matching SetUserString()'s own replace contract");
      ON_wString material;
      Check(attributes->GetUserString(L"Material", material) &&
                material == ON_wString("Aluminum"),
            "the reloaded mesh's \"Material\" user string exactly matches what AddMesh() was "
            "given");
    } else if (dynamic_cast<const ON_Brep*>(geometry) != nullptr) {
      found_untagged_brep = true;
      Check(attributes->UserStringCount() == 0,
            "the reloaded brep - added with no user_strings argument - carries none, proving "
            "the new parameter is a no-op when omitted");
    }
  }
  Check(found_tagged_mesh && found_untagged_brep,
        "both object types (tagged mesh, untagged brep) were found in the reloaded model");

  std::remove(path.c_str());
}

// Model::AddLinetype() plus AddLayer()'s and every Add*()'s new
// `linetype_index` parameter: PARITY_MAP.md's own ".3dm attribute/metadata
// fidelity" evidence named linetypes as the last field, alongside layers/
// materials/user-strings, this kernel had no way to write at all - every
// layer, and so every object on it, could only ever draw as a solid
// (Continuous) line. Checks a real round trip through an actual .3dm
// file: a named dash-dot linetype added via AddLinetype(); a layer that
// references it via AddLayer()'s own `linetype_index`; one object left on
// that layer with no per-object override (inheriting the layer's dash
// pattern, proving the new Add*() parameter is additive); and a second
// object on the same layer given its own `linetype_index` of 0
// (Continuous), proving the per-object override actually overrides
// LinetypeSource() rather than being shadowed by the layer.
void TestModelAddLinetypeRoundTrips() {
  using dino8::kernel::Brep;
  using dino8::kernel::Color;
  using dino8::kernel::LinetypePattern;
  using dino8::kernel::LinetypeSegment;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::UserStrings;

  Model model;
  const LinetypePattern pattern = {LinetypeSegment{5.0, true}, LinetypeSegment{2.0, false},
                                    LinetypeSegment{1.0, true}, LinetypeSegment{2.0, false}};
  const int linetype_index = model.AddLinetype("DashDot2", pattern);
  Check(linetype_index >= 0, "AddLinetype() with a non-empty name returns a valid (>= 0) index");
  Check(model.AddLinetype("") == -1,
        "AddLinetype() with an empty name returns -1, same contract as AddLayer()");

  const int layer_index = model.AddLayer("DashedLayer", Color(), linetype_index);
  Check(layer_index >= 0, "AddLayer() with a linetype_index argument still returns a valid index");

  const auto box_mesh = MakeQuadBoxMesh(0, 0, 0, 1, 1, 1);
  model.AddMesh(box_mesh, "InheritsLayerLinetype", layer_index);
  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep, "OverridesLinetype", layer_index, std::nullopt, UserStrings(),
                /*linetype_index=*/0);

  const std::string path = "dino8_kernel_model_linetype_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a linetype succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  const ON_Linetype* linetype = nullptr;
  {
    ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::LinePattern);
    for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
         component = iterator.NextComponent()) {
      const ON_Linetype* candidate = ON_Linetype::Cast(component);
      if (candidate != nullptr && candidate->Index() == linetype_index) {
        linetype = candidate;
        break;
      }
    }
  }
  Check(linetype != nullptr, "the reloaded model still has a linetype at the returned index");
  Check(linetype->Name() == ON_wString("DashDot2"),
        "the reloaded linetype's name exactly matches what AddLinetype() was given");
  Check(linetype->SegmentCount() == 4,
        "the reloaded linetype has exactly the 4 segments AddLinetype() was given");
  Check(linetype->Segment(0).m_length == 5.0 &&
            linetype->Segment(0).m_seg_type == ON_LinetypeSegment::eSegType::stLine &&
            linetype->Segment(1).m_length == 2.0 &&
            linetype->Segment(1).m_seg_type == ON_LinetypeSegment::eSegType::stSpace,
        "the reloaded linetype's segment lengths and dash/gap types exactly match what "
        "AddLinetype() was given");

  const ON_ModelComponentReference layer_ref = loaded.raw().LayerFromIndex(layer_index);
  const ON_Layer* layer = ON_Layer::Cast(layer_ref.ModelComponent());
  Check(layer != nullptr && layer->LinetypeIndex() == linetype_index,
        "the reloaded layer's linetype index exactly matches what AddLayer() was given");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_inheriting_mesh = false;
  bool found_overriding_brep = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const ON_3dmObjectAttributes* attributes = geometry_component->Attributes(nullptr);
    const ON_Geometry* geometry = geometry_component->Geometry(nullptr);
    if (dynamic_cast<const ON_Mesh*>(geometry) != nullptr) {
      found_inheriting_mesh = true;
      Check(attributes->LinetypeSource() == ON::linetype_from_layer,
            "the reloaded mesh - added with no linetype_index argument - kept LinetypeSource() "
            "at its default ON::linetype_from_layer, proving the new parameter is a no-op when "
            "omitted");
    } else if (dynamic_cast<const ON_Brep*>(geometry) != nullptr) {
      found_overriding_brep = true;
      Check(attributes->LinetypeSource() == ON::linetype_from_object,
            "the reloaded brep's LinetypeSource() switched to ON::linetype_from_object");
      Check(attributes->m_linetype_index == 0,
            "the reloaded brep's linetype index exactly matches what AddBrep() was given, "
            "overriding rather than being shadowed by its layer's own linetype");
    }
  }
  Check(found_inheriting_mesh && found_overriding_brep,
        "both object types (layer-inheriting mesh, linetype-overriding brep) were found in the "
        "reloaded model");

  std::remove(path.c_str());
}

// Model::AddGroup() plus every Add*()'s new `group_indices` parameter:
// PARITY_MAP.md's ".3dm attribute/metadata fidelity" evidence named groups
// as a field this kernel had no way to write at all, alongside layers/
// materials/linetypes/user-strings - Rhino's own Group/Ungroup commands,
// which let a user select every object in a group with one click even
// across objects on different layers, a relationship the layer table alone
// cannot express. Checks a real round trip through an actual .3dm file: a
// named group added via AddGroup(); two objects placed in that same group
// (one of them also in a second group, proving `group_indices` is a list,
// not a single value); and a third object given no group_indices argument
// (proving the new parameter is additive, not a behavior change for
// existing callers - GroupCount() stays 0, exactly as every object's
// attributes were before this parameter existed).
void TestModelAddGroupRoundTrips() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::UserStrings;

  Model model;
  const int group_index = model.AddGroup("Fasteners");
  Check(group_index >= 0, "AddGroup() with a non-empty name returns a valid (>= 0) index");
  Check(model.AddGroup("") == -1,
        "AddGroup() with an empty name returns -1, same contract as AddLayer()/AddLinetype()");
  const int second_group_index = model.AddGroup("Hidden");
  Check(second_group_index >= 0 && second_group_index != group_index,
        "a second AddGroup() call returns a distinct valid index");

  const auto box_mesh = MakeQuadBoxMesh(0, 0, 0, 1, 1, 1);
  model.AddMesh(box_mesh, "GroupedMesh", 0, std::nullopt, UserStrings(), std::nullopt,
                {group_index});
  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep, "GroupedBrepInTwoGroups", 0, std::nullopt, UserStrings(), std::nullopt,
                {group_index, second_group_index});
  const auto ungrouped_mesh = MakeQuadBoxMesh(2, 0, 0, 3, 1, 1);
  model.AddMesh(ungrouped_mesh);  // no group_indices given: carries none

  const std::string path = "dino8_kernel_model_group_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with object groups succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  const ON_Group* group = nullptr;
  {
    ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::Group);
    for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
         component = iterator.NextComponent()) {
      const ON_Group* candidate = ON_Group::Cast(component);
      if (candidate != nullptr && candidate->Index() == group_index) {
        group = candidate;
        break;
      }
    }
  }
  Check(group != nullptr, "the reloaded model still has a group at the returned index");
  Check(group->Name() == ON_wString("Fasteners"),
        "the reloaded group's name exactly matches what AddGroup() was given");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_grouped_mesh = false;
  bool found_two_group_brep = false;
  bool found_ungrouped_mesh = false;
  int ungrouped_mesh_count = 0;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const ON_3dmObjectAttributes* attributes = geometry_component->Attributes(nullptr);
    if (attributes->Name() == ON_wString("GroupedMesh")) {
      found_grouped_mesh = true;
      Check(attributes->GroupCount() == 1 && attributes->IsInGroup(group_index),
            "the reloaded mesh belongs to exactly the one group AddMesh() was given");
    } else if (attributes->Name() == ON_wString("GroupedBrepInTwoGroups")) {
      found_two_group_brep = true;
      Check(attributes->GroupCount() == 2 && attributes->IsInGroup(group_index) &&
                attributes->IsInGroup(second_group_index),
            "the reloaded brep belongs to both groups AddBrep() was given, proving "
            "group_indices is a list rather than a single value");
    } else {
      ++ungrouped_mesh_count;
      found_ungrouped_mesh = true;
      Check(attributes->GroupCount() == 0,
            "the reloaded mesh - added with no group_indices argument - belongs to no groups, "
            "proving the new parameter is a no-op when omitted");
    }
  }
  Check(found_grouped_mesh && found_two_group_brep && found_ungrouped_mesh &&
            ungrouped_mesh_count == 1,
        "all three objects (single-group mesh, two-group brep, ungrouped mesh) were found "
        "exactly once each in the reloaded model");

  std::remove(path.c_str());
}

// Model::AddMaterial() plus every Add*()'s new `material_index` parameter:
// PARITY_MAP.md's ".3dm attribute/metadata fidelity" evidence named
// materials (alongside layers/linetypes/groups/user-strings) as a field
// this kernel had no way to write at all - "grep ON_Layer/ON_Material in
// dino8-kernel/src: none". A rendered material is a distinct .3dm component
// table (ON_ModelComponent::Type::RenderMaterial) from the plain per-object
// `render_color`/ColorSource() pair TestModelAddRenderColorRoundTrips()
// already covers - Rhino keeps a render/shaded-viewport material's diffuse
// color separate from the flat wireframe/object display color, so this is a
// genuinely different field, not a duplicate of that existing test. Checks
// a real round trip through an actual .3dm file: a named material with a
// distinct diffuse color, added via AddMaterial(); one object assigned that
// material (proving MaterialSource() flips to ON::material_from_object and
// `m_material_index` survives the round trip); a second object given no
// material_index argument (proving the new parameter is additive, not a
// behavior change for existing callers - MaterialSource() stays at its
// default ON::material_from_layer, exactly as every object's attributes
// were before this parameter existed).
void TestModelAddMaterialRoundTrips() {
  using dino8::kernel::Brep;
  using dino8::kernel::Color;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::UserStrings;

  Model model;
  const int material_index = model.AddMaterial("Anodized Red", Color{200, 20, 20});
  Check(material_index >= 0, "AddMaterial() with a non-empty name returns a valid (>= 0) index");
  Check(model.AddMaterial("") == -1,
        "AddMaterial() with an empty name returns -1, same contract as "
        "AddLayer()/AddLinetype()/AddGroup()");
  const int second_material_index = model.AddMaterial("Brushed Steel", Color{150, 150, 160});
  Check(second_material_index >= 0 && second_material_index != material_index,
        "a second AddMaterial() call returns a distinct valid index");

  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep, "MaterialedBrep", 0, std::nullopt, UserStrings(), std::nullopt,
                std::vector<int>(), material_index);
  const auto box_mesh = MakeQuadBoxMesh(2, 0, 0, 3, 1, 1);
  model.AddMesh(box_mesh);  // no material_index given: stays layer-materialed

  const std::string path = "dino8_kernel_model_material_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with an object material succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  const ON_Material* material = nullptr;
  {
    ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::RenderMaterial);
    for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
         component = iterator.NextComponent()) {
      const ON_Material* candidate = ON_Material::Cast(component);
      if (candidate != nullptr && candidate->Index() == material_index) {
        material = candidate;
        break;
      }
    }
  }
  Check(material != nullptr, "the reloaded model still has a material at the returned index");
  Check(material->Name() == ON_wString("Anodized Red"),
        "the reloaded material's name exactly matches what AddMaterial() was given");
  Check(material->Diffuse() == ON_Color(200, 20, 20),
        "the reloaded material's diffuse color exactly matches what AddMaterial() was given");

  ONX_ModelComponentIterator iterator(loaded.raw(), ON_ModelComponent::Type::ModelGeometry);
  bool found_materialed_brep = false;
  bool found_unmaterialed_mesh = false;
  for (const ON_ModelComponent* component = iterator.FirstComponent(); component != nullptr;
       component = iterator.NextComponent()) {
    const auto* geometry_component = static_cast<const ON_ModelGeometryComponent*>(component);
    const ON_3dmObjectAttributes* attributes = geometry_component->Attributes(nullptr);
    const ON_Geometry* geometry = geometry_component->Geometry(nullptr);
    if (dynamic_cast<const ON_Brep*>(geometry) != nullptr) {
      found_materialed_brep = true;
      Check(attributes->MaterialSource() == ON::material_from_object,
            "the reloaded brep's MaterialSource() switched to ON::material_from_object");
      Check(attributes->m_material_index == material_index,
            "the reloaded brep's material index exactly matches what AddBrep() was given");
    } else if (dynamic_cast<const ON_Mesh*>(geometry) != nullptr) {
      found_unmaterialed_mesh = true;
      Check(attributes->MaterialSource() == ON::material_from_layer,
            "the reloaded mesh - added with no material_index argument - kept MaterialSource() "
            "at its default ON::material_from_layer, proving the new parameter is a no-op when "
            "omitted");
    }
  }
  Check(found_materialed_brep && found_unmaterialed_mesh,
        "both object types (materialed brep, unmaterialed mesh) were found in the reloaded "
        "model");

  std::remove(path.c_str());
}

// Model::ObjectAttributesAt()/LayerAt()/LinetypeAt()/GroupNameAt() (plus
// their *Count() companions): the read-side counterpart to every Add*()/
// AddLayer()/AddLinetype()/AddGroup() parameter above. Before this, the
// only way to read any of that metadata back was raw() plus a hand-rolled
// ONX_ModelComponentIterator - exactly what every round-trip test above
// this one does, each with its own copy of that iteration - the gap
// PARITY_MAP.md's own ".3dm attribute/metadata fidelity" evidence names:
// "no read-side accessor apart from raw()". Checks a real round trip
// through an actual .3dm file, then reads everything back exclusively
// through the new accessors (no raw()/ONX_ModelComponentIterator at all):
// two layers (one with a non-default color and a linetype override, one
// left at every default), two linetypes (one referenced by a layer, one
// standalone and never referenced by anything), two groups, and two
// objects - one carrying every optional attribute at once (name, a
// non-default layer, a per-object render color override, two user
// strings, a per-object linetype override, and membership in both
// groups) and one added with every parameter left at its default, proving
// the accessors report "inherit from layer" (std::nullopt) and "no
// groups/user-strings" (empty) rather than some other placeholder for the
// untouched case. Also checks that every *At() accessor handles an index
// that names nothing this model actually has without crashing.
void TestModelReadAccessorsRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::Color;
  using dino8::kernel::LinetypePattern;
  using dino8::kernel::LinetypeSegment;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::UserStrings;

  Model model;

  const LinetypePattern dashed_pattern = {LinetypeSegment{4.0, true}, LinetypeSegment{1.5, false},
                                           LinetypeSegment{0.5, true}};
  const int dashed_linetype_index = model.AddLinetype("Dashed3", dashed_pattern);
  const LinetypePattern dotted_pattern = {LinetypeSegment{0.25, true}};
  const int dotted_linetype_index = model.AddLinetype("Dotted", dotted_pattern);

  const int structural_layer_index =
      model.AddLayer("Structural", Color{10, 20, 30}, dashed_linetype_index);
  const int auxiliary_layer_index = model.AddLayer("Auxiliary");

  const int fasteners_group_index = model.AddGroup("Fasteners");
  const int hidden_group_index = model.AddGroup("Hidden");

  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep, "NamedBrep", structural_layer_index, Color{1, 2, 3},
                UserStrings{{"k1", "v1"}, {"k2", "v2"}}, dashed_linetype_index,
                {fasteners_group_index, hidden_group_index});
  const auto box_mesh = MakeQuadBoxMesh(2, 0, 0, 3, 1, 1);
  model.AddMesh(box_mesh);  // every parameter left at its default

  const std::string path = "dino8_kernel_model_read_accessors_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  Check(loaded.LayerCount() == 2, "LayerCount() reports exactly the 2 layers AddLayer() added");
  const auto structural_layer = loaded.LayerAt(structural_layer_index);
  Check(structural_layer.name == "Structural",
        "LayerAt() reports the reloaded layer's name exactly as AddLayer() was given");
  Check(structural_layer.color.r == 10 && structural_layer.color.g == 20 &&
            structural_layer.color.b == 30,
        "LayerAt() reports the reloaded layer's color exactly as AddLayer() was given");
  Check(structural_layer.linetype_index == dashed_linetype_index,
        "LayerAt() reports the reloaded layer's linetype_index exactly as AddLayer() was given");
  const auto auxiliary_layer = loaded.LayerAt(auxiliary_layer_index);
  Check(auxiliary_layer.name == "Auxiliary" && auxiliary_layer.linetype_index == -1,
        "LayerAt() reports a layer added with no color/linetype_index argument at every "
        "OpenNURBS default (Continuous == -1), proving the accessor doesn't invent a value");
  const auto missing_layer = loaded.LayerAt(9999);
  Check(missing_layer.name.empty() && missing_layer.linetype_index == -1,
        "LayerAt() on an index naming no real layer returns a default-constructed LayerInfo "
        "rather than crashing");

  Check(loaded.LinetypeCount() == 2,
        "LinetypeCount() reports exactly the 2 linetypes AddLinetype() added");
  const auto dashed_linetype = loaded.LinetypeAt(dashed_linetype_index);
  Check(dashed_linetype.name == "Dashed3",
        "LinetypeAt() reports the reloaded (layer-referenced) linetype's name exactly as "
        "AddLinetype() was given");
  Check(dashed_linetype.pattern.size() == 3 && dashed_linetype.pattern[0].length_mm == 4.0 &&
            dashed_linetype.pattern[0].is_dash && dashed_linetype.pattern[1].length_mm == 1.5 &&
            !dashed_linetype.pattern[1].is_dash && dashed_linetype.pattern[2].length_mm == 0.5 &&
            dashed_linetype.pattern[2].is_dash,
        "LinetypeAt() reports the reloaded linetype's segment lengths and dash/gap types "
        "exactly as AddLinetype() was given, in order");
  const auto dotted_linetype = loaded.LinetypeAt(dotted_linetype_index);
  Check(dotted_linetype.name == "Dotted" && dotted_linetype.pattern.size() == 1 &&
            dotted_linetype.pattern[0].length_mm == 0.25 && dotted_linetype.pattern[0].is_dash,
        "LinetypeAt() also reports a linetype no layer or object ever referenced - proving the "
        "accessor reads the linetype table directly, not just whatever layers happen to point "
        "at");
  const auto missing_linetype = loaded.LinetypeAt(9999);
  Check(missing_linetype.name.empty() && missing_linetype.pattern.empty(),
        "LinetypeAt() on an index naming no real linetype returns a default-constructed "
        "LinetypeInfo rather than crashing");

  Check(loaded.GroupCount() == 2, "GroupCount() reports exactly the 2 groups AddGroup() added");
  Check(loaded.GroupNameAt(fasteners_group_index) == "Fasteners" &&
            loaded.GroupNameAt(hidden_group_index) == "Hidden",
        "GroupNameAt() reports each reloaded group's name exactly as AddGroup() was given");
  Check(loaded.GroupNameAt(9999).empty(),
        "GroupNameAt() on an index naming no real group returns an empty string rather than "
        "crashing");

  Check(loaded.ObjectCount() == 2, "ObjectCount() reports exactly the 2 objects added");
  bool found_named_brep = false;
  bool found_default_mesh = false;
  for (int i = 0; i < loaded.ObjectCount(); ++i) {
    const auto attributes = loaded.ObjectAttributesAt(i);
    if (attributes.name == "NamedBrep") {
      found_named_brep = true;
      Check(attributes.layer_index == structural_layer_index,
            "ObjectAttributesAt() reports the fully-specified object's layer_index exactly as "
            "AddBrep() was given");
      Check(attributes.render_color.has_value() && attributes.render_color->r == 1 &&
                attributes.render_color->g == 2 && attributes.render_color->b == 3,
            "ObjectAttributesAt() reports the fully-specified object's per-object render_color "
            "override exactly as AddBrep() was given");
      Check(attributes.linetype_index.has_value() &&
                *attributes.linetype_index == dashed_linetype_index,
            "ObjectAttributesAt() reports the fully-specified object's per-object "
            "linetype_index override exactly as AddBrep() was given");
      Check(attributes.group_indices.size() == 2, "ObjectAttributesAt() reports both groups "
                                                    "the fully-specified object belongs to");
      bool in_fasteners = false;
      bool in_hidden = false;
      for (int group_index : attributes.group_indices) {
        if (group_index == fasteners_group_index) in_fasteners = true;
        if (group_index == hidden_group_index) in_hidden = true;
      }
      Check(in_fasteners && in_hidden,
            "ObjectAttributesAt()'s group_indices names exactly the two groups AddBrep() was "
            "given, proving it's a list rather than a single value");
      Check(attributes.user_strings.size() == 2,
            "ObjectAttributesAt() reports both user strings the fully-specified object was "
            "given");
      bool has_k1 = false;
      bool has_k2 = false;
      for (const auto& [key, value] : attributes.user_strings) {
        if (key == "k1" && value == "v1") has_k1 = true;
        if (key == "k2" && value == "v2") has_k2 = true;
      }
      Check(has_k1 && has_k2,
            "ObjectAttributesAt()'s user_strings exactly match the key/value pairs AddBrep() "
            "was given");
    } else {
      found_default_mesh = true;
      Check(attributes.name.empty() && attributes.layer_index == -1,
            "ObjectAttributesAt() reports the default-added object's name/layer_index exactly "
            "as the (omitted) Add*() defaults - -1, OpenNURBS' own Default-layer sentinel, not "
            "a real layer-table index");
      Check(attributes.layer_index != structural_layer_index,
            "the default-added mesh's layer index is genuinely distinct from \"Structural\"'s "
            "own index, even though \"Structural\" - the first layer added to this model - "
            "claimed manifest index 0, the same value the old plain-0 default used to collide "
            "with");
      Check(!attributes.render_color.has_value(),
            "ObjectAttributesAt() reports std::nullopt (inherit from layer), not some other "
            "placeholder, for an object added with no render_color argument");
      Check(!attributes.linetype_index.has_value(),
            "ObjectAttributesAt() reports std::nullopt (inherit from layer), not some other "
            "placeholder, for an object added with no linetype_index argument");
      Check(attributes.group_indices.empty(),
            "ObjectAttributesAt() reports no groups for an object added with no "
            "group_indices argument");
      Check(attributes.user_strings.empty(),
            "ObjectAttributesAt() reports no user strings for an object added with no "
            "user_strings argument");
    }
  }
  Check(found_named_brep && found_default_mesh,
        "both objects (fully-specified brep, every-default mesh) were found in the reloaded "
        "model");

  const auto out_of_range = loaded.ObjectAttributesAt(loaded.ObjectCount());
  Check(out_of_range.name.empty() && !out_of_range.render_color.has_value(),
        "ObjectAttributesAt() on an out-of-range index returns a default-constructed "
        "ObjectAttributes rather than crashing");

  std::remove(path.c_str());
}

// Model::MaterialAt()/MaterialCount(), plus ObjectAttributesAt()'s new
// material_index field: the read-side counterpart to AddMaterial() and to
// every Add*() method's own `material_index` parameter - the one read-side
// gap TestModelReadAccessorsRoundTrip() above left open (PARITY_MAP.md's
// own ".3dm attribute/metadata fidelity" evidence named it explicitly: "no
// MaterialAt()/MaterialCount()"). Checks a real round trip through an
// actual .3dm file: two materials, one object overriding its material and
// one left at every default (inheriting from its layer), then reads
// everything back exclusively through the new accessors - no raw()/
// ONX_ModelComponentIterator at all. Also checks that MaterialAt() and
// ObjectAttributesAt().material_index handle an index/object that names
// nothing this model actually has without crashing.
void TestModelMaterialAccessorsRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::Color;
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::UserStrings;

  Model model;

  const int red_material_index = model.AddMaterial("Anodized Red", Color{200, 20, 20});
  const int steel_material_index = model.AddMaterial("Brushed Steel", Color{150, 150, 160});

  const auto box_brep = Brep::Box(0, 0, 0, 1, 1, 1);
  model.AddBrep(box_brep, "MaterialedBrep", 0, std::nullopt, UserStrings(), std::nullopt,
                std::vector<int>(), red_material_index);
  const auto box_mesh = MakeQuadBoxMesh(2, 0, 0, 3, 1, 1);
  model.AddMesh(box_mesh);  // every parameter left at its default

  const std::string path = "dino8_kernel_model_material_accessors_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  Check(loaded.MaterialCount() == 2,
        "MaterialCount() reports exactly the 2 materials AddMaterial() added");
  const auto red_material = loaded.MaterialAt(red_material_index);
  Check(red_material.name == "Anodized Red",
        "MaterialAt() reports the reloaded material's name exactly as AddMaterial() was given");
  Check(red_material.diffuse_color.r == 200 && red_material.diffuse_color.g == 20 &&
            red_material.diffuse_color.b == 20,
        "MaterialAt() reports the reloaded material's diffuse color exactly as AddMaterial() "
        "was given");
  const auto steel_material = loaded.MaterialAt(steel_material_index);
  Check(steel_material.name == "Brushed Steel" && steel_material.diffuse_color.r == 150 &&
            steel_material.diffuse_color.g == 150 && steel_material.diffuse_color.b == 160,
        "MaterialAt() also reports a material no object ever referenced - proving the accessor "
        "reads the material table directly, not just whatever objects happen to point at");
  const auto missing_material = loaded.MaterialAt(9999);
  Check(missing_material.name.empty(),
        "MaterialAt() on an index naming no real material returns a default-constructed "
        "MaterialInfo rather than crashing");

  Check(loaded.ObjectCount() == 2, "ObjectCount() reports exactly the 2 objects added");
  bool found_materialed_brep = false;
  bool found_default_mesh = false;
  for (int i = 0; i < loaded.ObjectCount(); ++i) {
    const auto attributes = loaded.ObjectAttributesAt(i);
    if (attributes.name == "MaterialedBrep") {
      found_materialed_brep = true;
      Check(attributes.material_index.has_value() && *attributes.material_index == red_material_index,
            "ObjectAttributesAt() reports the materialed object's per-object material_index "
            "override exactly as AddBrep() was given");
    } else {
      found_default_mesh = true;
      Check(!attributes.material_index.has_value(),
            "ObjectAttributesAt() reports std::nullopt (inherit from layer), not some other "
            "placeholder, for an object added with no material_index argument");
    }
  }
  Check(found_materialed_brep && found_default_mesh,
        "both objects (materialed brep, every-default mesh) were found in the reloaded model");

  const auto out_of_range = loaded.ObjectAttributesAt(loaded.ObjectCount());
  Check(!out_of_range.material_index.has_value(),
        "ObjectAttributesAt() on an out-of-range index reports std::nullopt for material_index, "
        "same as every other default-constructed ObjectAttributes field");

  std::remove(path.c_str());
}

void TestModelUnitSystemRoundTrips() {
  using dino8::kernel::Model;
  using dino8::kernel::Result;
  using dino8::kernel::UnitSystem;

  // A never-SetUnitSystem() Model reports Millimeters, matching
  // ON_3dmUnitsAndTolerances' own documented default.
  Model default_model;
  Check(default_model.GetUnitSystem() == UnitSystem::Millimeters,
        "GetUnitSystem() on a Model that never called SetUnitSystem() reports Millimeters, "
        "the same default ON_3dmUnitsAndTolerances itself documents");

  // In-memory (pre-save) round trip: SetUnitSystem() is readable back
  // immediately via GetUnitSystem(), without going through a .3dm at all.
  Model in_memory;
  in_memory.SetUnitSystem(UnitSystem::Inches);
  Check(in_memory.GetUnitSystem() == UnitSystem::Inches,
        "GetUnitSystem() reports SetUnitSystem()'s own value before any save/load round trip");

  // Real .3dm round trip, one file per unit system, covering every value
  // this kernel's UnitSystem enum has.
  const std::vector<UnitSystem> units_to_check = {
      UnitSystem::Millimeters, UnitSystem::Centimeters, UnitSystem::Meters,
      UnitSystem::Kilometers,  UnitSystem::Microns,      UnitSystem::Inches,
      UnitSystem::Feet,        UnitSystem::Yards,        UnitSystem::Miles,
      UnitSystem::None,
  };
  int index = 0;
  for (UnitSystem units : units_to_check) {
    Model model;
    model.SetUnitSystem(units);
    const auto box = MakeBox(0, 0, 0, 1, 1, 1);
    model.AddMesh(box);  // a model carrying real geometry, not an empty file

    const std::string path =
        "dino8_kernel_model_unit_system_roundtrip_test_" + std::to_string(index++) + ".3dm";
    Check(model.Save(path) == Result::Ok, ".3dm save succeeded");

    Model loaded;
    Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
    Check(loaded.GetUnitSystem() == units,
          "GetUnitSystem() on a reloaded .3dm reports the exact UnitSystem SetUnitSystem() was "
          "given before saving");
    Check(loaded.ObjectCount() == 1,
          "the model's geometry survives the same round trip its unit system does");

    std::remove(path.c_str());
  }
}

void TestModelAddNamedViewRoundTrips() {
  using dino8::kernel::Model;
  using dino8::kernel::NamedViewInfo;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  Model model;
  Check(model.NamedViewCount() == 0, "a fresh Model has no named views");
  Check(model.AddNamedView("", Point3d(0, 0, 0), Point3d(1, 0, 0)) == -1,
        "AddNamedView() returns -1 for an empty name, same contract as AddLayer() etc.");
  Check(model.NamedViewCount() == 0, "the empty-name call above added nothing");

  const Point3d camera(0, -10, 5);
  const Point3d target(0, 0, 0);
  const Vector3d up(0, 0, 1);
  const int index = model.AddNamedView("Front", camera, target, up);
  Check(index == 0, "the first real AddNamedView() call returns index 0");
  Check(model.NamedViewCount() == 1, "model has one named view after AddNamedView()");

  const NamedViewInfo info = model.NamedViewAt(0);
  Check(info.name == "Front", "NamedViewAt(0) reports the name AddNamedView() was given");
  Check(info.camera_location.DistanceTo(camera) < 1e-9,
        "NamedViewAt(0) reports the exact camera_location AddNamedView() was given");
  Check(info.target_point.DistanceTo(target) < 1e-9,
        "NamedViewAt(0) reports the exact target_point AddNamedView() was given");
  Check((info.camera_up - up).Length() < 1e-9,
        "NamedViewAt(0) reports the exact camera_up AddNamedView() was given");

  const NamedViewInfo out_of_range = model.NamedViewAt(5);
  Check(out_of_range.name.empty(),
        "NamedViewAt() on an index this model doesn't have returns a default-constructed "
        "NamedViewInfo, same contract as LayerAt()/MaterialAt() etc.");

  // A degenerate view (camera_location == target_point, no direction to
  // derive) doesn't crash and still leaves the viewport with a valid
  // camera direction - AddNamedView()'s own documented (0, 0, -1) fallback.
  model.AddNamedView("Degenerate", Point3d(1, 2, 3), Point3d(1, 2, 3));
  Check(model.NamedViewCount() == 2, "the degenerate-view call still adds a named view");

  // Real .3dm round trip: ON_3dmSettings::m_named_views is part of the
  // settings chunk ONX_Model::Write/Read already carries through
  // unmodified, the same situation SetUnitSystem() found for its own
  // field - so no Save()/Load() change was needed to make this round-trip.
  const std::string path = "dino8_kernel_model_named_view_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with named views succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.NamedViewCount() == 2, "both named views survive the .3dm round trip");
  const NamedViewInfo reloaded = loaded.NamedViewAt(0);
  Check(reloaded.name == "Front", "the reloaded named view's name survives the round trip");
  Check(reloaded.camera_location.DistanceTo(camera) < 1e-6,
        "the reloaded named view's camera_location survives the round trip");
  Check(reloaded.target_point.DistanceTo(target) < 1e-6,
        "the reloaded named view's target_point survives the round trip");
  Check((reloaded.camera_up - up).Length() < 1e-6,
        "the reloaded named view's camera_up survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddLayoutRoundTrips() {
  using dino8::kernel::LayoutInfo;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  Model model;
  Check(model.LayoutCount() == 0, "a fresh Model has no layouts");
  Check(model.AddLayout("", 297.0, 210.0) == -1,
        "AddLayout() returns -1 for an empty name, same contract as AddLayer() etc.");
  Check(model.AddLayout("Bad width", 0.0, 210.0) == -1,
        "AddLayout() returns -1 for a non-positive page_width_mm");
  Check(model.AddLayout("Bad height", 297.0, -5.0) == -1,
        "AddLayout() returns -1 for a non-positive page_height_mm");
  Check(model.LayoutCount() == 0, "none of the rejected calls above added a layout");

  const int index = model.AddLayout("A4 Landscape", 297.0, 210.0);
  Check(index == 0, "the first real AddLayout() call returns index 0");
  Check(model.LayoutCount() == 1, "model has one layout after AddLayout()");

  const LayoutInfo info = model.LayoutAt(0);
  Check(info.name == "A4 Landscape", "LayoutAt(0) reports the name AddLayout() was given");
  Check(std::abs(info.page_width_mm - 297.0) < 1e-9,
        "LayoutAt(0) reports the exact page_width_mm AddLayout() was given");
  Check(std::abs(info.page_height_mm - 210.0) < 1e-9,
        "LayoutAt(0) reports the exact page_height_mm AddLayout() was given");

  const LayoutInfo out_of_range = model.LayoutAt(5);
  Check(out_of_range.name.empty(),
        "LayoutAt() on an index this model doesn't have returns a default-constructed "
        "LayoutInfo, same contract as NamedViewAt()/LayerAt() etc.");

  model.AddLayout("A3 Portrait", 297.0, 420.0);
  Check(model.LayoutCount() == 2, "a second AddLayout() call adds a second layout");

  // Real .3dm round trip: ON_3dmSettings::m_views (distinct from
  // m_named_views above) is part of the settings chunk ONX_Model::Write/
  // Read already carries through unmodified, the same situation
  // AddNamedView() itself found for its own table - so no Save()/Load()
  // change was needed to make this round-trip either.
  const std::string path = "dino8_kernel_model_layout_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with layouts succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.LayoutCount() == 2, "both layouts survive the .3dm round trip");
  const LayoutInfo reloaded0 = loaded.LayoutAt(0);
  Check(reloaded0.name == "A4 Landscape", "the first reloaded layout's name survives the round trip");
  Check(std::abs(reloaded0.page_width_mm - 297.0) < 1e-6,
        "the first reloaded layout's page_width_mm survives the round trip");
  Check(std::abs(reloaded0.page_height_mm - 210.0) < 1e-6,
        "the first reloaded layout's page_height_mm survives the round trip");
  const LayoutInfo reloaded1 = loaded.LayoutAt(1);
  Check(reloaded1.name == "A3 Portrait", "the second reloaded layout's name survives the round trip");
  Check(std::abs(reloaded1.page_width_mm - 297.0) < 1e-6,
        "the second reloaded layout's page_width_mm survives the round trip");
  Check(std::abs(reloaded1.page_height_mm - 420.0) < 1e-6,
        "the second reloaded layout's page_height_mm survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddDetailViewRoundTrips() {
  using dino8::kernel::DetailViewInfo;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  // Closes the one item AddLayout() above explicitly disclosed as not
  // attempted: "Detail views (the viewport windows placed ON a layout,
  // each framing part of model space at its own scale) are a separate,
  // larger ON_Viewport-per-detail feature this call does not attempt - a
  // layout added here has a page size but no details on it yet." Before
  // this, nothing in this kernel could create an ON_DetailView at all.
  Model model;
  Check(model.DetailViewCount() == 0, "a fresh Model has no detail views");

  const int layout0 = model.AddLayout("A4 Landscape", 297.0, 210.0);
  const int layout1 = model.AddLayout("A3 Portrait", 297.0, 420.0);
  Check(layout0 == 0 && layout1 == 1, "both layouts were added at the expected indices");

  Check(model.AddDetailView(layout1, 10.0, 20.0, 150.0, 100.0, 0.02083, "") == -1,
        "AddDetailView() returns -1 for an empty name, same contract as AddLight() etc.");
  Check(model.AddDetailView(9999, 10.0, 20.0, 150.0, 100.0, 0.02083, "No Such Layout") == -1,
        "AddDetailView() returns -1 for a layout_index this model doesn't have");
  Check(model.AddDetailView(layout1, 10.0, 20.0, 0.0, 100.0, 0.02083, "Bad Width") == -1,
        "AddDetailView() returns -1 for a non-positive width_mm");
  Check(model.AddDetailView(layout1, 10.0, 20.0, 150.0, -5.0, 0.02083, "Bad Height") == -1,
        "AddDetailView() returns -1 for a non-positive height_mm");
  Check(model.DetailViewCount() == 0, "none of the rejected calls above added a detail view");

  const int index =
      model.AddDetailView(layout1, 10.0, 20.0, 150.0, 100.0, 0.02083, "Front View Detail");
  Check(index == 0, "the first real AddDetailView() call returns index 0");
  Check(model.DetailViewCount() == 1, "model has one detail view after AddDetailView()");
  Check(model.ObjectCount() == 1,
        "a detail view is a real model geometry object, also counted by ObjectCount()");

  const DetailViewInfo info = model.DetailViewAt(0);
  Check(info.name == "Front View Detail", "DetailViewAt(0) reports the name AddDetailView() was given");
  Check(info.layout_index == layout1,
        "DetailViewAt(0) resolves layout_index back to the exact layout AddDetailView() was given, "
        "not the other one");
  Check(std::abs(info.x_mm - 10.0) < 1e-9 && std::abs(info.y_mm - 20.0) < 1e-9,
        "DetailViewAt(0) reports the exact x_mm/y_mm AddDetailView() was given");
  Check(std::abs(info.width_mm - 150.0) < 1e-9 && std::abs(info.height_mm - 100.0) < 1e-9,
        "DetailViewAt(0) reports the exact width_mm/height_mm AddDetailView() was given");
  Check(std::abs(info.page_per_model_ratio - 0.02083) < 1e-9,
        "DetailViewAt(0) reports the exact page_per_model_ratio AddDetailView() was given");

  const DetailViewInfo out_of_range = model.DetailViewAt(9999);
  Check(out_of_range.name.empty() && out_of_range.layout_index == -1,
        "DetailViewAt() on an index this model doesn't have returns a default-constructed "
        "DetailViewInfo, same contract as LayoutAt()/HatchAt() etc.");

  const std::string path = "dino8_kernel_model_detail_view_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a detail view succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.DetailViewCount() == 1, "the detail view survives the .3dm round trip");
  Check(loaded.LayoutCount() == 2, "both layouts survive the .3dm round trip too");
  const DetailViewInfo reloaded = loaded.DetailViewAt(0);
  Check(reloaded.name == "Front View Detail", "the reloaded detail view's name survives the round trip");
  Check(reloaded.layout_index == layout1,
        "the reloaded detail view still resolves to the exact layout it was placed on, "
        "matched by that layout's own ON_Viewport::ViewportId() surviving the round trip");
  Check(std::abs(reloaded.x_mm - 10.0) < 1e-6 && std::abs(reloaded.y_mm - 20.0) < 1e-6,
        "the reloaded detail view's x_mm/y_mm survive the round trip");
  Check(std::abs(reloaded.width_mm - 150.0) < 1e-6 && std::abs(reloaded.height_mm - 100.0) < 1e-6,
        "the reloaded detail view's width_mm/height_mm survive the round trip");
  Check(std::abs(reloaded.page_per_model_ratio - 0.02083) < 1e-6,
        "the reloaded detail view's page_per_model_ratio survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddDetailViewCameraRoundTrips() {
  using dino8::kernel::Color;
  using dino8::kernel::DetailViewInfo;
  using dino8::kernel::Model;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::UserStrings;

  // Closes the disclosed narrowing TestModelAddDetailViewRoundTrips's own
  // AddDetailView() call above left open: "this call does not attempt
  // the detail's own nested model-space camera (ON_DetailView::m_view)."
  Model model;
  const int layout = model.AddLayout("A4 Landscape", 297.0, 210.0);

  const int no_camera_index =
      model.AddDetailView(layout, 10.0, 20.0, 150.0, 100.0, 0.02083, "No Camera");
  Check(no_camera_index == 0, "the first AddDetailView() call (no camera) returns index 0");
  const DetailViewInfo no_camera_info = model.DetailViewAt(0);
  Check(!no_camera_info.camera_location.has_value() && !no_camera_info.target_point.has_value(),
        "DetailViewAt() reports no camera for a detail added with neither camera_location nor "
        "target_point - the pre-existing behavior, unchanged by this pass");

  const Point3d camera_location(0, -20, 15);
  const Point3d target_point(0, 0, 0);
  const int index = model.AddDetailView(
      layout, 10.0, 20.0, 150.0, 100.0, 0.02083, "Front Elevation",
      /*layer_index=*/-1, /*render_color=*/std::optional<Color>(std::nullopt),
      /*user_strings=*/UserStrings(), /*linetype_index=*/std::optional<int>(std::nullopt),
      /*group_indices=*/std::vector<int>(), /*material_index=*/std::optional<int>(std::nullopt),
      camera_location, target_point);
  Check(index == 1, "the second real AddDetailView() call (with a camera) returns index 1");

  const DetailViewInfo info = model.DetailViewAt(1);
  Check(info.camera_location.has_value() && info.camera_location->DistanceTo(camera_location) < 1e-9,
        "DetailViewAt() reports the exact camera_location AddDetailView() was given");
  Check(info.target_point.has_value() && info.target_point->DistanceTo(target_point) < 1e-9,
        "DetailViewAt() reports the exact target_point AddDetailView() was given");

  const std::string path = "dino8_kernel_model_detail_view_camera_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a detail view camera succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  const DetailViewInfo reloaded_no_camera = loaded.DetailViewAt(0);
  Check(!reloaded_no_camera.camera_location.has_value(),
        "the reloaded no-camera detail view still reports no camera after the round trip");
  const DetailViewInfo reloaded = loaded.DetailViewAt(1);
  Check(reloaded.camera_location.has_value() &&
            reloaded.camera_location->DistanceTo(camera_location) < 1e-6,
        "the reloaded detail view's camera_location survives the round trip");
  Check(reloaded.target_point.has_value() && reloaded.target_point->DistanceTo(target_point) < 1e-6,
        "the reloaded detail view's target_point survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddExtrusionRoundTrips() {
  using dino8::kernel::ExtrusionInfo;
  using dino8::kernel::Model;
  using dino8::kernel::Point2d;
  using dino8::kernel::Result;

  // Closes the "extrusions" item PARITY_MAP.md's own ".3dm attribute/
  // metadata fidelity" bullet's own opening enumeration names - before
  // this, nothing in this kernel's Model wrapper could create an
  // ON_Extrusion at all.
  Model model;
  Check(model.ExtrusionCount() == 0, "a fresh Model has no extrusions");

  // A counter-clockwise rectangle (standard x-right/y-up orientation),
  // chosen so ON_Extrusion::SetOuterProfile()'s own automatic winding
  // correction is a no-op - the reloaded profile should come back in the
  // exact same order it was given, not reversed.
  const std::vector<Point2d> rectangle = {Point2d(0, 0), Point2d(10, 0), Point2d(10, 5),
                                           Point2d(0, 5)};

  Check(model.AddExtrusion(rectangle, 20.0, true, "") == -1,
        "AddExtrusion() returns -1 for an empty name, same contract as AddLight() etc.");
  const std::vector<Point2d> too_few = {Point2d(0, 0), Point2d(1, 0)};
  Check(model.AddExtrusion(too_few, 20.0, true, "Too Few Points") == -1,
        "AddExtrusion() returns -1 for a profile with fewer than 3 points");
  Check(model.AddExtrusion(rectangle, 0.0, true, "Bad Path Length") == -1,
        "AddExtrusion() returns -1 for a non-positive path_length");
  Check(model.AddExtrusion(rectangle, -5.0, true, "Negative Path Length") == -1,
        "AddExtrusion() returns -1 for a negative path_length");
  Check(model.ExtrusionCount() == 0, "none of the rejected calls above added an extrusion");

  const int index = model.AddExtrusion(rectangle, 20.0, true, "Rect Tube");
  Check(index == 0, "the first real AddExtrusion() call returns index 0");
  Check(model.ExtrusionCount() == 1, "model has one extrusion after AddExtrusion()");
  Check(model.ObjectCount() == 1,
        "an extrusion is a real model geometry object, also counted by ObjectCount()");

  const ExtrusionInfo info = model.ExtrusionAt(0);
  Check(info.name == "Rect Tube", "ExtrusionAt(0) reports the name AddExtrusion() was given");
  Check(std::abs(info.path_length - 20.0) < 1e-9,
        "ExtrusionAt(0) reports the exact path_length AddExtrusion() was given");
  Check(info.capped, "ExtrusionAt(0) reports capped == true, matching the capped argument given");
  Check(info.profile.size() == rectangle.size(),
        "ExtrusionAt(0) reports the same number of profile points AddExtrusion() was given");
  for (size_t i = 0; i < rectangle.size() && i < info.profile.size(); ++i) {
    Check(info.profile[i].DistanceTo(rectangle[i]) < 1e-9,
          "ExtrusionAt(0) reports the exact profile point AddExtrusion() was given, in the same "
          "order - the rectangle's own counter-clockwise winding needed no correction");
  }

  const int uncapped_index = model.AddExtrusion(rectangle, 8.0, false, "Open Sheet");
  Check(uncapped_index == 1, "a second AddExtrusion() call (uncapped) returns index 1");
  const ExtrusionInfo uncapped_info = model.ExtrusionAt(1);
  Check(!uncapped_info.capped, "an extrusion added with capped=false reports capped == false");

  const ExtrusionInfo out_of_range = model.ExtrusionAt(9999);
  Check(out_of_range.name.empty() && out_of_range.profile.empty(),
        "ExtrusionAt() on an index this model doesn't have returns a default-constructed "
        "ExtrusionInfo, same contract as DetailViewAt()/HatchAt() etc.");

  const std::string path = "dino8_kernel_model_extrusion_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with two extrusions succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.ExtrusionCount() == 2, "both extrusions survive the .3dm round trip");
  const ExtrusionInfo reloaded = loaded.ExtrusionAt(0);
  Check(reloaded.name == "Rect Tube", "the reloaded extrusion's name survives the round trip");
  Check(std::abs(reloaded.path_length - 20.0) < 1e-6,
        "the reloaded extrusion's path_length survives the round trip");
  Check(reloaded.capped, "the reloaded extrusion's capped flag survives the round trip");
  Check(reloaded.profile.size() == rectangle.size(),
        "the reloaded extrusion's profile point count survives the round trip");
  for (size_t i = 0; i < rectangle.size() && i < reloaded.profile.size(); ++i) {
    Check(reloaded.profile[i].DistanceTo(rectangle[i]) < 1e-6,
          "the reloaded extrusion's profile points survive the round trip, in order");
  }
  const ExtrusionInfo reloaded_uncapped = loaded.ExtrusionAt(1);
  Check(!reloaded_uncapped.capped,
        "the reloaded second extrusion's capped == false survives the round trip");

  std::remove(path.c_str());
}

void TestModelMaterialExtendedFieldsRoundTrip() {
  using dino8::kernel::Color;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  Model model;
  const int plain_index = model.AddMaterial("PlainRed", Color{200, 20, 20});
  const int full_index =
      model.AddMaterial("ChromeLike", Color{10, 10, 10}, Color{250, 250, 250},
                         Color{5, 5, 5}, 200.0, 0.25, 0.9);

  const std::string path = "dino8_kernel_model_material_extended_fields_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  const auto plain = loaded.MaterialAt(plain_index);
  Check(plain.diffuse_color.r == 200 && plain.diffuse_color.g == 20 && plain.diffuse_color.b == 20,
        "a material added with only diffuse_color still round-trips that field exactly");
  Check(plain.shine == 0.0 && plain.transparency == 0.0 && plain.reflectivity == 0.0,
        "a material added with no specular/emission/shine/transparency/reflectivity arguments "
        "reads back ON_Material's own constructor defaults, not garbage");

  const auto full = loaded.MaterialAt(full_index);
  Check(full.diffuse_color.r == 10 && full.diffuse_color.g == 10 && full.diffuse_color.b == 10,
        "diffuse_color still round-trips when every other field is also given");
  Check(full.specular_color.r == 250 && full.specular_color.g == 250 && full.specular_color.b == 250,
        "specular_color round-trips through an actual .3dm save/load");
  Check(full.emission_color.r == 5 && full.emission_color.g == 5 && full.emission_color.b == 5,
        "emission_color round-trips through an actual .3dm save/load");
  Check(std::abs(full.shine - 200.0) < 1e-6, "shine round-trips through an actual .3dm save/load");
  Check(std::abs(full.transparency - 0.25) < 1e-9,
        "transparency round-trips through an actual .3dm save/load");
  Check(std::abs(full.reflectivity - 0.9) < 1e-9,
        "reflectivity round-trips through an actual .3dm save/load");

  std::remove(path.c_str());
}

void TestModelMaterialTextureRoundTrips() {
  using dino8::kernel::Color;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  // A plain relative path, not a Windows-style "C:/..." one: OpenNURBS'
  // own ON_FileReference::SetFullPath() runs every path through
  // ON_FileSystemPath::CleanPath(), whose own documented contract is "If
  // the Platform is not windows, the UNC host names and volume letters
  // are deleted" - a "C:/..." fixture would silently lose its drive
  // letter on this (Linux) test run, failing this test over the fixture's
  // own platform-specific path, not over AddMaterial()/MaterialAt()
  // themselves. "textures/checker.png" has no drive letter or UNC prefix
  // to strip, so it round-trips unchanged on every platform this suite runs on.
  const std::string texture_path = "textures/checker.png";

  Model model;
  const int untextured_index = model.AddMaterial("PlainRed", Color{200, 20, 20});
  const int textured_index =
      model.AddMaterial("Checkerboard", Color{255, 255, 255}, std::nullopt, std::nullopt,
                         std::nullopt, std::nullopt, std::nullopt, texture_path);

  Check(!model.MaterialAt(untextured_index).texture_filename.has_value(),
        "a material added with no texture_filename reports std::nullopt, not an empty string "
        "standing in for 'no texture'");
  Check(model.MaterialAt(textured_index).texture_filename == texture_path,
        "a material's texture_filename reads back exactly, in memory before any save");

  const std::string path = "dino8_kernel_model_material_texture_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");

  Check(!loaded.MaterialAt(untextured_index).texture_filename.has_value(),
        "the untextured material still reports std::nullopt after a real .3dm save/reload");
  Check(loaded.MaterialAt(textured_index).texture_filename == texture_path,
        "the textured material's filename round-trips exactly through a real .3dm save/reload");
  Check(loaded.MaterialAt(textured_index).diffuse_color.r == 255,
        "adding a texture_filename doesn't disturb this same call's own diffuse_color");

  std::remove(path.c_str());
}

void TestModelAddLightRoundTrips() {
  using dino8::kernel::Color;
  using dino8::kernel::LightInfo;
  using dino8::kernel::LightStyle;
  using dino8::kernel::Model;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  Model model;
  Check(model.LightCount() == 0, "a fresh Model has no lights");
  Check(model.AddLight("", LightStyle::Point, Point3d(0, 0, 0), Vector3d(0, 0, -1)) == -1,
        "AddLight() returns -1 for an empty name, same contract as AddLayer()/AddNamedView() etc.");
  Check(model.LightCount() == 0, "the empty-name call above added nothing");

  const Point3d bulb_location(1, 2, 3);
  const int point_index = model.AddLight("Bulb", LightStyle::Point, bulb_location,
                                          Vector3d(0, 0, -1), Color{255, 200, 150}, 0.75);
  Check(point_index == 0, "the first real AddLight() call returns index 0");
  Check(model.LightCount() == 1, "model has one light after AddLight()");

  const Vector3d sun_direction(1, -1, -1);
  const int sun_index = model.AddLight("Sun", LightStyle::Directional, Point3d(0, 0, 0),
                                        sun_direction);
  Check(sun_index == 1, "a second AddLight() call returns index 1, among lights specifically");
  Check(model.LightCount() == 2, "model has two lights after the second AddLight()");

  // A light is filed under its own ON_ModelComponent::Type::RenderLight
  // (ON_ModelGeometryComponent::Geometry()'s own documented contract),
  // not the plain ModelGeometry table AddMesh()/AddBrep() use - so it
  // does NOT show up in ObjectCount(), unlike a clipping plane (see
  // TestModelAddClippingPlaneRoundTrips() below, which is NOT
  // special-cased this way).
  Check(model.ObjectCount() == 0,
        "a light lives only in LightCount()'s own table, not ObjectCount()'s");

  const LightInfo bulb = model.LightAt(point_index);
  Check(bulb.name == "Bulb", "LightAt() reports the name AddLight() was given");
  Check(bulb.style == LightStyle::Point, "LightAt() reports the style AddLight() was given");
  Check(bulb.location.DistanceTo(bulb_location) < 1e-9,
        "LightAt() reports the exact location AddLight() was given");
  Check(bulb.diffuse_color.r == 255 && bulb.diffuse_color.g == 200 && bulb.diffuse_color.b == 150,
        "LightAt() reports the exact diffuse_color AddLight() was given");
  Check(std::abs(bulb.intensity - 0.75) < 1e-9,
        "LightAt() reports the exact intensity AddLight() was given");

  const LightInfo sun = model.LightAt(sun_index);
  Check(sun.name == "Sun" && sun.style == LightStyle::Directional,
        "the second light's name/style are independent of the first");
  Check((sun.direction - sun_direction).Length() < 1e-9,
        "LightAt() reports the exact direction AddLight() was given, unmodified - "
        "ON_Light::SetDirection() stores it raw, with no unitization");

  const LightInfo out_of_range = model.LightAt(9999);
  Check(out_of_range.name.empty(),
        "LightAt() on an index this model doesn't have returns a default-constructed LightInfo, "
        "same contract as NamedViewAt()/MaterialAt() etc.");

  const std::string path = "dino8_kernel_model_light_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with lights succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.LightCount() == 2, "both lights survive the .3dm round trip");
  const LightInfo reloaded_bulb = loaded.LightAt(point_index);
  Check(reloaded_bulb.name == "Bulb", "the reloaded light's name survives the round trip");
  Check(reloaded_bulb.style == LightStyle::Point,
        "the reloaded light's style survives the round trip");
  Check(reloaded_bulb.location.DistanceTo(bulb_location) < 1e-6,
        "the reloaded light's location survives the round trip");
  Check(std::abs(reloaded_bulb.intensity - 0.75) < 1e-6,
        "the reloaded light's intensity survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddClippingPlaneRoundTrips() {
  using dino8::kernel::Model;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  Model model;
  Check(model.ClippingPlaneCount() == 0, "a fresh Model has no clipping planes");
  Check(model.AddClippingPlane("", Point3d(0, 0, 0), Vector3d(0, 0, 1)) == -1,
        "AddClippingPlane() returns -1 for an empty name, same contract as AddLight() etc.");
  Check(model.AddClippingPlane("Degenerate", Point3d(0, 0, 0), Vector3d(0, 0, 0)) == -1,
        "AddClippingPlane() returns -1 for a zero normal (not a valid plane), rather than "
        "silently writing a broken one");
  Check(model.ClippingPlaneCount() == 0, "neither refused call above added anything");

  const Point3d origin(1, 2, 3);
  const Vector3d normal(0, 0, 1);
  const int index = model.AddClippingPlane("Section A", origin, normal, /*enabled=*/false);
  Check(index == 0, "the first real AddClippingPlane() call returns index 0");
  Check(model.ClippingPlaneCount() == 1, "model has one clipping plane after AddClippingPlane()");
  Check(model.ObjectCount() == 1,
        "a clipping plane is a real model geometry object, also counted by ObjectCount()");

  const auto plane = model.ClippingPlaneAt(0);
  Check(plane.name == "Section A", "ClippingPlaneAt() reports the name AddClippingPlane() was given");
  Check(plane.origin.DistanceTo(origin) < 1e-9,
        "ClippingPlaneAt() reports the exact origin AddClippingPlane() was given");
  Check((plane.normal - normal).Length() < 1e-9,
        "ClippingPlaneAt() reports the exact normal AddClippingPlane() was given");
  Check(plane.enabled == false,
        "ClippingPlaneAt() reports the exact enabled flag AddClippingPlane() was given");

  const auto out_of_range = model.ClippingPlaneAt(9999);
  Check(out_of_range.name.empty(),
        "ClippingPlaneAt() on an index this model doesn't have returns a default-constructed "
        "ClippingPlaneInfo, same contract as LightAt()/NamedViewAt() etc.");

  const std::string path = "dino8_kernel_model_clipping_plane_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a clipping plane succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.ClippingPlaneCount() == 1, "the clipping plane survives the .3dm round trip");
  const auto reloaded = loaded.ClippingPlaneAt(0);
  Check(reloaded.name == "Section A", "the reloaded clipping plane's name survives the round trip");
  Check(reloaded.origin.DistanceTo(origin) < 1e-6,
        "the reloaded clipping plane's origin survives the round trip");
  Check((reloaded.normal - normal).Length() < 1e-6,
        "the reloaded clipping plane's normal survives the round trip");
  Check(reloaded.enabled == false,
        "the reloaded clipping plane's enabled flag survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddInstanceReferenceRoundTrips() {
  using dino8::kernel::Mesh;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  // PARITY_MAP.md's own "kernel: Kernel-level data exchange" evidence for
  // ".3dm composite objects" names block instances as entirely missing:
  // before this, nothing in this kernel could create an
  // ON_InstanceDefinition/ON_InstanceRef pair at all.
  const auto box = MakeQuadBoxMesh(0, 0, 0, 1, 1, 1);
  Model model;
  Check(model.InstanceDefinitionCount() == 0, "a fresh Model has no instance definitions");
  Check(model.AddInstanceDefinition("", {box}) == -1,
        "AddInstanceDefinition() returns -1 for an empty name, same contract as AddLayer() etc.");
  Check(model.AddInstanceDefinition("Empty", {}) == -1,
        "AddInstanceDefinition() returns -1 for no member geometry - nothing to define");
  Check(model.InstanceDefinitionCount() == 0, "neither refused call above added anything");

  const int def_index = model.AddInstanceDefinition("Block A", {box});
  Check(def_index == 0, "the first real AddInstanceDefinition() call returns index 0");
  Check(model.InstanceDefinitionCount() == 1, "model has one instance definition after AddInstanceDefinition()");
  Check(model.InstanceDefinitionNameAt(def_index) == "Block A",
        "InstanceDefinitionNameAt() reports the name AddInstanceDefinition() was given");
  Check(model.InstanceDefinitionMemberMeshCount(def_index) == 1,
        "the definition has exactly the one member mesh it was created with");
  Check(model.ObjectCount() == 0,
        "a block's own member geometry does NOT show up in ObjectCount() - it's marked "
        "ON::idef_object, not an ordinary scene object");
  const Mesh member = model.InstanceDefinitionMemberMeshAt(def_index, 0);
  Check(member.VertexCount() == box.VertexCount() && member.FaceCount() == box.FaceCount(),
        "InstanceDefinitionMemberMeshAt() reports the same mesh AddInstanceDefinition() was given");

  Check(model.AddInstanceReference(9999, ON_Xform::IdentityTransformation) == -1,
        "AddInstanceReference() returns -1 for a definition_index this model doesn't have");
  Check(model.InstanceReferenceCount() == 0, "the refused call above added nothing");

  const ON_Xform xform = ON_Xform::TranslationTransformation(ON_3dVector(5, 6, 7));
  const int ref_index = model.AddInstanceReference(def_index, xform, "Insert 1");
  Check(ref_index == 0, "the first real AddInstanceReference() call returns index 0");
  Check(model.InstanceReferenceCount() == 1, "model has one instance reference after AddInstanceReference()");
  Check(model.ObjectCount() == 1,
        "an instance reference IS an ordinary ModelGeometry object, unlike its own definition's "
        "member geometry above");

  const auto placement = model.InstanceReferenceAt(0);
  Check(placement.name == "Insert 1", "InstanceReferenceAt() reports the name AddInstanceReference() was given");
  Check(placement.definition_index == def_index,
        "InstanceReferenceAt() reports the definition_index AddInstanceReference() was given");
  Check(placement.transform == xform,
        "InstanceReferenceAt() reports the exact transform AddInstanceReference() was given");

  const auto out_of_range = model.InstanceReferenceAt(9999);
  Check(out_of_range.name.empty() && out_of_range.definition_index == -1,
        "InstanceReferenceAt() on an index this model doesn't have returns a default-constructed "
        "InstanceReferenceInfo, same contract as LightAt()/ClippingPlaneAt() etc.");

  const std::string path = "dino8_kernel_model_instance_reference_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a block instance succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.InstanceDefinitionCount() == 1, "the instance definition survives the .3dm round trip");
  Check(loaded.InstanceDefinitionNameAt(0) == "Block A",
        "the reloaded instance definition's name survives the round trip");
  Check(loaded.InstanceDefinitionMemberMeshCount(0) == 1,
        "the reloaded instance definition still has its one member mesh");
  const Mesh reloaded_member = loaded.InstanceDefinitionMemberMeshAt(0, 0);
  Check(reloaded_member.VertexCount() == box.VertexCount() && reloaded_member.FaceCount() == box.FaceCount(),
        "the reloaded member mesh's vertex/face counts survive the round trip");
  Check(loaded.InstanceReferenceCount() == 1, "the instance reference survives the .3dm round trip");
  const auto reloaded_ref = loaded.InstanceReferenceAt(0);
  Check(reloaded_ref.name == "Insert 1", "the reloaded instance reference's name survives the round trip");
  Check(reloaded_ref.definition_index == 0,
        "the reloaded instance reference still points at the (only) instance definition");
  Check(reloaded_ref.transform == xform,
        "the reloaded instance reference's transform survives the round trip exactly (a pure "
        "translation, representable exactly in a .3dm's own double-precision xform)");

  std::remove(path.c_str());
}

void TestModelAddHatchRoundTrips() {
  using dino8::kernel::HatchFillType;
  using dino8::kernel::Model;
  using dino8::kernel::Point2d;
  using dino8::kernel::Result;

  // PARITY_MAP.md's own "kernel: Kernel-level data exchange" evidence for
  // ".3dm composite objects" names hatches as entirely missing: before
  // this, nothing in this kernel could create an ON_Hatch at all.
  Model model;
  Check(model.HatchPatternCount() == 0, "a fresh Model has no hatch patterns");
  Check(model.AddHatchPattern("") == -1,
        "AddHatchPattern() returns -1 for an empty name, same contract as AddLayer() etc.");
  const int pattern_index = model.AddHatchPattern("Solid Fill", HatchFillType::Solid);
  Check(pattern_index == 0, "the first real AddHatchPattern() call returns index 0");
  Check(model.HatchPatternCount() == 1, "model has one hatch pattern after AddHatchPattern()");

  const std::vector<Point2d> square = {Point2d(0, 0), Point2d(2, 0), Point2d(2, 2), Point2d(0, 2)};
  Check(model.AddHatch(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), square, /*pattern_index=*/-1) ==
            -1,
        "AddHatch() returns -1 for a negative pattern_index, even though ON_HatchPattern::Solid "
        "itself is index -1 - see AddHatchPattern()'s own doc comment for why");
  Check(model.AddHatch(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), {Point2d(0, 0), Point2d(1, 0)},
                        pattern_index) == -1,
        "AddHatch() returns -1 for a boundary with fewer than 3 points");
  Check(model.HatchCount() == 0, "none of the refused calls above added anything");

  const ON_Plane plane(ON_3dPoint(1, 2, 3), ON_3dVector(0, 0, 1));
  const int hatch_index =
      model.AddHatch(plane, square, pattern_index, /*pattern_rotation=*/0.1, /*pattern_scale=*/2.0, "Hatch A");
  Check(hatch_index == 0, "the first real AddHatch() call returns index 0");
  Check(model.HatchCount() == 1, "model has one hatch after AddHatch()");
  Check(model.ObjectCount() == 1, "a hatch is a real model geometry object, also counted by ObjectCount()");

  const auto hatch_info = model.HatchAt(0);
  Check(hatch_info.name == "Hatch A", "HatchAt() reports the name AddHatch() was given");
  Check(hatch_info.plane.origin.DistanceTo(plane.origin) < 1e-9,
        "HatchAt() reports the exact plane origin AddHatch() was given");
  Check(hatch_info.pattern_index == pattern_index,
        "HatchAt() reports the exact pattern_index AddHatch() was given");
  Check(std::abs(hatch_info.pattern_rotation - 0.1) < 1e-9,
        "HatchAt() reports the exact pattern_rotation AddHatch() was given");
  Check(std::abs(hatch_info.pattern_scale - 2.0) < 1e-9,
        "HatchAt() reports the exact pattern_scale AddHatch() was given");
  Check(hatch_info.boundary.size() == square.size(),
        "HatchAt() reports a boundary with the same point count AddHatch() was given");
  bool boundary_matches = hatch_info.boundary.size() == square.size();
  for (size_t i = 0; boundary_matches && i < square.size(); ++i) {
    if (hatch_info.boundary[i].DistanceTo(square[i]) > 1e-9) boundary_matches = false;
  }
  Check(boundary_matches, "HatchAt() reports the exact boundary points AddHatch() was given, in order");

  const std::string path = "dino8_kernel_model_hatch_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a hatch succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.HatchCount() == 1, "the hatch survives the .3dm round trip");
  const auto reloaded = loaded.HatchAt(0);
  Check(reloaded.name == "Hatch A", "the reloaded hatch's name survives the round trip");
  Check(reloaded.plane.origin.DistanceTo(plane.origin) < 1e-6,
        "the reloaded hatch's plane origin survives the round trip");
  Check(std::abs(reloaded.pattern_rotation - 0.1) < 1e-6,
        "the reloaded hatch's pattern_rotation survives the round trip");
  Check(std::abs(reloaded.pattern_scale - 2.0) < 1e-6,
        "the reloaded hatch's pattern_scale survives the round trip");
  Check(reloaded.boundary.size() == square.size(),
        "the reloaded hatch's boundary point count survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddHatchPatternLinesRoundTrips() {
  using dino8::kernel::HatchFillType;
  using dino8::kernel::HatchPatternLine;
  using dino8::kernel::Model;
  using dino8::kernel::Point2d;
  using dino8::kernel::Result;

  // HatchFillType's own doc comment in file_io.h names this exact gap: "a
  // Lines pattern this kernel creates always has zero lines in it... this
  // kernel adds no way to populate its actual dash/offset lines via
  // ON_HatchPattern::AddHatchLine()" - PARITY_MAP.md's own evidence for the
  // same item. Before this, AddHatchPattern() had no `lines` parameter at
  // all.
  Model model;
  const int empty_pattern = model.AddHatchPattern("No Lines", HatchFillType::Lines);
  Check(empty_pattern == 0, "AddHatchPattern() with no lines argument still succeeds, unchanged behavior");
  Check(model.HatchPatternLineCount(empty_pattern) == 0,
        "a pattern added with no lines argument has zero lines - the pre-existing behavior, unchanged");

  HatchPatternLine solid_line;
  solid_line.angle_radians = 0.0;
  solid_line.base = Point2d(0.0, 0.0);
  solid_line.offset = Point2d(0.0, 0.5);
  // no dashes - a solid line, ON_HatchLine's own "no dashes means solid" contract

  HatchPatternLine dashed_line;
  dashed_line.angle_radians = ON_PI / 2.0;  // vertical
  dashed_line.base = Point2d(0.25, 0.0);
  dashed_line.offset = Point2d(0.0, 0.5);
  dashed_line.dashes = {0.25, -0.125, 0.25};  // dash, gap, dash

  const int pattern_index =
      model.AddHatchPattern("Cross-Hatch", HatchFillType::Lines, {solid_line, dashed_line});
  Check(pattern_index == 1, "the second AddHatchPattern() call returns index 1");
  Check(model.HatchPatternLineCount(pattern_index) == 2,
        "the pattern has exactly the 2 lines AddHatchPattern()'s own lines argument gave it");

  const auto line0 = model.HatchPatternLineAt(pattern_index, 0);
  Check(std::abs(line0.angle_radians - 0.0) < 1e-9, "the first line's angle survives HatchPatternLineAt()");
  Check(line0.base.DistanceTo(ON_2dPoint(0.0, 0.0)) < 1e-9, "the first line's base survives HatchPatternLineAt()");
  Check(line0.offset.DistanceTo(ON_2dPoint(0.0, 0.5)) < 1e-9,
        "the first line's offset survives HatchPatternLineAt()");
  Check(line0.dashes.empty(), "the first (solid) line reports no dashes");

  const auto line1 = model.HatchPatternLineAt(pattern_index, 1);
  Check(std::abs(line1.angle_radians - ON_PI / 2.0) < 1e-9, "the second line's angle survives HatchPatternLineAt()");
  Check(line1.base.DistanceTo(ON_2dPoint(0.25, 0.0)) < 1e-9,
        "the second line's base survives HatchPatternLineAt()");
  Check(line1.dashes.size() == 3, "the second line's dash count survives HatchPatternLineAt()");
  Check(line1.dashes.size() == 3 && std::abs(line1.dashes[0] - 0.25) < 1e-9 &&
            std::abs(line1.dashes[1] - (-0.125)) < 1e-9 && std::abs(line1.dashes[2] - 0.25) < 1e-9,
        "the second line's exact dash/gap lengths, in order, survive HatchPatternLineAt()");

  const auto out_of_range = model.HatchPatternLineAt(pattern_index, 9999);
  Check(out_of_range.dashes.empty() && std::abs(out_of_range.angle_radians) < 1e-12,
        "HatchPatternLineAt() on a line index this pattern doesn't have returns a "
        "default-constructed HatchPatternLine, same contract as HatchAt()/TextDotAt() etc.");
  Check(model.HatchPatternLineCount(9999) == 0,
        "HatchPatternLineCount() on a pattern index this model doesn't have returns 0");

  const std::string path = "dino8_kernel_model_hatch_pattern_lines_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a lined hatch pattern succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.HatchPatternLineCount(pattern_index) == 2,
        "both lines survive the .3dm round trip");
  const auto reloaded_line1 = loaded.HatchPatternLineAt(pattern_index, 1);
  Check(std::abs(reloaded_line1.angle_radians - ON_PI / 2.0) < 1e-6,
        "the reloaded second line's angle survives the .3dm round trip");
  Check(reloaded_line1.dashes.size() == 3 && std::abs(reloaded_line1.dashes[0] - 0.25) < 1e-6,
        "the reloaded second line's dash lengths survive the .3dm round trip");

  std::remove(path.c_str());
}

void TestModelAddHatchHolesRoundTrips() {
  using dino8::kernel::HatchFillType;
  using dino8::kernel::Model;
  using dino8::kernel::Point2d;
  using dino8::kernel::Result;

  // PARITY_MAP.md's own "kernel: Kernel-level data exchange" evidence for
  // "Rhino non-geometry/composite objects in .3dm" named this directly:
  // "ON_Hatch (single outer loop, given as plane-relative (u, v) points -
  // no inner loops/holes)" - before this, AddHatch() had no way to give a
  // hatch a hole at all, no matter how many loops ON_Hatch::Create()
  // itself could already accept.
  Model model;
  const int pattern_index = model.AddHatchPattern("Solid Fill", HatchFillType::Solid);
  Check(pattern_index == 0, "the first AddHatchPattern() call returns index 0");

  const ON_Plane plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1));
  const std::vector<Point2d> outer = {Point2d(0, 0), Point2d(4, 0), Point2d(4, 4), Point2d(0, 4)};
  const std::vector<Point2d> hole = {Point2d(1, 1), Point2d(2, 1), Point2d(2, 2), Point2d(1, 2)};

  Check(model.AddHatch(plane, outer, pattern_index, 0.0, 1.0, "Bad Hole", -1, std::nullopt,
                        dino8::kernel::UserStrings(), std::nullopt, std::vector<int>(), std::nullopt,
                        {{Point2d(0, 0), Point2d(1, 0)}}) == -1,
        "AddHatch() returns -1 when a hole has fewer than 3 points, same contract the outer "
        "boundary already has");
  Check(model.HatchCount() == 0, "the refused call above added nothing - not even a hatch with no holes");

  const int hatch_index =
      model.AddHatch(plane, outer, pattern_index, 0.0, 1.0, "Annulus", -1, std::nullopt,
                      dino8::kernel::UserStrings(), std::nullopt, std::vector<int>(), std::nullopt, {hole});
  Check(hatch_index == 0, "the first real AddHatch() call with a hole returns index 0");
  Check(model.HatchCount() == 1, "model has one hatch after AddHatch()");

  const auto info = model.HatchAt(0);
  Check(info.boundary.size() == outer.size(),
        "HatchAt() still reports the outer boundary with the exact point count AddHatch() was given");
  Check(info.hole_boundaries.size() == 1, "HatchAt() reports exactly the one hole AddHatch() was given");
  bool hole_matches = info.hole_boundaries.size() == 1 && info.hole_boundaries[0].size() == hole.size();
  for (size_t i = 0; hole_matches && i < hole.size(); ++i) {
    if (info.hole_boundaries[0][i].DistanceTo(hole[i]) > 1e-9) hole_matches = false;
  }
  Check(hole_matches, "HatchAt() reports the exact hole boundary points AddHatch() was given, in order");

  // A second, independent hole: confirms holes compose (not just "exactly
  // one works"), and that hole order survives both construction and the
  // round trip below.
  const std::vector<Point2d> hole2 = {Point2d(3, 3), Point2d(3.5, 3), Point2d(3.5, 3.5)};
  const int two_hole_index =
      model.AddHatch(plane, outer, pattern_index, 0.0, 1.0, "Two Holes", -1, std::nullopt,
                      dino8::kernel::UserStrings(), std::nullopt, std::vector<int>(), std::nullopt,
                      {hole, hole2});
  Check(two_hole_index == 1, "the second AddHatch() call returns index 1");
  const auto two_hole_info = model.HatchAt(1);
  Check(two_hole_info.hole_boundaries.size() == 2,
        "HatchAt() reports both holes when AddHatch() is given two");
  Check(two_hole_info.hole_boundaries.size() == 2 && two_hole_info.hole_boundaries[1].size() == hole2.size(),
        "the second hole's own point count survives, independent of the first hole");

  const std::string path = "dino8_kernel_model_hatch_holes_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a holed hatch succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.HatchCount() == 2, "both hatches survive the .3dm round trip");
  const auto reloaded = loaded.HatchAt(0);
  Check(reloaded.hole_boundaries.size() == 1, "the single-hole hatch's hole count survives the round trip");
  bool reloaded_hole_matches =
      reloaded.hole_boundaries.size() == 1 && reloaded.hole_boundaries[0].size() == hole.size();
  for (size_t i = 0; reloaded_hole_matches && i < hole.size(); ++i) {
    if (reloaded.hole_boundaries[0][i].DistanceTo(hole[i]) > 1e-6) reloaded_hole_matches = false;
  }
  Check(reloaded_hole_matches, "the reloaded hole's exact boundary points survive the round trip");
  const auto reloaded_two_hole = loaded.HatchAt(1);
  Check(reloaded_two_hole.hole_boundaries.size() == 2,
        "the two-hole hatch's hole count survives the round trip");

  std::remove(path.c_str());
}

void TestModelAddHatchPatternDescriptionRoundTrips() {
  using dino8::kernel::HatchFillType;
  using dino8::kernel::Model;
  using dino8::kernel::Result;

  // PARITY_MAP.md's own "kernel: Kernel-level data exchange" evidence for
  // "Rhino non-geometry/composite objects in .3dm" named this as one of
  // this bullet's own last two remaining open items: "ON_HatchPattern's
  // own other fields" - ON_HatchPattern::SetDescription()/Description()
  // had no caller-reachable path through this kernel's Model at all.
  Model model;
  const int no_description = model.AddHatchPattern("Plain", HatchFillType::Solid);
  Check(no_description == 0, "the first AddHatchPattern() call returns index 0");
  Check(model.HatchPatternDescriptionAt(no_description).empty(),
        "a pattern added with no description argument reports an empty description, the "
        "pre-existing behavior, unchanged");

  const int described =
      model.AddHatchPattern("Brick", HatchFillType::Lines, {}, "Standard brick coursing pattern");
  Check(described == 1, "the second AddHatchPattern() call returns index 1");
  Check(model.HatchPatternDescriptionAt(described) == "Standard brick coursing pattern",
        "HatchPatternDescriptionAt() reports the exact description AddHatchPattern() was given");
  Check(model.HatchPatternDescriptionAt(no_description).empty(),
        "giving the second pattern a description does not retroactively affect the first");

  Check(model.HatchPatternDescriptionAt(9999).empty(),
        "HatchPatternDescriptionAt() on a pattern index this model doesn't have returns an "
        "empty string, same contract as HatchPatternLineCount() etc.");

  const std::string path = "dino8_kernel_model_hatch_pattern_description_roundtrip_test.3dm";
  Check(model.Save(path) == Result::Ok, ".3dm save with a described hatch pattern succeeded");

  Model loaded;
  Check(Model::Load(path, loaded) == Result::Ok, ".3dm load succeeded");
  Check(loaded.HatchPatternDescriptionAt(described) == "Standard brick coursing pattern",
        "the reloaded pattern's description survives the .3dm round trip");
  Check(loaded.HatchPatternDescriptionAt(no_description).empty(),
        "the reloaded undescribed pattern's empty description survives the round trip too");

  std::remove(path.c_str());
}

