void TestCurveOffsetInPlanePartialArcPreservesAngularSpan() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const ON_Arc arc(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 4.0, ON_PI);
  ON_NurbsCurve raw;
  Check(arc.GetNurbForm(raw) != 0, "OffsetInPlane arc setup: GetNurbForm succeeds");
  NurbsCurve c;
  c.raw() = raw;

  NurbsCurve out;
  Check(c.OffsetInPlane(1.0, out) == Result::Ok, "OffsetInPlane(+1.0) succeeds on a half-circle arc");
  double worst = 0.0;
  for (double t = out.Domain().min; t <= out.Domain().max; t += 0.1) {
    worst = std::max(worst, std::abs(out.PointAt(t).DistanceTo(Point3d(0, 0, 0)) - 5.0));
  }
  Check(worst < 1e-9, "OffsetInPlane(+1.0) on an arc: every sampled point sits at exactly radius 5.0");

  // Same angular span: the offset arc's start direction from the center
  // matches the original's exactly (only the radius changed).
  Vector3d dir_orig = c.PointAt(c.Domain().min) - Point3d(0, 0, 0);
  Vector3d dir_new = out.PointAt(out.Domain().min) - Point3d(0, 0, 0);
  dir_orig.Unitize();
  dir_new.Unitize();
  Check((dir_orig - dir_new).Length() < 1e-9, "OffsetInPlane on an arc preserves the exact start angle");
}

void TestCurveOffsetInPlaneGeneralCurveApproximatesAndDetectsSelfIntersection() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  // A gentle, smoothly-bulging degree-3 curve - the point here is to check
  // the approximate fit is reasonable for an ordinary curve, not to
  // stress-test worst-case error on a deliberately extreme control net.
  const std::vector<Point3d> cps = {Point3d(0, 0, 0), Point3d(3, 2, 0), Point3d(7, 2, 0), Point3d(10, 0, 0)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);
  Check(c.IsPlanar(1e-9), "OffsetInPlane general-curve setup: curve is planar");
  Check(!c.IsLinear(1e-6) && !c.IsArc(1e-6), "OffsetInPlane general-curve setup: not a line or arc (exercises the approximate path)");

  NurbsCurve out;
  Check(c.OffsetInPlane(0.5, out) == Result::Ok, "OffsetInPlane(+0.5) succeeds on a general planar curve");

  ON_Plane plane;
  c.raw().IsPlanar(&plane, 1e-6);
  double worst = 0.0;
  for (double t = c.Domain().min + 0.5; t < c.Domain().max; t += 1.0) {
    Vector3d offset_dir = ON_CrossProduct(c.TangentAt(t), plane.zaxis);
    offset_dir.Unitize();
    const Point3d expected = c.PointAt(t) + 0.5 * offset_dir;
    worst = std::max(worst, out.ClosestPoint(expected, 500).DistanceTo(expected));
  }
  Check(worst < 0.05, "OffsetInPlane(+0.5) on a general curve: the least-squares refit approximates the true offset reasonably well");

  // Self-intersection: a large-magnitude offset in at least one direction
  // must fold this curve's tighter bend through itself and be refused.
  const Result r_pos = c.OffsetInPlane(20.0, out);
  const Result r_neg = c.OffsetInPlane(-20.0, out);
  Check(r_pos == Result::Failed || r_neg == Result::Failed,
        "OffsetInPlane on a general curve: at least one large-magnitude direction is refused as self-intersecting");
}

void TestCurveOffsetInPlaneGeneralCurveRefinesUntilWithinTolerance() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  // A genuinely wiggly planar curve (unlike the gentle single-bulge
  // fixture above, deliberately NOT stress-testing worst-case error) -
  // several full oscillations packed into a short span, so the true
  // offset curve's own curvature varies enough that fitting at this
  // curve's own (small) ControlPointCount() alone leaves real,
  // measurable error - the exact gap this method's own tolerance-driven
  // refinement loop was added to close, not merely a fit-quality nicety.
  std::vector<Point3d> cps;
  for (int i = 0; i <= 10; ++i) cps.push_back(Point3d(i, 2.0 * std::sin(i * 0.9), 0.0));
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);
  Check(c.IsPlanar(1e-9), "OffsetInPlane tolerance-refit setup: curve is planar");

  NurbsCurve out;
  Check(c.OffsetInPlane(0.5, out) == Result::Ok, "OffsetInPlane(+0.5) succeeds on a genuinely wiggly planar curve");
  Check(out.ControlPointCount() > c.ControlPointCount(),
        "OffsetInPlane(+0.5) on a wiggly curve: refinement actually grew the control-point count beyond this curve's own - fitting at the ORIGINAL count alone was not accurate enough");

  ON_Plane plane;
  c.raw().IsPlanar(&plane, 1e-6);
  const dino8::kernel::Interval dom = c.Domain();
  double worst = 0.0;
  for (int i = 0; i <= 200; ++i) {
    const double t = dom.min + (dom.max - dom.min) * i / 200.0;
    Vector3d offset_dir = ON_CrossProduct(c.TangentAt(t), plane.zaxis);
    offset_dir.Unitize();
    const Point3d expected = c.PointAt(t) + 0.5 * offset_dir;
    worst = std::max(worst, out.ClosestPoint(expected, 200).DistanceTo(expected));
  }
  const double bbox_diag = (c.GetTightBoundingBox().max - c.GetTightBoundingBox().min).Length();
  const double expected_tol = dino8::kernel::tolerance::DistanceForSize(bbox_diag);
  Check(worst <= 2.0 * expected_tol,
        "OffsetInPlane(+0.5) on a wiggly curve: the REFINED fit's worst-case deviation from the true offset locus is at (or very near) the tolerance this method targets internally, not merely 'reasonable'");

  // Directly proves this is a real fix, not a cosmetic change: fitting at
  // the OLD fixed ControlPointCount() alone (bypassing the refinement
  // loop entirely, calling FitLeastSquares directly the way this method
  // used to) leaves a MUCH larger, previously-unchecked error on this
  // exact fixture.
  const int n = std::max(50, 4 * c.ControlPointCount());
  std::vector<Point3d> offset_points;
  for (int i = 0; i <= n; ++i) {
    const double t = dom.min + (dom.max - dom.min) * i / n;
    Vector3d offset_dir = ON_CrossProduct(c.TangentAt(t), plane.zaxis);
    offset_dir.Unitize();
    offset_points.push_back(c.PointAt(t) + 0.5 * offset_dir);
  }
  NurbsCurve fitted_at_original_count;
  Check(NurbsCurve::FitLeastSquares(offset_points, c.Degree(), c.ControlPointCount(), fitted_at_original_count) == Result::Ok,
        "tolerance-refit regression setup: FitLeastSquares at the original control-point count succeeds");
  double worst_unrefined = 0.0;
  for (const Point3d& p : offset_points) {
    worst_unrefined = std::max(worst_unrefined, fitted_at_original_count.ClosestPoint(p, 100).DistanceTo(p));
  }
  Check(worst_unrefined > 50.0 * expected_tol,
        "OffsetInPlane's OWN tolerance-driven refinement is genuinely necessary here: fitting at the original (unrefined) control-point count alone would have left an error over 50x this method's own target tolerance");
}

void TestCurveOffsetInPlaneRefusesNonPlanarCurve() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> cps = {Point3d(0, 0, 0), Point3d(1, 1, 1), Point3d(2, -1, 2), Point3d(3, 2, -1)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);
  Check(!c.IsPlanar(1e-6), "OffsetInPlane non-planar setup: curve is genuinely non-planar");

  NurbsCurve out;
  Check(c.OffsetInPlane(1.0, out) == Result::Failed, "OffsetInPlane refuses a genuinely non-planar curve");
}

void TestCurveOffsetInPlaneWithExplicitPlaneSucceedsOnNonPlanarCurve() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  // Same fixture as TestCurveOffsetInPlaneRefusesNonPlanarCurve - a
  // genuinely non-planar cubic. The single-plane overload refuses this
  // outright; the whole point of the caller-supplied-plane overload is
  // that it does not.
  const std::vector<Point3d> cps = {Point3d(0, 0, 0), Point3d(1, 1, 1), Point3d(2, -1, 2), Point3d(3, 2, -1)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);
  Check(!c.IsPlanar(1e-6), "OffsetInPlane(plane) non-planar setup: curve is genuinely non-planar");

  NurbsCurve out_noplane;
  Check(c.OffsetInPlane(1.0, out_noplane) == Result::Failed,
        "OffsetInPlane(plane) setup: the single-plane overload still refuses this curve");

  const ON_Plane plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1));
  NurbsCurve out;
  Check(c.OffsetInPlane(plane, 1.0, out) == Result::Ok,
        "OffsetInPlane(plane, +1.0) succeeds on a genuinely non-planar curve given an explicit plane");

  const dino8::kernel::Interval dom = c.Domain();
  double worst = 0.0;
  for (int i = 0; i <= 40; ++i) {
    const double t = dom.min + (dom.max - dom.min) * i / 40.0;
    Vector3d offset_dir = ON_CrossProduct(c.TangentAt(t), plane.zaxis);
    offset_dir.Unitize();
    const Point3d expected = c.PointAt(t) + 1.0 * offset_dir;
    worst = std::max(worst, out.ClosestPoint(expected, 200).DistanceTo(expected));
  }
  Check(worst < 0.05,
        "OffsetInPlane(plane, +1.0) on a non-planar curve: the refit tracks TangentAt(t) x plane.zaxis reasonably well");
}

void TestCurveOffsetInPlaneWithExplicitPlaneLineIsExactForAnyNonParallelPlane() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const std::vector<Point3d> cps = {Point3d(0, 0, 0), Point3d(10, 0, 0)};
  const NurbsCurve line = NurbsCurve::FromControlPoints(cps, 1);

  // A plane whose normal has nothing to do with this line's own natural
  // (infinitely many) planes - the point is that the exact line-offset
  // formula generalizes to ANY plane, not only one aligned with a
  // coordinate axis.
  const ON_Plane plane(ON_3dPoint(5, 5, 5), ON_3dVector(1, 1, 1));
  Vector3d expected_dir = ON_CrossProduct(Vector3d(1, 0, 0), plane.zaxis);
  expected_dir.Unitize();

  NurbsCurve out;
  Check(line.OffsetInPlane(plane, 3.0, out) == Result::Ok,
        "OffsetInPlane(plane, +3.0) succeeds on a line for an arbitrary non-parallel plane");
  const Point3d p0 = out.PointAt(out.Domain().min);
  const Point3d p1 = out.PointAt(out.Domain().max);
  Check(p0.DistanceTo(Point3d(0, 0, 0) + 3.0 * expected_dir) < 1e-9,
        "OffsetInPlane(plane, +3.0) on a line: start endpoint matches the independently-computed exact offset");
  Check(p1.DistanceTo(Point3d(10, 0, 0) + 3.0 * expected_dir) < 1e-9,
        "OffsetInPlane(plane, +3.0) on a line: end endpoint matches the independently-computed exact offset");
}

void TestCurveOffsetInPlaneWithExplicitPlaneRefusesWhenTangentParallelToNormal() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // A line running straight along the SAME direction as the given
  // plane's normal: TangentAt(t) x plane.zaxis is the zero vector
  // everywhere, so no offset direction exists.
  const std::vector<Point3d> cps = {Point3d(0, 0, 0), Point3d(0, 0, 5)};
  const NurbsCurve line = NurbsCurve::FromControlPoints(cps, 1);
  const ON_Plane plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1));

  NurbsCurve out;
  Check(line.OffsetInPlane(plane, 1.0, out) == Result::Failed,
        "OffsetInPlane(plane) refuses a line running parallel to the plane's own normal");
}

void TestCurveOffsetInPlaneWithExplicitPlaneMatchesSinglePlaneOverloadWhenPlanesAgree() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // The same genuinely-wiggly planar fixture the tolerance-refit test
  // above uses. Handing this overload the curve's OWN fitted plane must
  // reproduce exactly what the single-plane overload already computes -
  // both funnel into the same shared helper with the same normal.
  std::vector<Point3d> cps;
  for (int i = 0; i <= 10; ++i) cps.push_back(Point3d(i, 2.0 * std::sin(i * 0.9), 0.0));
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);
  ON_Plane plane;
  Check(c.raw().IsPlanar(&plane, 1e-6), "OffsetInPlane(plane) consistency setup: curve is planar");

  NurbsCurve out_old;
  NurbsCurve out_new;
  Check(c.OffsetInPlane(0.5, out_old) == Result::Ok, "OffsetInPlane(+0.5) (single-plane overload) succeeds");
  Check(c.OffsetInPlane(plane, 0.5, out_new) == Result::Ok, "OffsetInPlane(plane, +0.5) (explicit-plane overload) succeeds");

  Check(out_old.ControlPointCount() == out_new.ControlPointCount(),
        "OffsetInPlane(plane) consistency: both overloads land on the same refined control-point count");
  const dino8::kernel::Interval dom = out_old.Domain();
  double worst = 0.0;
  for (int i = 0; i <= 50; ++i) {
    const double t = dom.min + (dom.max - dom.min) * i / 50.0;
    const Point3d p_old = out_old.PointAt(t);
    worst = std::max(worst, out_new.ClosestPoint(p_old, 200).DistanceTo(p_old));
  }
  Check(worst < 1e-9,
        "OffsetInPlane(plane) consistency: the explicit-plane overload exactly reproduces the single-plane overload when the plane matches the curve's own fit");
}

void TestCurveOffsetInPlaneWithExplicitPlaneThrowsOnInvalidArguments() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;

  const std::vector<Point3d> cps = {Point3d(0, 0, 0), Point3d(10, 0, 0)};
  const NurbsCurve line = NurbsCurve::FromControlPoints(cps, 1);
  const ON_Plane valid_plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1));

  NurbsCurve out;
  bool threw_on_nan_distance = false;
  try {
    line.OffsetInPlane(valid_plane, std::numeric_limits<double>::quiet_NaN(), out);
  } catch (const std::invalid_argument&) {
    threw_on_nan_distance = true;
  }
  Check(threw_on_nan_distance, "OffsetInPlane(plane) throws std::invalid_argument on a non-finite distance");

  const ON_Plane invalid_plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 0));
  Check(!invalid_plane.IsValid(), "OffsetInPlane(plane) invalid-plane setup: a zero-normal plane is indeed invalid");
  bool threw_on_invalid_plane = false;
  try {
    line.OffsetInPlane(invalid_plane, 1.0, out);
  } catch (const std::invalid_argument&) {
    threw_on_invalid_plane = true;
  }
  Check(threw_on_invalid_plane, "OffsetInPlane(plane) throws std::invalid_argument on an invalid plane");
}

void TestCurveOffsetInPlaneZeroDistanceIsNoOpCopy() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Result;

  const ON_Circle circle(ON_3dPoint(0, 0, 0), 3.0);
  ON_NurbsCurve raw;
  circle.GetNurbForm(raw);
  NurbsCurve c;
  c.raw() = raw;
  NurbsCurve out;
  Check(c.OffsetInPlane(0.0, out) == Result::Ok, "OffsetInPlane(0.0) succeeds");
  Check(out.PointAt(0.5).DistanceTo(c.PointAt(0.5)) < 1e-12, "OffsetInPlane(0.0) reproduces the same curve");
}

// Flat-plane fixture: NormalAt() is the same constant vector everywhere,
// so OffsetOnSurfaceNormal()'s own sample+closest-point+normal-offset
// construction is exactly checkable pointwise, not just bounded.
dino8::kernel::NurbsSurface MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  std::vector<Point3d> grid;
  for (int i = 0; i < 4; ++i)
    for (int j = 0; j < 4; ++j)
      grid.push_back(Point3d(i * 4.0, j * 4.0, 0.0));
  return NurbsSurface::FromControlGrid(grid, 4, 4, 3, 3);
}

// Translates every control point of `c` by the Euclidean vector `v`,
// exactly (not approximately): a rational curve's basis functions still
// sum to 1 everywhere, so translating each CV's own homogeneous
// (w*x, w*y, w*z, w) by (w*v.x, w*v.y, w*v.z) translates every curve
// point by the same v, for any degree/rationality/closedness.
dino8::kernel::NurbsCurve TranslateCurveForOffsetOnSurfaceNormalTests(const dino8::kernel::NurbsCurve& c,
                                                                       const dino8::kernel::Vector3d& v) {
  dino8::kernel::NurbsCurve out = c;
  ON_NurbsCurve& raw = out.raw();
  for (int i = 0; i < raw.CVCount(); ++i) {
    ON_4dPoint cv;
    raw.GetCV(i, cv);
    cv.x += cv.w * v.x;
    cv.y += cv.w * v.y;
    cv.z += cv.w * v.z;
    raw.SetCV(i, cv);
  }
  return out;
}

void TestCurveOffsetOnSurfaceNormalOpenCubicCurveIsExactOnAFlatPlane() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  Check(plane.IsPlanar(1e-9), "OffsetOnSurfaceNormal flat-plane setup: the constructed grid is genuinely planar");

  // A degree-3 curve lying in the same z=0 plane - not degree 1, so this
  // exercises the InterpolateCubic() refit branch, not the exact-polyline
  // one (see the dedicated polyline test below for that branch).
  const std::vector<Point3d> cps = {Point3d(1, 1, 0), Point3d(4, 8, 0), Point3d(8, 3, 0), Point3d(11, 10, 0)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);

  NurbsCurve out;
  Check(c.OffsetOnSurfaceNormal(plane, 2.0, out) == Result::Ok, "OffsetOnSurfaceNormal(+2.0) succeeds on a curve lying in a flat plane");

  // The surface's normal is the same (0,0,+/-1) everywhere on a flat
  // plane, so translating c by that constant vector gives the EXACT
  // offset curve - an independent ground truth, not a re-run of this
  // method's own sample+refit construction. out's own refit uses a
  // DIFFERENT (chord-length) parameterization than c's, so points are
  // compared via ClosestPoint() rather than assuming the same parameter
  // value lands on the same point on both curves.
  const dino8::kernel::Vector3d n = plane.NormalAt(0.5, 0.5);
  const NurbsCurve expected = TranslateCurveForOffsetOnSurfaceNormalTests(c, 2.0 * n);

  double worst = 0.0;
  const dino8::kernel::Interval od = out.Domain();
  for (double t = od.min; t <= od.max; t += (od.max - od.min) / 20.0) {
    const Point3d p = out.PointAt(t);
    worst = std::max(worst, p.DistanceTo(expected.ClosestPoint(p)));
  }
  Check(worst < 1e-4, "OffsetOnSurfaceNormal(+2.0) on a flat plane: the refit curve stays close to the exact translated curve everywhere sampled, not just at the fit points");
}

void TestCurveOffsetOnSurfaceNormalOpenPolylineStaysAnExactPolyline() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  const std::vector<Point3d> cps = {Point3d(1, 1, 0), Point3d(6, 5, 0), Point3d(10, 2, 0)};
  const NurbsCurve polyline = NurbsCurve::FromControlPoints(cps, 1);
  Check(polyline.Degree() == 1, "OffsetOnSurfaceNormal polyline setup: degree 1 as expected");

  NurbsCurve out;
  Check(polyline.OffsetOnSurfaceNormal(plane, 1.5, out) == Result::Ok, "OffsetOnSurfaceNormal(+1.5) succeeds on an open degree-1 polyline");
  Check(out.Degree() == 1, "OffsetOnSurfaceNormal on an open degree-1 curve stays an exact polyline (not smoothed into a cubic)");

  const dino8::kernel::Vector3d n = plane.NormalAt(0.5, 0.5);
  Check(out.PointAt(out.Domain().min).DistanceTo(polyline.PointAt(polyline.Domain().min) + 1.5 * n) < 1e-9,
        "OffsetOnSurfaceNormal polyline: start point is exactly the original start plus distance*normal");
  Check(out.PointAt(out.Domain().max).DistanceTo(polyline.PointAt(polyline.Domain().max) + 1.5 * n) < 1e-9,
        "OffsetOnSurfaceNormal polyline: end point is exactly the original end plus distance*normal");
}

void TestCurveOffsetOnSurfaceNormalClosedCurveStaysClosed() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  const ON_Circle circle(ON_3dPoint(6, 6, 0), 2.0);
  ON_NurbsCurve raw;
  Check(circle.GetNurbForm(raw) != 0, "OffsetOnSurfaceNormal closed-curve setup: GetNurbForm succeeds");
  NurbsCurve c;
  c.raw() = raw;
  Check(c.IsClosed(), "OffsetOnSurfaceNormal closed-curve setup: the circle is genuinely closed");

  NurbsCurve out;
  Check(c.OffsetOnSurfaceNormal(plane, 1.0, out) == Result::Ok, "OffsetOnSurfaceNormal(+1.0) succeeds on a closed curve lying in a flat plane");
  Check(out.IsClosed(), "OffsetOnSurfaceNormal on a closed input curve produces a closed result");

  // Ground truth: translating the circle by the flat plane's own constant
  // normal is exact (same reasoning as the open-curve test above) - the
  // circle does NOT grow in radius (that would be an IN-PLANE offset,
  // PARITY_MAP's separate "Curve offset on surface" item), it moves off
  // the plane entirely. Compared via ClosestPoint() since out's own
  // chord-length parameterization around the seam doesn't correspond to
  // the exact circle's own parameterization.
  const dino8::kernel::Vector3d n = plane.NormalAt(0.5, 0.5);
  const NurbsCurve expected = TranslateCurveForOffsetOnSurfaceNormalTests(c, 1.0 * n);

  double worst = 0.0;
  const dino8::kernel::Interval od = out.Domain();
  for (double t = 0.0; t < 1.0; t += 0.05) {
    const Point3d p = out.PointAt(od.min + (od.max - od.min) * t);
    worst = std::max(worst, p.DistanceTo(expected.ClosestPoint(p)));
  }
  Check(worst < 1e-2, "OffsetOnSurfaceNormal on a closed planar circle: the refit stays close to the exact translated circle all the way around, including across the seam");
}

void TestCurveOffsetOnSurfaceNormalArgumentChecks() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  const std::vector<Point3d> cps = {Point3d(1, 1, 0), Point3d(4, 8, 0), Point3d(8, 3, 0), Point3d(11, 10, 0)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);

  NurbsCurve out;
  bool threw = false;
  try {
    c.OffsetOnSurfaceNormal(plane, std::numeric_limits<double>::quiet_NaN(), out);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw, "OffsetOnSurfaceNormal(NaN) throws std::invalid_argument");

  threw = false;
  try {
    c.OffsetOnSurfaceNormal(plane, 1.0, out, 1);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw, "OffsetOnSurfaceNormal(sample_count=1) throws std::invalid_argument");

  Check(c.OffsetOnSurfaceNormal(plane, 1.0, out, 5) == dino8::kernel::Result::Ok, "OffsetOnSurfaceNormal(sample_count=5) succeeds");
}

// PARITY_MAP.md's offsetshell category, "Curve offset on surface
// (in-surface, geodesic-style)": on a FLAT plane, OffsetInSurface's own
// `TangentAt(t) x surface_normal` sideways direction is IDENTICAL to
// OffsetInPlane's own general-case in-plane direction `TangentAt(t) x
// plane.zaxis` - and re-projecting a point already in a flat plane back
// onto that same plane is a no-op - so the two methods must agree
// exactly (up to each one's own independent sampling/refit numerics),
// giving a genuine independent cross-check neither method's own isolated
// test can provide.
void TestCurveOffsetInSurfaceOpenCubicCurveMatchesOffsetInPlaneOnFlatPlane() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  Check(plane.IsPlanar(1e-9), "OffsetInSurface flat-plane setup: the constructed grid is genuinely planar");

  // Unlike OffsetOnSurfaceNormal's own fixture above (which moves OFF the
  // plane, so how close a sample sits to the plane's own domain edge
  // never matters), this curve must stay well clear of the plane's own
  // [0, 12] x [0, 12] domain boundary on EVERY side: OffsetInSurface
  // re-projects each offset sample back onto the surface, and a sample
  // that would land outside the domain is honestly clamped to the
  // boundary instead - correct behavior for a genuinely bounded surface,
  // but not what this test's own independent (infinite-plane) ground
  // truth formula assumes. A margin of 3 on every side, against a
  // distance of 1.5, leaves ample room.
  const std::vector<Point3d> cps = {Point3d(3, 3, 0), Point3d(5, 8, 0), Point3d(7, 4, 0), Point3d(9, 9, 0)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);

  NurbsCurve out;
  Check(c.OffsetInSurface(plane, 1.5, out) == Result::Ok, "OffsetInSurface(+1.5) succeeds on a curve lying in a flat plane");

  const dino8::kernel::Vector3d n = plane.NormalAt(0.5, 0.5);
  const ON_Plane matching_plane(ON_3dPoint(0, 0, 0), n);
  NurbsCurve expected;
  Check(c.OffsetInPlane(matching_plane, 1.5, expected) == Result::Ok,
        "OffsetInSurface cross-check setup: OffsetInPlane(same plane, +1.5) succeeds");

  double worst = 0.0;
  const dino8::kernel::Interval od = out.Domain();
  for (double t = od.min; t <= od.max; t += (od.max - od.min) / 20.0) {
    const Point3d p = out.PointAt(t);
    worst = std::max(worst, p.DistanceTo(expected.ClosestPoint(p)));
  }
  Check(worst < 1e-3,
        "OffsetInSurface on a flat plane matches OffsetInPlane(same plane) everywhere sampled - both methods "
        "move along the identical TangentAt(t) x normal direction there, and re-projecting onto a flat plane "
        "changes nothing");
}

void TestCurveOffsetInSurfaceOpenPolylineEndpointsMoveByTheExactSidewaysDistance() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  // Same "stay clear of the plane's own domain edge" reasoning as
  // TestCurveOffsetInSurfaceOpenCubicCurveMatchesOffsetInPlaneOnFlatPlane
  // above - a margin of 3 on every side against a distance of 1.5.
  const std::vector<Point3d> cps = {Point3d(3, 3, 0), Point3d(6, 5, 0), Point3d(9, 9, 0)};
  const NurbsCurve polyline = NurbsCurve::FromControlPoints(cps, 1);
  Check(polyline.Degree() == 1, "OffsetInSurface polyline setup: degree 1 as expected");

  NurbsCurve out;
  Check(polyline.OffsetInSurface(plane, 1.5, out) == Result::Ok, "OffsetInSurface(+1.5) succeeds on an open degree-1 polyline");
  Check(out.Degree() == 1, "OffsetInSurface on an open degree-1 curve stays an exact polyline (not smoothed into a cubic)");

  // Each endpoint's own sideways direction, computed independently of
  // this method's own construction: tangent (along the first/last
  // segment) crossed with the flat plane's constant normal - and since
  // the result is already exactly in the plane, re-projection changes
  // nothing MATHEMATICALLY, so the moved endpoint should land at
  // distance*side from the original - but unlike OffsetOnSurfaceNormal's
  // own polyline test (pure vector arithmetic, exact to the bit), this
  // method's own re-projection goes through ClosestPointParameter()'s own
  // iterative grid-refinement search TWICE per sample, which converges
  // closely but not to machine precision (measured ~1e-9 to 1e-8 here
  // before this comment was written, not assumed) - so the tolerance
  // below is set to what that search actually achieves, not a weakened
  // claim of exactness.
  const Vector3d n = plane.NormalAt(0.5, 0.5);
  const double d0 = polyline.Domain().min, d1 = polyline.Domain().max;
  Vector3d side0 = ON_CrossProduct(polyline.TangentAt(d0), n);
  Vector3d side1 = ON_CrossProduct(polyline.TangentAt(d1), n);
  Check(side0.Unitize() && side1.Unitize(), "OffsetInSurface polyline setup: both endpoint sideways directions are well-defined");

  Check(out.PointAt(out.Domain().min).DistanceTo(polyline.PointAt(d0) + 1.5 * side0) < 1e-6,
        "OffsetInSurface polyline: start point is exactly the original start plus distance*(tangent x normal), "
        "up to ClosestPointParameter's own iterative-search precision");
  Check(out.PointAt(out.Domain().max).DistanceTo(polyline.PointAt(d1) + 1.5 * side1) < 1e-6,
        "OffsetInSurface polyline: end point is exactly the original end plus distance*(tangent x normal), "
        "up to ClosestPointParameter's own iterative-search precision");
}

void TestCurveOffsetInSurfaceClosedCircleStaysAConcentricCircleInThePlane() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  const Point3d center(6, 6, 0);
  const double radius = 2.0;
  const ON_Circle circle(ON_Plane(center, ON_3dVector(0, 0, 1)), radius);
  ON_NurbsCurve raw;
  Check(circle.GetNurbForm(raw) != 0, "OffsetInSurface closed-curve setup: GetNurbForm succeeds");
  NurbsCurve c;
  c.raw() = raw;
  Check(c.IsClosed(), "OffsetInSurface closed-curve setup: the circle is genuinely closed");

  NurbsCurve out;
  Check(c.OffsetInSurface(plane, 1.0, out) == Result::Ok, "OffsetInSurface(+1.0) succeeds on a closed curve lying in a flat plane");
  Check(out.IsClosed(), "OffsetInSurface on a closed input curve produces a closed result");

  // Ground truth: offsetting a circle SIDEWAYS (in its own plane) is
  // exactly a concentric circle of radius +/- distance - the IN-PLANE
  // counterpart to OffsetOnSurfaceNormal's own "moves the whole circle
  // off the plane, radius unchanged" ground truth. Which sign the
  // construction's own tangent x normal convention picks is not
  // asserted up front; instead the first sampled point's own
  // center-distance pins down which of the two the construction actually
  // took, and every other sampled point is then checked against that SAME
  // value - a genuine circle invariant, not a tautology, since a
  // non-circular (or off-center) result would fail this uniformity check
  // even if one single point happened to match by chance.
  const dino8::kernel::Interval od = out.Domain();
  const double first_radius = out.PointAt(od.min).DistanceTo(center);
  Check(std::fabs(first_radius - (radius + 1.0)) < 1e-2 || std::fabs(first_radius - (radius - 1.0)) < 1e-2,
        "OffsetInSurface circle: the offset radius is exactly radius+distance or radius-distance, not some other value");

  double worst = 0.0;
  for (double t = 0.0; t < 1.0; t += 0.05) {
    const Point3d p = out.PointAt(od.min + (od.max - od.min) * t);
    worst = std::max(worst, std::fabs(p.DistanceTo(center) - first_radius));
    worst = std::max(worst, std::fabs(p.z));
  }
  Check(worst < 1e-2,
        "OffsetInSurface on a closed planar circle: every sampled point stays at the SAME radius from the "
        "center (a genuine concentric circle) and exactly in the z=0 plane, all the way around the seam");
}

// The same bulged-control-net fixture
// TestSurfaceOffsetApproximateOnBulgedFreeformIsBoundedAndRejectsExcessiveDistance
// already uses - a genuinely curved (not flat, not analytic) freeform
// surface, the one case that actually distinguishes OffsetInSurface from
// OffsetOnSurfaceNormal: both methods move "sideways" from the curve's
// own point, but only OffsetInSurface re-projects the result back onto
// the surface afterward, so only its own output should actually land ON
// the surface (zero closest-surface-point distance, within sampling
// resolution) - OffsetOnSurfaceNormal's output, by contrast, moves OFF
// the surface by construction and is never expected to land back on it.
void TestCurveOffsetInSurfaceStaysOnACurvedSurfaceUnlikeOffsetOnSurfaceNormal() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  std::vector<Point3d> grid;
  for (int i = 0; i < 4; ++i)
    for (int j = 0; j < 4; ++j)
      grid.push_back(Point3d(i, j, (i == 2 && j == 2) ? 3.0 : 0.0));
  const NurbsSurface s = NurbsSurface::FromControlGrid(grid, 4, 4, 3, 3);

  // A curve roughly through the middle of the patch, close enough to the
  // surface for ClosestPointParameter's own sampling-based search to find
  // a genuine nearby point reliably.
  const std::vector<Point3d> cps = {Point3d(0.5, 0.5, 0.1), Point3d(1.5, 1.0, 0.3),
                                     Point3d(2.0, 2.0, 1.0), Point3d(1.0, 2.5, 0.2)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);

  NurbsCurve in_surface;
  Check(c.OffsetInSurface(s, 0.2, in_surface) == Result::Ok, "OffsetInSurface(+0.2) succeeds on a genuinely curved surface");
  NurbsCurve off_surface;
  Check(c.OffsetOnSurfaceNormal(s, 0.2, off_surface) == Result::Ok,
        "OffsetInSurface cross-check setup: OffsetOnSurfaceNormal(+0.2) also succeeds on the same curve/surface");

  const auto surface_distance = [&](const NurbsCurve& curve) {
    double worst = 0.0;
    const dino8::kernel::Interval od = curve.Domain();
    for (double t = od.min; t <= od.max; t += (od.max - od.min) / 20.0) {
      const Point3d p = curve.PointAt(t);
      const dino8::kernel::Point2d uv = s.ClosestPointParameter(p, 40, 40);
      worst = std::max(worst, p.DistanceTo(s.PointAt(uv.x, uv.y)));
    }
    return worst;
  };

  Check(surface_distance(in_surface) < 1e-3,
        "OffsetInSurface's own result lies genuinely ON the curved surface (every sampled point's closest-"
        "surface-point distance is ~0), unlike a point merely moved sideways in a straight line and left there");
  Check(surface_distance(off_surface) > 0.1,
        "OffsetOnSurfaceNormal's own result, by contrast, lies OFF the curved surface by roughly the offset "
        "distance - proof the two methods are genuinely solving different problems, not just named differently");
}

void TestCurveOffsetInSurfaceArgumentChecks() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;

  const dino8::kernel::NurbsSurface plane = MakeFlatPlaneSurfaceForOffsetOnSurfaceNormal();
  const std::vector<Point3d> cps = {Point3d(1, 1, 0), Point3d(4, 8, 0), Point3d(8, 3, 0), Point3d(11, 10, 0)};
  const NurbsCurve c = NurbsCurve::FromControlPoints(cps, 3);

  NurbsCurve out;
  bool threw = false;
  try {
    c.OffsetInSurface(plane, std::numeric_limits<double>::quiet_NaN(), out);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw, "OffsetInSurface(NaN) throws std::invalid_argument");

  threw = false;
  try {
    c.OffsetInSurface(plane, 1.0, out, 1);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  Check(threw, "OffsetInSurface(sample_count=1) throws std::invalid_argument");

  Check(c.OffsetInSurface(plane, 1.0, out, 5) == dino8::kernel::Result::Ok, "OffsetInSurface(sample_count=5) succeeds");
}

// An open, axis-aligned "U" bracket: 3 straight segments, 4 vertices,
// planar in z = 0. Exercises the new exact per-corner-miter polyline
// path `OffsetInPlane` now takes instead of falling to the general
// sampled least-squares refit (PARITY_MAP.md's offsetshell category,
// "Planar curve offset": "a kinked polyline goes through the smooth
// refit, blurring corners").
void TestCurveOffsetInPlaneOpenPolylineExactSharpCorners() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const std::vector<Point3d> cps = {
      Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 0), Point3d(0, 10, 0)};
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);
  Check(poly.raw().IsPolyline(), "OffsetInPlane open-polyline setup: this IS recognized as a polyline");
  Check(!poly.IsClosed(), "OffsetInPlane open-polyline setup: this polyline is open, not closed");

  NurbsCurve out;
  Check(poly.OffsetInPlane(1.0, out) == Result::Ok, "OffsetInPlane(+1.0) succeeds on an open polyline");
  Check(out.Degree() == 1 && out.ControlPointCount() == 4,
        "OffsetInPlane on an open 4-vertex polyline: result is itself a plain 4-vertex polyline, not a "
        "doubled-up smooth refit - proof the exact per-corner miter path was taken, not the old blurring one");

  // The two open ENDS only ever see their single adjacent edge (no
  // miter needed there) - checked exactly against this method's own
  // documented per-point contract (`TangentAt(t) x plane.zaxis`), the
  // same way the existing general-curve tests above already cross-check
  // direction, not a re-derivation of the corner-miter formula under
  // test below.
  ON_Plane plane;
  Check(poly.raw().IsPlanar(&plane, 1e-9), "OffsetInPlane open-polyline setup: curve is planar");
  Vector3d dir0 = ON_CrossProduct(cps[1] - cps[0], plane.zaxis);
  dir0.Unitize();
  Vector3d dir_last = ON_CrossProduct(cps[3] - cps[2], plane.zaxis);
  dir_last.Unitize();
  Check(out.ControlPointAt(0).DistanceTo(cps[0] + 1.0 * dir0) < 1e-9,
        "OffsetInPlane open polyline: start endpoint offsets exactly along TangentAt(t) x plane.zaxis");
  Check(out.ControlPointAt(3).DistanceTo(cps[3] + 1.0 * dir_last) < 1e-9,
        "OffsetInPlane open polyline: end endpoint offsets exactly along TangentAt(t) x plane.zaxis");

  // The two INTERIOR corners: verified independently (point-to-line
  // distance, NOT this file's own miter formula) to sit at exactly 1.0
  // from BOTH adjacent original edges, and on the SAME side as the
  // already-verified endpoint direction above (rules out a mirrored/
  // wrong-side corner that would still happen to be equidistant).
  for (int i = 1; i <= 2; ++i) {
    const Point3d p = out.ControlPointAt(i);
    const double d_prev = PerpDistancePointToLine(p, cps[static_cast<size_t>(i - 1)], cps[static_cast<size_t>(i)]);
    const double d_next = PerpDistancePointToLine(p, cps[static_cast<size_t>(i)], cps[static_cast<size_t>(i + 1)]);
    Check(std::abs(d_prev - 1.0) < 1e-9 && std::abs(d_next - 1.0) < 1e-9,
          "OffsetInPlane open polyline: interior corner sits exactly 1.0 from both adjacent original edges");
  }
  Check(ON_DotProduct(out.ControlPointAt(1) - cps[1], dir0) > 0.0,
        "OffsetInPlane open polyline: first interior corner is on the same side as the verified endpoint offset");
}

// A closed, axis-aligned square: the seam vertex (index 0, shared with
// the repeated closing point) must miter exactly like any other corner,
// wrapping around from the LAST edge to the FIRST - not split into two
// different corner positions the way the old smooth refit risked
// (PARITY_MAP.md: "potentially splitting a closed polygon's seam").
void TestCurveOffsetInPlaneClosedPolygonMitersSeamCorner() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> verts = {Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 0), Point3d(0, 10, 0)};
  std::vector<Point3d> cps = verts;
  cps.push_back(verts[0]);
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);
  Check(poly.raw().IsPolyline(), "OffsetInPlane closed-polygon setup: this IS recognized as a polyline");
  Check(poly.IsClosed(), "OffsetInPlane closed-polygon setup: this polygon is closed");

  NurbsCurve out;
  Check(poly.OffsetInPlane(1.0, out) == Result::Ok, "OffsetInPlane(+1.0) succeeds on a closed polygon");
  Check(out.IsClosed(), "OffsetInPlane on a closed polygon: the result is itself closed");
  Check(out.Degree() == 1 && out.ControlPointCount() == 5,
        "OffsetInPlane on a closed 4-vertex polygon: result is a plain closed 4-vertex (5-CV) polygon, not a "
        "smooth refit");
  Check(out.ControlPointAt(0).DistanceTo(out.ControlPointAt(4)) < 1e-9,
        "OffsetInPlane on a closed polygon: the seam does not split - start and end CVs coincide exactly");

  // All 4 distinct corners, INCLUDING the seam vertex (index 0, whose two
  // adjacent edges wrap from D->A to A->B), sit exactly 1.0 from both
  // adjacent original edges.
  for (int i = 0; i < 4; ++i) {
    const Point3d p = out.ControlPointAt(i);
    const Point3d& prev_vertex = verts[static_cast<size_t>((i - 1 + 4) % 4)];
    const Point3d& this_vertex = verts[static_cast<size_t>(i)];
    const Point3d& next_vertex = verts[static_cast<size_t>((i + 1) % 4)];
    const double d_prev = PerpDistancePointToLine(p, prev_vertex, this_vertex);
    const double d_next = PerpDistancePointToLine(p, this_vertex, next_vertex);
    Check(std::abs(d_prev - 1.0) < 1e-9 && std::abs(d_next - 1.0) < 1e-9,
          "OffsetInPlane closed polygon: every corner (including the wraparound seam) sits exactly 1.0 from "
          "both adjacent original edges");
  }
}

// An L-tromino hexagon: one REFLEX (concave) vertex. `OffsetConvexPolyline`
// (sweep.cpp) explicitly refuses any non-convex polygon; this exact miter
// formula needs no such restriction (only a near-180-degree fold is
// refused), so this closed polygon - genuinely concave, confirmed below
// via the same turn-sign check `OffsetConvexPolyline` itself uses -
// exercises real generalization beyond that sibling's convex-only scope.
void TestCurveOffsetInPlaneConcavePolygonGeneralizesBeyondConvexOnlyMiter() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const std::vector<Point3d> verts = {Point3d(0, 0, 0),  Point3d(10, 0, 0), Point3d(10, 4, 0),
                                       Point3d(4, 4, 0),  Point3d(4, 10, 0), Point3d(0, 10, 0)};
  const int n = static_cast<int>(verts.size());

  // Confirm this really is concave: at least one turn's cross-product
  // sign disagrees with the rest (the reflex vertex, index 3).
  double sign = 0.0;
  bool found_reflex = false;
  for (int i = 0; i < n; ++i) {
    Vector3d a = verts[static_cast<size_t>((i + 1) % n)] - verts[static_cast<size_t>(i)];
    Vector3d b = verts[static_cast<size_t>((i + 2) % n)] - verts[static_cast<size_t>((i + 1) % n)];
    a.Unitize();
    b.Unitize();
    const double cross_z = a.x * b.y - a.y * b.x;
    if (std::abs(cross_z) < 1e-9) continue;
    const double this_sign = cross_z > 0.0 ? 1.0 : -1.0;
    if (sign == 0.0) {
      sign = this_sign;
    } else if (this_sign != sign) {
      found_reflex = true;
    }
  }
  Check(found_reflex, "OffsetInPlane concave-polygon setup: this L-shaped hexagon genuinely has a reflex vertex");

  std::vector<Point3d> cps = verts;
  cps.push_back(verts[0]);
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  NurbsCurve out;
  Check(poly.OffsetInPlane(1.0, out) == Result::Ok,
        "OffsetInPlane(+1.0) succeeds on a concave (reflex-vertex) polygon - not refused for lacking convexity");
  Check(out.ControlPointCount() == n + 1, "OffsetInPlane on a concave polygon: still a plain (n+1)-CV polygon");

  for (int i = 0; i < n; ++i) {
    const Point3d p = out.ControlPointAt(i);
    const Point3d& prev_vertex = verts[static_cast<size_t>((i - 1 + n) % n)];
    const Point3d& this_vertex = verts[static_cast<size_t>(i)];
    const Point3d& next_vertex = verts[static_cast<size_t>((i + 1) % n)];
    const double d_prev = PerpDistancePointToLine(p, prev_vertex, this_vertex);
    const double d_next = PerpDistancePointToLine(p, this_vertex, next_vertex);
    Check(std::abs(d_prev - 1.0) < 1e-9 && std::abs(d_next - 1.0) < 1e-9,
          "OffsetInPlane concave polygon: every corner, including the reflex one, sits exactly 1.0 from both "
          "adjacent original edges");
  }
}

// A "spike": the polyline goes forward, then almost straight back on
// itself at the next vertex - a genuine near-180-degree fold, where no
// finite miter point exists. Must be REFUSED, not silently blurred (the
// old general-refit path never refused this at all, since it has no
// concept of a discrete corner to fold through).
void TestCurveOffsetInPlanePolylineRefusesNearFullFold() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> cps = {Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(0.001, 0, 0), Point3d(0.001, 10, 0)};
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);
  Check(poly.raw().IsPolyline(), "OffsetInPlane fold setup: this IS recognized as a polyline");

  NurbsCurve out;
  Check(poly.OffsetInPlane(1.0, out) == Result::Failed,
        "OffsetInPlane refuses a polyline with a near-180-degree fold - no finite miter point exists there");
}

// The explicit-plane overload, handed a plane that agrees with this
// polyline's own fitted plane, must take the SAME exact miter path (not
// silently fall back to the approximate general path just because a
// caller-supplied plane object was used).
void TestCurveOffsetInPlaneWithExplicitPlanePolylineMatchesSinglePlaneOverload() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> cps = {
      Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 0), Point3d(0, 10, 0)};
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  ON_Plane plane;
  Check(poly.raw().IsPlanar(&plane, 1e-9), "OffsetInPlane(plane) polyline setup: curve is planar");

  NurbsCurve out_single, out_explicit;
  Check(poly.OffsetInPlane(1.0, out_single) == Result::Ok, "OffsetInPlane(distance) succeeds on the polyline");
  Check(poly.OffsetInPlane(plane, 1.0, out_explicit) == Result::Ok,
        "OffsetInPlane(plane, distance) succeeds on the same polyline with its own fitted plane");
  Check(out_explicit.ControlPointCount() == out_single.ControlPointCount() && out_explicit.ControlPointCount() == 4,
        "OffsetInPlane(plane, ...) on a polyline: same exact-miter (4-CV) result shape as the single-plane overload");
  for (int i = 0; i < 4; ++i) {
    Check(out_explicit.ControlPointAt(i).DistanceTo(out_single.ControlPointAt(i)) < 1e-9,
          "OffsetInPlane(plane, ...) on a polyline: matches the single-plane overload's own exact corner, "
          "control point for control point");
  }
}

// `CurveOffsetCornerStyle::Round`: on a genuinely convex corner (one
// where the exact Sharp miter point sticks out PAST the fillet radius -
// every corner of this already-established open-polyline fixture, per
// `TestCurveOffsetInPlaneOpenPolylineExactSharpCorners`'s own "same side
// as the verified endpoint offset" check), Round replaces the sharp spike
// with a circular arc of radius `distance` centered on the original
// vertex. Verified independently of the implementation: the arc's own
// 45-degree bisector point (for this fixture's two 90-degree corners) is
// computed here from scratch, not reused from `BuildRoundOffsetCorner()`,
// and must lie ON the result while Sharp's own (farther) corner point
// does not.
void TestCurveOffsetInPlaneRoundStyleFilletsConvexCorners() {
  using dino8::kernel::CurveOffsetCornerStyle;
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const std::vector<Point3d> cps = {
      Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 0), Point3d(0, 10, 0)};
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  ON_Plane plane;
  Check(poly.raw().IsPlanar(&plane, 1e-9), "OffsetInPlane Round setup: curve is planar");

  NurbsCurve out_sharp, out_round;
  Check(poly.OffsetInPlane(1.0, out_sharp) == Result::Ok, "Sharp offset still succeeds on this fixture");
  Check(poly.OffsetInPlane(1.0, out_round, -1.0, CurveOffsetCornerStyle::Round) == Result::Ok,
        "Round offset succeeds on the same open polyline");

  // A plain 4-CV degree-1 polyline can no longer represent two genuinely
  // rounded corners - proof Round did not silently fall back to Sharp's
  // own construction.
  Check(!(out_round.Degree() == 1 && out_round.ControlPointCount() == 4),
        "Round offset is NOT the same plain 4-CV polyline Sharp produces - the corners were genuinely rounded");

  for (int i = 1; i <= 2; ++i) {
    Vector3d edge_in_dir = cps[static_cast<size_t>(i)] - cps[static_cast<size_t>(i - 1)];
    Vector3d edge_out_dir = cps[static_cast<size_t>(i + 1)] - cps[static_cast<size_t>(i)];
    edge_in_dir.Unitize();
    edge_out_dir.Unitize();
    Vector3d n0 = ON_CrossProduct(edge_in_dir, plane.zaxis);
    Vector3d n1 = ON_CrossProduct(edge_out_dir, plane.zaxis);
    n0.Unitize();
    n1.Unitize();

    const Point3d vertex = cps[static_cast<size_t>(i)];
    const Point3d T0 = vertex + 1.0 * n0;
    const Point3d T1 = vertex + 1.0 * n1;
    Vector3d bisector = n0 + n1;
    const double bisector_len = bisector.Length();
    Check(bisector_len > 1e-9, "Round corner setup: the two offset directions are not opposite");
    const Point3d bisector_point = vertex + (1.0 / bisector_len) * bisector;

    Check(out_round.ClosestPoint(T0, 2000).DistanceTo(T0) < 1e-6,
          "Round offset: the result passes through the arc's own start tangent point T0");
    Check(out_round.ClosestPoint(T1, 2000).DistanceTo(T1) < 1e-6,
          "Round offset: the result passes through the arc's own end tangent point T1");
    Check(out_round.ClosestPoint(bisector_point, 2000).DistanceTo(bisector_point) < 1e-6,
          "Round offset: the result passes through the arc's own independently-computed 45-degree bisector "
          "point at exactly radius 1.0 from the vertex - proof this corner is a genuine circular arc, not "
          "just T0/T1 joined by a straight miter");

    // Sharp's own corner for this 90-degree turn sits at distance
    // sqrt(2) =~ 1.414 from the vertex, well past the fillet radius
    // Round's own arc is confined to - confirming Round genuinely
    // shortened this corner rather than coincidentally reproducing it.
    const Point3d sharp_corner = out_sharp.ControlPointAt(i);
    Check((sharp_corner - vertex).Length() > 1.3,
          "Round corner setup: Sharp's own corner for this fixture really is farther than the fillet radius");
    Check(out_round.ClosestPoint(sharp_corner, 2000).DistanceTo(sharp_corner) > 0.1,
          "Round offset: the result does NOT pass through Sharp's own (farther) sharp corner point");
  }
}

// On a polygon with one reflex (concave) vertex, `Round` must leave that
// one corner exactly as `Sharp` already does - the same miter-line
// crossing, since there is no gap there to fill - while still rounding
// its genuinely convex neighbors. Reuses
// `TestCurveOffsetInPlaneConcavePolygonGeneralizesBeyondConvexOnlyMiter`'s
// own L-tromino fixture (vertex index 3 is its one reflex corner).
void TestCurveOffsetInPlaneRoundStyleLeavesConcaveCornerAsExactMiter() {
  using dino8::kernel::CurveOffsetCornerStyle;
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> verts = {Point3d(0, 0, 0),  Point3d(10, 0, 0), Point3d(10, 4, 0),
                                       Point3d(4, 4, 0),  Point3d(4, 10, 0), Point3d(0, 10, 0)};
  std::vector<Point3d> cps = verts;
  cps.push_back(verts[0]);
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  NurbsCurve out_sharp, out_round;
  Check(poly.OffsetInPlane(1.0, out_sharp) == Result::Ok, "Sharp offset still succeeds on the reflex fixture");
  Check(poly.OffsetInPlane(1.0, out_round, -1.0, CurveOffsetCornerStyle::Round) == Result::Ok,
        "Round offset succeeds on the same reflex fixture");

  const Point3d reflex_sharp_corner = out_sharp.ControlPointAt(3);
  Check(out_round.ClosestPoint(reflex_sharp_corner, 2000).DistanceTo(reflex_sharp_corner) < 1e-6,
        "Round offset: the reflex (concave) corner is untouched - the result still passes through exactly "
        "Sharp's own miter point there");

  // The reflex vertex's two immediate neighbors (indices 2 and 4) are
  // genuinely convex, per the same turn-sign check the concave-polygon
  // test above already uses to confirm index 3 alone disagrees with the
  // rest - each one's own Sharp corner point should no longer lie on the
  // Round result.
  for (int i : {2, 4}) {
    const Point3d sharp_corner = out_sharp.ControlPointAt(i);
    Check(out_round.ClosestPoint(sharp_corner, 2000).DistanceTo(sharp_corner) > 0.01,
          "Round offset: a genuinely convex neighbor of the reflex vertex is NOT left at Sharp's own corner "
          "point - it was rounded");
  }
}

// A CLOSED polygon exercises the wraparound seam corner Round's own
// assembly has to splice last (the open-polyline tests above never touch
// it) - must still close up exactly, and its own total length must match
// the independent closed-form perimeter of a rounded square: four
// straight sides at the ORIGINAL edge length (Round's own tangent points
// sit at the same "edge-fraction" position Sharp's miter extends from,
// unlike a chamfer, which would shorten them) plus four quarter-circle
// arcs of radius `distance` - i.e. one full circle of that radius.
void TestCurveOffsetInPlaneRoundStyleClosedSquareMatchesClosedFormPerimeter() {
  using dino8::kernel::CurveOffsetCornerStyle;
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> verts = {Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 0), Point3d(0, 10, 0)};
  std::vector<Point3d> cps = verts;
  cps.push_back(verts[0]);
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  NurbsCurve out;
  const double distance = 1.0;
  Check(poly.OffsetInPlane(distance, out, -1.0, CurveOffsetCornerStyle::Round) == Result::Ok,
        "Round offset succeeds on a closed square");
  Check(out.IsClosed(), "Round offset on a closed square: the result is itself closed");
  Check(out.PointAt(out.Domain().min).DistanceTo(out.PointAt(out.Domain().max)) < 1e-6,
        "Round offset on a closed square: the wraparound seam corner closes the loop exactly");

  const double expected_length = 4.0 * 10.0 + 2.0 * ON_PI * distance;
  Check(std::abs(out.Length(4000) - expected_length) < 1e-3,
        "Round offset on a closed square: total length matches 4 full-length sides plus one full circle of "
        "radius `distance` (four quarter-circle corners) - the independent closed-form perimeter of a "
        "rounded square, not Sharp's own longer mitered-corner perimeter");
}

// `CurveOffsetCornerStyle::Chamfer`: on the same genuinely convex corners
// `TestCurveOffsetInPlaneRoundStyleFilletsConvexCorners()` already
// exercises, Chamfer must cut the sharp spike with the single STRAIGHT
// segment directly between the two tangent points T0/T1 - the arc's own
// chord, not the arc itself. Verified independently of the
// implementation: the chord's own midpoint (computed here from scratch)
// must lie ON the result, while neither Sharp's own (farther) corner
// point nor Round's own (farther-still, since it bulges OUT to the full
// fillet radius) bisector point do.
void TestCurveOffsetInPlaneChamferStyleCutsConvexCorners() {
  using dino8::kernel::CurveOffsetCornerStyle;
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const std::vector<Point3d> cps = {
      Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 0), Point3d(0, 10, 0)};
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  ON_Plane plane;
  Check(poly.raw().IsPlanar(&plane, 1e-9), "OffsetInPlane Chamfer setup: curve is planar");

  NurbsCurve out_sharp, out_round, out_chamfer;
  Check(poly.OffsetInPlane(1.0, out_sharp) == Result::Ok, "Sharp offset still succeeds on this fixture");
  Check(poly.OffsetInPlane(1.0, out_round, -1.0, CurveOffsetCornerStyle::Round) == Result::Ok,
        "Round offset still succeeds on this fixture");
  Check(poly.OffsetInPlane(1.0, out_chamfer, -1.0, CurveOffsetCornerStyle::Chamfer) == Result::Ok,
        "Chamfer offset succeeds on the same open polyline");

  Check(!(out_chamfer.Degree() == 1 && out_chamfer.ControlPointCount() == 4),
        "Chamfer offset is NOT the same plain 4-CV polyline Sharp produces - the corners were genuinely cut");

  for (int i = 1; i <= 2; ++i) {
    Vector3d edge_in_dir = cps[static_cast<size_t>(i)] - cps[static_cast<size_t>(i - 1)];
    Vector3d edge_out_dir = cps[static_cast<size_t>(i + 1)] - cps[static_cast<size_t>(i)];
    edge_in_dir.Unitize();
    edge_out_dir.Unitize();
    Vector3d n0 = ON_CrossProduct(edge_in_dir, plane.zaxis);
    Vector3d n1 = ON_CrossProduct(edge_out_dir, plane.zaxis);
    n0.Unitize();
    n1.Unitize();

    const Point3d vertex = cps[static_cast<size_t>(i)];
    const Point3d T0 = vertex + 1.0 * n0;
    const Point3d T1 = vertex + 1.0 * n1;
    const Point3d chord_mid((T0.x + T1.x) * 0.5, (T0.y + T1.y) * 0.5, (T0.z + T1.z) * 0.5);

    Check(out_chamfer.ClosestPoint(T0, 2000).DistanceTo(T0) < 1e-6,
          "Chamfer offset: the result passes through the chord's own start tangent point T0");
    Check(out_chamfer.ClosestPoint(T1, 2000).DistanceTo(T1) < 1e-6,
          "Chamfer offset: the result passes through the chord's own end tangent point T1");
    Check(out_chamfer.ClosestPoint(chord_mid, 2000).DistanceTo(chord_mid) < 1e-6,
          "Chamfer offset: the result passes through the chord's own independently-computed midpoint - proof "
          "this corner is a genuine straight cut, not an arc or a miter");

    // The chord's own midpoint sits at distance 1/sqrt(2) =~ 0.707 from
    // the vertex for this fixture's 90-degree corners - strictly inside
    // Round's own full fillet radius (1.0) - so Round's independently-
    // computed bisector point must NOT lie on the Chamfer result.
    Vector3d bisector = n0 + n1;
    const double bisector_len = bisector.Length();
    Check(bisector_len > 1e-9, "Chamfer corner setup: the two offset directions are not opposite");
    const Point3d round_bisector_point = vertex + (1.0 / bisector_len) * bisector;
    Check((round_bisector_point - vertex).Length() > (chord_mid - vertex).Length() + 1e-6,
          "Chamfer corner setup: Round's own bisector point really is farther from the vertex than Chamfer's "
          "own chord midpoint");
    Check(out_chamfer.ClosestPoint(round_bisector_point, 2000).DistanceTo(round_bisector_point) > 0.01,
          "Chamfer offset: the result does NOT pass through Round's own (farther) bisector point");

    const Point3d sharp_corner = out_sharp.ControlPointAt(i);
    Check(out_chamfer.ClosestPoint(sharp_corner, 2000).DistanceTo(sharp_corner) > 0.1,
          "Chamfer offset: the result does NOT pass through Sharp's own (farther) sharp corner point");
  }
}

// On a polygon with one reflex (concave) vertex, `Chamfer` must leave that
// one corner exactly as `Sharp`/`Round` already do - the same miter-line
// crossing, since there is no gap there to cut - while still cutting its
// genuinely convex neighbors. Reuses
// `TestCurveOffsetInPlaneConcavePolygonGeneralizesBeyondConvexOnlyMiter`'s
// own L-tromino fixture (vertex index 3 is its one reflex corner).
void TestCurveOffsetInPlaneChamferStyleLeavesConcaveCornerAsExactMiter() {
  using dino8::kernel::CurveOffsetCornerStyle;
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> verts = {Point3d(0, 0, 0),  Point3d(10, 0, 0), Point3d(10, 4, 0),
                                       Point3d(4, 4, 0),  Point3d(4, 10, 0), Point3d(0, 10, 0)};
  std::vector<Point3d> cps = verts;
  cps.push_back(verts[0]);
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  NurbsCurve out_sharp, out_chamfer;
  Check(poly.OffsetInPlane(1.0, out_sharp) == Result::Ok, "Sharp offset still succeeds on the reflex fixture");
  Check(poly.OffsetInPlane(1.0, out_chamfer, -1.0, CurveOffsetCornerStyle::Chamfer) == Result::Ok,
        "Chamfer offset succeeds on the same reflex fixture");

  const Point3d reflex_sharp_corner = out_sharp.ControlPointAt(3);
  Check(out_chamfer.ClosestPoint(reflex_sharp_corner, 2000).DistanceTo(reflex_sharp_corner) < 1e-6,
        "Chamfer offset: the reflex (concave) corner is untouched - the result still passes through exactly "
        "Sharp's own miter point there");

  for (int i : {2, 4}) {
    const Point3d sharp_corner = out_sharp.ControlPointAt(i);
    Check(out_chamfer.ClosestPoint(sharp_corner, 2000).DistanceTo(sharp_corner) > 0.01,
          "Chamfer offset: a genuinely convex neighbor of the reflex vertex is NOT left at Sharp's own corner "
          "point - it was cut");
  }
}

// A CLOSED polygon exercises the wraparound seam corner Chamfer's own
// assembly has to splice last - must still close up exactly, and its own
// total length must match the independent closed-form perimeter of a
// chamfered square: four straight sides at the ORIGINAL edge length (same
// "edge-fraction" position Sharp's own miter extends from, unlike a
// shortened chamfered side - see below) minus nothing (the chamfer cut
// replaces the corner's own extension, it does not shorten the straight
// edge pieces themselves, exactly the same convention
// `TestCurveOffsetInPlaneRoundStyleClosedSquareMatchesClosedFormPerimeter()`
// already establishes for Round) plus four straight chords, each of
// length `2 * distance * sin(turn_angle / 2)` - for this fixture's four
// 90-degree turns, `2 * distance * sin(45deg) = distance * sqrt(2)`.
void TestCurveOffsetInPlaneChamferStyleClosedSquareMatchesClosedFormPerimeter() {
  using dino8::kernel::CurveOffsetCornerStyle;
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> verts = {Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 0), Point3d(0, 10, 0)};
  std::vector<Point3d> cps = verts;
  cps.push_back(verts[0]);
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  NurbsCurve out;
  const double distance = 1.0;
  Check(poly.OffsetInPlane(distance, out, -1.0, CurveOffsetCornerStyle::Chamfer) == Result::Ok,
        "Chamfer offset succeeds on a closed square");
  Check(out.IsClosed(), "Chamfer offset on a closed square: the result is itself closed");
  Check(out.PointAt(out.Domain().min).DistanceTo(out.PointAt(out.Domain().max)) < 1e-6,
        "Chamfer offset on a closed square: the wraparound seam corner closes the loop exactly");

  const double expected_length = 4.0 * 10.0 + 4.0 * distance * std::sqrt(2.0);
  Check(std::abs(out.Length(4000) - expected_length) < 1e-3,
        "Chamfer offset on a closed square: total length matches 4 full-length sides plus four straight "
        "45-degree chamfer chords - the independent closed-form perimeter of a chamfered square, shorter "
        "than both Sharp's own mitered-corner perimeter and Round's own arc-cornered one");
  Check(out.Length(4000) < 4.0 * 10.0 + 2.0 * ON_PI * distance - 1e-3,
        "Chamfer offset on a closed square: strictly shorter than the Round-style perimeter at the same "
        "distance - a straight chord is always shorter than its own arc");
}

// Reuses `TestCurveOffsetInPlaneConcavePolygonGeneralizesBeyondConvexOnlyMiter()`'s
// own L-tromino fixture, but shrinking it INWARD (a negative distance,
// confirmed by direct probe - not assumed - to genuinely cross two
// non-adjacent edges of the exact miter polygon well past the point where
// the two arms' own offset lines invert past each other, rather than
// merely touch) - a real, not hypothetical, self-intersecting loop.
// PARITY_MAP.md's own "Offset self-intersection / invalid-loop removal"
// item discloses this is honestly unrepaired for curves - this test locks
// in that the exact polyline path at least DETECTS it now
// (`Result::Failed`) instead of silently returning the bowtied loop as
// `Result::Ok`, while a distance that stays safely within both arms'
// own thickness still succeeds cleanly.
void TestCurveOffsetInPlaneClosedPolygonRefusesSelfIntersectingLoop() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const std::vector<Point3d> verts = {Point3d(0, 0, 0),  Point3d(10, 0, 0), Point3d(10, 4, 0),
                                       Point3d(4, 4, 0),  Point3d(4, 10, 0), Point3d(0, 10, 0)};
  std::vector<Point3d> cps = verts;
  cps.push_back(verts[0]);
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);

  NurbsCurve out_safe;
  Check(poly.OffsetInPlane(-1.0, out_safe) == Result::Ok,
        "Offset self-intersection setup: an inward distance (-1.0), well within both arms' own 4-unit "
        "thickness, still succeeds cleanly");
  Check(out_safe.IsClosed(), "Offset self-intersection setup: the safe-distance result is itself closed");

  NurbsCurve out_crossed;
  Check(poly.OffsetInPlane(-6.0, out_crossed) == Result::Failed,
        "OffsetInPlane refuses a closed-polygon inward offset distance (-6.0) that collapses this L-shape "
        "past itself - detected as a genuinely self-intersecting loop instead of silently returned");
}

void TestNurbsCurveFilletCornerRightAngle() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // Two legs meeting at a right angle at the origin: legs along +x and
  // +y, radius 1 - the same fixture shape as this codebase's own
  // right-angle 3D fillet sanity checks.
  const Point3d p0(3, 0, 0), corner(0, 0, 0), p1(0, 3, 0);
  const double radius = 1.0;
  NurbsCurve out;
  Check(NurbsCurve::FilletCorner(p0, corner, p1, radius, out) == Result::Ok, "FilletCorner succeeds on a right-angle corner");

  // Closed form for a right-angle corner: tangent length d = r/tan(45) =
  // r, so T0 = (1, 0, 0), T1 = (0, 1, 0); the fillet is a quarter circle.
  const Point3d T0(1, 0, 0), T1(0, 1, 0);
  Check(out.PointAt(out.Domain().min).DistanceTo(p0) < 1e-9, "the joined curve starts exactly at p0");
  Check(out.PointAt(out.Domain().max).DistanceTo(p1) < 1e-9, "the joined curve ends exactly at p1");

  Check(out.ClosestPoint(T0, 2000).DistanceTo(T0) < 1e-6,
        "the curve passes through the closed-form tangent point T0 = (1, 0, 0)");
  Check(out.ClosestPoint(T1, 2000).DistanceTo(T1) < 1e-6,
        "the curve passes through the closed-form tangent point T1 = (0, 1, 0)");

  // A coarse but discriminating "did the arc actually go the SHORT way,
  // not loop the long way around a full circle" sanity check: every
  // sampled point must stay within the two legs' own bounding region.
  const int n = 2000;
  bool all_in_bounds = true;
  for (int i = 0; i <= n; ++i) {
    const double t = out.Domain().min + (out.Domain().max - out.Domain().min) * i / n;
    const Point3d pt = out.PointAt(t);
    if (!(pt.x > -0.01 && pt.x < 3.01 && pt.y > -0.01 && pt.y < 3.01 && std::fabs(pt.z) < 1e-6)) {
      all_in_bounds = false;
    }
  }
  Check(all_in_bounds, "every point of the filleted corner stays within the two legs' own bounding region - the "
                        "arc goes the short way, not around a full circle");

  // Closed-form total length: |p0 - T0| + quarter-circle arc length
  // (radius * pi/2) + |T1 - p1| = 2 + pi/2 + 2.
  const double expected_length = 2.0 + radius * ON_PI / 2.0 + 2.0;
  Check(std::fabs(out.Length(2000) - expected_length) < 1e-4,
        "the filleted corner's total length matches |p0-T0| + quarter-circle arc + |T1-p1| exactly");
}

void TestNurbsCurveFilletCornerObtuseAngleAndTangency() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  // A genuinely non-right, non-planar-trivial obtuse corner: p0 along
  // +x, p1 at 120 degrees from p0 around the corner, radius 0.5.
  const Point3d corner(1, 2, 3);
  const double theta = 2.0 * ON_PI / 3.0;  // 120 degrees
  const Point3d p0 = corner + Point3d(5, 0, 0);
  const Point3d p1 = corner + Point3d(5 * std::cos(theta), 5 * std::sin(theta), 0);
  const double radius = 0.5;
  NurbsCurve out;
  Check(NurbsCurve::FilletCorner(p0, corner, p1, radius, out) == Result::Ok, "FilletCorner succeeds on a 120-degree corner");

  const double d = radius / std::tan(theta / 2.0);
  const Point3d T0 = corner + d * Point3d(1, 0, 0);
  const Point3d T1 = corner + d * Point3d(std::cos(theta), std::sin(theta), 0);

  // Tangency check: the curve's own tangent direction just inside the
  // start must match the straight leg's own direction (p0 - corner,
  // normalized) - a genuine G1 junction, not just position-continuous.
  Vector3d leg0_dir = p0 - corner;
  leg0_dir.Unitize();
  const Vector3d start_tangent = out.TangentAt(out.Domain().min);
  Check(std::fabs(ON_DotProduct(start_tangent, leg0_dir)) > 1.0 - 1e-6,
        "the joined curve's own tangent at p0 matches the incoming leg's direction (G1, not just G0)");

  Vector3d leg1_dir = p1 - corner;
  leg1_dir.Unitize();
  const Vector3d end_tangent = out.TangentAt(out.Domain().max);
  Check(std::fabs(ON_DotProduct(end_tangent, leg1_dir)) > 1.0 - 1e-6,
        "the joined curve's own tangent at p1 matches the outgoing leg's direction (G1, not just G0)");

  // Every point on the arc-only middle portion must be at exactly
  // `radius` from the tangent-circle center C = corner + (radius /
  // sin(theta/2)) * bisector.
  Vector3d bis = leg0_dir + leg1_dir;
  bis.Unitize();
  const Point3d C = corner + (radius / std::sin(theta / 2.0)) * bis;
  Check(std::fabs(T0.DistanceTo(C) - radius) < 1e-9 && std::fabs(T1.DistanceTo(C) - radius) < 1e-9,
        "both closed-form tangent points sit at exactly `radius` from the closed-form arc center");

  const double expected_length = T0.DistanceTo(p0) + radius * (ON_PI - theta) + T1.DistanceTo(p1);
  Check(std::fabs(out.Length(2000) - expected_length) < 1e-3,
        "the filleted corner's total length matches the closed form |p0-T0| + radius*(pi-theta) + |T1-p1|");
}

void TestNurbsCurveFilletCornerRejectsInvalidInput() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  auto throws = [](const std::function<void()>& fn) {
    try {
      fn();
    } catch (const std::invalid_argument&) {
      return true;
    }
    return false;
  };

  NurbsCurve out;
  const Point3d corner(0, 0, 0), p0(1, 0, 0), p1(0, 1, 0);
  Check(throws([&] { NurbsCurve::FilletCorner(p0, corner, p1, 0.0, out); }), "rejects a non-positive radius");
  Check(throws([&] { NurbsCurve::FilletCorner(p0, corner, p1, -1.0, out); }), "rejects a negative radius");
  Check(throws([&] { NurbsCurve::FilletCorner(corner, corner, p1, 1.0, out); }), "rejects p0 == corner");
  Check(throws([&] { NurbsCurve::FilletCorner(p0, corner, corner, 1.0, out); }), "rejects p1 == corner");
  Check(throws([&] { NurbsCurve::FilletCorner(Point3d(1, 0, 0), corner, Point3d(2, 0, 0), 1.0, out); }),
        "rejects a straight (collinear, same-direction) corner");
  Check(throws([&] { NurbsCurve::FilletCorner(Point3d(-1, 0, 0), corner, Point3d(1, 0, 0), 1.0, out); }),
        "rejects a straight (collinear, opposite-direction) corner");
  // A radius too large for the short legs: tangent length d = r/tan(45)
  // = r for a right-angle corner, so r = 1 needs legs of length > 1 -
  // legs of length 0.5 can't fit it.
  Check(NurbsCurve::FilletCorner(Point3d(0.5, 0, 0), corner, Point3d(0, 0.5, 0), 1.0, out) == Result::Failed,
        "reports Result::Failed (not a throw) when radius is too large for the two legs to fit");
}

void TestNurbsCurveFilletCornerArcMatchesFilletCornerOnRightAngle() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // Same right-angle fixture `TestNurbsCurveFilletCornerRightAngle` uses:
  // legs along +x and +y from the origin, radius 1.
  const Point3d p0(3, 0, 0), corner(0, 0, 0), p1(0, 3, 0);
  const double radius = 1.0;

  NurbsCurve arc;
  Check(NurbsCurve::FilletCornerArc(p0, corner, p1, radius, arc) == Result::Ok,
        "FilletCornerArc succeeds on a right-angle corner");

  const Point3d T0(1, 0, 0), T1(0, 1, 0);
  Check(arc.PointAt(arc.Domain().min).DistanceTo(T0) < 1e-9, "FilletCornerArc's own curve starts exactly at T0");
  Check(arc.PointAt(arc.Domain().max).DistanceTo(T1) < 1e-9, "FilletCornerArc's own curve ends exactly at T1");

  // Unlike FilletCorner's own joined result, this is the arc ALONE - no
  // straight legs back to p0/p1 at all, so its total length is exactly
  // the quarter-circle arc length, not the legs-plus-arc closed form
  // `TestNurbsCurveFilletCornerRightAngle` checks.
  const double expected_arc_length = radius * ON_PI / 2.0;
  Check(std::fabs(arc.Length(2000) - expected_arc_length) < 1e-4,
        "FilletCornerArc's own length is exactly the quarter-circle arc, none of FilletCorner's straight legs");

  // FilletCorner is now built ON TOP of FilletCornerArc (same construction,
  // shared implementation) - so the full joined curve's own arc-only
  // portion must trace the identical locus FilletCornerArc returns
  // directly, not just an equivalent one: every point sampled off
  // FilletCornerArc's own curve must lie ON FilletCorner's joined curve.
  NurbsCurve joined;
  Check(NurbsCurve::FilletCorner(p0, corner, p1, radius, joined) == Result::Ok,
        "FilletCorner still succeeds on the same corner");
  bool all_on_joined = true;
  const int n = 50;
  for (int i = 0; i <= n; ++i) {
    const double t = arc.Domain().min + (arc.Domain().max - arc.Domain().min) * i / n;
    const Point3d pt = arc.PointAt(t);
    if (joined.ClosestPoint(pt, 4000).DistanceTo(pt) > 1e-6) all_on_joined = false;
  }
  Check(all_on_joined,
        "every point FilletCornerArc's own curve visits also lies on FilletCorner's joined curve - genuinely the "
        "same shared construction, not two independent implementations of the same formula");
}

void TestNurbsCurveFilletCornerArcAcceptsSyntheticFarRayPoints() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // The documented app-level use case: a caller (a two-curve fillet
  // command trimming its own legs separately, or a polyline corner whose
  // shared edges are built elsewhere) doesn't have real leg endpoints at
  // exactly the tangent length - only the two ray DIRECTIONS from the
  // corner, plus its own independently-established guarantee that the
  // radius fits. It passes synthetic points, placed arbitrarily farther
  // out along each ray than the true tangent length, purely to satisfy
  // the "does it fit" check - the returned arc must be identical either
  // way, since the arc's own geometry depends only on direction.
  const Point3d corner(1, 2, 3);
  const double theta = 2.0 * ON_PI / 3.0;  // 120 degrees, same as the obtuse FilletCorner fixture
  const Point3d dir0(1, 0, 0), dir1(std::cos(theta), std::sin(theta), 0);
  const double radius = 0.5;

  NurbsCurve short_ray, long_ray;
  Check(NurbsCurve::FilletCornerArc(corner + dir0 * 5.0, corner, corner + dir1 * 5.0, radius, short_ray) ==
            Result::Ok,
        "FilletCornerArc succeeds with rays of length 5");
  Check(NurbsCurve::FilletCornerArc(corner + dir0 * 500.0, corner, corner + dir1 * 500.0, radius, long_ray) ==
            Result::Ok,
        "FilletCornerArc succeeds with rays of length 500, far past the true tangent length");

  Check(short_ray.PointAt(short_ray.Domain().min).DistanceTo(long_ray.PointAt(long_ray.Domain().min)) < 1e-9 &&
            short_ray.PointAt(short_ray.Domain().max).DistanceTo(long_ray.PointAt(long_ray.Domain().max)) < 1e-9,
        "the returned arc's own tangent points are identical regardless of how far out the ray points were placed");
  Check(std::fabs(short_ray.Length(2000) - long_ray.Length(2000)) < 1e-9,
        "the returned arc's own length is identical regardless of how far out the ray points were placed");
}

void TestNurbsCurveFilletCornerArcRejectsInvalidInput() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  auto throws = [](const std::function<void()>& fn) {
    try {
      fn();
    } catch (const std::invalid_argument&) {
      return true;
    }
    return false;
  };

  NurbsCurve out;
  const Point3d corner(0, 0, 0), p0(1, 0, 0), p1(0, 1, 0);
  Check(throws([&] { NurbsCurve::FilletCornerArc(p0, corner, p1, 0.0, out); }), "rejects a non-positive radius");
  Check(throws([&] { NurbsCurve::FilletCornerArc(p0, corner, p1, -1.0, out); }), "rejects a negative radius");
  Check(throws([&] { NurbsCurve::FilletCornerArc(corner, corner, p1, 1.0, out); }), "rejects p0 == corner");
  Check(throws([&] { NurbsCurve::FilletCornerArc(p0, corner, corner, 1.0, out); }), "rejects p1 == corner");
  Check(throws([&] { NurbsCurve::FilletCornerArc(Point3d(1, 0, 0), corner, Point3d(2, 0, 0), 1.0, out); }),
        "rejects a straight (collinear, same-direction) corner");
  Check(throws([&] { NurbsCurve::FilletCornerArc(Point3d(-1, 0, 0), corner, Point3d(1, 0, 0), 1.0, out); }),
        "rejects a straight (collinear, opposite-direction) corner");
  Check(NurbsCurve::FilletCornerArc(Point3d(0.5, 0, 0), corner, Point3d(0, 0.5, 0), 1.0, out) == Result::Failed,
        "reports Result::Failed (not a throw) when radius is too large for the two legs to fit");
}

void TestNurbsCurveChamferCornerAsymmetricDistances() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  const Point3d p0(5, 0, 0), corner(0, 0, 0), p1(0, 5, 0);
  NurbsCurve out;
  Check(NurbsCurve::ChamferCorner(p0, corner, p1, 1.0, 2.0, out) == Result::Ok,
        "ChamferCorner succeeds with two independent distances");
  Check(out.ControlPointCount() == 4, "ChamferCorner's result is the honest 4-point polyline: p0, T0, T1, p1");
  const Point3d T0(1, 0, 0), T1(0, 2, 0);
  Check(out.ControlPointAt(0).DistanceTo(p0) < 1e-9, "control point 0 is exactly p0");
  Check(out.ControlPointAt(1).DistanceTo(T0) < 1e-9, "control point 1 is exactly T0 = corner + distance0 * leg0");
  Check(out.ControlPointAt(2).DistanceTo(T1) < 1e-9, "control point 2 is exactly T1 = corner + distance1 * leg1");
  Check(out.ControlPointAt(3).DistanceTo(p1) < 1e-9, "control point 3 is exactly p1");

  // Length() approximates via uniform-parameter chord sampling (see its
  // own doc comment) - exact for a piecewise-LINEAR curve only when the
  // samples land exactly on the polyline's own kinks (T0, T1), i.e. when
  // `samples` is a multiple of the curve's own 3 knot spans (one span per
  // straight piece, `FromControlPoints()`'s own "cv_count - degree wide
  // domain" for 4 control points at degree 1). 300 is such a multiple.
  const double expected_length = T0.DistanceTo(p0) + T0.DistanceTo(T1) + T1.DistanceTo(p1);
  Check(std::fabs(out.Length(300) - expected_length) < 1e-9,
        "ChamferCorner's total length matches |p0-T0| + |T0-T1| + |T1-p1| exactly");
}

void TestNurbsCurveChamferCornerRejectsInvalidInput() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  auto throws = [](const std::function<void()>& fn) {
    try {
      fn();
    } catch (const std::invalid_argument&) {
      return true;
    }
    return false;
  };

  NurbsCurve out;
  const Point3d corner(0, 0, 0), p0(1, 0, 0), p1(0, 1, 0);
  Check(throws([&] { NurbsCurve::ChamferCorner(p0, corner, p1, 0.0, 0.5, out); }), "rejects a non-positive distance0");
  Check(throws([&] { NurbsCurve::ChamferCorner(p0, corner, p1, 0.5, 0.0, out); }), "rejects a non-positive distance1");
  Check(throws([&] { NurbsCurve::ChamferCorner(corner, corner, p1, 0.5, 0.5, out); }), "rejects p0 == corner");
  Check(NurbsCurve::ChamferCorner(Point3d(0.5, 0, 0), corner, Point3d(0, 0.5, 0), 1.0, 0.2, out) == Result::Failed,
        "reports Result::Failed when distance0 exceeds the p0 leg's own length");
  Check(NurbsCurve::ChamferCorner(Point3d(0.5, 0, 0), corner, Point3d(0, 0.5, 0), 0.2, 1.0, out) == Result::Failed,
        "reports Result::Failed when distance1 exceeds the p1 leg's own length");
  // Unlike FilletCorner, a collinear corner is a well-defined (if odd)
  // chamfer - not rejected.
  Check(NurbsCurve::ChamferCorner(Point3d(-1, 0, 0), corner, Point3d(1, 0, 0), 0.3, 0.3, out) == Result::Ok,
        "does NOT reject a collinear corner - a straight-line chamfer is still a well-defined 4-point polyline");
}

namespace {

// Two genuinely curved (nonzero curvature) NurbsCurve fixtures for the
// BlendCurves tests below - two independent circles, so G2/G3 continuity
// checks actually exercise real 2nd/3rd derivative matching rather than
// the degenerate all-derivatives-past-1st-are-zero case a straight line
// would give.
dino8::kernel::NurbsCurve BlendTestCircle(dino8::kernel::Point3d center, double radius) {
  const ON_Circle on_circle(ON_Plane(center, ON_3dVector(0, 0, 1)), radius);
  ON_NurbsCurve nurbs_form;
  on_circle.GetNurbForm(nurbs_form);
  dino8::kernel::NurbsCurve out;
  out.raw() = nurbs_form;
  return out;
}

// Reads position + derivatives up to order 3 of `curve` at `t` directly
// off the raw `ON_NurbsCurve`, independent of `NurbsCurve::BlendCurves`'
// own internal `EvaluateBlendEnd` helper (curve.cpp) - so a test built on
// this checks BlendCurves' OWN output against an independently-obtained
// reference, not against a second call into the exact same helper it is
// itself testing.
void BlendTestEvaluate(const dino8::kernel::NurbsCurve& curve, double t, dino8::kernel::Point3d& point,
                        dino8::kernel::Vector3d& d1, dino8::kernel::Vector3d& d2, dino8::kernel::Vector3d& d3) {
  double v[12] = {0};
  Check(curve.raw().Evaluate(t, 3, 3, v), "BlendTestEvaluate: underlying ON_Curve::Evaluate succeeded");
  point = dino8::kernel::Point3d(v[0], v[1], v[2]);
  d1 = dino8::kernel::Vector3d(v[3], v[4], v[5]);
  d2 = dino8::kernel::Vector3d(v[6], v[7], v[8]);
  d3 = dino8::kernel::Vector3d(v[9], v[10], v[11]);
}

// Central finite-difference derivatives of `s` up to order 3, purely in
// direction `dir` (0 = u, 1 = v) at a point held fixed in the other
// direction - a ground truth for NurbsSurface::BlendSurfaces()'s own
// cross-boundary derivative extraction (sweep.cpp's anonymous-namespace-
// private `EvaluateSurfaceBlendEnd`, untestable directly from this file)
// that depends on NEITHER that function's own ON_Surface::Evaluate
// triangular-layout indexing NOR any assumption about how `s` happens to
// be parameterized - only on `ON_Surface::PointAt`, already exercised
// elsewhere in this file. Standard 5-point central-difference stencils
// (4th-order accurate for d1/d2, verified here by direct Taylor-series
// substitution, not merely cited): d1 = (D - 8B + 8A - C)/(12h),
// d2 = (-D + 16B + 16A - C)/(12h^2), d3 = (-D + 2B - 2A + C)/(2h^3),
// where A/B/C/D are f(+-h)/f(+-2h) each taken RELATIVE to f(0) (safe
// since every one of these three combinations has coefficients summing
// to exactly 0, so the f(0) terms cancel whether or not it is subtracted
// first).
void FiniteDiffPureSurfaceDerivs(const ON_Surface& s, int dir, double fixed_u, double fixed_v, double h,
                                  dino8::kernel::Vector3d& d1, dino8::kernel::Vector3d& d2,
                                  dino8::kernel::Vector3d& d3) {
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;
  auto at = [&](double delta) {
    const ON_3dPoint p = dir == 0 ? s.PointAt(fixed_u + delta, fixed_v) : s.PointAt(fixed_u, fixed_v + delta);
    return Point3d(p.x, p.y, p.z);
  };
  const Point3d p0 = at(0.0);
  const Vector3d A = at(h) - p0, B = at(-h) - p0, C = at(2 * h) - p0, D = at(-2 * h) - p0;
  d1 = (D - B * 8.0 + A * 8.0 - C) * (1.0 / (12.0 * h));
  d2 = (D * -1.0 + B * 16.0 + A * 16.0 - C) * (1.0 / (12.0 * h * h));
  d3 = (D * -1.0 + B * 2.0 - A * 2.0 + C) * (1.0 / (2.0 * h * h * h));
}

// A real cylinder wall (ON_Cylinder::GetNurbForm, the same proven
// technique this file already uses elsewhere) - genuinely curved in the
// circular (U) direction, so its cross-boundary derivatives are honestly
// nonzero up to 3rd order when that direction is held fixed, unlike a
// flat/ruled fixture where a higher-order check would pass vacuously
// (both sides zero).
dino8::kernel::NurbsSurface BlendTestCylinder(dino8::kernel::Point3d center, double radius, double height) {
  const ON_Circle circle(ON_Plane(center, ON_3dVector(0, 0, 1)), radius);
  const ON_Cylinder cylinder(circle, height);
  ON_NurbsSurface ns;
  Check(cylinder.GetNurbForm(ns) != 0, "BlendTestCylinder: ON_Cylinder::GetNurbForm succeeds");
  dino8::kernel::NurbsSurface out;
  out.raw() = ns;
  return out;
}

}  // namespace

void TestNurbsCurveBlendCurvesG1MatchesEndpointPositionsAndTangents() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const NurbsCurve c0 = BlendTestCircle(Point3d(0, 0, 0), 2.0);
  const NurbsCurve c1 = BlendTestCircle(Point3d(10, 0, 0), 3.0);
  const double t0 = c0.Domain().min, t1 = c1.Domain().min;

  NurbsCurve out;
  Check(NurbsCurve::BlendCurves(c0, t0, false, c1, t1, false, 1, out) == Result::Ok,
        "BlendCurves(continuity=1) succeeds on two independent circles");
  Check(out.Degree() == 3, "continuity=1 gives a cubic (degree 3, order 4) Bezier-basis curve");
  Check(out.ControlPointCount() == 4, "a cubic has exactly 4 control points");

  Point3d p0, p1;
  Vector3d d0_1, d0_2, d0_3, d1_1, d1_2, d1_3;
  BlendTestEvaluate(c0, t0, p0, d0_1, d0_2, d0_3);
  BlendTestEvaluate(c1, t1, p1, d1_1, d1_2, d1_3);

  const dino8::kernel::Interval out_dom = out.Domain();
  Point3d out_p0, out_p1;
  Vector3d out_d0_1, out_d0_2, out_d0_3, out_d1_1, out_d1_2, out_d1_3;
  BlendTestEvaluate(out, out_dom.min, out_p0, out_d0_1, out_d0_2, out_d0_3);
  BlendTestEvaluate(out, out_dom.max, out_p1, out_d1_1, out_d1_2, out_d1_3);

  Check(out_p0.DistanceTo(p0) < 1e-9, "the blend's own start point is exactly curve0's point at t0");
  Check(out_p1.DistanceTo(p1) < 1e-9, "the blend's own end point is exactly curve1's point at t1");
  Check((out_d0_1 - d0_1).Length() < 1e-9 * std::max(1.0, d0_1.Length()),
        "the blend's own first derivative at its start matches curve0's own first derivative at t0 (G1/tangent)");
  Check((out_d1_1 - d1_1).Length() < 1e-9 * std::max(1.0, d1_1.Length()),
        "the blend's own first derivative at its end matches curve1's own first derivative at t1 (G1/tangent)");
}

void TestNurbsCurveBlendCurvesG2MatchesCurvatureAtBothEnds() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const NurbsCurve c0 = BlendTestCircle(Point3d(0, 0, 0), 2.0);
  const NurbsCurve c1 = BlendTestCircle(Point3d(10, 0, 0), 3.0);
  const double t0 = c0.Domain().min, t1 = c1.Domain().min;

  NurbsCurve out;
  Check(NurbsCurve::BlendCurves(c0, t0, false, c1, t1, false, 2, out) == Result::Ok,
        "BlendCurves(continuity=2) succeeds on two independent circles");
  Check(out.Degree() == 5, "continuity=2 gives a quintic (degree 5, order 6) Bezier-basis curve");
  Check(out.ControlPointCount() == 6, "a quintic has exactly 6 control points");

  Point3d p0, p1;
  Vector3d d0_1, d0_2, d0_3, d1_1, d1_2, d1_3;
  BlendTestEvaluate(c0, t0, p0, d0_1, d0_2, d0_3);
  BlendTestEvaluate(c1, t1, p1, d1_1, d1_2, d1_3);

  const dino8::kernel::Interval out_dom = out.Domain();
  Point3d out_p0, out_p1;
  Vector3d out_d0_1, out_d0_2, out_d0_3, out_d1_1, out_d1_2, out_d1_3;
  BlendTestEvaluate(out, out_dom.min, out_p0, out_d0_1, out_d0_2, out_d0_3);
  BlendTestEvaluate(out, out_dom.max, out_p1, out_d1_1, out_d1_2, out_d1_3);

  Check((out_d0_1 - d0_1).Length() < 1e-9 * std::max(1.0, d0_1.Length()), "G2 blend still matches 1st derivative at start");
  Check((out_d1_1 - d1_1).Length() < 1e-9 * std::max(1.0, d1_1.Length()), "G2 blend still matches 1st derivative at end");
  Check(d0_2.Length() > 1e-6, "sanity: curve0's own 2nd derivative at t0 is genuinely nonzero (a real circle, not "
                              "a degenerate straight fixture)");
  Check((out_d0_2 - d0_2).Length() < 1e-6 * std::max(1.0, d0_2.Length()),
        "the blend's own 2nd derivative at its start matches curve0's own 2nd derivative at t0 (G2/curvature)");
  Check((out_d1_2 - d1_2).Length() < 1e-6 * std::max(1.0, d1_2.Length()),
        "the blend's own 2nd derivative at its end matches curve1's own 2nd derivative at t1 (G2/curvature)");
}

// The genuine new capability PARITY_MAP.md's own "Curve-to-curve blend"
// bullet names as missing entirely ("No G3+ and no kernel API"):
// continuity = 3 matches position and derivatives up to 3rd order at
// both ends, on a real (nonzero-3rd-derivative) curved fixture.
void TestNurbsCurveBlendCurvesG3MatchesThirdDerivativeAtBothEnds() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const NurbsCurve c0 = BlendTestCircle(Point3d(0, 0, 0), 2.0);
  const NurbsCurve c1 = BlendTestCircle(Point3d(10, 0, 0), 3.0);
  const double t0 = c0.Domain().min, t1 = c1.Domain().min;

  NurbsCurve out;
  Check(NurbsCurve::BlendCurves(c0, t0, false, c1, t1, false, 3, out) == Result::Ok,
        "BlendCurves(continuity=3) succeeds on two independent circles");
  Check(out.Degree() == 7, "continuity=3 gives a septic (degree 7, order 8) Bezier-basis curve");
  Check(out.ControlPointCount() == 8, "a septic has exactly 8 control points");

  Point3d p0, p1;
  Vector3d d0_1, d0_2, d0_3, d1_1, d1_2, d1_3;
  BlendTestEvaluate(c0, t0, p0, d0_1, d0_2, d0_3);
  BlendTestEvaluate(c1, t1, p1, d1_1, d1_2, d1_3);

  const dino8::kernel::Interval out_dom = out.Domain();
  Point3d out_p0, out_p1;
  Vector3d out_d0_1, out_d0_2, out_d0_3, out_d1_1, out_d1_2, out_d1_3;
  BlendTestEvaluate(out, out_dom.min, out_p0, out_d0_1, out_d0_2, out_d0_3);
  BlendTestEvaluate(out, out_dom.max, out_p1, out_d1_1, out_d1_2, out_d1_3);

  Check(out_p0.DistanceTo(p0) < 1e-9 && out_p1.DistanceTo(p1) < 1e-9, "G3 blend matches both endpoint positions");
  Check((out_d0_1 - d0_1).Length() < 1e-6 * std::max(1.0, d0_1.Length()) &&
            (out_d1_1 - d1_1).Length() < 1e-6 * std::max(1.0, d1_1.Length()),
        "G3 blend matches both endpoints' 1st derivative");
  Check((out_d0_2 - d0_2).Length() < 1e-6 * std::max(1.0, d0_2.Length()) &&
            (out_d1_2 - d1_2).Length() < 1e-6 * std::max(1.0, d1_2.Length()),
        "G3 blend matches both endpoints' 2nd derivative");
  Check(d0_3.Length() > 1e-6 && d1_3.Length() > 1e-6,
        "sanity: both fixtures' own 3rd derivatives are genuinely nonzero");
  Check((out_d0_3 - d0_3).Length() < 1e-4 * std::max(1.0, d0_3.Length()),
        "the blend's own 3rd derivative at its start matches curve0's own 3rd derivative at t0 (G3, the new "
        "capability this closes)");
  Check((out_d1_3 - d1_3).Length() < 1e-4 * std::max(1.0, d1_3.Length()),
        "the blend's own 3rd derivative at its end matches curve1's own 3rd derivative at t1 (G3)");
}

void TestNurbsCurveBlendCurvesReverseFlagNegatesOddDerivatives() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const NurbsCurve c0 = BlendTestCircle(Point3d(0, 0, 0), 2.0);
  const NurbsCurve c1 = BlendTestCircle(Point3d(10, 0, 0), 3.0);
  const double t0 = c0.Domain().min, t1 = c1.Domain().min;

  NurbsCurve fwd, rev;
  Check(NurbsCurve::BlendCurves(c0, t0, false, c1, t1, false, 2, fwd) == Result::Ok, "forward blend succeeds");
  Check(NurbsCurve::BlendCurves(c0, t0, true, c1, t1, false, 2, rev) == Result::Ok,
        "reverse0=true blend succeeds");

  Point3d unused_p;
  Vector3d fwd_d1, fwd_d2, fwd_d3, rev_d1, rev_d2, rev_d3;
  BlendTestEvaluate(fwd, fwd.Domain().min, unused_p, fwd_d1, fwd_d2, fwd_d3);
  BlendTestEvaluate(rev, rev.Domain().min, unused_p, rev_d1, rev_d2, rev_d3);

  Check((rev_d1 + fwd_d1).Length() < 1e-6 * std::max(1.0, fwd_d1.Length()),
        "reverse0=true negates the 1st (odd-order) derivative matched at the start, relative to reverse0=false");
  Check((rev_d2 - fwd_d2).Length() < 1e-6 * std::max(1.0, fwd_d2.Length()),
        "reverse0=true leaves the 2nd (even-order) derivative matched at the start UNCHANGED");
}

void TestNurbsCurveBlendCurvesRejectsInvalidInput() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  auto throws = [](const std::function<void()>& fn) {
    try {
      fn();
    } catch (const std::invalid_argument&) {
      return true;
    }
    return false;
  };

  const NurbsCurve c0 = BlendTestCircle(Point3d(0, 0, 0), 2.0);
  const NurbsCurve c1 = BlendTestCircle(Point3d(10, 0, 0), 3.0);
  const double t0 = c0.Domain().min, t1 = c1.Domain().min;
  NurbsCurve out;

  Check(throws([&] { NurbsCurve::BlendCurves(c0, t0, false, c1, t1, false, 0, out); }),
        "BlendCurves rejects continuity == 0");
  Check(throws([&] { NurbsCurve::BlendCurves(c0, t0, false, c1, t1, false, 4, out); }),
        "BlendCurves rejects continuity == 4 (only 1/2/3 are implemented)");
  Check(throws([&] { NurbsCurve::BlendCurves(c0, c0.Domain().max + 1.0, false, c1, t1, false, 1, out); }),
        "BlendCurves rejects t0 outside curve0's own Domain()");
  Check(throws([&] { NurbsCurve::BlendCurves(c0, t0, false, c1, c1.Domain().max + 1.0, false, 1, out); }),
        "BlendCurves rejects t1 outside curve1's own Domain()");

  // Coincident endpoints: blending a circle to ITSELF at the same
  // parameter has zero-length position gap - no well-defined tangent
  // direction to solve for.
  Check(NurbsCurve::BlendCurves(c0, t0, false, c0, t0, false, 1, out) == Result::Failed,
        "BlendCurves reports Result::Failed when both ends coincide");
}

// The genuine new capability PARITY_MAP.md's own "Surface-to-surface
// continuity blend (BlendSrf / VariableBlendSrf)" bullet names as missing
// entirely ("No G3/G4... no kernel API" - the app's own BuildBlendSurfaceG1/
// G2, dino8-app/src/geom/BlendSurface.h, cap out at G2 and live outside the
// kernel): NurbsSurface::BlendSurfaces() at continuity 1/2/3, between two
// independent cylinder walls, each one honestly curved (nonzero up to 3rd
// derivative) in the direction held fixed across the blend - so a 3rd-
// derivative match here is a real check, not a 0-matches-0 vacuous one.
// The rail runs along each cylinder's HEIGHT (dir 1): a straight line in
// 3D, so position/derivative ground truth along the rail itself needs no
// independent check, leaving the cross-boundary (circular, dir 0)
// derivatives the whole point of this test. Verified against
// FiniteDiffPureSurfaceDerivs() - independent of BlendSurfaces()'s own
// ON_Surface::Evaluate-based extraction, and independent of any assumption
// about how ON_Cylinder::GetNurbForm parameterizes the circular direction.
void TestNurbsSurfaceBlendSurfacesMatchesPositionAndCrossBoundaryDerivatives() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  const NurbsSurface cyl0 = BlendTestCylinder(Point3d(0, 0, 0), 2.0, 4.0);
  const NurbsSurface cyl1 = BlendTestCylinder(Point3d(0, 0, 10), 3.0, 4.0);
  const ON_Interval u_dom0 = cyl0.raw().Domain(0), u_dom1 = cyl1.raw().Domain(0);
  const double u0 = u_dom0.Min();  // at_max0 = false below -> fixed at Domain(0).Min()
  const double u1 = u_dom1.Min();  // at_max1 = false below -> fixed at Domain(0).Min()
  const double h0 = u_dom0.Length() * 1e-3, h1 = u_dom1.Length() * 1e-3;

  for (int continuity = 1; continuity <= 3; ++continuity) {
    const int rows = 6;
    NurbsSurface out;
    const std::string succeeds_msg =
        "BlendSurfaces succeeds between two independent cylinder walls (continuity=" + std::to_string(continuity) + ")";
    Check(NurbsSurface::BlendSurfaces(cyl0, /*dir0=*/1, /*at_max0=*/false, cyl1, /*dir1=*/1, /*at_max1=*/false,
                                       /*reverse_rail1=*/false, continuity, rows, out) == Result::Ok,
          succeeds_msg.c_str());
    Check(out.DegreeU() == 2 * continuity + 1,
          "the cross-section (U) direction has the expected Hermite degree 2*continuity+1");

    // Only rows 0 and rows-1 (the first/last stations) are checked below:
    // SkinSections() reparameterizes intermediate stations by chord length
    // (SkinParameters(), sweep.cpp), not by uniform fraction, so only the
    // two ENDS are guaranteed - independent of that internal, private
    // reparameterization - to sit exactly at the output surface's own
    // Domain(1).Min()/.Max(). That still exercises the cross-boundary
    // derivative extraction this test cares about at both ends of both
    // rails, for every continuity level.
    const ON_Interval out_u = out.raw().Domain(0), out_v = out.raw().Domain(1);
    for (int k : {0, rows - 1}) {
      const std::string row = "row " + std::to_string(k) + " (continuity=" + std::to_string(continuity) + "): ";
      const double t = static_cast<double>(k) / static_cast<double>(rows - 1);
      const double v0 = cyl0.raw().Domain(1).ParameterAt(t);
      const double v1 = cyl1.raw().Domain(1).ParameterAt(t);  // reverse_rail1 = false
      const double out_v_k = t < 0.5 ? out_v.Min() : out_v.Max();

      const ON_3dPoint raw_p0 = cyl0.raw().PointAt(u0, v0), raw_p1 = cyl1.raw().PointAt(u1, v1);
      const Point3d p0(raw_p0.x, raw_p0.y, raw_p0.z), p1(raw_p1.x, raw_p1.y, raw_p1.z);
      const ON_3dPoint raw_out_p0 = out.raw().PointAt(out_u.Min(), out_v_k);
      const ON_3dPoint raw_out_p1 = out.raw().PointAt(out_u.Max(), out_v_k);
      const Point3d out_p0(raw_out_p0.x, raw_out_p0.y, raw_out_p0.z), out_p1(raw_out_p1.x, raw_out_p1.y, raw_out_p1.z);
      const std::string p0_msg = row + "the blend's own U=min boundary position matches cylinder 0's rail exactly";
      const std::string p1_msg = row + "the blend's own U=max boundary position matches cylinder 1's rail exactly";
      Check(out_p0.DistanceTo(p0) < 1e-9, p0_msg.c_str());
      Check(out_p1.DistanceTo(p1) < 1e-9, p1_msg.c_str());

      double der_out0[30] = {0}, der_out1[30] = {0};
      Check(out.raw().Evaluate(out_u.Min(), out_v_k, continuity, 3, der_out0), "out.Evaluate at U=min succeeds");
      Check(out.raw().Evaluate(out_u.Max(), out_v_k, continuity, 3, der_out1), "out.Evaluate at U=max succeeds");

      // FiniteDiffPureSurfaceDerivs() returns the RAW (unflipped) partials.
      // BlendSurfaces() itself negates ODD orders when the fixed parameter
      // sits at Domain.Min() (at_max0/at_max1 = false here, for both
      // surfaces - see its own doc comment for why: increasing from Min
      // moves INTO the surface, the opposite of "outward"), so the ground
      // truth below must apply that SAME flip before comparing - this is
      // re-stating BlendSurfaces()'s own documented sign convention, not
      // re-deriving it.
      Vector3d fd_d1_0, fd_d2_0, fd_d3_0, fd_d1_1, fd_d2_1, fd_d3_1;
      FiniteDiffPureSurfaceDerivs(cyl0.raw(), /*dir=*/0, u0, v0, h0, fd_d1_0, fd_d2_0, fd_d3_0);
      FiniteDiffPureSurfaceDerivs(cyl1.raw(), /*dir=*/0, u1, v1, h1, fd_d1_1, fd_d2_1, fd_d3_1);
      fd_d1_0 = -fd_d1_0;
      fd_d3_0 = -fd_d3_0;
      fd_d1_1 = -fd_d1_1;
      fd_d3_1 = -fd_d3_1;

      Check(fd_d1_0.Length() > 1e-6 && fd_d1_1.Length() > 1e-6,
            "sanity: both cylinders' own circular-direction 1st derivative is genuinely nonzero");
      const Vector3d out_d1_0(der_out0[3], der_out0[4], der_out0[5]);
      const Vector3d out_d1_1(der_out1[3], der_out1[4], der_out1[5]);
      const std::string d1_0_msg = row + "the blend's own U=min cross-boundary 1st derivative matches cylinder 0's "
                                          "own finite-difference ground truth (G1)";
      const std::string d1_1_msg = row + "the blend's own U=max cross-boundary 1st derivative matches cylinder 1's "
                                          "own finite-difference ground truth (G1)";
      Check((out_d1_0 - fd_d1_0).Length() < 1e-3 * std::max(1.0, fd_d1_0.Length()), d1_0_msg.c_str());
      Check((out_d1_1 - fd_d1_1).Length() < 1e-3 * std::max(1.0, fd_d1_1.Length()), d1_1_msg.c_str());

      if (continuity >= 2) {
        const Vector3d out_d2_0(der_out0[9], der_out0[10], der_out0[11]);
        const Vector3d out_d2_1(der_out1[9], der_out1[10], der_out1[11]);
        Check(fd_d2_0.Length() > 1e-6 && fd_d2_1.Length() > 1e-6,
              "sanity: both cylinders' own circular-direction 2nd derivative is genuinely nonzero");
        const std::string d2_0_msg = row + "the blend's own U=min cross-boundary 2nd derivative matches cylinder "
                                            "0's own finite-difference ground truth (G2)";
        const std::string d2_1_msg = row + "the blend's own U=max cross-boundary 2nd derivative matches cylinder "
                                            "1's own finite-difference ground truth (G2)";
        Check((out_d2_0 - fd_d2_0).Length() < 1e-2 * std::max(1.0, fd_d2_0.Length()), d2_0_msg.c_str());
        Check((out_d2_1 - fd_d2_1).Length() < 1e-2 * std::max(1.0, fd_d2_1.Length()), d2_1_msg.c_str());
      }
      if (continuity >= 3) {
        const Vector3d out_d3_0(der_out0[18], der_out0[19], der_out0[20]);
        const Vector3d out_d3_1(der_out1[18], der_out1[19], der_out1[20]);
        Check(fd_d3_0.Length() > 1e-6 && fd_d3_1.Length() > 1e-6,
              "sanity: both cylinders' own circular-direction 3rd derivative is genuinely nonzero");
        const std::string d3_0_msg = row + "the blend's own U=min cross-boundary 3rd derivative matches cylinder "
                                            "0's own finite-difference ground truth (G3, the new capability this "
                                            "closes)";
        const std::string d3_1_msg = row + "the blend's own U=max cross-boundary 3rd derivative matches cylinder "
                                            "1's own finite-difference ground truth (G3)";
        Check((out_d3_0 - fd_d3_0).Length() < 5e-2 * std::max(1.0, fd_d3_0.Length()), d3_0_msg.c_str());
        Check((out_d3_1 - fd_d3_1).Length() < 5e-2 * std::max(1.0, fd_d3_1.Length()), d3_1_msg.c_str());
      }
    }
  }
}

void TestNurbsSurfaceBlendSurfacesRejectsInvalidInput() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  auto throws = [](const std::function<void()>& fn) {
    try {
      fn();
    } catch (const std::invalid_argument&) {
      return true;
    }
    return false;
  };

  const NurbsSurface cyl0 = BlendTestCylinder(Point3d(0, 0, 0), 2.0, 4.0);
  const NurbsSurface cyl1 = BlendTestCylinder(Point3d(0, 0, 10), 3.0, 4.0);
  NurbsSurface out;

  Check(throws([&] { NurbsSurface::BlendSurfaces(cyl0, 1, false, cyl1, 1, false, false, 0, 6, out); }),
        "BlendSurfaces rejects continuity == 0");
  Check(throws([&] { NurbsSurface::BlendSurfaces(cyl0, 1, false, cyl1, 1, false, false, 4, 6, out); }),
        "BlendSurfaces rejects continuity == 4 (only 1/2/3 are implemented)");
  Check(throws([&] { NurbsSurface::BlendSurfaces(cyl0, 2, false, cyl1, 1, false, false, 1, 6, out); }),
        "BlendSurfaces rejects dir0 outside {0, 1}");
  Check(throws([&] { NurbsSurface::BlendSurfaces(cyl0, 1, false, cyl1, -1, false, false, 1, 6, out); }),
        "BlendSurfaces rejects dir1 outside {0, 1}");
  Check(throws([&] { NurbsSurface::BlendSurfaces(cyl0, 1, false, cyl1, 1, false, false, 1, 1, out); }),
        "BlendSurfaces rejects rows < 2");

  // Coincident rails: blending a cylinder wall to ITSELF with the SAME
  // fixed boundary has zero position gap at every row - no well-defined
  // Hermite direction to solve for, the same degenerate case
  // NurbsCurve::BlendCurves() reports as Result::Failed rather than
  // throwing (an input-shape problem discovered only once the two ends
  // are actually evaluated, not a malformed-argument problem).
  Check(NurbsSurface::BlendSurfaces(cyl0, 1, false, cyl0, 1, false, false, 1, 6, out) == Result::Failed,
        "BlendSurfaces reports Result::Failed when both rails coincide");
}

// A genuinely 3D (non-coplanar-in-the-given-plane) polyline handed to the
// explicit-plane overload: the exact per-corner miter formula does NOT
// apply here (it only lands on both offset lines when every edge is
// perpendicular to the given plane's normal), so this must fall through
// to the old general sampled path instead of producing a silently wrong
// "exact" result.
void TestCurveOffsetInPlaneWithExplicitPlaneNonCoplanarPolylineFallsBackToGeneralPath() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;
  using dino8::kernel::Vector3d;

  // NOT coplanar - the 4th point is deliberately off the plane the other
  // three would otherwise define (verified below via `IsPlanar()`
  // itself, not assumed from the coordinates alone).
  const std::vector<Point3d> cps = {
      Point3d(0, 0, 0), Point3d(10, 0, 0), Point3d(10, 10, 5), Point3d(0, 10, 8)};
  const NurbsCurve poly = NurbsCurve::FromControlPoints(cps, 1);
  Check(poly.raw().IsPolyline(), "OffsetInPlane non-coplanar setup: this IS recognized as a polyline");
  const ON_Plane plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1));
  Check(!poly.raw().IsPlanar(nullptr, 1e-9),
        "OffsetInPlane non-coplanar setup: this polyline is NOT planar at all (genuinely 3D), let alone "
        "coplanar in the z=0 plane below");

  // At the tight DEFAULT tolerance, this is honestly refused: the exact
  // miter path correctly declined (this polyline isn't coplanar in
  // `plane`), so it falls to the general sampled path - but that path's
  // own per-sample offset locus has a genuine jump at each kink here
  // (each segment's own `tangent x plane.zaxis` is a different constant
  // direction, and unlike the exact-miter case, nothing here reconciles
  // them into a shared corner point), which a CONTINUOUS refit curve
  // cannot close to within a tiny tolerance no matter how many control
  // points it's given. This is the same honest "Result::Failed rather
  // than silently returning a wrong-but-plausible result" contract the
  // general path already enforces for curvature folds - not a defect,
  // and not this new polyline code's own doing (any non-polyline curve
  // whose `tangent x plane.zaxis` jumped this much would refuse the same
  // way, at this curve's own tight default tolerance).
  NurbsCurve out;
  Check(poly.OffsetInPlane(plane, 1.0, out) == Result::Failed,
        "OffsetInPlane(plane, +1.0) on a non-coplanar polyline, at the tight default tolerance: honestly "
        "refused rather than silently returning a blurred-together corner");

  // With an explicit, looser tolerance the SAME general fallback path
  // succeeds (proving this was a real tolerance-driven refusal above,
  // not a hard failure) - and even then, the result is NOT a plain 4-CV
  // polygon (the exact-miter path's own signature), confirming this
  // really did take the general refit, not a wrongly-applied miter.
  Check(poly.OffsetInPlane(plane, 1.0, out, 0.5) == Result::Ok,
        "OffsetInPlane(plane, +1.0, tolerance=0.5) succeeds on the same non-coplanar polyline via the general "
        "fallback path");
  Check(out.ControlPointCount() != 4,
        "OffsetInPlane(plane, ...) on a non-coplanar polyline: result is NOT a plain 4-CV polygon - proof the "
        "exact miter path correctly declined and this fell back to the general refit instead of returning a "
        "wrong 'exact' corner");

  // That looser-tolerance result still starts and ends exactly where the
  // single-edge (non-miter) endpoint formula says it should - the SAME
  // documented `TangentAt(t) x plane.zaxis` contract the exact-miter
  // path's own endpoints use, checked here on the general fallback path
  // instead (this curve's two ends are each adjacent to only one edge,
  // so both paths must agree on them exactly regardless of which one
  // ran in between).
  const dino8::kernel::Interval dom = poly.Domain();
  Vector3d start_dir = ON_CrossProduct(poly.TangentAt(dom.min), plane.zaxis);
  start_dir.Unitize();
  Vector3d end_dir = ON_CrossProduct(poly.TangentAt(dom.max), plane.zaxis);
  end_dir.Unitize();
  Check(out.PointAt(out.Domain().min).DistanceTo(poly.PointAt(dom.min) + 1.0 * start_dir) < 1e-6,
        "OffsetInPlane(plane, ..., tolerance=0.5) fallback on a non-coplanar polyline: still starts exactly "
        "at the documented single-edge offset point");
  Check(out.PointAt(out.Domain().max).DistanceTo(poly.PointAt(dom.max) + 1.0 * end_dir) < 1e-6,
        "OffsetInPlane(plane, ..., tolerance=0.5) fallback on a non-coplanar polyline: still ends exactly at "
        "the documented single-edge offset point");
}

// distance between two curves at 201 matching normalized domain positions.
double MaxCurveDeviation(const dino8::kernel::NurbsCurve& a, const dino8::kernel::NurbsCurve& b) {
  const auto da = a.Domain();
  const auto db = b.Domain();
  double worst = 0.0;
  for (int i = 0; i <= 200; ++i) {
    const double s = i / 200.0;
    worst = std::max(worst, (a.PointAt(da.min + (da.max - da.min) * s) -
                             b.PointAt(db.min + (db.max - db.min) * s))
                                .Length());
  }
  return worst;
}

// Same for two surfaces, over a 31x31 grid of matching normalized positions.
double MaxSurfaceDeviation(const dino8::kernel::NurbsSurface& a, const dino8::kernel::NurbsSurface& b) {
  double worst = 0.0;
  for (int i = 0; i <= 30; ++i) {
    for (int j = 0; j <= 30; ++j) {
      const double s = i / 30.0, t = j / 30.0;
      const auto au = a.Domain(0), av = a.Domain(1), bu = b.Domain(0), bv = b.Domain(1);
      worst = std::max(worst, (a.PointAt(au.min + (au.max - au.min) * s, av.min + (av.max - av.min) * t) -
                               b.PointAt(bu.min + (bu.max - bu.min) * s, bv.min + (bv.max - bv.min) * t))
                                  .Length());
    }
  }
  return worst;
}

// Regression test for a real, measured bug in the routine
// NurbsCurve::ElevateDegree() used to delegate to: OpenNURBS'
// ON_NurbsCurve::IncreaseDegree silently CHANGES THE SHAPE of a curve with
// a non-uniform knot vector at moderate-to-high degree (a randomized probe
// measured up to 1.7e-6 at degree 8, 3.2e+2 at degree 12 and 1e+24 at
// degree 16, unit scale). The kernel now elevates via
// detail/degree_elevate.h (Piegl & Tiller A5.9, verified against an exact
// piecewise-Bezier elevation). Fixed inputs derived from that probe.
void TestCurveElevateDegreePreservesShapeWithNonUniformKnots() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  // Fixture 1: degree 12, 21 control points, 8 distinct non-uniform
  // interior knots. ON_NurbsCurve::IncreaseDegree moves THIS exact curve
  // by 1.6e-8 (+1), 3.1e-8 (+2) and 7.7e-5 (+3); the exact elevation
  // stays at ~1.6e-14.
  {
    std::vector<Point3d> pts;
    for (int i = 0; i < 21; ++i) {
      pts.emplace_back(0.7 * i, 2.0 * std::sin(1.3 * i), 1.5 * std::cos(0.9 * i));
    }
    NurbsCurve c12 = NurbsCurve::FromControlPoints(pts, /*degree=*/12);
    // FromControlPoints() gives the clamped-uniform domain [0, 21 - 12] =
    // [0, 9]; the 8 interior knots sit at indices 12..19.
    const double interior[8] = {0.3, 0.9, 1.1, 2.6, 4.0, 4.05, 6.7, 8.2};
    bool knots_ok = true;
    for (int i = 0; i < 8; ++i) {
      knots_ok = knots_ok && c12.SetKnotAt(12 + i, interior[i]) == Result::Ok;
    }
    Check(knots_ok, "degree-12 fixture's 8 non-uniform interior knots were set");
    for (int target = 13; target <= 15; ++target) {
      NurbsCurve e = c12;
      Check(e.ElevateDegree(target) == Result::Ok && e.Degree() == target,
            "degree-12 non-uniform-knot curve elevates to the requested degree");
      const double dev = MaxCurveDeviation(c12, e);
      char msg[256];
      std::snprintf(msg, sizeof msg,
                    "degree-12 non-uniform-knot curve keeps its shape when elevated to %d (max deviation "
                    "%.3g < 1e-10; ON_NurbsCurve::IncreaseDegree gave 1.6e-8 / 3.1e-8 / 7.7e-5 here)",
                    target, dev);
      Check(dev < 1e-10, msg);
      // Still a valid, evaluable curve everywhere (a corrupt control net
      // would show up as non-finite points, not just displaced ones).
      const auto d = e.Domain();
      bool finite = true;
      for (int i = 0; i <= 50; ++i) {
        const Point3d p = e.PointAt(d.min + (d.max - d.min) * i / 50.0);
        finite = finite && std::isfinite(p.x) && std::isfinite(p.y) && std::isfinite(p.z);
      }
      Check(finite, "elevated degree-12 curve evaluates to finite points everywhere");
    }
  }

  // Fixture 2: degree 8, 12 control points, 3 clustered interior knots
  // (0.35, 0.4, 3.1 on the domain [0, 4]) - the everyday-degree case.
  // ON_NurbsCurve::IncreaseDegree moves this one by 2.1e-5 for +3.
  {
    const std::vector<Point3d> pts = {
        Point3d(0.0, 0.0, 0.0),   Point3d(1.3, 2.1, -0.4), Point3d(2.2, -1.7, 0.9), Point3d(3.8, 1.2, 1.5),
        Point3d(4.1, -2.4, -1.1), Point3d(5.7, 0.6, 0.3),  Point3d(6.3, 2.8, -0.7), Point3d(7.9, -0.9, 1.8),
        Point3d(8.4, 1.9, -1.6),  Point3d(9.6, -2.2, 0.5), Point3d(10.2, 0.8, 1.2), Point3d(11.5, -1.3, -0.2),
    };
    NurbsCurve c8 = NurbsCurve::FromControlPoints(pts, /*degree=*/8);
    Check(c8.SetKnotAt(8, 0.35) == Result::Ok && c8.SetKnotAt(9, 0.4) == Result::Ok &&
              c8.SetKnotAt(10, 3.1) == Result::Ok,
          "degree-8 fixture's clustered interior knots were set");
    NurbsCurve e = c8;
    Check(e.ElevateDegree(11) == Result::Ok && e.Degree() == 11, "degree-8 clustered-knot curve elevates to 11");
    const double dev = MaxCurveDeviation(c8, e);
    char msg[256];
    std::snprintf(msg, sizeof msg,
                  "degree-8 clustered-knot curve keeps its shape when elevated to 11 (max deviation %.3g < "
                  "1e-10; ON_NurbsCurve::IncreaseDegree gave 2.1e-5 here)",
                  dev);
    Check(dev < 1e-10, msg);
  }

  // Fixture 3: a genuine rational curve (a radius-2.5 NURBS circle, degree
  // 2, 9 control points over 4 Bezier spans) elevated to degree 5 is
  // still exactly that circle, in the minimal 9 + 3 * 4 = 21 control
  // points (knot removal verifies cleanly at this degree).
  {
    ON_Circle circle(ON_Plane::World_xy, 2.5);
    NurbsCurve c;
    circle.GetNurbForm(c.raw());
    Check(c.IsRational() && c.Degree() == 2 && c.ControlPointCount() == 9, "circle fixture is the expected rational quadratic");
    NurbsCurve e = c;
    Check(e.ElevateDegree(5) == Result::Ok && e.Degree() == 5, "rational circle elevates to degree 5");
    double worst_radius_error = 0.0;
    const auto d = e.Domain();
    for (int i = 0; i <= 200; ++i) {
      const Point3d p = e.PointAt(d.min + (d.max - d.min) * i / 200.0);
      worst_radius_error = std::max(worst_radius_error, std::abs(p.DistanceTo(ON_3dPoint::Origin) - 2.5));
    }
    Check(worst_radius_error < 1e-12, "degree-5 elevation of a rational circle is still exactly that circle (radius error < 1e-12)");
    Check(e.ControlPointCount() == 21, "rational circle's degree-5 elevation is the minimal 21-control-point form");
    Check(MaxCurveDeviation(c, e) < 1e-12, "...and matches the original circle pointwise");
  }

  // Fixture 4: the everyday case (uniform cubic, 7 control points, 4
  // spans) still comes back in the minimal 7 + 4 = 11 control points, so
  // the exact-Bezier-form fallback is genuinely a fallback, not the norm.
  {
    const std::vector<Point3d> pts = {Point3d(0, 0, 0),   Point3d(1.3, 2.1, -0.4), Point3d(2.2, -1.7, 0.9),
                                      Point3d(3.8, 1.2, 1.5), Point3d(4.1, -2.4, -1.1), Point3d(5.7, 0.6, 0.3),
                                      Point3d(6.3, 2.8, -0.7)};
    NurbsCurve c = NurbsCurve::FromControlPoints(pts, /*degree=*/3);
    NurbsCurve e = c;
    Check(e.ElevateDegree(4) == Result::Ok && e.Degree() == 4, "uniform cubic elevates to 4");
    Check(e.ControlPointCount() == 11, "uniform cubic's degree-4 elevation is the minimal 7 + 4 = 11 control points");
    Check(MaxCurveDeviation(c, e) < 1e-12, "uniform cubic keeps its shape under degree elevation");
    Check(c.ElevateDegree(3) == Result::NoOpAlreadySatisfied, "elevating to the current degree is still a no-op");
  }
}

// Surface counterpart: ON_NurbsSurface::IncreaseDegree packs the rows into
// one high-dimensional ON_NurbsCurve and calls the same broken routine.
// Fixed inputs derived from the same probe (21x4 grid, degrees (12, 2),
// the same 8 non-uniform U knots as the curve fixture above).
void TestSurfaceElevateDegreePreservesShapeWithNonUniformKnots() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::Result;

  std::vector<Point3d> grid;
  for (int i = 0; i < 21; ++i) {
    for (int j = 0; j < 4; ++j) {
      grid.emplace_back(0.7 * i, 1.5 * j + 0.3 * std::sin(1.3 * i), 1.5 * std::cos(0.9 * i + j));
    }
  }
  NurbsSurface s = NurbsSurface::FromControlGrid(grid, 21, 4, /*u_degree=*/12, /*v_degree=*/2);
  const double interior[8] = {0.3, 0.9, 1.1, 2.6, 4.0, 4.05, 6.7, 8.2};
  bool knots_ok = true;
  for (int i = 0; i < 8; ++i) {
    knots_ok = knots_ok && s.SetKnotAt(0, 12 + i, interior[i]) == Result::Ok;
  }
  Check(knots_ok, "surface fixture's 8 non-uniform U knots were set");

  // ON_NurbsSurface::IncreaseDegree moves this surface by 2.4e-8 (U to 13)
  // and 3.2e-8 (U to 14); the exact elevation stays at ~1.3e-14.
  for (int target = 13; target <= 14; ++target) {
    NurbsSurface e = s;
    Check(e.ElevateDegree(/*direction=*/0, target) == Result::Ok && e.DegreeU() == target && e.DegreeV() == 2,
          "surface U-degree elevation reaches the requested degree and leaves V alone");
    const double dev = MaxSurfaceDeviation(s, e);
    char msg[256];
    std::snprintf(msg, sizeof msg,
                  "degree-(12,2) non-uniform-U-knot surface keeps its shape when U is elevated to %d (max "
                  "deviation %.3g < 1e-10; ON_NurbsSurface::IncreaseDegree gave 2.4e-8 / 3.2e-8 here)",
                  target, dev);
    Check(dev < 1e-10, msg);
  }

  // V direction too (degree 2 -> 4 across a non-uniform V knot), which
  // exercises the other row-packing orientation; 4 + 2 * 2 = 8 control
  // points is the minimal form.
  {
    NurbsSurface sv = s;
    Check(sv.SetKnotAt(1, 2, 0.15) == Result::Ok, "surface fixture's non-uniform V knot was set");
    NurbsSurface e = sv;
    Check(e.ElevateDegree(/*direction=*/1, 4) == Result::Ok && e.DegreeV() == 4 && e.DegreeU() == 12,
          "surface V-degree elevation reaches degree 4 and leaves U alone");
    Check(MaxSurfaceDeviation(sv, e) < 1e-10, "surface keeps its shape when V is elevated across a non-uniform knot");
    Check(e.CVCountV() == 8 && e.CVCountU() == 21, "V elevation from 2 to 4 over 2 spans gives the minimal 8 V control points");
    Check(e.ElevateDegree(2, 5) == Result::Failed, "an invalid direction is refused, not silently treated as U or V");
  }
}

// Regression test for a real, reproduced ClosestPointParameter() miss: a
// closed-but-not-periodic degree-4 curve (FromControlPoints() with the
// first and last control points equal, so its seam is only C0 - a kink),
// queried from a point just off that seam. The true nearest point lies on
// the far side of the seam, INSIDE the +/- one-coarse-step refinement
// window - but the golden-section search assumes the distance function is
// unimodal on that window, and the kink makes it bimodal, so the search
// walked to the near side's own local minimum instead: 0.00215 away, when
// the true nearest point (found by a plain 20000-sample scan) is 0.000743
// away - 2.9x farther, with the better point sitting in the very window
// being searched. Fixed by sub-sampling the window before the polish and
// never returning worse than the best sample seen.
void TestCurveClosestPointAcrossClampedSeamKink() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;

  NurbsCurve c;
  ON_NurbsCurve& raw = c.raw();
  raw.Create(3, false, /*order=*/5, /*cv_count=*/10);
  const double knots[13] = {0, 0, 0, 0, 1.38698490512363, 1.8705936816984137, 2.4378860258037047,
                            3.9907205095635137, 5.7989363609240074, 6, 6, 6, 6};
  for (int i = 0; i < 13; ++i) raw.SetKnot(i, knots[i]);
  const double cvs[10][3] = {
      {0.069708490269153156, 0.11210293680398298, -0.76322511230777346},
      {-0.87819820398321835, -0.58847452229800756, -0.62787389330361498},
      {0.27604673936746327, 0.89687423431623925, 0.44903236329897744},
      {-0.88183841960085951, 0.75904190962741169, -0.32157359872369684},
      {-0.64086752287908633, 0.55969799332998682, 0.32300630136893282},
      {-0.57767551394033068, 0.92786576740538873, 0.39939359053737244},
      {0.99461568065996309, 0.92485348423054248, 0.93400209607383222},
      {-0.15484731753059866, -0.40079670420498592, 0.42383170313092755},
      {-0.28678184268560891, -0.2545467512471794, -0.34008569262013022},
      {0.069708490269153156, 0.11210293680398298, -0.76322511230777346}};
  for (int i = 0; i < 10; ++i) raw.SetCV(i, ON_3dPoint(cvs[i][0], cvs[i][1], cvs[i][2]));
  Check(raw.IsValid() && c.IsClosed() && !c.IsPeriodic(), "seam-kink fixture is a valid closed, non-periodic curve");

  const Point3d query(0.068231429730267426, 0.11023876276341521, -0.76088826174781632);
  // Reference: a plain dense scan, no refinement at all.
  double brute = std::numeric_limits<double>::infinity();
  const auto dom = c.Domain();
  for (int i = 0; i <= 20000; ++i) {
    brute = std::min(brute, (c.PointAt(dom.min + (dom.max - dom.min) * i / 20000.0) - query).Length());
  }
  Check(brute < 1e-3, "sanity: the query point is within 1e-3 of the curve (brute-force scan)");

  for (int samples : {200, 2000}) {
    const double t = c.ClosestPointParameter(query, samples);
    Check(t >= dom.min && t <= dom.max, "ClosestPointParameter returns a parameter inside the domain");
    const double d = (c.PointAt(t) - query).Length();
    char msg[256];
    std::snprintf(msg, sizeof msg,
                  "ClosestPoint(samples=%d) across the clamped seam kink is no farther than the dense scan's "
                  "nearest point (%.6g vs %.6g; used to return 0.00215 for samples=2000)",
                  samples, d, brute);
    Check(d <= brute * (1.0 + 1e-6), msg);
  }
}

// Regression test for ParameterAtArcLength(Length()) landing a few 1e-12
// PAST Domain().max: the interpolation fraction (target - previous) /
// segment was computed from the ROUNDED cumulative length and could exceed
// 1 by an ulp of a large cumulative sum. A polyline whose first segment
// (1e6) dwarfs its last (1e-3) reproduces it deterministically; the method
// promises to clamp to the domain.
void TestCurveParameterAtArcLengthStaysInsideDomain() {
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;

  const NurbsCurve line = NurbsCurve::FromControlPoints(
      {Point3d(0, 0, 0), Point3d(1e6, 0, 0), Point3d(1e6 + 1e-3, 0, 0)}, /*degree=*/1);
  const auto dom = line.Domain();
  const double length = line.Length(1000);
  const double t_end = line.ParameterAtArcLength(length, 1000);
  char msg[200];
  std::snprintf(msg, sizeof msg,
                "ParameterAtArcLength(Length()) is exactly Domain().max (%.17g vs %.17g; used to overshoot "
                "by ~1e-11)",
                t_end, dom.max);
  Check(t_end == dom.max, msg);
  // Monotone and in-domain for every intermediate target too.
  bool monotone = true, inside = true;
  double prev = dom.min;
  for (int i = 0; i <= 40; ++i) {
    const double t = line.ParameterAtArcLength(length * i / 40.0, 1000);
    monotone = monotone && t >= prev;
    inside = inside && t >= dom.min && t <= dom.max;
    prev = t;
  }
  Check(monotone && inside, "ParameterAtArcLength stays monotone and inside the domain across its whole range");
  const auto divisions = line.DivideByCount(5, 1000);
  Check(divisions.size() == 6 && divisions.front() == dom.min && divisions.back() == dom.max,
        "DivideByCount on the same polyline still ends exactly at the domain bounds");
}

// Regression test for a real scale bug in NurbsSurface::CurvatureAt():
// its "degenerate first fundamental form" guard was the ABSOLUTE test
// `EG - F^2 < 1e-15`, but EG - F^2 scales with length^4, so a perfectly
// regular point on a radius-1e-4 sphere (EG - F^2 ~ 1e-16) threw while
// the same point on a radius-1 sphere returned K = 1/r^2 as it should. The
// guard is now relative (the partials' angle). A genuinely singular point
// (the pole) must still throw.
void TestSurfaceCurvatureAtIsScaleInvariant() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;
  using dino8::kernel::SurfaceCurvature;

  for (double r : {1.0, 1e-4, 1e-6}) {
    NurbsSurface s;
    ON_Sphere sphere(Point3d(0.3 * r, -0.7 * r, 1.1 * r), r);
    sphere.GetNurbForm(s.raw());
    const auto du = s.Domain(0), dv = s.Domain(1);
    const double u = du.min + 0.37 * (du.max - du.min);
    const double v = dv.min + 0.41 * (dv.max - dv.min);
    bool threw = false;
    SurfaceCurvature k{0, 0, 0, 0};
    try {
      k = s.CurvatureAt(u, v);
    } catch (const std::runtime_error&) {
      threw = true;
    }
    char msg[200];
    std::snprintf(msg, sizeof msg,
                  "CurvatureAt on a radius-%g sphere at a regular point does not throw 'degenerate' (used to "
                  "for r <= 1e-4)",
                  r);
    Check(!threw, msg);
    if (!threw) {
      std::snprintf(msg, sizeof msg, "radius-%g sphere: Gaussian curvature * r^2 = %.9g (expect 1)", r,
                    k.gaussian * r * r);
      Check(std::abs(k.gaussian * r * r - 1.0) < 1e-6, msg);
      std::snprintf(msg, sizeof msg, "radius-%g sphere: |mean curvature| * r = %.9g (expect 1)", r,
                    std::abs(k.mean) * r);
      Check(std::abs(std::abs(k.mean) * r - 1.0) < 1e-6, msg);
    }
    // The pole (v at the domain end) is genuinely singular: still throws.
    bool pole_threw = false;
    try {
      s.CurvatureAt(u, dv.min);
    } catch (const std::runtime_error&) {
      pole_threw = true;
    }
    std::snprintf(msg, sizeof msg, "radius-%g sphere: CurvatureAt at the pole still throws (genuinely singular)", r);
    Check(pole_threw, msg);
  }
}

// Regression test for a real, reproduced NurbsSurface::ClosestPoint() bug
// at a degenerate edge: on a sphere's pole row every u sample evaluates
// to the same point, so the coarse scan's best u there was just the first
// tied sample (u = 0), and narrowing the u window around it locked every
// later refinement level into the wrong azimuth. A query 0.3r off the
// surface at u = pi (180 degrees from that tie-break), 0.36 degrees from
// the pole, came back with a closest point ~32 degrees of azimuth away:
// distance 0.30007r instead of 0.3r, and a returned POINT ~0.0035r from
// the true one - 3500x the true distance for a query 1e-6 r off the
// surface. Fixed by not narrowing a direction whose samples are flat.
void TestSurfaceClosestPointNearSpherePoleDoesNotLockAzimuth() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Point3d;

  for (double r : {1.0, 1e-4}) {
    const Point3d center(0.3 * r, -0.7 * r, 1.1 * r);
    NurbsSurface s;
    ON_Sphere sphere(center, r);
    sphere.GetNurbForm(s.raw());
    const auto du = s.Domain(0), dv = s.Domain(1);
    for (double fv : {0.002, 0.998}) {
      const double u = du.min + 0.5 * (du.max - du.min);
      const double v = dv.min + fv * (dv.max - dv.min);
      const Point3d on = s.PointAt(u, v);
      const Point3d query = center + (on - center) * 1.3;
      const Point3d cp = s.ClosestPoint(query);
      const double d = cp.DistanceTo(query);
      char msg[256];
      std::snprintf(msg, sizeof msg,
                    "radius-%g sphere, query 0.36 degrees from the %s pole at u=pi: ClosestPoint distance "
                    "%.12g is 0.3r to 1e-9 relative (used to be 0.30007r)",
                    r, fv < 0.5 ? "south" : "north", d / r);
      Check(std::abs(d - 0.3 * r) <= 1e-9 * r, msg);
      std::snprintf(msg, sizeof msg,
                    "...and the returned point is the radial foot itself (%.3g r away; used to be ~3.5e-3 r)",
                    cp.DistanceTo(on) / r);
      Check(cp.DistanceTo(on) <= 1e-6 * r, msg);
    }
  }
}

// ---- NurbsSurface::ExtendLinear ----

namespace {

// Point-to-line distance for a point `p`, given a point `a` on the line
// and its (not necessarily unit) direction `dir`.
double DistanceToLine(dino8::kernel::Point3d p, dino8::kernel::Point3d a, ON_3dVector dir) {
  dir.Unitize();
  const ON_3dVector w = p - a;
  const ON_3dVector perp = w - dir * ON_DotProduct(w, dir);
  return perp.Length();
}

}  // namespace

void TestSurfaceExtendLinearIsExactlyStraightAndG1AtTheJoin() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Result;

  NurbsSurface s = WigglyBicubic(5, 4);  // degree 3x3, genuinely curved
  const NurbsSurface original = s;
  const double u_old = original.Domain(0).max;  // FromControlGrid's own clamped-uniform domain end (not necessarily CV count - 1)
  const double u_new = u_old + 6.0;
  const double v_lo = s.Domain(1).min, v_hi = s.Domain(1).max;

  // Boundary points and true end derivatives (U-direction) at u = u_old,
  // for several different v - the surface's own cross-boundary
  // derivative genuinely varies with v (a wiggly, non-ruled edge), so
  // this exercises the per-row construction, not just one shared line.
  const std::vector<double> vs = {v_lo, v_lo + (v_hi - v_lo) * 0.3, v_lo + (v_hi - v_lo) * 0.7, v_hi};
  std::vector<dino8::kernel::Point3d> boundary_pt(vs.size());
  std::vector<ON_3dVector> boundary_deriv(vs.size());
  for (size_t i = 0; i < vs.size(); ++i) {
    ON_3dPoint pt;
    ON_3dVector du, dv;
    original.raw().Ev1Der(u_old, vs[i], pt, du, dv);
    boundary_pt[i] = pt;
    boundary_deriv[i] = du;
  }

  const Result r = s.ExtendLinear(0, s.Domain(0).min, u_new);
  Check(r == Result::Ok, "ExtendLinear extends the U-max end successfully");
  Check(std::abs(s.Domain(0).max - u_new) < 1e-9, "ExtendLinear reaches exactly the requested new domain end");
  Check(std::abs(s.Domain(0).min - original.Domain(0).min) < 1e-12, "ExtendLinear leaves the untouched (min) end of the same direction alone");
  Check(std::abs(s.Domain(1).min - original.Domain(1).min) < 1e-12 && std::abs(s.Domain(1).max - original.Domain(1).max) < 1e-12,
        "ExtendLinear leaves the other direction's domain completely unchanged");

  // Straightness: every sampled point in the NEW region, for each of
  // the 4 rows, lies exactly on that row's own boundary tangent line -
  // not merely "low curvature", a hard zero-distance check.
  double worst_line_dev = 0.0;
  for (size_t i = 0; i < vs.size(); ++i) {
    for (int k = 0; k <= 20; ++k) {
      const double u = u_old + (u_new - u_old) * k / 20.0;
      worst_line_dev = std::max(worst_line_dev, DistanceToLine(s.PointAt(u, vs[i]), boundary_pt[i], boundary_deriv[i]));
    }
  }
  Check(worst_line_dev < 1e-9, "ExtendLinear: every sampled point in the new region lies exactly on its row's boundary tangent line (< 1e-9)");

  // Exact endpoint position, not just "somewhere on the line": the
  // construction is a constant-velocity extrapolation holding the
  // boundary's own derivative fixed, so PointAt(u_new) must equal
  // EXACTLY boundary_pt + (u_new - u_old) * boundary_deriv - this is
  // the check that actually pins down the *speed* along the line (the
  // "on the line" check above alone can't distinguish this from any
  // other constant multiple of the same direction, since a uniformly
  // mis-scaled arithmetic progression is still perfectly collinear).
  double worst_endpoint_err = 0.0;
  for (size_t i = 0; i < vs.size(); ++i) {
    const dino8::kernel::Point3d expected = boundary_pt[i] + boundary_deriv[i] * (u_new - u_old);
    worst_endpoint_err = std::max(worst_endpoint_err, s.PointAt(u_new, vs[i]).DistanceTo(expected));
  }
  Check(worst_endpoint_err < 1e-9,
        "ExtendLinear: the new domain endpoint lands exactly at boundary_pt + (u_new - u_old) * boundary_deriv (pins down the extrapolation speed, not just direction)");

  // The old (unextended) region is bit-identical - this operation only
  // adds new control points/knots, never touches the original ones.
  double old_region_err = 0.0;
  for (int k = 0; k <= 20; ++k) {
    const double u = original.Domain(0).min + (u_old - original.Domain(0).min) * k / 20.0;
    for (double v : vs) old_region_err = std::max(old_region_err, s.PointAt(u, v).DistanceTo(original.PointAt(u, v)));
  }
  Check(old_region_err < 1e-9, "ExtendLinear leaves the original (pre-extension) region of the surface unchanged");

  // G1 continuity at the join: the extended surface's own U-derivative
  // evaluated exactly at u = u_old (still inside its new, larger
  // domain) matches the ORIGINAL surface's boundary derivative exactly
  // - the real substance of "tangent-continuous", not just "looks
  // smooth".
  double worst_deriv_err = 0.0;
  for (size_t i = 0; i < vs.size(); ++i) {
    ON_3dPoint pt;
    ON_3dVector du, dv;
    s.raw().Ev1Der(u_old, vs[i], pt, du, dv);
    worst_deriv_err = std::max(worst_deriv_err, (du - boundary_deriv[i]).Length());
  }
  Check(worst_deriv_err < 1e-9, "ExtendLinear: the extended surface's own derivative at the join exactly matches the original boundary derivative (G1)");

  // But NOT G2: the new region has zero curvature (it's straight) while
  // the original surface at that same boundary is genuinely curved -
  // confirming this is really "linear", not a disguised smooth extend.
  const auto orig_curv = original.CurvatureAt(u_old, vs[1]);
  Check(std::abs(orig_curv.gaussian) > 1e-3 || std::abs(orig_curv.mean) > 1e-3,
        "ExtendLinear setup: the original wiggly surface genuinely has nonzero curvature at the join");
}

void TestSurfaceExtendLinearDiffersFromSmoothExtend() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Result;

  NurbsSurface linear = WigglyBicubic(5, 4);
  NurbsSurface smooth = linear;
  const double u_old = linear.Domain(0).max, u_new = u_old + 6.0, v_mid = linear.Domain(1).max * 0.5;
  Check(linear.ExtendLinear(0, linear.Domain(0).min, u_new) == Result::Ok, "ExtendLinear (comparison setup) succeeds");
  Check(smooth.Extend(0, smooth.Domain(0).min, u_new) == Result::Ok, "Extend (comparison setup, smooth) succeeds");

  // Both agree at the join (position and, to the extent Extend() also
  // matches derivative there - both must at least agree on position).
  Check(linear.PointAt(u_old, v_mid).DistanceTo(smooth.PointAt(u_old, v_mid)) < 1e-9,
        "ExtendLinear and Extend agree exactly at the join itself (both continue from the same boundary)");

  // But diverge further into the new region, since one follows the
  // original curvature and the other goes straight - a real, measured
  // difference, not a rounding-level one.
  double diff = 0.0;
  for (int k = 1; k <= 20; ++k) {
    const double u = u_old + (u_new - u_old) * k / 20.0;
    diff = std::max(diff, linear.PointAt(u, v_mid).DistanceTo(smooth.PointAt(u, v_mid)));
  }
  Check(diff > 1e-3, "ExtendLinear's straight extension measurably diverges from Extend()'s curvature-continuing one further from the join");
}

void TestSurfaceExtendLinearBothEndsBothDirectionsAndRational() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Result;

  // Both ends of U at once.
  {
    NurbsSurface s = WigglyBicubic(5, 4);
    const NurbsSurface original = s;
    const double v_mid = original.Domain(1).min + (original.Domain(1).max - original.Domain(1).min) * 0.5;
    Check(s.ExtendLinear(0, -5.0, 12.0) == Result::Ok, "ExtendLinear extends both U ends at once");
    Check(std::abs(s.Domain(0).min - (-5.0)) < 1e-9 && std::abs(s.Domain(0).max - 12.0) < 1e-9,
          "ExtendLinear's both-ends domain is exactly [-5, 12]");
    ON_3dPoint pt;
    ON_3dVector du, dv;
    original.raw().Ev1Der(original.Domain(0).min, v_mid, pt, du, dv);
    Check(DistanceToLine(s.PointAt(-5.0, v_mid), pt, du) < 1e-9, "ExtendLinear's min-end extension also lies exactly on the boundary tangent line");
  }
  // V direction (not just U) - confirms the row/column index logic in
  // ExtendOneEndLinear isn't accidentally U-only.
  {
    NurbsSurface s = WigglyBicubic(4, 5);  // degree 3x3, U has 4 CVs, V has 5
    const NurbsSurface original = s;
    const double u_mid = original.Domain(0).min + (original.Domain(0).max - original.Domain(0).min) * 0.5;
    const double v_old = original.Domain(1).max, v_new = v_old + 6.0;
    Check(s.ExtendLinear(1, original.Domain(1).min, v_new) == Result::Ok, "ExtendLinear extends the V direction");
    Check(std::abs(s.Domain(1).max - v_new) < 1e-9, "ExtendLinear's V-direction domain reaches exactly the requested new end");
    Check(std::abs(s.Domain(0).min - original.Domain(0).min) < 1e-12 && std::abs(s.Domain(0).max - original.Domain(0).max) < 1e-12,
          "ExtendLinear(direction=1) leaves the U domain untouched");
    ON_3dPoint pt;
    ON_3dVector du, dv;
    original.raw().Ev1Der(u_mid, v_old, pt, du, dv);
    double worst = 0.0;
    for (int k = 0; k <= 10; ++k) {
      const double v = v_old + (v_new - v_old) * k / 10.0;
      worst = std::max(worst, DistanceToLine(s.PointAt(u_mid, v), pt, dv));
    }
    Check(worst < 1e-9, "ExtendLinear(direction=1)'s extension lies exactly on the boundary's V-tangent line");
  }
  // A genuine rational surface (sphere): the homogeneous-space
  // arithmetic-progression construction must still trace an exact
  // straight line in real 3D Euclidean space, not merely in projective
  // (homogeneous) space.
  {
    ON_NurbsSurface sphere_raw;
    ON_Sphere(ON_3dPoint(1, -2, 3), 2.5).GetNurbForm(sphere_raw);
    NurbsSurface sphere;
    sphere.raw() = sphere_raw;
    Check(sphere.IsRational(), "ExtendLinear rational setup: the sphere NURBS form is rational");
    const NurbsSurface original_sphere = sphere;
    const double v_max = sphere.Domain(1).max;
    const double new_v_max = v_max + (sphere.Domain(1).max - sphere.Domain(1).min);
    const Result r = sphere.ExtendLinear(1, sphere.Domain(1).min, new_v_max);
    Check(r == Result::Ok, "ExtendLinear succeeds on a genuine rational (sphere) surface");
    ON_3dPoint pt;
    ON_3dVector du, dv;
    original_sphere.raw().Ev1Der(original_sphere.Domain(0).min, v_max, pt, du, dv);
    double worst = 0.0;
    for (int k = 1; k <= 10; ++k) {
      const double v = v_max + (new_v_max - v_max) * k / 10.0;
      worst = std::max(worst, DistanceToLine(sphere.PointAt(sphere.Domain(0).min, v), pt, dv));
    }
    Check(worst < 1e-6, "ExtendLinear on a rational sphere: the extension is still an exact straight line in 3D (< 1e-6, float-mesh-free double precision)");
  }
}

void TestSurfaceExtendLinearNoOpAndRefusalChecks() {
  using dino8::kernel::NurbsSurface;
  using dino8::kernel::Result;

  NurbsSurface s = WigglyBicubic(5, 4);
  const dino8::kernel::Interval d = s.Domain(0);
  Check(s.ExtendLinear(0, d.min, d.max) == Result::NoOpAlreadySatisfied, "ExtendLinear reports a no-op when the requested domain is already covered");
  Check(s.ExtendLinear(0, d.max, d.min) == Result::Failed, "ExtendLinear refuses t0 >= t1");

  bool threw = false;
  try { s.ExtendLinear(2, 0.0, 1.0); } catch (const std::invalid_argument&) { threw = true; }
  Check(threw, "ExtendLinear throws on a direction other than 0/1");

  // A closed direction (a full cylinder wall, closed in U) is refused,
  // same restriction Extend() already documents for the same reason.
  const ON_Circle circle(ON_Plane(ON_3dPoint(0, 0, 0), ON_3dVector(0, 0, 1)), 2.0);
  const ON_Cylinder cylinder(circle, 5.0);
  ON_NurbsSurface cyl_raw;
  cylinder.GetNurbForm(cyl_raw);
  NurbsSurface wall;
  wall.raw() = cyl_raw;
  Check(wall.IsClosed(0), "ExtendLinear closed-direction setup: the full cylinder wall is closed in U");
  Check(wall.ExtendLinear(0, wall.Domain(0).min - 1.0, wall.Domain(0).max) == Result::Failed,
        "ExtendLinear refuses to extend a closed direction");
}

// dino8::kernel::CounterboreHole - a real kernel-native feature operation
// (PARITY_MAP.md's "kernel: Feature operations" Counterbore item), composed
// from two coaxial BooleanCombineMixed(..., BooleanOp::Difference) passes:
// the narrow drill cylinder first, then the wider, shallower counterbore
// cylinder, which lands squarely in the already-supported coaxial
// (radially-nested, axially-overlapping) CYLINDER/CYLINDER Difference case
// (boolean.h's own BooleanCombineMixed doc comment, "CYLINDER/CYLINDER
// (PARALLEL AXES)" section).
void TestCounterboreHoleArgumentChecks() {
  using dino8::kernel::Brep;
  using dino8::kernel::CounterboreHole;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const Point3d origin(5, 5, 10);
  const Vector3d axis(0, 0, -1);

  auto throws_invalid_argument = [&](auto&& call) {
    try {
      call();
    } catch (const std::invalid_argument&) {
      return true;
    }
    return false;
  };

  Check(throws_invalid_argument([&] { CounterboreHole(box, origin, Vector3d(0, 0, 0), 1.0, 10.0, 2.0, 3.0); }),
        "CounterboreHole throws on a zero-length axis");
  Check(throws_invalid_argument([&] { CounterboreHole(box, origin, axis, 0.0, 10.0, 2.0, 3.0); }),
        "CounterboreHole throws on a non-positive drill_radius");
  Check(throws_invalid_argument([&] { CounterboreHole(box, origin, axis, 1.0, 0.0, 2.0, 3.0); }),
        "CounterboreHole throws on a non-positive drill_depth");
  Check(throws_invalid_argument([&] { CounterboreHole(box, origin, axis, 1.0, 10.0, 1.0, 3.0); }),
        "CounterboreHole throws when counterbore_radius does not exceed drill_radius (not a counterbore at all)");
  Check(throws_invalid_argument([&] { CounterboreHole(box, origin, axis, 1.0, 10.0, 2.0, 0.0); }),
        "CounterboreHole throws on a non-positive counterbore_depth");
  Check(throws_invalid_argument([&] { CounterboreHole(box, origin, axis, 1.0, 10.0, 2.0, 10.5); }),
        "CounterboreHole throws when counterbore_depth exceeds drill_depth");

  // The same call with every argument in range does NOT throw - the
  // checks above are genuinely rejecting only the bad cases, not
  // everything.
  bool ok_call_threw = false;
  try {
    CounterboreHole(box, origin, axis, 1.0, 10.0, 2.0, 3.0);
  } catch (const std::invalid_argument&) {
    ok_call_threw = true;
  }
  Check(!ok_call_threw, "CounterboreHole does not throw on an in-range, well-formed call");
}

// The main geometric check: drilling a counterbore straight down through
// the top face of a box, exactly through (drill_depth == box height, the
// same "coincident cap height" edge case TestBooleanCombineMixedDrilledBoxCoincidentCapHeight
// already exercises for a plain single-cylinder hole).
void TestCounterboreHoleAxisAlignedVolumeAndTopology() {
  using dino8::kernel::Brep;
  using dino8::kernel::BooleanCombine;
  using dino8::kernel::CounterboreHole;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const double drill_radius = 1.0;
  const double drill_depth = 10.0;
  const double counterbore_radius = 2.0;
  const double counterbore_depth = 3.0;

  const Brep result = CounterboreHole(box, Point3d(5, 5, 10), Vector3d(0, 0, -1), drill_radius, drill_depth,
                                       counterbore_radius, counterbore_depth);

  Check(result.raw().IsValid(), "CounterboreHole's result is a genuinely valid ON_Brep");
  Check(result.FaceCount() > box.FaceCount(),
        "CounterboreHole's result has strictly more faces than the untouched box - real topology was cut, not a "
        "no-op");

  // Hand-derived exact volume: box (1000) minus the UNION of the drill
  // cylinder (radius 1, full height 10: pi*1^2*10 = 10*pi) and the
  // counterbore cylinder (radius 2, depth 3 at the top: pi*2^2*3 = 12*pi),
  // whose intersection is exactly the drill cylinder's own top 3 units
  // (pi*1^2*3 = 3*pi) since the counterbore radius strictly contains the
  // drill radius and sits at the same starting face. Union volume =
  // 10*pi + 12*pi - 3*pi = 19*pi.
  const double hand_derived_volume = 1000.0 - ON_PI * 19.0;  // ~= 940.3097

  const Mesh mesh_256 = result.TessellateToClosedMesh(256, 256);
  const double measured_volume = mesh_256.Volume();
  Check(std::fabs(measured_volume - hand_derived_volume) < 0.1,
        "CounterboreHole's tessellated volume (div=256) matches the hand-derived 1000-19*pi to within 0.1 - a real "
        "bounded arc-sampling/tessellation tolerance across TWO composed drilling passes, not floating-point "
        "exactness (see TestBooleanCombineMixedDrilledBoxThroughHole's own comment for why a single pass alone "
        "already carries this kind of bounded error)");

  // Second, fully independent derivation via the mesh-based (Manifold)
  // boolean path: build both cutters as real closed solid cylinder
  // meshes, union them, and subtract that union from the box's own mesh -
  // entirely separate machinery from BooleanCombineMixed's exact B-rep
  // pipeline.
  const Mesh mesh_box = box.TessellateToClosedMesh(64, 64);
  const Mesh mesh_drill = Mesh::Cylinder(Point3d(5, 5, 0), Vector3d(0, 0, 1), drill_radius, drill_depth,
                                          /*circle_segments=*/200, /*grid_divisions=*/64);
  const Mesh mesh_counterbore =
      Mesh::Cylinder(Point3d(5, 5, 10 - counterbore_depth), Vector3d(0, 0, 1), counterbore_radius, counterbore_depth,
                      /*circle_segments=*/200, /*grid_divisions=*/64);
  const Mesh mesh_cutters_union = BooleanCombine(mesh_drill, mesh_counterbore, dino8::kernel::BooleanOp::Union);
  const Mesh mesh_diff = BooleanCombine(mesh_box, mesh_cutters_union, dino8::kernel::BooleanOp::Difference);
  Check(std::fabs(mesh_diff.Volume() - hand_derived_volume) < 0.5,
        "the independent mesh-based (Manifold) Difference of the same box against the UNION of both cutters' own "
        "tessellations also matches the hand-derived volume, within Manifold's own single-precision-mesh tolerance");
  Check(std::fabs(mesh_diff.Volume() - measured_volume) < 0.5,
        "CounterboreHole's own exact-B-rep volume and the independent mesh-based Manifold volume agree with each "
        "other, not just with the hand-derived value separately");
}

// A blind (non-through) counterbore: confirms a counterbore need not
// reach all the way through the solid.
//
// Not also tested here with an OBLIQUE drilling axis (MakeAxisFrame's own
// arbitrary-axis frame construction is otherwise exact and axis-agnostic
// - only this specific downstream call is the issue): confirmed directly
// that a large-enough combination of radius and axis tilt trips
// BooleanCombineMixed's own disclosed, out-of-scope "oblique plane's own
// intersection with a cylindrical face enters/exits across only part of
// the swept angle" non-monotonic case (boolean.cpp's
// SplitCylindricalByObliquePlane) regardless of how much margin the
// cutter is given past the surface - a real, pre-existing kernel
// limitation on steep-tilt oblique holes in general, not something this
// feature's own composition could route around, and out of scope to fix
// in this increment.
void TestCounterboreHoleBlindAxisAlignedVolume() {
  using dino8::kernel::Brep;
  using dino8::kernel::CounterboreHole;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);

  // A blind hole straight down from the top, not reaching the bottom.
  const double drill_radius = 1.5;
  const double drill_depth = 6.0;  // z: 10 -> 4, strictly inside the box.
  const double counterbore_radius = 2.5;
  const double counterbore_depth = 2.0;

  const Brep blind = CounterboreHole(box, Point3d(5, 5, 10), Vector3d(0, 0, -1), drill_radius, drill_depth,
                                      counterbore_radius, counterbore_depth);
  Check(blind.raw().IsValid(), "a blind (non-through) counterbore's result is a genuinely valid ON_Brep");

  const double hand_derived_blind_volume =
      1000.0 - (ON_PI * drill_radius * drill_radius * drill_depth +
                ON_PI * counterbore_radius * counterbore_radius * counterbore_depth -
                ON_PI * drill_radius * drill_radius * counterbore_depth);
  const double measured_blind_volume = blind.TessellateToClosedMesh(256, 256).Volume();
  Check(std::fabs(measured_blind_volume - hand_derived_blind_volume) < 0.1,
        "a blind counterbore's tessellated volume matches its own hand-derived value (box minus the union of a "
        "6-unit-deep drill and a 2-unit-deep counterbore, both stopping short of the box's own far side)");
}

// The geometric inverse of CounterboreHole() (features.cpp): closes
// RecognizeHoles()'s own disclosed "no attempt is made here to recognize
// a COUNTERBORE/COUNTERSINK's own second, wider cylindrical/conical step
// as part of the SAME feature" gap, for the CYLINDRICAL-step case (a real
// counterbore, built via CounterboreHole()'s own two-CylindricalFace
// construction - NOT MakeCounterboreHole()'s single Brep::Revolve() wall,
// which ON_Surface::IsCylinder() never classifies as a cylinder at all,
// see TestMakeCounterboreHoleBoxStepped()'s own doc comment).
void TestRecognizeCounterboreHolesRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::CounterboreFeature;
  using dino8::kernel::CounterboreHole;
  using dino8::kernel::MakeHole;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeCounterboreHoles;
  using dino8::kernel::RecognizeHoles;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const Point3d origin(5, 5, 10);
  const Vector3d down(0, 0, -1);
  const double drill_radius = 1.0, drill_depth = 6.0;
  const double counterbore_radius = 2.0, counterbore_depth = 3.0;

  const Brep result =
      CounterboreHole(box, origin, down, drill_radius, drill_depth, counterbore_radius, counterbore_depth);

  // Sanity: RecognizeHoles() itself still sees this as TWO separate holes
  // (its own disclosed limitation) - confirms this fixture actually
  // exercises the gap RecognizeCounterboreHoles() closes, rather than
  // some fixture RecognizeHoles() already handled correctly on its own.
  Check(RecognizeHoles(result).size() == 2,
        "sanity: RecognizeHoles() itself still reports a counterbore's two steps as two independent HoleFeature "
        "entries");

  const std::vector<CounterboreFeature> found = RecognizeCounterboreHoles(result);
  Check(found.size() == 1, "RecognizeCounterboreHoles merges the two steps into exactly one compound feature");
  const CounterboreFeature& cf = found[0];
  Check(cf.origin.DistanceTo(origin) < 1e-6, "RecognizeCounterboreHoles recovers the counterbore's own exact entry point");
  Check((cf.axis - down).Length() < 1e-6,
        "RecognizeCounterboreHoles recovers the counterbore's own exact drilling direction");
  Check(std::abs(cf.counterbore_radius - counterbore_radius) < 1e-6,
        "RecognizeCounterboreHoles recovers the counterbore's own exact recess radius");
  Check(std::abs(cf.counterbore_depth - counterbore_depth) < 1e-6,
        "RecognizeCounterboreHoles recovers the counterbore's own exact recess depth");
  Check(std::abs(cf.drill_radius - drill_radius) < 1e-6,
        "RecognizeCounterboreHoles recovers the pilot bore's own exact radius");
  Check(std::abs(cf.drill_depth - drill_depth) < 1e-6,
        "RecognizeCounterboreHoles recovers the pilot bore's own exact total depth, measured from the entry "
        "surface (not just the pilot segment's own length)");
  Check(!cf.through, "RecognizeCounterboreHoles reports this blind pilot bore as NOT through");

  // Round-trip: feed the recognized parameters straight back into
  // CounterboreHole() against a fresh box and confirm it reproduces the
  // original's own volume - the real test these numbers are usable, not
  // merely plausible-looking.
  const Brep rebuilt =
      CounterboreHole(box, cf.origin, cf.axis, cf.drill_radius, cf.drill_depth, cf.counterbore_radius, cf.counterbore_depth);
  const Mesh original_mesh = result.TessellateToClosedMesh(64, 64);
  const Mesh rebuilt_mesh = rebuilt.TessellateToClosedMesh(64, 64);
  Check(std::abs(original_mesh.Volume() - rebuilt_mesh.Volume()) < 0.5,
        "CounterboreHole(box, recognized_origin, recognized_axis, recognized_drill_radius, recognized_drill_depth, "
        "recognized_counterbore_radius, recognized_counterbore_depth) reproduces the original counterbore's own "
        "volume");

  // Negative control: a plain single-radius through hole has no step to
  // merge into anything.
  const Brep single = MakeHole(box, origin, down, drill_radius, /*depth=*/0.0, /*through=*/true);
  Check(RecognizeCounterboreHoles(single).empty(),
        "RecognizeCounterboreHoles finds no compound step on a plain single-radius hole");
}

// Builds a countersink-shaped tool - a conical frustum (wide mouth ->
// narrow bore_radius) immediately followed by a straight cylindrical bore
// segment, MakeCountersinkHole()'s own two-piece geometry (see that
// function's own "standard countersink geometry" doc comment,
// boolean_general.h, for the derived countersink_depth formula) - but as
// two DISCRETE analytic Brep::ConicalFace/Brep::CylindricalFace primitives
// (CounterboreHole()'s own "adjacent same-axis segments via
// FromMixedFaces()" construction, features.cpp, generalized to a conical
// first segment) rather than MakeCountersinkHole()'s own single Revolve()
// wall - so the cone IS recognizable by ON_Surface::IsCone(), unlike
// MakeCountersinkHole()'s own product (see RecognizeCountersinkHoles()'s
// own doc comment, features.h, for why that distinction matters here).
// `origin` is the entry point on `solid`'s own surface, `axis` points INTO
// the material (MakeHole()'s own convention), and `bore_depth` is the
// TOTAL axial distance from `origin` to the pilot bore's own far end
// (MakeCountersinkHole()'s own `bore_depth` convention, not just the
// straight-bore segment's own length).
//
// Subtracted via BooleanCombineGeneral() rather than BooleanCombineMixed()
// specifically because BooleanCombineMixed() itself refuses any operand
// carrying a ConicalFace outright (boolean.h's own doc comment, confirmed
// directly by TestBooleanCombineMixedRefusesConicalFaceOperand elsewhere
// in this file) - BooleanCombineGeneral() has no such restriction.
//
// Unlike BooleanCombineMixed() (boolean.cpp), which situationally
// synthesizes a bare, uncapped CylindricalFace tool's own end material
// during the boolean itself (see MakeCylinderZ()'s own doc comment,
// scratch_test.cpp), BooleanCombineGeneral() has no such special-casing -
// confirmed directly (dino8_scratch_test): an UNCAPPED cone+cylinder tool
// throws "an edge is claimed by 3 or more fragment loops" even for a
// fixture with every cap well clear of every box face, an open-tube
// operand fed to an engine that requires a genuinely closed solid. The
// tool is therefore explicitly capped - but a SECOND, independently
// confirmed (dino8_scratch_test) coincident-face degeneracy also applies
// here: a tool cap landing exactly ON `solid`'s own surface (not just
// past it) throws the identical error, the same pitfall
// MakeHole()/MakeCountersinkHole() (boolean_general.cpp) avoid by backing
// their own cutting tool off the entry surface by a small margin. Since
// `origin` sits exactly ON `solid`'s own surface by construction, the
// tool's own wide mouth cap can't sit there directly - a short
// `margin`-length cylindrical SLEEVE (radius countersink_radius) is
// prepended, so the tool's own TRUE outer cap floats just outside `solid`
// instead, and the sleeve/cone transition (still exactly at `origin`)
// becomes an ordinary interior weld rather than an operand boundary.
dino8::kernel::Brep BuildCountersinkHoleFixture(const dino8::kernel::Brep& solid, dino8::kernel::Point3d origin,
                                                 dino8::kernel::Vector3d axis, double countersink_radius,
                                                 double countersink_angle_degrees, double bore_radius,
                                                 double bore_depth) {
  using dino8::kernel::BooleanCombineGeneral;
  using dino8::kernel::BooleanOp;
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  Vector3d dir = axis;
  dir.Unitize();
  const double half_angle = countersink_angle_degrees * ON_PI / 360.0;
  const double countersink_depth = (countersink_radius - bore_radius) / std::tan(half_angle);
  const Point3d transition = origin + dir * countersink_depth;
  const double cyl_length = bore_depth - countersink_depth;
  const double margin = std::max(0.5, countersink_radius * 0.25);

  Brep::CylindricalFace sleeve;
  sleeve.frame = FrameFromAxisForGeneralBooleanTest(origin - dir * margin, dir);
  sleeve.radius = countersink_radius;
  sleeve.angle = 2.0 * ON_PI;
  sleeve.length = margin;

  // The cone segment, via MakeFrustumAxisForGeneralBooleanTest()'s own
  // "base = narrow end (r0), axis points toward the wide end (r1)"
  // convention - so base=transition (radius bore_radius), its own axis
  // -dir (toward the wide mouth, the opposite sense from `dir`'s "into the
  // material" convention).
  const ON_Plane cone_base_frame = FrameFromAxisForGeneralBooleanTest(transition, -dir);
  Brep::ConicalFace cone;
  cone.frame = cone_base_frame;
  // The apex sits FURTHER into the material beyond `transition` - where a
  // full cone's own radius would extrapolate to exactly zero - at distance
  // bore_radius/tan(half_angle) past it, the same similar-triangles
  // relationship ConicalFace's own doc comment (brep.h) describes for a
  // patch's "distance from apex to its own start".
  cone.frame.origin = transition - cone_base_frame.zaxis * (bore_radius / std::tan(half_angle));
  cone.frame.UpdateEquation();
  cone.radius0 = bore_radius;         // at the narrow end (transition)
  cone.radius1 = countersink_radius;  // at the wide end (origin, the mouth)
  cone.angle = 2.0 * ON_PI;
  cone.length = countersink_depth;

  const ON_Plane cyl_frame = FrameFromAxisForGeneralBooleanTest(transition, dir);
  Brep::CylindricalFace cyl;
  cyl.frame = cyl_frame;
  cyl.radius = bore_radius;
  cyl.angle = 2.0 * ON_PI;
  cyl.length = cyl_length;

  // Only the tool's own two TRUE outer ends are capped (flip=false, the
  // "far cap in its own local frame" convention DiskCapForGeneralBooleanTest's
  // other callers already use, since h=0 is each own segment's own NEAR
  // end) - every interior transition (sleeve/cone at `origin`, cone/cyl at
  // `transition`) is deliberately left uncapped so FromMixedFaces() welds
  // each into one interior edge instead.
  const Brep::PlanarFace mouth_cap = DiskCapForGeneralBooleanTest(sleeve.frame, 0.0, countersink_radius, /*flip=*/true);
  const Brep::PlanarFace far_cap = DiskCapForGeneralBooleanTest(cyl_frame, cyl_length, bore_radius, /*flip=*/false);

  const Brep tool = Brep::FromMixedFaces({mouth_cap, far_cap}, {sleeve, cyl}, {cone});
  return BooleanCombineGeneral(solid, tool, BooleanOp::Difference);
}

// parity-map "kernel: Feature operations" - "Feature recognition": closes
// RecognizeCounterboreHoles()'s own disclosed "a countersink's own conical
// step ... is a different surface type entirely and is not merged here"
// gap. RecognizeCountersinkHoles() merges a concave full-cone face with an
// adjacent concave full-cylinder face into one CountersinkFeature, the
// conical sibling of RecognizeCounterboreHoles() above.
void TestRecognizeCountersinkHolesRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::CounterboreHole;
  using dino8::kernel::CountersinkFeature;
  using dino8::kernel::MakeCountersinkHole;
  using dino8::kernel::MakeHole;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeCounterboreHoles;
  using dino8::kernel::RecognizeCountersinkHoles;
  using dino8::kernel::RecognizeHoles;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const Point3d origin(5, 5, 10);
  const Vector3d down(0, 0, -1);

  {
    // A THROUGH countersink at a standard 90-degree included angle - the
    // tool's own nominal bore_depth (12.0) deliberately extends PAST the
    // box's own 10-unit height, so its far cap floats below the box rather
    // than landing exactly flush with the bottom face - the same
    // "deliberately uses a depth past the box's own height rather than
    // exactly equal to it" avoidance EmbossProfile's own pitfall note
    // (features.h) already establishes for the identical
    // BooleanCombineGeneral() "edge is claimed by 3 or more fragment
    // loops" coincident-face degeneracy (confirmed directly: bore_depth ==
    // 10.0 exactly throws that very error). The RESULT's own true bore
    // depth is therefore the box's own remaining 10.0 - origin.z, not the
    // tool's own nominal 12.0 - RecognizeCountersinkHoles() must recover
    // that CLIPPED value, the real test here.
    const double countersink_radius = 2.0, angle_degrees = 90.0;
    const double bore_radius = 0.5, tool_bore_depth = 12.0;  // extends 2 units past the box's own bottom face
    const double true_bore_depth = 10.0;                     // the box's own real depth from origin.z to z=0
    const Brep result = BuildCountersinkHoleFixture(box, origin, down, countersink_radius, angle_degrees, bore_radius,
                                                      tool_bore_depth);

    // Sanity: RecognizeHoles() itself never reports the cone at all (it
    // only ever scans for a full CYLINDER) and RecognizeCounterboreHoles()
    // finds no cylindrical/cylindrical step here - confirms this fixture
    // genuinely exercises the gap being closed, not something either
    // function already handled.
    Check(RecognizeHoles(result).size() == 1,
          "sanity: RecognizeHoles() itself reports only the cylindrical pilot bore, never the cone");
    Check(RecognizeCounterboreHoles(result).empty(),
          "sanity: RecognizeCounterboreHoles() itself finds no cylindrical/cylindrical step on a countersink");

    const std::vector<CountersinkFeature> found = RecognizeCountersinkHoles(result);
    Check(found.size() == 1, "RecognizeCountersinkHoles merges the cone and the pilot bore into exactly one compound feature");
    const CountersinkFeature& cf = found[0];
    Check(cf.origin.DistanceTo(origin) < 1e-6, "RecognizeCountersinkHoles recovers the countersink's own exact entry point");
    Check((cf.axis - down).Length() < 1e-6, "RecognizeCountersinkHoles recovers the countersink's own exact drilling direction");
    // Loose (not 1e-6) tolerance here specifically: unlike origin/axis/
    // bore_radius/bore_depth (all read off a real SHARED interior edge
    // between two analytic tool faces, exact to floating-point precision),
    // the mouth diameter/angle are read off the cone's OWN wide end, whose
    // true radius is perturbed by a few parts in 1e3 through
    // BooleanCombineGeneral()'s own SSX curve-intersection sampling
    // against `solid`'s flat top face (confirmed directly,
    // dino8_scratch_test: ~0.09% on diameter, ~0.08% on angle at this
    // fixture's own default SSX tolerance) - a real, small numerical
    // effect of the general boolean engine itself, not a recognition bug.
    Check(std::abs(cf.countersink_diameter - 2.0 * countersink_radius) < 0.01,
          "RecognizeCountersinkHoles recovers the countersink's own mouth diameter to within the general boolean "
          "engine's own SSX tolerance");
    Check(std::abs(cf.countersink_angle_degrees - angle_degrees) < 0.2,
          "RecognizeCountersinkHoles recovers the countersink's own full included angle to within the general "
          "boolean engine's own SSX tolerance");
    Check(std::abs(cf.bore_radius - bore_radius) < 1e-6, "RecognizeCountersinkHoles recovers the pilot bore's own exact radius");
    Check(std::abs(cf.bore_depth - true_bore_depth) < 1e-6,
          "RecognizeCountersinkHoles recovers the pilot bore's own exact TOTAL (box-clipped) depth, not the tool's "
          "own nominal, further-reaching bore_depth");
    Check(cf.through, "RecognizeCountersinkHoles reports this through bore as through");

    const double countersink_depth = (countersink_radius - bore_radius) / std::tan(angle_degrees * ON_PI / 360.0);
    const double expected_removed = ON_PI * countersink_depth / 3.0 *
                                         (countersink_radius * countersink_radius +
                                          countersink_radius * bore_radius + bore_radius * bore_radius) +
                                     ON_PI * bore_radius * bore_radius * (true_bore_depth - countersink_depth);
    const Mesh result_mesh = result.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - (1000.0 - expected_removed)) < 0.5,
          "the through countersink's own tessellated volume matches the hand-derived closed form (box minus a "
          "cone frustum minus a cylinder)");

    // Round-trip through MakeCountersinkHole() itself (not just this
    // file's own fixture builder) - the real test that the recognized
    // parameters are usable in MakeCountersinkHole()'s own exact units and
    // convention, even though it builds the shape via a single Revolve()
    // wall rather than this fixture's discrete ConicalFace/CylindricalFace
    // pair.
    const Brep rebuilt = MakeCountersinkHole(box, cf.origin, cf.axis, cf.bore_radius, cf.bore_depth, cf.through,
                                              cf.countersink_diameter, cf.countersink_angle_degrees);
    const Mesh rebuilt_mesh = rebuilt.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - rebuilt_mesh.Volume()) < 0.5,
          "MakeCountersinkHole(box, recognized_origin, recognized_axis, recognized_bore_radius, "
          "recognized_bore_depth, recognized_through, recognized_countersink_diameter, "
          "recognized_countersink_angle_degrees) reproduces the original countersink's own volume");
  }
  {
    // A BLIND countersink at a different, also-standard angle (82 degrees)
    // - verified structurally (recognized fields + `through`), not via
    // tessellated volume, for the same disclosed reason MakeHole()'s own
    // blind case is (BooleanCombineGeneral()'s own blind-hole tessellation
    // is not reliably closed near the entry rim - see MakeHole()'s own doc
    // comment, boolean_general.h).
    const double countersink_radius = 1.5, angle_degrees = 82.0;
    const double bore_radius = 0.4, bore_depth = 4.0;  // well short of the box's own 10-unit depth
    const Brep result =
        BuildCountersinkHoleFixture(box, origin, down, countersink_radius, angle_degrees, bore_radius, bore_depth);

    const std::vector<CountersinkFeature> found = RecognizeCountersinkHoles(result);
    Check(found.size() == 1, "RecognizeCountersinkHoles merges the blind countersink's cone and pilot bore into one feature");
    const CountersinkFeature& cf = found[0];
    Check(cf.origin.DistanceTo(origin) < 1e-6, "RecognizeCountersinkHoles recovers the blind countersink's own exact entry point");
    Check((cf.axis - down).Length() < 1e-6, "RecognizeCountersinkHoles recovers the blind countersink's own exact drilling direction");
    // Same loosened tolerance as the through case above, for the same
    // "read off the SSX-perturbed mouth" reason.
    Check(std::abs(cf.countersink_diameter - 2.0 * countersink_radius) < 0.01,
          "RecognizeCountersinkHoles recovers the blind countersink's own mouth diameter to within the general "
          "boolean engine's own SSX tolerance");
    Check(std::abs(cf.countersink_angle_degrees - angle_degrees) < 0.2,
          "RecognizeCountersinkHoles recovers the blind countersink's own full included angle to within the "
          "general boolean engine's own SSX tolerance");
    Check(std::abs(cf.bore_radius - bore_radius) < 1e-6, "RecognizeCountersinkHoles recovers the blind pilot bore's own exact radius");
    Check(std::abs(cf.bore_depth - bore_depth) < 1e-6,
          "RecognizeCountersinkHoles recovers the blind pilot bore's own exact total depth");
    Check(!cf.through, "RecognizeCountersinkHoles reports this blind pilot bore as NOT through");
  }
  {
    // Negative controls: a plain single-radius hole (no cone at all) and a
    // plain cylindrical/cylindrical counterbore (RecognizeCounterboreHoles()'s
    // own domain, no conical step) both find no countersink here.
    const Brep plain_hole = MakeHole(box, origin, down, 1.0, /*depth=*/0.0, /*through=*/true);
    Check(RecognizeCountersinkHoles(plain_hole).empty(), "RecognizeCountersinkHoles finds no cone on a plain single-radius hole");

    const Brep plain_counterbore = CounterboreHole(box, origin, down, /*drill_radius=*/1.0, /*drill_depth=*/6.0,
                                                    /*counterbore_radius=*/2.0, /*counterbore_depth=*/3.0);
    Check(RecognizeCountersinkHoles(plain_counterbore).empty(),
          "RecognizeCountersinkHoles finds no cone on a plain cylindrical/cylindrical counterbore");
  }
}

// The boss-side mirror of TestRecognizeCounterboreHolesRoundTrip() above:
// closes BossFeature's own disclosed "a counterbore/countersink's own
// second step ... has no boss-side analogue implemented here" gap.
// Built via BooleanCombineMixed(box, TWO-segment bare tube, Union) - a
// single compound tool with two adjacent, non-overlapping
// Brep::CylindricalFace segments of different radii, CounterboreHole()'s
// own "compound cutter" construction (features.cpp), additive instead of
// subtractive. Deliberately NOT BooleanCombineGeneral(), whose own
// disclosed Union-side "floating base cap" gap (see BossFeature's own doc
// comment, and MakeTwoSegmentCylinder()'s own doc comment above) would
// leave Mesh::ContainsPoint() wrong across the whole embedded span; a
// flush-base Union boss built via BooleanCombineMixed is already
// well-tested elsewhere (TestBooleanCombineMixedUnionBossFlushBaseVolumeAndCapSeamIsClosed) -
// confirmed directly (dino8_scratch_test) that its own two-segment
// generalization here produces a genuinely valid ON_Brep with the correct
// closed-form volume (box + the two cylinders' own volumes) and that
// RecognizeSteppedBosses() reads it back correctly, in BOTH physical
// orientations (a wide shoulder at the base narrowing to the tip, and the
// opposite - a narrow post based in a wide pad) - unlike a counterbore, a
// stepped boss has no fixed "wide is always first" convention.
void TestRecognizeSteppedBossesRoundTrip() {
  using dino8::kernel::BooleanCombineMixed;
  using dino8::kernel::BooleanOp;
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeBosses;
  using dino8::kernel::RecognizeSteppedBosses;
  using dino8::kernel::SteppedBossFeature;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const Point3d base(5, 5, 10.0);
  const Vector3d up(0, 0, 1);
  const double shoulder_radius = 2.0, shoulder_height = 1.0;
  const double shaft_radius = 0.8, shaft_height = 3.0;
  const ON_Plane frame = FrameFromAxisForGeneralBooleanTest(base, up);

  {
    // The common case: a wide shoulder flush with the box's own top face,
    // narrowing to a free-standing shaft.
    Brep::CylindricalFace shoulder_cf;
    shoulder_cf.frame = frame;
    shoulder_cf.radius = shoulder_radius;
    shoulder_cf.angle = 2.0 * ON_PI;
    shoulder_cf.length = shoulder_height;

    Brep::CylindricalFace shaft_cf;
    shaft_cf.frame = frame;
    shaft_cf.frame.origin = frame.PointAt(0, 0, shoulder_height);
    shaft_cf.radius = shaft_radius;
    shaft_cf.angle = 2.0 * ON_PI;
    shaft_cf.length = shaft_height;

    const Brep tool = Brep::FromMixedFaces({}, {shoulder_cf, shaft_cf});
    const Brep result = BooleanCombineMixed(box, tool, BooleanOp::Union);

    // Sanity: RecognizeBosses() itself still sees this as ONE boss (its
    // own on-axis probe for the shoulder's own far end lands inside the
    // shaft, so the shoulder alone reads as "both ends attached" and is
    // silently skipped - see RecognizeBosses()'s own doc comment) -
    // confirms this fixture actually exercises a genuine compound step,
    // not something RecognizeBosses() already handles correctly as two
    // separate features the way MakeTwoSegmentCylinder()'s own
    // same-radius fixture does.
    Check(RecognizeBosses(result).size() == 1,
          "sanity: RecognizeBosses() itself reports only the shaft as an independent boss (the wider shoulder's "
          "own far end reads as attached to the shaft above it, not free)");

    const std::vector<SteppedBossFeature> found = RecognizeSteppedBosses(result);
    Check(found.size() == 1, "RecognizeSteppedBosses merges the two segments into exactly one compound feature");
    const SteppedBossFeature& sf = found[0];
    Check(!sf.through, "RecognizeSteppedBosses reports this flush-base boss as NOT through");
    Check(sf.origin.DistanceTo(base) < 1e-6, "RecognizeSteppedBosses recovers the boss's own exact base/attach point");
    Check((sf.axis - up).Length() < 1e-6, "RecognizeSteppedBosses recovers the boss's own exact outward direction");
    Check(std::abs(sf.base_radius - shoulder_radius) < 1e-6,
          "RecognizeSteppedBosses recovers the shoulder's own exact radius as the base segment");
    Check(std::abs(sf.base_height - shoulder_height) < 1e-6,
          "RecognizeSteppedBosses recovers the shoulder's own exact height as the base segment");
    Check(std::abs(sf.tip_radius - shaft_radius) < 1e-6,
          "RecognizeSteppedBosses recovers the shaft's own exact radius as the tip segment");
    Check(std::abs(sf.tip_height - shaft_height) < 1e-6,
          "RecognizeSteppedBosses recovers the shaft's own exact height as the tip segment");
  }
  {
    // The opposite orientation: a NARROW post based flush with the box's
    // own top face, flaring out to a WIDE free end - confirms
    // RecognizeSteppedBosses() doesn't assume the wider segment is always
    // the one attached (unlike RecognizeCounterboreHoles()'s own fixed
    // "recess is always the entry side" convention).
    Brep::CylindricalFace narrow_cf;
    narrow_cf.frame = frame;
    narrow_cf.radius = shaft_radius;
    narrow_cf.angle = 2.0 * ON_PI;
    narrow_cf.length = shoulder_height;

    Brep::CylindricalFace wide_cf;
    wide_cf.frame = frame;
    wide_cf.frame.origin = frame.PointAt(0, 0, shoulder_height);
    wide_cf.radius = shoulder_radius;
    wide_cf.angle = 2.0 * ON_PI;
    wide_cf.length = shaft_height;

    const Brep tool = Brep::FromMixedFaces({}, {narrow_cf, wide_cf});
    const Brep result = BooleanCombineMixed(box, tool, BooleanOp::Union);

    const std::vector<SteppedBossFeature> found = RecognizeSteppedBosses(result);
    Check(found.size() == 1, "RecognizeSteppedBosses merges the flared boss's two segments too");
    const SteppedBossFeature& sf = found[0];
    Check(!sf.through, "RecognizeSteppedBosses reports the flared boss as NOT through");
    Check(sf.origin.DistanceTo(base) < 1e-6, "RecognizeSteppedBosses recovers the flared boss's own exact base point");
    Check((sf.axis - up).Length() < 1e-6, "RecognizeSteppedBosses recovers the flared boss's own exact outward direction");
    Check(std::abs(sf.base_radius - shaft_radius) < 1e-6,
          "RecognizeSteppedBosses recovers the NARROW segment's own radius as the base, not the wider one");
    Check(std::abs(sf.base_height - shoulder_height) < 1e-6,
          "RecognizeSteppedBosses recovers the narrow base segment's own exact height");
    Check(std::abs(sf.tip_radius - shoulder_radius) < 1e-6,
          "RecognizeSteppedBosses recovers the WIDE segment's own radius as the tip");
    Check(std::abs(sf.tip_height - shaft_height) < 1e-6,
          "RecognizeSteppedBosses recovers the wide tip segment's own exact height");
  }
  {
    // Negative control: a plain, single-radius boss (both segments welded
    // at the same radius, MakeTwoSegmentCylinder()'s own construction
    // reused via a single uniform-radius CylindricalFace here) has no
    // step to merge into anything.
    Brep::CylindricalFace plain_cf;
    plain_cf.frame = frame;
    plain_cf.radius = shoulder_radius;
    plain_cf.angle = 2.0 * ON_PI;
    plain_cf.length = shoulder_height + shaft_height;
    const Brep plain_tool = Brep::FromMixedFaces({}, {plain_cf});
    const Brep plain_result = BooleanCombineMixed(box, plain_tool, BooleanOp::Union);
    Check(RecognizeSteppedBosses(plain_result).empty(),
          "RecognizeSteppedBosses finds no compound step on a plain single-radius boss");
  }
}

// Builds a compound TOOL Brep with N adjacent, non-overlapping
// Brep::CylindricalFace segments - NO caps at all, the same bare-tube
// convention TestRecognizeSteppedBossesRoundTrip's own two-segment tool
// above already uses - starting at `origin` and growing along `axis`.
// `steps` gives each segment's own (radius, length) pair in the order
// they're laid out from `origin` outward; shared by
// TestRecognizeSteppedHoleChainsRoundTrip (subtracted via Difference
// below) and TestRecognizeSteppedBossChainsRoundTrip (added via Union
// below) - the same CylindricalFace-chain compound-cutter construction
// CounterboreHole() itself uses (features.cpp), generalized here from
// exactly two segments to an arbitrary N for these tests' own multi-step
// fixtures.
dino8::kernel::Brep BuildSteppedCylinderTool(dino8::kernel::Point3d origin, dino8::kernel::Vector3d axis,
                                              const std::vector<std::pair<double, double>>& steps) {
  using dino8::kernel::Brep;

  dino8::kernel::Vector3d dir = axis;
  dir.Unitize();
  const ON_Plane frame = FrameFromAxisForGeneralBooleanTest(origin, dir);

  std::vector<Brep::CylindricalFace> faces;
  double running = 0.0;
  for (const auto& step : steps) {
    Brep::CylindricalFace cf;
    cf.frame = frame;
    cf.frame.origin = frame.PointAt(0, 0, running);
    cf.radius = step.first;
    cf.angle = 2.0 * ON_PI;
    cf.length = step.second;
    faces.push_back(cf);
    running += step.second;
  }
  return Brep::FromMixedFaces({}, faces);
}

// Subtracts a BuildSteppedCylinderTool() chain from `solid` via ONE
// BooleanCombineMixed(..., Difference) call - CounterboreHole()'s own
// two-segment construction (features.cpp), generalized to N segments,
// for a real, tested multi-step bore (not a mock).
dino8::kernel::Brep BuildSteppedHoleFixture(const dino8::kernel::Brep& solid, dino8::kernel::Point3d origin,
                                             dino8::kernel::Vector3d axis,
                                             const std::vector<std::pair<double, double>>& steps) {
  using dino8::kernel::BooleanCombineMixed;
  using dino8::kernel::BooleanOp;
  const dino8::kernel::Brep tool = BuildSteppedCylinderTool(origin, axis, steps);
  return BooleanCombineMixed(solid, tool, BooleanOp::Difference);
}

// Adds a BuildSteppedCylinderTool() chain onto `solid` via ONE
// BooleanCombineMixed(..., Union) call - the additive mirror of
// BuildSteppedHoleFixture() above, and TestRecognizeSteppedBossesRoundTrip's
// own two-segment Union tool construction, generalized to N segments.
dino8::kernel::Brep BuildSteppedBossFixture(const dino8::kernel::Brep& solid, dino8::kernel::Point3d origin,
                                             dino8::kernel::Vector3d axis,
                                             const std::vector<std::pair<double, double>>& steps) {
  using dino8::kernel::BooleanCombineMixed;
  using dino8::kernel::BooleanOp;
  const dino8::kernel::Brep tool = BuildSteppedCylinderTool(origin, axis, steps);
  return BooleanCombineMixed(solid, tool, BooleanOp::Union);
}

// parity-map "kernel: Feature operations" - "Feature recognition": closes
// RecognizeCounterboreHoles()'s own disclosed "a stepped hole with more
// than two radii (a counterbore followed by its own further pilot
// reduction) is not walked past the first pair" gap.
// RecognizeSteppedHoleChains() walks the FULL chain via features.cpp's
// own internal FindSteppedChains() helper, not just its first adjacent
// pair.
void TestRecognizeSteppedHoleChainsRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeCounterboreHoles;
  using dino8::kernel::RecognizeSteppedHoleChains;
  using dino8::kernel::SteppedHoleChain;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const Point3d origin(5, 5, 10);
  const Vector3d down(0, 0, -1);

  {
    // A THROUGH three-step bore, radii strictly narrowing toward the far
    // end (a spot-face, then a counterbore recess, then a pilot drill) -
    // the "counterbore followed by its own further pilot reduction" case
    // this item's own doc comment names. l1+l2+l3 == 10: exits the box's
    // own bottom face.
    const double r1 = 2.0, l1 = 2.0;
    const double r2 = 1.2, l2 = 3.0;
    const double r3 = 0.6, l3 = 5.0;
    const Brep result = BuildSteppedHoleFixture(box, origin, down, {{r1, l1}, {r2, l2}, {r3, l3}});

    // Sanity: RecognizeCounterboreHoles() itself only ever merges the
    // FIRST adjacent pair of this 3-step bore (its own disclosed
    // limitation), leaving the third segment out entirely - confirms this
    // fixture actually exercises the "not walked past the first pair"
    // gap, rather than something RecognizeCounterboreHoles() already
    // handles in full on its own.
    Check(RecognizeCounterboreHoles(result).size() == 1,
          "sanity: RecognizeCounterboreHoles() merges only the FIRST adjacent pair of this 3-step bore, not the "
          "whole chain");

    const std::vector<SteppedHoleChain> found = RecognizeSteppedHoleChains(result);
    Check(found.size() == 1, "RecognizeSteppedHoleChains merges all three steps into exactly one compound feature");
    const SteppedHoleChain& chain = found[0];
    Check(chain.origin.DistanceTo(origin) < 1e-6, "RecognizeSteppedHoleChains recovers the chain's own exact entry point");
    Check((chain.axis - down).Length() < 1e-6, "RecognizeSteppedHoleChains recovers the chain's own exact drilling direction");
    Check(chain.through, "RecognizeSteppedHoleChains reports this through bore as through");
    Check(chain.steps.size() == 3, "RecognizeSteppedHoleChains recovers all three steps, not just the first pair");
    Check(std::abs(chain.steps[0].radius - r1) < 1e-6 && std::abs(chain.steps[0].length - l1) < 1e-6,
          "RecognizeSteppedHoleChains recovers step 1's own exact radius/length");
    Check(std::abs(chain.steps[1].radius - r2) < 1e-6 && std::abs(chain.steps[1].length - l2) < 1e-6,
          "RecognizeSteppedHoleChains recovers step 2's own exact radius/length");
    Check(std::abs(chain.steps[2].radius - r3) < 1e-6 && std::abs(chain.steps[2].length - l3) < 1e-6,
          "RecognizeSteppedHoleChains recovers step 3's own exact radius/length");

    // Hand-derived closed-form volume: the box minus each step's own
    // cylindrical volume (all coaxial, non-overlapping, axis-aligned with
    // the box's own extrusion direction).
    const double expected_volume = 1000.0 - (ON_PI * r1 * r1 * l1 + ON_PI * r2 * r2 * l2 + ON_PI * r3 * r3 * l3);
    const Mesh result_mesh = result.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - expected_volume) < 0.5,
          "the 3-step through bore's own tessellated volume matches the hand-derived closed form (box minus three "
          "coaxial cylinders)");

    // Round-trip: feed the recognized steps straight back into the same
    // construction against a fresh box and confirm it reproduces the
    // original's own volume - the real test these recognized numbers are
    // usable, not merely plausible-looking.
    const Brep rebuilt = BuildSteppedHoleFixture(
        box, chain.origin, chain.axis,
        {{chain.steps[0].radius, chain.steps[0].length},
         {chain.steps[1].radius, chain.steps[1].length},
         {chain.steps[2].radius, chain.steps[2].length}});
    const Mesh rebuilt_mesh = rebuilt.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - rebuilt_mesh.Volume()) < 1e-6,
          "rebuilding from RecognizeSteppedHoleChains()'s own recognized origin/axis/steps reproduces the original "
          "3-step bore's own exact volume");
  }
  {
    // A BLIND three-step bore whose radii do NOT trend monotonically (a
    // spot-face WIDER than the counterbore recess beneath it) - confirms
    // RecognizeSteppedHoleChains() doesn't assume any fixed radius trend,
    // unlike RecognizeCounterboreHoles()'s own fixed "wide is always the
    // entry side" rule.
    const double r1 = 1.0, l1 = 1.5;
    const double r2 = 2.0, l2 = 1.5;
    const double r3 = 1.2, l3 = 2.0;  // total 5.0, well short of the box's own 10 height: blind
    const Brep result = BuildSteppedHoleFixture(box, origin, down, {{r1, l1}, {r2, l2}, {r3, l3}});

    const std::vector<SteppedHoleChain> found = RecognizeSteppedHoleChains(result);
    Check(found.size() == 1, "RecognizeSteppedHoleChains merges a non-monotonic-radius 3-step blind bore too");
    const SteppedHoleChain& chain = found[0];
    Check(!chain.through, "RecognizeSteppedHoleChains reports this blind bore as NOT through");
    Check(chain.origin.DistanceTo(origin) < 1e-6, "RecognizeSteppedHoleChains recovers the blind chain's own exact entry point");
    Check((chain.axis - down).Length() < 1e-6, "RecognizeSteppedHoleChains recovers the blind chain's own exact drilling direction");
    Check(chain.steps.size() == 3, "RecognizeSteppedHoleChains recovers all three steps of the non-monotonic chain");
    Check(std::abs(chain.steps[0].radius - r1) < 1e-6,
          "RecognizeSteppedHoleChains keeps step 1's own narrower radius first, not reordered by size");
    Check(std::abs(chain.steps[1].radius - r2) < 1e-6,
          "RecognizeSteppedHoleChains keeps step 2's own WIDER radius in the middle, not reordered by size");
    Check(std::abs(chain.steps[2].radius - r3) < 1e-6, "RecognizeSteppedHoleChains recovers step 3's own radius");

    const double expected_volume = 1000.0 - (ON_PI * r1 * r1 * l1 + ON_PI * r2 * r2 * l2 + ON_PI * r3 * r3 * l3);
    const Mesh result_mesh = result.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - expected_volume) < 0.5,
          "the non-monotonic 3-step blind bore's own tessellated volume matches the hand-derived closed form");
  }
  {
    // Negative control: a plain single-radius through hole (MakeHole()'s
    // own well-tested construction) has no chain to merge.
    const Brep single = dino8::kernel::MakeHole(box, origin, down, 1.0, 0.0, /*through=*/true);
    Check(RecognizeSteppedHoleChains(single).empty(), "RecognizeSteppedHoleChains finds no chain on a plain single-radius hole");
  }
  {
    // Negative control: a plain two-segment counterbore
    // (CounterboreHole()'s own well-tested construction, already
    // RecognizeCounterboreHoles()'s own domain) is NOT also reported
    // here - the two functions' own outputs stay disjoint, the same
    // one-capability-several-vocabularies convention this file's other
    // Recognize* functions already follow.
    const Brep two_step = dino8::kernel::CounterboreHole(box, origin, down, 1.0, 6.0, 2.0, 3.0);
    Check(RecognizeSteppedHoleChains(two_step).empty(),
          "RecognizeSteppedHoleChains finds no chain on a plain two-segment counterbore - that stays "
          "RecognizeCounterboreHoles()'s own domain, not duplicated here");
  }
}

// The boss-side mirror of TestRecognizeSteppedHoleChainsRoundTrip() above:
// closes RecognizeSteppedBosses()'s own disclosed "a stepped chain of
// more than two radii is not walked past the first adjacent pair" gap for
// a convex chain.
void TestRecognizeSteppedBossChainsRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeBosses;
  using dino8::kernel::RecognizeSteppedBossChains;
  using dino8::kernel::RecognizeSteppedBosses;
  using dino8::kernel::SteppedBossChain;
  using dino8::kernel::SteppedBossFeature;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const Point3d surface(5, 5, 10);
  const Vector3d up(0, 0, 1);

  {
    // The common case: a wide shoulder flush with the box's own top face,
    // narrowing in two further steps to a free-standing tip - the tool's
    // own segments are supplied base-to-tip, offset 0 exactly at the
    // box's own surface, so the FIRST candidate ScanFullCylinderFaces()
    // finds is the attached one and no chain reversal is needed.
    const double r1 = 2.0, h1 = 1.0;
    const double r2 = 1.2, h2 = 1.0;
    const double r3 = 0.6, h3 = 2.0;
    const Brep result = BuildSteppedBossFixture(box, surface, up, {{r1, h1}, {r2, h2}, {r3, h3}});

    // Sanity: RecognizeBosses() itself reports only the free tip segment
    // as an independent boss (both other segments read "both ends
    // attached" - real material genuinely continues on both sides of
    // each interior step - and are silently skipped), and
    // RecognizeSteppedBosses() itself finds NOTHING AT ALL for this
    // fixture: its own only considered pair (the first two segments)
    // reads BOTH ends attached too (backed by the third segment
    // continuing beyond it) and is silently skipped - an even starker
    // symptom of the "not walked past the first pair" gap than a case
    // where it partially, wrongly matches (see the flared case below for
    // that one). Confirms this fixture genuinely exercises the gap being
    // closed.
    Check(RecognizeBosses(result).size() == 1,
          "sanity: RecognizeBosses() itself reports only the free tip as an independent boss on this 3-step "
          "shoulder");
    Check(RecognizeSteppedBosses(result).empty(),
          "sanity: RecognizeSteppedBosses() itself finds NOTHING on this 3-step shoulder - its own only "
          "considered pair (segments 1+2) reads both ends attached, backed by the third segment continuing "
          "beyond it, and is silently skipped");

    const std::vector<SteppedBossChain> found = RecognizeSteppedBossChains(result);
    Check(found.size() == 1, "RecognizeSteppedBossChains merges all three steps into exactly one compound feature");
    const SteppedBossChain& chain = found[0];
    Check(!chain.through, "RecognizeSteppedBossChains reports this flush-base boss as NOT through");
    Check(chain.origin.DistanceTo(surface) < 1e-6, "RecognizeSteppedBossChains recovers the chain's own exact base/attach point");
    Check((chain.axis - up).Length() < 1e-6, "RecognizeSteppedBossChains recovers the chain's own exact outward direction");
    Check(chain.steps.size() == 3, "RecognizeSteppedBossChains recovers all three steps, not just the first pair");
    Check(std::abs(chain.steps[0].radius - r1) < 1e-6 && std::abs(chain.steps[0].height - h1) < 1e-6,
          "RecognizeSteppedBossChains recovers the base step's own exact radius/height");
    Check(std::abs(chain.steps[1].radius - r2) < 1e-6 && std::abs(chain.steps[1].height - h2) < 1e-6,
          "RecognizeSteppedBossChains recovers the middle step's own exact radius/height");
    Check(std::abs(chain.steps[2].radius - r3) < 1e-6 && std::abs(chain.steps[2].height - h3) < 1e-6,
          "RecognizeSteppedBossChains recovers the tip step's own exact radius/height");

    const double expected_volume = 1000.0 + (ON_PI * r1 * r1 * h1 + ON_PI * r2 * r2 * h2 + ON_PI * r3 * r3 * h3);
    const Mesh result_mesh = result.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - expected_volume) < 0.5,
          "the 3-step flush boss's own tessellated volume matches the hand-derived closed form (box plus three "
          "coaxial cylinders)");

    const Brep rebuilt = BuildSteppedBossFixture(
        box, chain.origin, chain.axis,
        {{chain.steps[0].radius, chain.steps[0].height},
         {chain.steps[1].radius, chain.steps[1].height},
         {chain.steps[2].radius, chain.steps[2].height}});
    const Mesh rebuilt_mesh = rebuilt.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - rebuilt_mesh.Volume()) < 1e-6,
          "rebuilding from RecognizeSteppedBossChains()'s own recognized origin/axis/steps reproduces the original "
          "3-step boss's own exact volume");
  }
  {
    // The opposite construction order: the tool's own segments are
    // supplied TIP-to-base (offset 0 sits at the free tip, well away from
    // the box; the LAST segment is the one flush against the box's own
    // surface) - so the candidate ScanFullCylinderFaces()/
    // FindSteppedChains() walk first-to-last from is the FREE end, not
    // the attached one, and RecognizeSteppedBossChains() must reverse the
    // whole walked chain to put `origin` back at the genuinely attached
    // end. This is exactly the correctness pitfall this session's own
    // hole-side hand-derivation flagged as a real risk (see
    // RecognizeSteppedBossChains()'s own "far_attached" branch,
    // features.cpp) - a case that would silently misreport `origin` (and
    // reverse every step) if that branch were missing or wrong.
    const double r1 = 0.6, h1 = 1.5;  // built first (offset 0): the tip, free
    const double r2 = 1.2, h2 = 1.0;  // built second: the middle step
    const double r3 = 2.0, h3 = 0.5;  // built last: the base, flush with the box
    const Point3d tip(5, 5, 13.0);    // h1+h2+h3 == 3.0, landing exactly on the box's own top face (z=10)
    const Vector3d down(0, 0, -1);
    const Brep result = BuildSteppedBossFixture(box, tip, down, {{r1, h1}, {r2, h2}, {r3, h3}});

    // Sanity: RecognizeSteppedBosses() itself, pairing only the first two
    // segments it scans (tip + middle), reports a base_radius of 1.2 (the
    // MIDDLE segment) - not this boss's own true base radius of 2.0,
    // which sits in the unconsumed third segment its own pairing never
    // reaches. A real, visible wrong-number symptom of the "not walked
    // past the first pair" gap, not merely an abstract limitation.
    const std::vector<SteppedBossFeature> partial = RecognizeSteppedBosses(result);
    Check(partial.size() == 1 && std::abs(partial[0].base_radius - r2) < 1e-6,
          "sanity: RecognizeSteppedBosses() itself reports the flared boss's own base_radius as 1.2 (the middle "
          "segment) rather than the true base radius 2.0, since its own pairing never reaches the third segment");

    const std::vector<SteppedBossChain> found = RecognizeSteppedBossChains(result);
    Check(found.size() == 1, "RecognizeSteppedBossChains merges the flared boss's three steps into one compound feature");
    const SteppedBossChain& chain = found[0];
    Check(!chain.through, "RecognizeSteppedBossChains reports the flared boss as NOT through");
    Check(chain.origin.DistanceTo(surface) < 1e-6,
          "RecognizeSteppedBossChains recovers the flared boss's own true base point (the box's own surface), not "
          "the free tip the underlying chain walk actually started from");
    Check((chain.axis - up).Length() < 1e-6, "RecognizeSteppedBossChains recovers the flared boss's own exact outward direction");
    Check(chain.steps.size() == 3, "RecognizeSteppedBossChains recovers all three of the flared boss's own steps");
    Check(std::abs(chain.steps[0].radius - r3) < 1e-6 && std::abs(chain.steps[0].height - h3) < 1e-6,
          "RecognizeSteppedBossChains reorders the reversed walk so the TRUE base segment (radius 2.0) comes "
          "first, not the segment the underlying chain walk happened to start from");
    Check(std::abs(chain.steps[1].radius - r2) < 1e-6 && std::abs(chain.steps[1].height - h2) < 1e-6,
          "RecognizeSteppedBossChains recovers the flared boss's own middle step");
    Check(std::abs(chain.steps[2].radius - r1) < 1e-6 && std::abs(chain.steps[2].height - h1) < 1e-6,
          "RecognizeSteppedBossChains recovers the flared boss's own tip step last, after reversal");

    const double expected_volume = 1000.0 + (ON_PI * r1 * r1 * h1 + ON_PI * r2 * r2 * h2 + ON_PI * r3 * r3 * h3);
    const Mesh result_mesh = result.TessellateToClosedMesh(64, 64);
    Check(std::abs(result_mesh.Volume() - expected_volume) < 0.5,
          "the flared 3-step boss's own tessellated volume matches the hand-derived closed form");
  }
  {
    // Negative control: a free-standing single-radius solid cylinder
    // (MakeCylinderAxisForGeneralBooleanTest()'s own fixture, used
    // earlier in this file for the same "plain convex cylinder" shape)
    // has no chain to merge.
    const Brep solid_pin = MakeCylinderAxisForGeneralBooleanTest(Point3d(0, 0, 0), Vector3d(0, 0, 1), 1.0, 6.0);
    Check(RecognizeSteppedBossChains(solid_pin).empty(), "RecognizeSteppedBossChains finds no chain on a plain single-radius boss");
  }
  {
    // Negative control: a plain two-segment stepped boss
    // (RecognizeSteppedBosses()'s own well-tested construction, already
    // its own domain) is NOT also reported here.
    const double shoulder_radius = 2.0, shoulder_height = 1.0;
    const double shaft_radius = 0.8, shaft_height = 3.0;
    const Brep two_step = BuildSteppedBossFixture(box, surface, up, {{shoulder_radius, shoulder_height}, {shaft_radius, shaft_height}});
    Check(RecognizeSteppedBossChains(two_step).empty(),
          "RecognizeSteppedBossChains finds no chain on a plain two-segment stepped boss - that stays "
          "RecognizeSteppedBosses()'s own domain, not duplicated here");
  }
}

// Local helper shared by BuildTaperedBossFixture()/BuildFlaredTaperedBossFixture()
// below: given a ConicalFace whose `frame`/`radius0` are already set for a
// patch that STARTS (radius0) at `patch_start`, shifts `frame.origin` back
// to the cone's own TRUE apex - ConicalFace's own contract (brep.h):
// `frame.origin` is the apex, strictly outside the trimmed patch, offset
// from the patch's own narrow end by radius0/tan(half_angle)
// (BuildCountersinkHoleFixture()'s own "cone.frame.origin = transition -
// zaxis*(bore_radius/tan(half_angle))" construction above, generalized
// from an angle PARAMETER to the slope implied directly by
// radius0/radius1/length).
void ShiftConeFrameToApex(ON_Plane& frame, dino8::kernel::Point3d patch_start, double radius0, double radius1,
                           double length) {
  const double tan_half_angle = (radius1 - radius0) / length;
  frame.origin = patch_start - frame.zaxis * (radius0 / tan_half_angle);
  frame.UpdateEquation();
}

// Builds a standalone tapered-boss shape directly via FromMixedFaces (no
// boolean) - a "body" filler cylinder (standing in for the larger body
// the feature emerges from, the same standalone-weld precedent
// MakeTwoSegmentCylinder()/BuildCountersinkHoleFixture() above already
// use, sidestepping BooleanCombineGeneral()'s own confirmed Union-side
// "floating base cap" gap, BossFeature's own doc comment, a real
// boolean-Union fixture would hit), then a cylindrical shaft, then a
// conical taper down to `cone_tip_radius` - the "ordinary" orientation
// (cylindrical base, free conical tip). Only the body's own outer end and
// the taper's own tip are capped; every interior transition is left
// uncapped so FromMixedFaces() welds each into one interior edge instead
// - the same convention BuildCountersinkHoleFixture() itself uses.
dino8::kernel::Brep BuildTaperedBossFixture(dino8::kernel::Point3d body_far_end, dino8::kernel::Vector3d axis,
                                             double body_radius, double body_length, double shaft_radius,
                                             double shaft_length, double cone_tip_radius, double cone_length) {
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  Vector3d dir = axis;
  dir.Unitize();

  const ON_Plane body_frame = FrameFromAxisForGeneralBooleanTest(body_far_end, dir);
  Brep::CylindricalFace body_cf;
  body_cf.frame = body_frame;
  body_cf.radius = body_radius;
  body_cf.angle = 2.0 * ON_PI;
  body_cf.length = body_length;

  // body -> cylindrical shaft (radius shaft_radius, may differ from
  // body_radius - an ordinary step weld, same as CounterboreHole()'s own
  // "adjacent different-radius segments" construction) -> conical taper
  // down to cone_tip_radius.
  const Point3d after_body = body_far_end + dir * body_length;
  const ON_Plane shaft_frame = FrameFromAxisForGeneralBooleanTest(after_body, dir);
  Brep::CylindricalFace shaft_cf;
  shaft_cf.frame = shaft_frame;
  shaft_cf.radius = shaft_radius;
  shaft_cf.angle = 2.0 * ON_PI;
  shaft_cf.length = shaft_length;

  const Point3d cone_start = after_body + dir * shaft_length;
  const Point3d tip_point = cone_start + dir * cone_length;
  const ON_Plane tip_point_frame = FrameFromAxisForGeneralBooleanTest(tip_point, -dir);
  ON_Plane cone_frame = tip_point_frame;
  ShiftConeFrameToApex(cone_frame, tip_point, cone_tip_radius, shaft_radius, cone_length);
  Brep::ConicalFace cone_cf;
  cone_cf.frame = cone_frame;
  cone_cf.radius0 = cone_tip_radius;  // at the patch's own start (tip_point)
  cone_cf.radius1 = shaft_radius;     // at the patch's own end (cone_start)
  cone_cf.angle = 2.0 * ON_PI;
  cone_cf.length = cone_length;

  const Brep::PlanarFace body_cap = DiskCapForGeneralBooleanTest(body_frame, 0.0, body_radius, /*flip=*/true);
  const Brep::PlanarFace tip_cap = DiskCapForGeneralBooleanTest(tip_point_frame, 0.0, cone_tip_radius, /*flip=*/true);

  return Brep::FromMixedFaces({body_cap, tip_cap}, {body_cf, shaft_cf}, {cone_cf});
}

// A free-standing (unattached to any body) tapered rod - a cylindrical
// shaft with a conical taper down to `tip_radius` at one end, capped at
// its own two TRUE outer ends only (both open to air), the `through =
// true` fixture for RecognizeTaperedBosses() below.
dino8::kernel::Brep BuildFreeStandingTaperedRodFixture(dino8::kernel::Point3d base, dino8::kernel::Vector3d axis,
                                                        double shaft_radius, double shaft_length, double tip_radius,
                                                        double cone_length) {
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  Vector3d dir = axis;
  dir.Unitize();

  const ON_Plane shaft_frame = FrameFromAxisForGeneralBooleanTest(base, dir);
  Brep::CylindricalFace shaft_cf;
  shaft_cf.frame = shaft_frame;
  shaft_cf.radius = shaft_radius;
  shaft_cf.angle = 2.0 * ON_PI;
  shaft_cf.length = shaft_length;

  const Point3d cone_start = base + dir * shaft_length;
  const Point3d tip_point = cone_start + dir * cone_length;
  const ON_Plane tip_point_frame = FrameFromAxisForGeneralBooleanTest(tip_point, -dir);
  ON_Plane cone_frame = tip_point_frame;
  ShiftConeFrameToApex(cone_frame, tip_point, tip_radius, shaft_radius, cone_length);
  Brep::ConicalFace cone_cf;
  cone_cf.frame = cone_frame;
  cone_cf.radius0 = tip_radius;
  cone_cf.radius1 = shaft_radius;
  cone_cf.angle = 2.0 * ON_PI;
  cone_cf.length = cone_length;

  const Brep::PlanarFace base_cap = DiskCapForGeneralBooleanTest(shaft_frame, 0.0, shaft_radius, /*flip=*/true);
  const Brep::PlanarFace tip_cap = DiskCapForGeneralBooleanTest(tip_point_frame, 0.0, tip_radius, /*flip=*/true);

  return Brep::FromMixedFaces({base_cap, tip_cap}, {shaft_cf}, {cone_cf});
}

// The "flared base" tapered-boss fixture: TWO conical segments (a wide
// "pad" cone from `pad_radius` down to `mid_radius`, then the actual
// taper feature from `mid_radius` down to `shaft_radius`) feeding into a
// cylindrical shaft, capped only at the pad's own true outer end and the
// shaft's own free tip. Deliberately NOT a cylindrical "body" filler
// (BuildTaperedBossFixture()'s own construction, mirrored to a flared-base
// orientation, was tried first and reverted): a filler CYLINDER sharing
// the taper cone's own wide-end radius
// (required for a seamless weld, the same "no radius step directly next
// to a cap" constraint BuildCountersinkHoleFixture()'s own construction
// already follows) is ALSO, unavoidably, a second real full-cylinder
// candidate that happens to touch the SAME cone at the SAME radius -
// confirmed directly (a real, reproducible false pairing, not
// hypothetical) to let FindAdjacentConeCylinderPairs() match the cone to
// that filler body instead of to the actual shaft, silently reporting the
// wrong segment's own radius/length. A second CONE never has this
// problem: FindAdjacentConeCylinderPairs() only ever pairs a cone against
// a CYLINDER candidate, so a "pad" cone touching the feature's own cone
// at a shared radius is simply invisible to that pairing search, exactly
// the way ScanFullConeFaces()'s own candidates never collide with
// ScanFullCylinderFaces()'s.
dino8::kernel::Brep BuildFlaredTaperedBossFixture(dino8::kernel::Point3d base_far_end, dino8::kernel::Vector3d axis,
                                                   double pad_radius, double pad_length, double mid_radius,
                                                   double taper_length, double shaft_radius, double shaft_length) {
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  Vector3d dir = axis;
  dir.Unitize();

  // Pad cone: patch starts at base_far_end (radius0=pad_radius, the TRUE
  // outer/capped end) and ends at mid_point (radius1=mid_radius, welds to
  // the taper cone) - zaxis=dir (radius increases in the wrong direction
  // for the apex-offset formula's own "radius0 at the patch's own start"
  // convention unless pad_radius < mid_radius; both orderings are handled
  // via ShiftConeFrameToApex()'s own generic (radius1-radius0)/length
  // slope, which is negative when pad_radius > mid_radius - still a valid
  // apex offset, just on the other side).
  const Point3d mid_point = base_far_end + dir * pad_length;
  ON_Plane pad_frame = FrameFromAxisForGeneralBooleanTest(base_far_end, dir);
  ShiftConeFrameToApex(pad_frame, base_far_end, pad_radius, mid_radius, pad_length);
  Brep::ConicalFace pad_cf;
  pad_cf.frame = pad_frame;
  pad_cf.radius0 = pad_radius;
  pad_cf.radius1 = mid_radius;
  pad_cf.angle = 2.0 * ON_PI;
  pad_cf.length = pad_length;

  // Taper cone (the actual feature): patch starts at mid_point
  // (radius0=mid_radius, welds to the pad cone) and ends at
  // shaft_start (radius1=shaft_radius, welds to the shaft).
  const Point3d shaft_start = mid_point + dir * taper_length;
  ON_Plane taper_frame = FrameFromAxisForGeneralBooleanTest(mid_point, dir);
  ShiftConeFrameToApex(taper_frame, mid_point, mid_radius, shaft_radius, taper_length);
  Brep::ConicalFace taper_cf;
  taper_cf.frame = taper_frame;
  taper_cf.radius0 = mid_radius;
  taper_cf.radius1 = shaft_radius;
  taper_cf.angle = 2.0 * ON_PI;
  taper_cf.length = taper_length;

  const ON_Plane shaft_frame = FrameFromAxisForGeneralBooleanTest(shaft_start, dir);
  Brep::CylindricalFace shaft_cf;
  shaft_cf.frame = shaft_frame;
  shaft_cf.radius = shaft_radius;
  shaft_cf.angle = 2.0 * ON_PI;
  shaft_cf.length = shaft_length;

  const ON_Plane pad_cap_frame = FrameFromAxisForGeneralBooleanTest(base_far_end, dir);
  const Brep::PlanarFace pad_cap = DiskCapForGeneralBooleanTest(pad_cap_frame, 0.0, pad_radius, /*flip=*/true);
  const Brep::PlanarFace tip_cap = DiskCapForGeneralBooleanTest(shaft_frame, shaft_length, shaft_radius, /*flip=*/false);

  return Brep::FromMixedFaces({pad_cap, tip_cap}, {shaft_cf}, {pad_cf, taper_cf});
}

// parity-map "kernel: Feature operations" - "Feature recognition": closes
// this file's own total absence of any CONVEX-cone recognition - the
// boss-side mirror of TestRecognizeCountersinkHolesRoundTrip() above.
// RecognizeTaperedBosses() merges a convex full cone with an adjacent
// convex full cylinder into one TaperedBossFeature, using the SAME
// FindAdjacentConeCylinderPairs() geometry RecognizeCountersinkHoles()
// itself uses (concave/convex-agnostic).
void TestRecognizeTaperedBossesRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeCountersinkHoles;
  using dino8::kernel::RecognizeTaperedBosses;
  using dino8::kernel::TaperedBossFeature;
  using dino8::kernel::Vector3d;

  const Point3d body_far_end(0, 0, 0);
  const Vector3d up(0, 0, 1);

  {
    // The ordinary orientation: a cylindrical shaft attached to the body,
    // narrowing through a conical taper to a free (pencil-point) tip - a
    // dowel pin with a chamfered lead-in point.
    const double body_radius = 1.5, body_length = 1.0;
    const double shaft_radius = 0.6, shaft_length = 2.0;
    const double tip_radius = 0.2, cone_length = 0.8;
    const Brep result = BuildTaperedBossFixture(body_far_end, up, body_radius, body_length, shaft_radius,
                                                  shaft_length, tip_radius, cone_length);

    // Sanity: RecognizeCountersinkHoles() finds nothing here (it only ever
    // reads CONCAVE candidates) - confirms this fixture genuinely exercises
    // the CONVEX gap being closed. (Not cross-checked against
    // RecognizeBosses() here: this fixture's own body/shaft step weld,
    // directly adjacent to a true end cap, hits a separate, unrelated
    // FromMixedFaces() tessellation quirk - a heterogeneous-radius step
    // immediately next to a capped end leaves that specific cap's own
    // Mesh::ContainsPoint() reading unreliable, confirmed directly
    // (dino8_scratch_test) to reproduce even on a bare two-segment
    // cylinder+caps construction with no cone involved at all - harmless
    // to RecognizeTaperedBosses() itself, whose own occupancy probes never
    // go near that cap, but it does make RecognizeBosses()'s OWN "both
    // ends attached" cross-check unreliable specifically for this body
    // segment, so it's not used as a sanity check here.)
    Check(RecognizeCountersinkHoles(result).empty(), "sanity: RecognizeCountersinkHoles() finds nothing on a CONVEX cone/cylinder pair");

    const std::vector<TaperedBossFeature> found = RecognizeTaperedBosses(result);
    Check(found.size() == 1, "RecognizeTaperedBosses merges the shaft and taper into exactly one compound feature");
    const TaperedBossFeature& tf = found[0];
    const Point3d attach = body_far_end + up * body_length;
    Check(tf.origin.DistanceTo(attach) < 1e-6, "RecognizeTaperedBosses recovers the boss's own exact attach point");
    Check((tf.axis - up).Length() < 1e-6, "RecognizeTaperedBosses recovers the boss's own exact outward direction");
    Check(tf.base_is_cylindrical, "RecognizeTaperedBosses reports the cylindrical shaft as the base segment");
    Check(std::abs(tf.cyl_radius - shaft_radius) < 1e-6, "RecognizeTaperedBosses recovers the shaft's own exact radius");
    Check(std::abs(tf.cyl_length - shaft_length) < 1e-6, "RecognizeTaperedBosses recovers the shaft's own exact length");
    Check(std::abs(tf.cone_small_radius - tip_radius) < 1e-6, "RecognizeTaperedBosses recovers the taper's own exact tip radius");
    Check(std::abs(tf.cone_large_radius - shaft_radius) < 1e-6, "RecognizeTaperedBosses recovers the taper's own exact base radius (matching the shaft)");
    Check(std::abs(tf.cone_length - cone_length) < 1e-6, "RecognizeTaperedBosses recovers the taper's own exact length");
    const double expected_angle = 2.0 * std::atan2(shaft_radius - tip_radius, cone_length) * 180.0 / ON_PI;
    Check(std::abs(tf.taper_angle_degrees - expected_angle) < 1e-4, "RecognizeTaperedBosses recovers the taper's own exact full included angle");
    Check(!tf.through, "RecognizeTaperedBosses reports the attached boss as NOT through");

    // Verified directly on the B-rep (radius/length fields above), not via
    // tessellated volume, for the same disclosed reason given above (the
    // body/shaft step's own cap-adjacent tessellation quirk would corrupt
    // a whole-solid Volume() reading here) - the shaft's own true
    // cylindrical wall and the taper's own true conical wall are each
    // already confirmed exact above; this adds one more direct B-rep
    // check, that the tip actually reaches the expected point in space.
    const Point3d expected_tip = attach + up * (shaft_length + cone_length);
    const ON_BoundingBox bb = result.raw().BoundingBox();
    Check(bb.m_max.z > expected_tip.z - 1e-6, "the tapered boss's own bounding box genuinely reaches the taper's own tip height");
  }
  {
    // The opposite orientation: a flared conical pad at the base
    // narrowing to a cylindrical free tip - e.g. a countersunk-head-shaped
    // boss. BuildFlaredTaperedBossFixture() below attaches the actual
    // taper (mid_radius -> shaft_radius, the feature RecognizeTaperedBosses()
    // should recover) to a SECOND, wider pad cone rather than a
    // cylindrical filler body - see that function's own doc comment for
    // why a cylindrical filler is unsafe here (a real, confirmed false
    // pairing, not hypothetical).
    const double pad_radius = 2.0, pad_length = 1.0;
    const double mid_radius = 1.2, taper_length = 1.2;
    const double shaft_radius = 0.5, shaft_length = 1.5;
    const Brep result = BuildFlaredTaperedBossFixture(body_far_end, up, pad_radius, pad_length, mid_radius,
                                                        taper_length, shaft_radius, shaft_length);

    const std::vector<TaperedBossFeature> found = RecognizeTaperedBosses(result);
    Check(found.size() == 1, "RecognizeTaperedBosses merges the flared-base taper and shaft into exactly one compound feature");
    const TaperedBossFeature& tf = found[0];
    const Point3d attach = body_far_end + up * pad_length;
    Check(tf.origin.DistanceTo(attach) < 1e-6, "RecognizeTaperedBosses recovers the flared boss's own exact attach point");
    Check((tf.axis - up).Length() < 1e-6, "RecognizeTaperedBosses recovers the flared boss's own exact outward direction");
    Check(!tf.base_is_cylindrical, "RecognizeTaperedBosses reports the conical segment as the base (the flared pad), not the shaft");
    Check(std::abs(tf.cyl_radius - shaft_radius) < 1e-6, "RecognizeTaperedBosses recovers the flared boss's own exact shaft radius");
    Check(std::abs(tf.cyl_length - shaft_length) < 1e-6, "RecognizeTaperedBosses recovers the flared boss's own exact shaft length");
    Check(std::abs(tf.cone_large_radius - mid_radius) < 1e-6, "RecognizeTaperedBosses recovers the taper's own exact radius at the pad transition, not the pad's own further, wider radius");
    Check(std::abs(tf.cone_small_radius - shaft_radius) < 1e-6, "RecognizeTaperedBosses recovers the taper's own exact radius at the shaft transition");
    Check(std::abs(tf.cone_length - taper_length) < 1e-6, "RecognizeTaperedBosses recovers the taper's own exact length");
  }
  {
    // Negative control: a free-standing tapered rod, attached to nothing -
    // both ends open to air, the `through = true` case.
    const double shaft_radius = 0.8, shaft_length = 2.0;
    const double tip_radius = 0.3, cone_length = 1.0;
    const Brep rod = BuildFreeStandingTaperedRodFixture(body_far_end, up, shaft_radius, shaft_length, tip_radius, cone_length);
    const std::vector<TaperedBossFeature> found = RecognizeTaperedBosses(rod);
    Check(found.size() == 1, "RecognizeTaperedBosses finds exactly one feature on a free-standing tapered rod");
    Check(found[0].through, "RecognizeTaperedBosses reports a free-standing tapered rod (open on both ends) as through");
    Check(std::abs(found[0].cyl_length - shaft_length) < 1e-6, "RecognizeTaperedBosses recovers the free-standing rod's own exact shaft length");
    Check(std::abs(found[0].cone_length - cone_length) < 1e-6, "RecognizeTaperedBosses recovers the free-standing rod's own exact taper length");
  }
  {
    // Negative controls: a plain solid cylinder (no cone at all) and a
    // plain concave countersink (RecognizeCountersinkHoles()'s own domain,
    // opposite winding) both find no tapered boss here.
    const Brep plain_pin = MakeCylinderAxisForGeneralBooleanTest(Point3d(0, 0, 0), Vector3d(0, 0, 1), 1.0, 4.0);
    Check(RecognizeTaperedBosses(plain_pin).empty(), "RecognizeTaperedBosses finds no cone on a plain solid cylinder");

    const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
    const Brep countersink = BuildCountersinkHoleFixture(box, Point3d(5, 5, 10), Vector3d(0, 0, -1), 2.0, 90.0, 0.5, 5.0);
    Check(RecognizeTaperedBosses(countersink).empty(), "RecognizeTaperedBosses finds nothing on a concave (CONCAVE-winding) countersink");
  }
}

// Extends BuildCountersinkHoleFixture()'s own sleeve+cone+cylinder tool
// (one compound Brep, one BooleanCombineGeneral() Difference pass) with a
// second, narrower CylindricalFace segment immediately after the pilot
// bore - a real 3-step machined feature (countersink mouth, first pilot
// bore, a further-reduced final bore) as ONE compound tool cut in ONE
// boolean pass, the same "single compound tool, not two sequential
// Difference passes" precedent CounterboreHole()'s own doc comment
// establishes (features.cpp) - two sequential passes against a target
// eventually re-clip an already-circular face against a second, different
// circle, which ClipPolygonByCircle3d's own doc comment (boolean.h)
// explicitly disclaims.
dino8::kernel::Brep BuildCountersinkChainFixture(const dino8::kernel::Brep& solid, dino8::kernel::Point3d origin,
                                                  dino8::kernel::Vector3d axis, double countersink_radius,
                                                  double countersink_angle_degrees, double first_bore_radius,
                                                  double first_bore_length, double second_bore_radius,
                                                  double second_bore_length) {
  using dino8::kernel::BooleanCombineGeneral;
  using dino8::kernel::BooleanOp;
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  Vector3d dir = axis;
  dir.Unitize();
  const double half_angle = countersink_angle_degrees * ON_PI / 360.0;
  const double countersink_depth = (countersink_radius - first_bore_radius) / std::tan(half_angle);
  const Point3d transition = origin + dir * countersink_depth;
  const double margin = std::max(0.5, countersink_radius * 0.25);

  Brep::CylindricalFace sleeve;
  sleeve.frame = FrameFromAxisForGeneralBooleanTest(origin - dir * margin, dir);
  sleeve.radius = countersink_radius;
  sleeve.angle = 2.0 * ON_PI;
  sleeve.length = margin;

  const ON_Plane cone_base_frame = FrameFromAxisForGeneralBooleanTest(transition, -dir);
  Brep::ConicalFace cone;
  cone.frame = cone_base_frame;
  cone.frame.origin = transition - cone_base_frame.zaxis * (first_bore_radius / std::tan(half_angle));
  cone.frame.UpdateEquation();
  cone.radius0 = first_bore_radius;
  cone.radius1 = countersink_radius;
  cone.angle = 2.0 * ON_PI;
  cone.length = countersink_depth;

  const ON_Plane cyl1_frame = FrameFromAxisForGeneralBooleanTest(transition, dir);
  Brep::CylindricalFace cyl1;
  cyl1.frame = cyl1_frame;
  cyl1.radius = first_bore_radius;
  cyl1.angle = 2.0 * ON_PI;
  cyl1.length = first_bore_length;

  const Point3d step2_start = transition + dir * first_bore_length;
  const ON_Plane cyl2_frame = FrameFromAxisForGeneralBooleanTest(step2_start, dir);
  Brep::CylindricalFace cyl2;
  cyl2.frame = cyl2_frame;
  cyl2.radius = second_bore_radius;
  cyl2.angle = 2.0 * ON_PI;
  cyl2.length = second_bore_length;

  const Brep::PlanarFace mouth_cap = DiskCapForGeneralBooleanTest(sleeve.frame, 0.0, countersink_radius, /*flip=*/true);
  const Brep::PlanarFace far_cap = DiskCapForGeneralBooleanTest(cyl2_frame, second_bore_length, second_bore_radius, /*flip=*/false);

  const Brep tool = Brep::FromMixedFaces({mouth_cap, far_cap}, {sleeve, cyl1, cyl2}, {cone});
  return BooleanCombineGeneral(solid, tool, BooleanOp::Difference);
}

// parity-map "kernel: Feature operations" - "Feature recognition": closes
// RecognizeCountersinkHoles()'s own disclosed "a countersink stacked with
// a further counterbore/pilot step on the same axis (three or more steps
// mixing conical and cylindrical segments) is out of scope here" gap.
// RecognizeCountersinkChains() walks forward from the cone/cylinder touch
// point through any further adjacent, differing-radius cylindrical steps.
void TestRecognizeCountersinkChainsRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::CountersinkChain;
  using dino8::kernel::CountersinkFeature;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeCountersinkChains;
  using dino8::kernel::RecognizeCountersinkHoles;
  using dino8::kernel::Vector3d;

  const Brep box = Brep::Box(0, 0, 0, 10, 10, 10);
  const Point3d origin(5, 5, 10);
  const Vector3d down(0, 0, -1);

  {
    // A countersink whose pilot bore itself steps down through a second,
    // narrower cylindrical segment, extending all the way THROUGH the
    // box - the tool's own nominal second_bore_length (7.0) deliberately
    // extends past the box's own remaining depth (5.0, computed below),
    // the same "past the box's own height rather than exactly equal to
    // it" avoidance TestRecognizeCountersinkHolesRoundTrip's own through
    // case already establishes for this identical BooleanCombineGeneral()
    // "edge is claimed by 3 or more fragment loops" coincident-face
    // degeneracy.
    const double countersink_radius = 2.0, angle_degrees = 90.0;
    const double bore_radius = 0.6, first_bore_length = 3.6;
    const double final_radius = 0.3, nominal_second_bore_length = 7.0;
    const double countersink_depth = (countersink_radius - bore_radius) / std::tan(angle_degrees * ON_PI / 360.0);
    const double true_second_bore_length = 10.0 - countersink_depth - first_bore_length;  // box's own real remaining depth
    const Brep result = BuildCountersinkChainFixture(box, origin, down, countersink_radius, angle_degrees, bore_radius,
                                                       first_bore_length, final_radius, nominal_second_bore_length);

    // Sanity: RecognizeCountersinkHoles() itself still merges only the
    // cone with the FIRST pilot bore (its own two-segment domain), never
    // reaching the third segment - confirms this fixture genuinely
    // exercises the gap being closed.
    const std::vector<CountersinkFeature> partial = RecognizeCountersinkHoles(result);
    Check(partial.size() == 1 && std::abs(partial[0].bore_radius - bore_radius) < 1e-6,
          "sanity: RecognizeCountersinkHoles() itself reports only the first pilot bore's own radius, never "
          "reaching the third, further-reduced step");

    const std::vector<CountersinkChain> found = RecognizeCountersinkChains(result);
    Check(found.size() == 1, "RecognizeCountersinkChains merges the countersink and both pilot-bore steps into one compound feature");
    const CountersinkChain& chain = found[0];
    Check(chain.origin.DistanceTo(origin) < 1e-6, "RecognizeCountersinkChains recovers the chain's own exact entry point");
    Check((chain.axis - down).Length() < 1e-6, "RecognizeCountersinkChains recovers the chain's own exact drilling direction");
    Check(std::abs(chain.countersink_diameter - 2.0 * countersink_radius) < 0.01,
          "RecognizeCountersinkChains recovers the countersink's own mouth diameter to within the general boolean engine's own SSX tolerance");
    Check(std::abs(chain.countersink_angle_degrees - angle_degrees) < 0.2,
          "RecognizeCountersinkChains recovers the countersink's own full included angle to within the general boolean engine's own SSX tolerance");
    Check(chain.steps.size() == 2, "RecognizeCountersinkChains recovers both of the chain's own cylindrical steps");
    Check(std::abs(chain.steps[0].radius - bore_radius) < 1e-6, "RecognizeCountersinkChains recovers the first pilot bore's own exact radius");
    Check(std::abs(chain.steps[0].length - first_bore_length) < 1e-6, "RecognizeCountersinkChains recovers the first pilot bore's own exact length");
    Check(std::abs(chain.steps[1].radius - final_radius) < 1e-6, "RecognizeCountersinkChains recovers the second, further-reduced step's own exact radius");
    Check(std::abs(chain.steps[1].length - true_second_bore_length) < 1e-6,
          "RecognizeCountersinkChains recovers the second step's own exact TOTAL (box-clipped) length, not the "
          "tool's own nominal, further-reaching length");
    Check(chain.through, "RecognizeCountersinkChains reports this through chain as through");

    const double expected_removed = ON_PI * countersink_depth / 3.0 *
                                         (countersink_radius * countersink_radius +
                                          countersink_radius * bore_radius + bore_radius * bore_radius) +
                                     ON_PI * bore_radius * bore_radius * first_bore_length +
                                     ON_PI * final_radius * final_radius * true_second_bore_length;
    // Loose (0.2% relative, not the usual tight absolute tolerance) here
    // specifically: this fixture's own compound tool - a sleeve, a cone,
    // AND two cylindrical steps, all welded into ONE tool cut via ONE
    // BooleanCombineGeneral() call - is more complex than
    // TestRecognizeCountersinkHolesRoundTrip's own 2-segment tool, and
    // measurably (confirmed directly, ~0.1%) accumulates more of the
    // general boolean engine's own SSX curve-sampling residual into the
    // tessellated volume than that simpler fixture does - the same kind
    // of small, disclosed numerical effect (not a recognition bug) that
    // fixture's own mouth diameter/angle checks already tolerate.
    const Mesh result_mesh = result.TessellateToClosedMesh(64, 64);
    const double expected_volume = 1000.0 - expected_removed;
    Check(std::abs(result_mesh.Volume() - expected_volume) < expected_volume * 0.002,
          "the 3-step countersink chain's own tessellated volume matches the hand-derived closed form (box minus "
          "a cone frustum minus two cylinders) to within the general boolean engine's own SSX tolerance");
  }
  {
    // Negative controls: a plain (single-step) countersink is
    // RecognizeCountersinkHoles()'s own domain and is not repeated here;
    // a plain 3-step stepped hole (no cone at all) has no countersink
    // mouth to anchor a chain on.
    const Brep plain_countersink = BuildCountersinkHoleFixture(box, origin, down, 2.0, 90.0, 0.5, 5.0);
    Check(RecognizeCountersinkChains(plain_countersink).empty(),
          "RecognizeCountersinkChains finds no chain on a plain single-step countersink - that stays "
          "RecognizeCountersinkHoles()'s own domain");
  }
}

// Builds a standalone tapered-boss-CHAIN shape directly via FromMixedFaces
// (BuildTaperedBossFixture()'s own precedent, sidestepping
// BooleanCombineGeneral()'s own confirmed Union-side "floating base cap"
// gap) - a "body" filler cylinder, then TWO differing-radius cylindrical
// steps, then a conical taper down to `cone_tip_radius`: the ordinary
// (cylindrical-base) orientation, generalized from BuildTaperedBossFixture's
// own single shaft segment to a real two-step chain.
//
// `body_radius` is deliberately passed equal to `cyl_a_radius` by every
// caller below - a genuine, confirmed pitfall found while building this
// fixture (mirroring the precedent set by BuildFlaredTaperedBossFixture's
// own doc comment above): giving the filler body a DIFFERENT radius from
// `cyl_a` makes it a real third same-axis step, and RecognizeTaperedBossChains()'s
// own forward walk (correctly, not a bug) keeps walking straight through it,
// silently absorbing the standalone fixture's own "rest of the body" filler
// into the recognized chain instead of stopping at it. Radius-matching the
// body to `cyl_a` defeats the walk's own "differing radius" step test at
// exactly that boundary (`cand.radius == cur_radius` in
// RecognizeTaperedBossChains()), stopping the chain there while the on-axis
// occupancy probe (at that same boundary, not at the body's own true end
// cap - the one location this file's "eighth session"/"fourteenth session"
// notes already disclose as unreliable for a FromMixedFaces() fixture) still
// reads correctly.
dino8::kernel::Brep BuildTaperedBossChainFixture(dino8::kernel::Point3d body_far_end, dino8::kernel::Vector3d axis,
                                                  double body_radius, double body_length, double cyl_a_radius,
                                                  double cyl_a_length, double cyl_b_radius, double cyl_b_length,
                                                  double cone_tip_radius, double cone_length) {
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  Vector3d dir = axis;
  dir.Unitize();

  const ON_Plane body_frame = FrameFromAxisForGeneralBooleanTest(body_far_end, dir);
  Brep::CylindricalFace body_cf;
  body_cf.frame = body_frame;
  body_cf.radius = body_radius;
  body_cf.angle = 2.0 * ON_PI;
  body_cf.length = body_length;

  const Point3d after_body = body_far_end + dir * body_length;
  const ON_Plane a_frame = FrameFromAxisForGeneralBooleanTest(after_body, dir);
  Brep::CylindricalFace cyl_a_cf;
  cyl_a_cf.frame = a_frame;
  cyl_a_cf.radius = cyl_a_radius;
  cyl_a_cf.angle = 2.0 * ON_PI;
  cyl_a_cf.length = cyl_a_length;

  const Point3d after_a = after_body + dir * cyl_a_length;
  const ON_Plane b_frame = FrameFromAxisForGeneralBooleanTest(after_a, dir);
  Brep::CylindricalFace cyl_b_cf;
  cyl_b_cf.frame = b_frame;
  cyl_b_cf.radius = cyl_b_radius;
  cyl_b_cf.angle = 2.0 * ON_PI;
  cyl_b_cf.length = cyl_b_length;

  const Point3d cone_start = after_a + dir * cyl_b_length;
  const Point3d tip_point = cone_start + dir * cone_length;
  const ON_Plane tip_point_frame = FrameFromAxisForGeneralBooleanTest(tip_point, -dir);
  ON_Plane cone_frame = tip_point_frame;
  ShiftConeFrameToApex(cone_frame, tip_point, cone_tip_radius, cyl_b_radius, cone_length);
  Brep::ConicalFace cone_cf;
  cone_cf.frame = cone_frame;
  cone_cf.radius0 = cone_tip_radius;
  cone_cf.radius1 = cyl_b_radius;
  cone_cf.angle = 2.0 * ON_PI;
  cone_cf.length = cone_length;

  const Brep::PlanarFace body_cap = DiskCapForGeneralBooleanTest(body_frame, 0.0, body_radius, /*flip=*/true);
  const Brep::PlanarFace tip_cap = DiskCapForGeneralBooleanTest(tip_point_frame, 0.0, cone_tip_radius, /*flip=*/true);

  return Brep::FromMixedFaces({body_cap, tip_cap}, {body_cf, cyl_a_cf, cyl_b_cf}, {cone_cf});
}

// The flared-base orientation of the same chain shape: a wide conical "pad"
// (BuildFlaredTaperedBossFixture()'s own precedent, avoiding a cylindrical
// filler body for the identical reason that function's own doc comment
// gives - a filler CYLINDER sharing the taper cone's own wide-end radius is
// itself a second real full-cylinder candidate `FindAdjacentConeCylinderPairs()`
// could falsely match instead of the real shaft), feeding into the actual
// taper (the feature `RecognizeTaperedBossChains()` should recover), then
// TWO differing-radius cylindrical steps down to the free tip.
dino8::kernel::Brep BuildFlaredTaperedBossChainFixture(dino8::kernel::Point3d base_far_end, dino8::kernel::Vector3d axis,
                                                        double pad_radius, double pad_length, double mid_radius,
                                                        double taper_length, double cyl_c_radius, double cyl_c_length,
                                                        double cyl_d_radius, double cyl_d_length) {
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  Vector3d dir = axis;
  dir.Unitize();

  const Point3d mid_point = base_far_end + dir * pad_length;
  ON_Plane pad_frame = FrameFromAxisForGeneralBooleanTest(base_far_end, dir);
  ShiftConeFrameToApex(pad_frame, base_far_end, pad_radius, mid_radius, pad_length);
  Brep::ConicalFace pad_cf;
  pad_cf.frame = pad_frame;
  pad_cf.radius0 = pad_radius;
  pad_cf.radius1 = mid_radius;
  pad_cf.angle = 2.0 * ON_PI;
  pad_cf.length = pad_length;

  const Point3d cyl_c_start = mid_point + dir * taper_length;
  ON_Plane taper_frame = FrameFromAxisForGeneralBooleanTest(mid_point, dir);
  ShiftConeFrameToApex(taper_frame, mid_point, mid_radius, cyl_c_radius, taper_length);
  Brep::ConicalFace taper_cf;
  taper_cf.frame = taper_frame;
  taper_cf.radius0 = mid_radius;
  taper_cf.radius1 = cyl_c_radius;
  taper_cf.angle = 2.0 * ON_PI;
  taper_cf.length = taper_length;

  const ON_Plane c_frame = FrameFromAxisForGeneralBooleanTest(cyl_c_start, dir);
  Brep::CylindricalFace cyl_c_cf;
  cyl_c_cf.frame = c_frame;
  cyl_c_cf.radius = cyl_c_radius;
  cyl_c_cf.angle = 2.0 * ON_PI;
  cyl_c_cf.length = cyl_c_length;

  const Point3d cyl_d_start = cyl_c_start + dir * cyl_c_length;
  const ON_Plane d_frame = FrameFromAxisForGeneralBooleanTest(cyl_d_start, dir);
  Brep::CylindricalFace cyl_d_cf;
  cyl_d_cf.frame = d_frame;
  cyl_d_cf.radius = cyl_d_radius;
  cyl_d_cf.angle = 2.0 * ON_PI;
  cyl_d_cf.length = cyl_d_length;

  const ON_Plane pad_cap_frame = FrameFromAxisForGeneralBooleanTest(base_far_end, dir);
  const Brep::PlanarFace pad_cap = DiskCapForGeneralBooleanTest(pad_cap_frame, 0.0, pad_radius, /*flip=*/true);
  const Brep::PlanarFace tip_cap = DiskCapForGeneralBooleanTest(d_frame, cyl_d_length, cyl_d_radius, /*flip=*/false);

  return Brep::FromMixedFaces({pad_cap, tip_cap}, {cyl_c_cf, cyl_d_cf}, {pad_cf, taper_cf});
}

// parity-map "kernel: Feature operations" - "Feature recognition": closes
// TaperedBossFeature's own disclosed "this only ever matches a SINGLE cone
// segment directly adjacent to a SINGLE cylinder segment - a tapered boss
// stacked with a further stepped segment ... is out of scope here" gap - the
// boss-side mirror of TestRecognizeCountersinkChainsRoundTrip() above.
void TestRecognizeTaperedBossChainsRoundTrip() {
  using dino8::kernel::Brep;
  using dino8::kernel::Point3d;
  using dino8::kernel::RecognizeTaperedBosses;
  using dino8::kernel::RecognizeTaperedBossChains;
  using dino8::kernel::TaperedBossChain;
  using dino8::kernel::TaperedBossFeature;
  using dino8::kernel::Vector3d;

  const Point3d body_far_end(0, 0, 0);
  const Vector3d up(0, 0, 1);

  {
    // The ordinary orientation: a cylindrical base that itself steps once
    // before narrowing through a conical taper to a free tip.
    const double body_radius = 1.0, body_length = 1.0;
    const double cyl_a_radius = 1.0, cyl_a_length = 1.2;  // body_radius == cyl_a_radius: see the fixture's own doc comment
    const double cyl_b_radius = 0.6, cyl_b_length = 0.9;
    const double tip_radius = 0.2, cone_length = 0.7;
    const Brep result = BuildTaperedBossChainFixture(body_far_end, up, body_radius, body_length, cyl_a_radius,
                                                       cyl_a_length, cyl_b_radius, cyl_b_length, tip_radius, cone_length);

    // Sanity: RecognizeTaperedBosses() itself still merges only the cone
    // with the immediately-adjacent cyl_b (its own two-segment domain),
    // never reaching cyl_a - confirms this fixture genuinely exercises the
    // gap being closed.
    const std::vector<TaperedBossFeature> partial = RecognizeTaperedBosses(result);
    Check(partial.size() == 1 && std::abs(partial[0].cyl_radius - cyl_b_radius) < 1e-6,
          "sanity: RecognizeTaperedBosses() itself reports only the cone-adjacent segment's own radius, never "
          "reaching the further, second cylindrical step");

    const std::vector<TaperedBossChain> found = RecognizeTaperedBossChains(result);
    Check(found.size() == 1, "RecognizeTaperedBossChains merges both cylindrical steps and the taper into one compound feature");
    const TaperedBossChain& chain = found[0];
    // The chain's own base-attached end is the body/cyl_a boundary (where
    // the walk stops, per the fixture's own doc comment above) - NOT the
    // cyl_a/cyl_b boundary one step further in.
    const Point3d attach = body_far_end + up * body_length;
    Check(chain.origin.DistanceTo(attach) < 1e-6, "RecognizeTaperedBossChains recovers the chain's own exact attach point");
    Check((chain.axis - up).Length() < 1e-6, "RecognizeTaperedBossChains recovers the chain's own exact outward direction");
    Check(chain.base_is_cylindrical, "RecognizeTaperedBossChains reports the cylindrical side as the base");
    Check(chain.steps.size() == 2, "RecognizeTaperedBossChains recovers both of the chain's own cylindrical steps");
    Check(std::abs(chain.steps[0].radius - cyl_a_radius) < 1e-6, "RecognizeTaperedBossChains recovers the base-most step's own exact radius first");
    Check(std::abs(chain.steps[0].height - cyl_a_length) < 1e-6, "RecognizeTaperedBossChains recovers the base-most step's own exact height first");
    Check(std::abs(chain.steps[1].radius - cyl_b_radius) < 1e-6, "RecognizeTaperedBossChains recovers the tip-most cylindrical step's own exact radius second");
    Check(std::abs(chain.steps[1].height - cyl_b_length) < 1e-6, "RecognizeTaperedBossChains recovers the tip-most cylindrical step's own exact height second");
    Check(std::abs(chain.cone_small_radius - tip_radius) < 1e-6, "RecognizeTaperedBossChains recovers the taper's own exact tip radius");
    Check(std::abs(chain.cone_large_radius - cyl_b_radius) < 1e-6, "RecognizeTaperedBossChains recovers the taper's own exact base radius");
    Check(std::abs(chain.cone_length - cone_length) < 1e-6, "RecognizeTaperedBossChains recovers the taper's own exact length");
    const double expected_angle = 2.0 * std::atan2(cyl_b_radius - tip_radius, cone_length) * 180.0 / ON_PI;
    Check(std::abs(chain.taper_angle_degrees - expected_angle) < 1e-4, "RecognizeTaperedBossChains recovers the taper's own exact full included angle");
    Check(!chain.through, "RecognizeTaperedBossChains reports the attached chain as NOT through");
  }
  {
    // The opposite (flared-base) orientation: a conical pad at the base,
    // narrowing through the actual taper to a stepped cylindrical shaft.
    const double pad_radius = 2.0, pad_length = 1.0;
    const double mid_radius = 1.2, taper_length = 1.0;
    const double cyl_c_radius = 0.8, cyl_c_length = 0.9;
    const double cyl_d_radius = 0.4, cyl_d_length = 1.1;
    const Brep result = BuildFlaredTaperedBossChainFixture(body_far_end, up, pad_radius, pad_length, mid_radius,
                                                             taper_length, cyl_c_radius, cyl_c_length, cyl_d_radius,
                                                             cyl_d_length);

    const std::vector<TaperedBossChain> found = RecognizeTaperedBossChains(result);
    Check(found.size() == 1, "RecognizeTaperedBossChains merges the flared taper and both cylindrical steps into one compound feature");
    const TaperedBossChain& chain = found[0];
    const Point3d attach = body_far_end + up * pad_length;
    Check(chain.origin.DistanceTo(attach) < 1e-6, "RecognizeTaperedBossChains recovers the flared chain's own exact attach point");
    Check((chain.axis - up).Length() < 1e-6, "RecognizeTaperedBossChains recovers the flared chain's own exact outward direction");
    Check(!chain.base_is_cylindrical, "RecognizeTaperedBossChains reports the conical segment as the base for the flared orientation");
    Check(chain.steps.size() == 2, "RecognizeTaperedBossChains recovers both of the flared chain's own cylindrical steps");
    Check(std::abs(chain.steps[0].radius - cyl_c_radius) < 1e-6, "RecognizeTaperedBossChains recovers the taper-adjacent step's own exact radius first");
    Check(std::abs(chain.steps[0].height - cyl_c_length) < 1e-6, "RecognizeTaperedBossChains recovers the taper-adjacent step's own exact height first");
    Check(std::abs(chain.steps[1].radius - cyl_d_radius) < 1e-6, "RecognizeTaperedBossChains recovers the tip-most step's own exact radius second");
    Check(std::abs(chain.steps[1].height - cyl_d_length) < 1e-6, "RecognizeTaperedBossChains recovers the tip-most step's own exact height second");
    Check(std::abs(chain.cone_large_radius - mid_radius) < 1e-6,
          "RecognizeTaperedBossChains recovers the taper's own exact radius at the pad transition, not the pad's own further, wider radius");
    Check(std::abs(chain.cone_small_radius - cyl_c_radius) < 1e-6, "RecognizeTaperedBossChains recovers the taper's own exact radius at the shaft transition");
    Check(std::abs(chain.cone_length - taper_length) < 1e-6, "RecognizeTaperedBossChains recovers the flared taper's own exact length");
    Check(!chain.through, "RecognizeTaperedBossChains reports the attached flared chain as NOT through");
  }
  {
    // Negative control: a plain single-cylinder-step tapered boss has no
    // second cylindrical step to chain, so RecognizeTaperedBossChains()
    // finds nothing here. Deliberately `body_radius == shaft_radius`
    // (unlike TestRecognizeTaperedBossesRoundTrip's own same-named fixture
    // call, which uses a DIFFERENT body radius specifically so its own
    // two-segment-only RecognizeTaperedBosses() has a real step boundary to
    // probe occupancy at): a real, confirmed pitfall found while building
    // this negative control, not merely disclosed after the fact - a
    // differing body radius is not a "filler", it is a genuine second
    // cylindrical step on the same axis, and RecognizeTaperedBossChains()'s
    // own forward walk (correctly) keeps going straight into it, so THAT
    // fixture is actually a positive two-segment chain case, not a negative
    // control at all. Matching the body radius to the shaft's own defeats
    // the walk's "differing radius" step test right at that boundary (the
    // same technique BuildTaperedBossChainFixture() above uses deliberately,
    // just for the opposite purpose here - stopping the chain at exactly
    // one cylindrical step instead of two).
    const double body_radius = 0.6, body_length = 1.0;
    const double shaft_radius = 0.6, shaft_length = 2.0;
    const double tip_radius = 0.2, cone_length = 0.8;
    const Brep plain = BuildTaperedBossFixture(body_far_end, up, body_radius, body_length, shaft_radius, shaft_length,
                                                tip_radius, cone_length);
    Check(RecognizeTaperedBossChains(plain).empty(),
          "RecognizeTaperedBossChains finds no chain on a plain single-step tapered boss - that stays "
          "RecognizeTaperedBosses()'s own domain");
  }
}

void TestBendVolumeMatchesPappusClosedFormAndAllowanceSelfConsistency() {
  using dino8::kernel::Bend;
  using dino8::kernel::BendAllowance;
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;

  // parity-map "kernel: Feature operations" - "Sheet-metal features":
  // previously zero sheet-metal-specific code anywhere in this kernel
  // (`UnrollDevelopable()`, surface_edit.cpp, is single-surface unrolling
  // only) - `Bend()` is this kernel's first dedicated sheet-metal feature
  // op, a genuine curved single-bend part (not two flat legs joined by a
  // sharp crease): a closed 2D profile (inner/outer boundary, each a
  // leg-arc-leg shape) extruded by `width` via Brep::Extrude().
  //
  // Because this sweeps a constant rectangular cross-section through a
  // real circular arc, Pappus's centroid theorem gives its EXACT volume:
  // the two flat legs contribute leg_length*width*thickness each, and the
  // curved region contributes bend_angle_radians * (inside_radius +
  // thickness/2) * width*thickness - the cross-section's own geometric
  // centroid radius (deliberately not the K-factor-adjusted radius
  // BendAllowance() below uses for a different purpose).
  const double leg1 = 5.0, leg2 = 3.0, width = 2.0, thickness = 0.1, r_in = 0.2, angle_deg = 90.0;
  const Brep bent = Bend(leg1, leg2, width, thickness, r_in, angle_deg);
  Check(bent.raw().IsValid(), "Bend produces a valid ON_Brep");
  Check(bent.FaceCount() == 3,
        "Bend's single-arc profile extrudes into exactly 3 faces: the swept wall and its two end caps");

  const Mesh m = bent.TessellateToClosedMesh(128, 256);
  Check(m.IsClosedManifold(), "Bend's tessellation is a genuine closed manifold");
  const double theta = angle_deg * ON_PI / 180.0;
  const double r_mid = r_in + thickness / 2.0;
  const double expected_volume = (leg1 + leg2) * width * thickness + theta * r_mid * width * thickness;
  Check(std::abs(m.Volume() - expected_volume) < 0.01 * expected_volume,
        "Bend's tessellated volume matches the exact Pappus closed form to within 1%");

  // BendAllowance() self-consistency: at k_factor == 0.5, the K-factor
  // neutral axis coincides EXACTLY with the true geometric mid-plane
  // Bend()'s own construction sweeps through - so the flat-pattern length
  // for just the curved region must equal theta * r_mid exactly, tying
  // the two independent formulas together at that special case.
  const double allowance_half = BendAllowance(thickness, r_in, angle_deg, 0.5);
  Check(std::abs(allowance_half - theta * r_mid) < 1e-9,
        "BendAllowance at k_factor=0.5 exactly matches Bend()'s own true geometric mid-plane arc length");

  // A shallower bend (30 degrees) and a steeper one (60 degrees) both
  // stay valid, star-shaped, closed solids - not just the one 90-degree
  // case above. (A much steeper bend angle with these same dimensions -
  // confirmed directly, dino8_scratch_test - can exceed Brep::Extrude()'s
  // own star-shaped capping requirement well before 180 degrees, since a
  // fairly THICK annular sector's own star-shaped kernel shrinks faster
  // with angle than a thin one's does; picking dimensions/angles that
  // stay comfortably inside that boundary is this function's own caller's
  // responsibility, the same as any other Extrude()-based feature op in
  // this kernel.)
  for (double angle : {30.0, 60.0}) {
    const Brep b = Bend(2.0, 2.0, 1.0, 0.2, 0.3, angle);
    Check(b.raw().IsValid(), "Bend stays a valid ON_Brep across a range of bend angles");
    const Mesh bm = b.TessellateToClosedMesh(64, 128);
    Check(bm.IsClosedManifold(), "Bend's tessellation stays closed across a range of bend angles");
    Check(bm.Volume() > 0.0, "Bend's tessellated volume stays positive (outward-facing solid) across bend angles");
  }
}

void TestBendAndBendAllowanceRejectInvalidArguments() {
  using dino8::kernel::Bend;
  using dino8::kernel::BendAllowance;
  using sweep_tests::Throws;

  Check(Throws([&] { Bend(0.0, 3.0, 2.0, 0.1, 0.2, 90.0); }), "Bend throws for a non-positive leg1_length");
  Check(Throws([&] { Bend(5.0, -1.0, 2.0, 0.1, 0.2, 90.0); }), "Bend throws for a non-positive leg2_length");
  Check(Throws([&] { Bend(5.0, 3.0, 0.0, 0.1, 0.2, 90.0); }), "Bend throws for a non-positive width");
  Check(Throws([&] { Bend(5.0, 3.0, 2.0, 0.0, 0.2, 90.0); }), "Bend throws for a non-positive thickness");
  Check(Throws([&] { Bend(5.0, 3.0, 2.0, 0.1, 0.0, 90.0); }), "Bend throws for a non-positive inside_radius");
  Check(Throws([&] { Bend(5.0, 3.0, 2.0, 0.1, 0.2, 0.0); }), "Bend throws for a zero bend angle");
  Check(Throws([&] { Bend(5.0, 3.0, 2.0, 0.1, 0.2, 180.0); }), "Bend throws for a bend angle of exactly 180 degrees");
  Check(Throws([&] { Bend(5.0, 3.0, 2.0, 0.1, 0.2, 200.0); }), "Bend throws for a bend angle past 180 degrees");

  Check(Throws([&] { BendAllowance(0.0, 0.2, 90.0); }), "BendAllowance throws for a non-positive thickness");
  Check(Throws([&] { BendAllowance(0.1, 0.0, 90.0); }), "BendAllowance throws for a non-positive inside_radius");
  Check(Throws([&] { BendAllowance(0.1, 0.2, 0.0); }), "BendAllowance throws for a zero bend angle");
  Check(Throws([&] { BendAllowance(0.1, 0.2, 180.0); }), "BendAllowance throws for a bend angle of exactly 180 degrees");
  Check(Throws([&] { BendAllowance(0.1, 0.2, 90.0, -0.1); }), "BendAllowance throws for a negative k_factor");
  Check(Throws([&] { BendAllowance(0.1, 0.2, 90.0, 1.1); }), "BendAllowance throws for a k_factor past 1");
  Check(!Throws([&] { BendAllowance(0.1, 0.2, 90.0, 0.0); }), "BendAllowance accepts a k_factor of exactly 0");
  Check(!Throws([&] { BendAllowance(0.1, 0.2, 90.0, 1.0); }), "BendAllowance accepts a k_factor of exactly 1");
}

void TestMultiBendReducesToBendForASingleBend() {
  using dino8::kernel::Bend;
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::MultiBend;

  // parity-map "kernel: Feature operations" - "Sheet-metal features":
  // MultiBend() generalizes Bend() from a single bend to a CHAIN of N -
  // closing this item's own disclosed "no multi-bend flat pattern" gap.
  // At N == 1, MultiBend() must build the EXACT SAME profile Bend() itself
  // does (not just a similar-volume shape), since it's the identical
  // construction walked once instead of a fixed single call.
  const double leg1 = 5.0, leg2 = 3.0, width = 2.0, thickness = 0.1, r_in = 0.2, angle_deg = 90.0;
  const Brep bent = Bend(leg1, leg2, width, thickness, r_in, angle_deg);
  const Brep multi = MultiBend({leg1, leg2}, {angle_deg}, {r_in}, width, thickness);
  Check(multi.raw().IsValid(), "MultiBend(N=1) produces a valid ON_Brep");
  Check(multi.FaceCount() == bent.FaceCount(), "MultiBend(N=1) has exactly as many faces as Bend() itself (3)");

  const Mesh m_bent = bent.TessellateToClosedMesh(64, 128);
  const Mesh m_multi = multi.TessellateToClosedMesh(64, 128);
  Check(m_multi.IsClosedManifold(), "MultiBend(N=1) tessellation is a genuine closed manifold");
  Check(std::abs(m_bent.Volume() - m_multi.Volume()) < 1e-6 * std::max(1.0, m_bent.Volume()),
        "MultiBend(N=1) matches Bend()'s own tessellated volume almost exactly (the identical construction, not "
        "just a similar one)");
}

void TestMultiBendUChannelAndHatChannelMatchPappusClosedForm() {
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::MultiBend;

  // A real 2-bend U-channel: three legs (0.6, 0.8, 0.6), two 10-degree
  // bends with DIFFERENT radii (0.1, 0.25) - a real multi-radius part, not
  // just repeated identical bends. Pappus's closed form (the same sum-of-
  // legs-plus-sum-of-arcs formula
  // TestBendVolumeMatchesPappusClosedFormAndAllowanceSelfConsistency above
  // already establishes for a single bend, extended to two, each with its
  // own radius) gives an exact cross-check independent of MultiBend()'s own
  // construction. Dimensions chosen to stay comfortably inside
  // `Brep::Extrude()`'s own star-shaped capping requirement (see MultiBend()'s
  // own doc comment): a two-bend chain's overall profile hits that
  // requirement's own empty-kernel limit far sooner than a single bend of
  // similar size does (confirmed directly, dino8_scratch_test, sweeping
  // angle/leg-length/thickness - the same "stay comfortably inside the
  // boundary" caveat `Bend()`'s own doc comment already discloses for one
  // bend, compounding faster across a chain of them).
  const double width = 1.0, thickness = 0.08;
  const std::vector<double> legs = {0.6, 0.8, 0.6};
  const std::vector<double> angles_deg = {10.0, 10.0};
  const std::vector<double> radii = {0.1, 0.25};
  const Brep u = MultiBend(legs, angles_deg, radii, width, thickness);
  Check(u.raw().IsValid(), "MultiBend U-channel (2 bends, independent radii) is a valid ON_Brep");
  const Mesh m_u = u.TessellateToClosedMesh(64, 128);
  Check(m_u.IsClosedManifold(), "MultiBend U-channel tessellation is a genuine closed manifold");

  double leg_sum = 0.0;
  for (double l : legs) leg_sum += l;
  double arc_sum = 0.0;
  for (size_t i = 0; i < angles_deg.size(); ++i) {
    arc_sum += (angles_deg[i] * ON_PI / 180.0) * (radii[i] + thickness / 2.0);
  }
  const double expected_u = leg_sum * width * thickness + arc_sum * width * thickness;
  Check(std::abs(m_u.Volume() - expected_u) < 0.01 * expected_u,
        "MultiBend U-channel's tessellated volume matches the exact multi-radius Pappus closed form to within 1%");

  // A hat-channel: 4 legs, 3 bends, each with its OWN radius.
  const std::vector<double> hat_legs = {0.3, 0.5, 0.5, 0.3};
  const std::vector<double> hat_angles = {8.0, 10.0, 8.0};
  const std::vector<double> hat_radii = {0.2, 0.15, 0.2};
  const Brep hat = MultiBend(hat_legs, hat_angles, hat_radii, width, thickness);
  Check(hat.raw().IsValid(), "MultiBend hat-channel (3 bends, independent radii) is a valid ON_Brep");
  const Mesh m_hat = hat.TessellateToClosedMesh(64, 128);
  Check(m_hat.IsClosedManifold(), "MultiBend hat-channel tessellation is a genuine closed manifold");

  double hat_leg_sum = 0.0;
  for (double l : hat_legs) hat_leg_sum += l;
  double hat_arc_sum = 0.0;
  for (size_t i = 0; i < hat_angles.size(); ++i) {
    hat_arc_sum += (hat_angles[i] * ON_PI / 180.0) * (hat_radii[i] + thickness / 2.0);
  }
  const double expected_hat = hat_leg_sum * width * thickness + hat_arc_sum * width * thickness;
  Check(std::abs(m_hat.Volume() - expected_hat) < 0.01 * expected_hat,
        "MultiBend hat-channel's tessellated volume matches the exact multi-radius Pappus closed form to within 1%");
}

void TestMultiBendRejectsInvalidArguments() {
  using dino8::kernel::MultiBend;
  using sweep_tests::Throws;

  Check(Throws([&] { MultiBend({1.0}, {}, {}, 1.0, 0.1); }),
        "MultiBend throws when bend_angles_degrees is empty (at least one bend is required)");
  Check(Throws([&] { MultiBend({1.0, 2.0}, {90.0}, {0.1, 0.2}, 1.0, 0.1); }),
        "MultiBend throws when inside_radii's own count doesn't match bend_angles_degrees's");
  Check(Throws([&] { MultiBend({1.0, 2.0, 3.0}, {90.0}, {0.1}, 1.0, 0.1); }),
        "MultiBend throws when leg_lengths doesn't have exactly one more entry than bend_angles_degrees");
  Check(Throws([&] { MultiBend({0.0, 2.0}, {90.0}, {0.1}, 1.0, 0.1); }),
        "MultiBend throws for a non-positive leg length");
  Check(Throws([&] { MultiBend({1.0, 2.0}, {90.0}, {0.1}, 0.0, 0.1); }), "MultiBend throws for a non-positive width");
  Check(Throws([&] { MultiBend({1.0, 2.0}, {90.0}, {0.1}, 1.0, 0.0); }),
        "MultiBend throws for a non-positive thickness");
  Check(Throws([&] { MultiBend({1.0, 2.0}, {90.0}, {0.0}, 1.0, 0.1); }),
        "MultiBend throws for a non-positive inside_radius");
  Check(Throws([&] { MultiBend({1.0, 2.0}, {0.0}, {0.1}, 1.0, 0.1); }), "MultiBend throws for a zero bend angle");
  Check(Throws([&] { MultiBend({1.0, 2.0}, {180.0}, {0.1}, 1.0, 0.1); }),
        "MultiBend throws for a bend angle of exactly 180 degrees");
  Check(Throws([&] { MultiBend({1.0, 2.0, 3.0}, {90.0, 200.0}, {0.1, 0.1}, 1.0, 0.1); }),
        "MultiBend throws if ANY bend angle in a multi-bend chain is out of range, not just the first");
}

void TestUnfoldBendAtHalfKFactorExactlyMatchesBendPappusVolume() {
  using dino8::kernel::Bend;
  using dino8::kernel::Brep;
  using dino8::kernel::Mesh;
  using dino8::kernel::UnfoldBend;

  // parity-map "kernel: Feature operations" - "Sheet-metal features":
  // UnfoldBend() closes this item's own disclosed "Unfold" named
  // sub-feature - the inverse direction of Bend() above, flattening the
  // SAME parameters back to a flat Brep::BoxWelded() plate instead of
  // the bent part.
  const double leg1 = 5.0, leg2 = 3.0, width = 2.0, thickness = 0.1, r_in = 0.2, angle_deg = 90.0;
  const double theta = angle_deg * ON_PI / 180.0;
  const double r_mid = r_in + thickness / 2.0;
  const double expected_volume = (leg1 + leg2) * width * thickness + theta * r_mid * width * thickness;

  // At k_factor == 0.5, BendAllowance()'s own K-factor-adjusted radius
  // coincides EXACTLY with the true geometric mid-plane - so this must
  // match the analytic Pappus closed form bit-for-bit, not just within a
  // mesh-tessellation tolerance.
  const Brep flat_half = UnfoldBend(leg1, leg2, width, thickness, r_in, angle_deg, 0.5);
  Check(flat_half.raw().IsValid(), "UnfoldBend (k_factor=0.5) produces a valid ON_Brep");
  Check(std::abs(flat_half.Volume() - expected_volume) < 1e-9 * expected_volume,
        "UnfoldBend at k_factor=0.5 exactly matches the analytic Pappus closed form (bit-for-bit, not just within "
        "1%)");

  // Tying the new flat-pattern function directly to the existing bent
  // part: UnfoldBend's exact volume must also match Bend()'s own
  // TESSELLATED volume to within the same 1% tessellation tolerance
  // TestBendVolumeMatchesPappusClosedFormAndAllowanceSelfConsistency above
  // already establishes for Bend() itself - real round-trip consistency
  // between the two functions, not merely two formulas that happen to
  // agree on paper.
  const Brep bent = Bend(leg1, leg2, width, thickness, r_in, angle_deg);
  const Mesh m_bent = bent.TessellateToClosedMesh(128, 256);
  Check(std::abs(flat_half.Volume() - m_bent.Volume()) < 0.02 * m_bent.Volume(),
        "UnfoldBend's exact flat volume matches Bend()'s own tessellated volume to within 2%");

  // A k_factor other than 0.5 is the standard sheet-metal approximation,
  // deliberately NOT volume-exact: a smaller k_factor (material's
  // neutral axis closer to the inside face) gives a strictly SHORTER
  // flat pattern than the exact mid-plane case.
  const Brep flat_default = UnfoldBend(leg1, leg2, width, thickness, r_in, angle_deg);  // k_factor = 0.44 default
  Check(flat_default.Volume() < flat_half.Volume(),
        "UnfoldBend's default k_factor=0.44 gives a strictly shorter (smaller-volume) flat pattern than the exact "
        "k_factor=0.5 mid-plane case");
}

void TestUnfoldMultiBendAtHalfKFactorExactlyMatchesMultiBendPappusVolume() {
  using dino8::kernel::Brep;
  using dino8::kernel::MultiBend;
  using dino8::kernel::UnfoldMultiBend;

  // Same exact-at-k_factor=0.5 cross-check as UnfoldBend above, extended
  // to MultiBend()'s own multi-radius U-channel fixture (the identical
  // legs/angles/radii TestMultiBendUChannelAndHatChannelMatchPappusClosedForm
  // above already uses) - a genuine multi-radius flat pattern, not a
  // single shared radius.
  const double width = 1.0, thickness = 0.08;
  const std::vector<double> legs = {0.6, 0.8, 0.6};
  const std::vector<double> angles_deg = {10.0, 10.0};
  const std::vector<double> radii = {0.1, 0.25};

  double leg_sum = 0.0;
  for (double l : legs) leg_sum += l;
  double arc_sum = 0.0;
  for (size_t i = 0; i < angles_deg.size(); ++i) {
    arc_sum += (angles_deg[i] * ON_PI / 180.0) * (radii[i] + thickness / 2.0);
  }
  const double expected_u = leg_sum * width * thickness + arc_sum * width * thickness;

  const Brep flat_u = UnfoldMultiBend(legs, angles_deg, radii, width, thickness, 0.5);
  Check(flat_u.raw().IsValid(), "UnfoldMultiBend (k_factor=0.5) produces a valid ON_Brep");
  Check(std::abs(flat_u.Volume() - expected_u) < 1e-9 * expected_u,
        "UnfoldMultiBend at k_factor=0.5 exactly matches the same multi-radius Pappus closed form "
        "MultiBend()'s own U-channel fixture uses, bit-for-bit");

  const Brep u = MultiBend(legs, angles_deg, radii, width, thickness);
  const dino8::kernel::Mesh m_u = u.TessellateToClosedMesh(64, 128);
  Check(std::abs(flat_u.Volume() - m_u.Volume()) < 0.02 * m_u.Volume(),
        "UnfoldMultiBend's exact flat volume matches MultiBend()'s own tessellated U-channel volume to within 2%");
}

void TestUnfoldBendAndUnfoldMultiBendRejectInvalidArguments() {
  using dino8::kernel::UnfoldBend;
  using dino8::kernel::UnfoldMultiBend;
  using sweep_tests::Throws;

  Check(Throws([&] { UnfoldBend(0.0, 3.0, 2.0, 0.1, 0.2, 90.0); }), "UnfoldBend throws for a non-positive leg1_length");
  Check(Throws([&] { UnfoldBend(5.0, -1.0, 2.0, 0.1, 0.2, 90.0); }), "UnfoldBend throws for a non-positive leg2_length");
  Check(Throws([&] { UnfoldBend(5.0, 3.0, 0.0, 0.1, 0.2, 90.0); }), "UnfoldBend throws for a non-positive width");
  Check(Throws([&] { UnfoldBend(5.0, 3.0, 2.0, 0.0, 0.2, 90.0); }),
        "UnfoldBend throws for a non-positive thickness (delegated to BendAllowance)");
  Check(Throws([&] { UnfoldBend(5.0, 3.0, 2.0, 0.1, 0.0, 90.0); }),
        "UnfoldBend throws for a non-positive inside_radius (delegated to BendAllowance)");
  Check(Throws([&] { UnfoldBend(5.0, 3.0, 2.0, 0.1, 0.2, 180.0); }),
        "UnfoldBend throws for a bend angle of exactly 180 degrees (delegated to BendAllowance)");
  Check(Throws([&] { UnfoldBend(5.0, 3.0, 2.0, 0.1, 0.2, 90.0, -0.1); }),
        "UnfoldBend throws for a negative k_factor (delegated to BendAllowance)");
  Check(!Throws([&] { UnfoldBend(5.0, 3.0, 2.0, 0.1, 0.2, 90.0, 0.0); }), "UnfoldBend accepts a k_factor of exactly 0");

  Check(Throws([&] { UnfoldMultiBend({1.0}, {}, {}, 1.0, 0.1); }),
        "UnfoldMultiBend throws when bend_angles_degrees is empty (at least one bend is required)");
  Check(Throws([&] { UnfoldMultiBend({1.0, 2.0}, {90.0}, {0.1, 0.2}, 1.0, 0.1); }),
        "UnfoldMultiBend throws when inside_radii's own count doesn't match bend_angles_degrees's");
  Check(Throws([&] { UnfoldMultiBend({1.0, 2.0, 3.0}, {90.0}, {0.1}, 1.0, 0.1); }),
        "UnfoldMultiBend throws when leg_lengths doesn't have exactly one more entry than bend_angles_degrees");
  Check(Throws([&] { UnfoldMultiBend({0.0, 2.0}, {90.0}, {0.1}, 1.0, 0.1); }),
        "UnfoldMultiBend throws for a non-positive leg length");
  Check(Throws([&] { UnfoldMultiBend({1.0, 2.0}, {90.0}, {0.1}, 0.0, 0.1); }),
        "UnfoldMultiBend throws for a non-positive width");
  Check(Throws([&] { UnfoldMultiBend({1.0, 2.0, 3.0}, {90.0, 200.0}, {0.1, 0.1}, 1.0, 0.1); }),
        "UnfoldMultiBend throws if ANY bend angle in a multi-bend chain is out of range, not just the first "
        "(delegated per-bend to BendAllowance)");
}

void TestLatticeInfillFillsBoxAndConformsToNonBoxSolids() {
  using dino8::kernel::Brep;
  using dino8::kernel::LatticeInfill;
  using dino8::kernel::Mesh;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;

  // parity-map "kernel: Feature operations" - "Lattice/cellular infill":
  // previously the only "lattice" hits anywhere in this kernel were the
  // unrelated Cage FFD deformer - no cellular infill code of any kind.
  // LatticeInfill() closes this outright (`[missing]` -> at least
  // `[partial]`, a simple strut-based cubic lattice, not a gyroid/TPMS or
  // Voronoi infill - both of those remain genuinely unimplemented).
  const Brep box_brep = Brep::Box(0, 0, 0, 4, 4, 4);
  const Mesh box = box_brep.TessellateToClosedMesh(8, 8);
  Check(box.IsClosedManifold(), "sanity: the box fixture itself is a closed manifold");

  const double cell_size = 1.0, strut_radius = 0.05;
  const Mesh lattice = LatticeInfill(box, cell_size, strut_radius, 12);
  Check(lattice.IsClosedManifold(), "LatticeInfill(box) is a genuine closed manifold (every strut junction, not "
                                     "just isolated struts, merges cleanly)");
  Check(lattice.Volume() > 0.0, "LatticeInfill(box) has positive volume");
  Check(lattice.Volume() < box.Volume(), "LatticeInfill(box) is a sparse infill, strictly lighter than the solid box");

  // Increasing strut_radius (same grid, same cell_size) must increase the
  // total lattice volume - a basic monotonicity sanity check independent
  // of the exact strut-junction overlap math.
  const Mesh lattice_thicker = LatticeInfill(box, cell_size, 2.0 * strut_radius, 12);
  Check(lattice_thicker.IsClosedManifold(), "LatticeInfill(box) with a thicker strut radius is still closed manifold");
  Check(lattice_thicker.Volume() > lattice.Volume(),
        "doubling strut_radius (same grid) strictly increases the lattice's own total volume");

  // The lattice is genuinely trimmed to `solid`'s own shape, not just to
  // its bounding box: a cylinder inscribed in the SAME bounding box as the
  // box above has its own corners cut away, so its own lattice infill must
  // have LESS material than the box's, despite using an identical grid.
  const Mesh cylinder = Mesh::Cylinder(Point3d(2, 2, 0), Vector3d(0, 0, 1), 2.0, 4.0, 48);
  Check(cylinder.IsClosedManifold(), "sanity: the inscribed-cylinder fixture itself is a closed manifold");
  const Mesh lattice_cyl = LatticeInfill(cylinder, cell_size, strut_radius, 12);
  Check(lattice_cyl.IsClosedManifold(), "LatticeInfill(inscribed cylinder) is a genuine closed manifold");
  Check(lattice_cyl.Volume() > 0.0, "LatticeInfill(inscribed cylinder) has positive volume");
  Check(lattice_cyl.Volume() < lattice.Volume(),
        "LatticeInfill(inscribed cylinder) has strictly less volume than LatticeInfill(box) over the identical "
        "bounding box - the cylinder's own corners genuinely trim the lattice, not just its outer box");
}

void TestLatticeInfillRejectsInvalidArguments() {
  using dino8::kernel::Brep;
  using dino8::kernel::LatticeInfill;
  using dino8::kernel::Mesh;
  using dino8::kernel::NurbsCurve;
  using dino8::kernel::Point3d;
  using dino8::kernel::Vector3d;
  using sweep_tests::Throws;

  const Brep box_brep = Brep::Box(0, 0, 0, 4, 4, 4);
  const Mesh box = box_brep.TessellateToClosedMesh(8, 8);
  const NurbsCurve square = NurbsCurve::FromControlPoints(
      {Point3d(0, 0, 0), Point3d(1, 0, 0), Point3d(1, 1, 0), Point3d(0, 1, 0), Point3d(0, 0, 0)}, 1);
  const Mesh open_mesh = Brep::Extrude(square, Vector3d(0, 0, 1), /*cap=*/false).TessellateToClosedMesh(4, 4);
  Check(!open_mesh.IsClosedManifold(), "sanity: the uncapped-tube fixture itself is NOT a closed manifold");

  Check(Throws([&] { LatticeInfill(box, 0.0, 0.05, 12); }), "LatticeInfill throws for a non-positive cell_size");
  Check(Throws([&] { LatticeInfill(box, 1.0, 0.0, 12); }), "LatticeInfill throws for a non-positive strut_radius");
  Check(Throws([&] { LatticeInfill(box, 1.0, 0.5, 12); }),
        "LatticeInfill throws when strut_radius is not strictly less than half cell_size");
  Check(Throws([&] { LatticeInfill(box, 1.0, 0.05, 2); }), "LatticeInfill throws for circle_segments below 3");
  // A cell_size exceeding the solid's own bounding box is NOT an error -
  // ceil() of any positive ratio is always at least 1, so this just builds
  // one oversized cell, trimmed down to whatever of `solid` it crosses.
  Check(!Throws([&] { LatticeInfill(box, 10.0, 0.05, 12); }),
        "LatticeInfill does not throw when cell_size exceeds the solid's own bounding box - it degrades to one "
        "oversized cell instead");
  Check(LatticeInfill(box, 10.0, 0.05, 12).Volume() > 0.0,
        "LatticeInfill with an oversized cell_size still produces a genuine, positive-volume result");
  Check(Throws([&] { LatticeInfill(open_mesh, 0.2, 0.02, 12); }),
        "LatticeInfill throws when solid is not a closed manifold");

  // The opposite of the oversized-cell_size case above: cell_size small
  // relative to the solid's own bounding box must be rejected, not
  // silently accepted into a grid with an intractable strut count (the
  // fold after the strut-building loops is one real Boolean Union per
  // strut) - or, for a cell_size small enough to overflow int outright in
  // the ceil()-and-cast this kernel uses internally, undefined behavior
  // instead of a clean exception.
  Check(Throws([&] { LatticeInfill(box, 0.001, 0.0001, 12); }),
        "LatticeInfill throws when cell_size is too small relative to the solid's own bounding box (an "
        "intractable strut count), not left to build/union millions of struts");
  Check(Throws([&] { LatticeInfill(box, 1e-12, 1e-13, 12); }),
        "LatticeInfill throws for a cell_size small enough that the naive ratio would overflow int, instead of "
        "hitting undefined behavior in the ceil()-and-cast");
}

